// 马克思主义基本原理概论专项全量选择题 (520题)
var MARX_CHOICE_DATA = (typeof window !== 'undefined' ? (window.MARX_CHOICE_DATA = [{"id":"marx-1-1","globalId":1,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":1,"question":"学习马克思主义的根本方法是（ ）。","options":["精读马列原著","把握基本原理","理论联系实际","深入调查研究"],"answer":2,"answerLetter":"C","explain":"马克思主义是指导实践的科学理论，只有将理论与实际相结合，才能真正理解和运用马克思主义 ，所以理论联系实际是学习马克思主义的根本方法。"},{"id":"marx-1-2","globalId":2,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":2,"question":"规律具有两个特点，一个是普遍性，另一个是（ ）","options":["客观性","变动性","社会性","能动性"],"answer":0,"answerLetter":"A","explain":"规律是事物运动发展中的本质的、必然的、稳定的联系。规律具有普遍性和客观性，客观性是规律 的根本特点，不以人的意志为转移。变动性、社会性、能动性都不属于规律特点。答案选A。"},{"id":"marx-1-3","globalId":3,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":3,"question":"“白马非马”这一诡辩命题的错误在于割裂了（ ）。","options":["现象和本质的联系","局部和整体的联系","个别和一般的联系","量变和质变的联系"],"answer":2,"answerLetter":"C","explain":"“白马”是个别、具体的马，“马”是一般、抽象的概念，代表所有马的共性。“白马非马”说白 马不是马，就是把个别（白马）和一般（马）的联系割裂了。"},{"id":"marx-1-4","globalId":4,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":4,"question":"“存在就是被感知”这种观点属于（ ）。","options":["朴素唯物主义","形而上学唯物主义","主观唯心主义","客观唯心主义"],"answer":2,"answerLetter":"C","explain":"“存在就是被感知”强调个人的感知决定事物的存在，把人的主观精神当作世界的本原，这符合主 观唯心主义的特征。"},{"id":"marx-1-5","globalId":5,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":5,"question":"“革命是解放生产力，改革也是解放生产力”。这一论断表明社会改革与社会革命（ ）","options":["都以夺取国家政权为目的","都不改变社会制度的根本性质","都是要解决社会基本矛盾","都不需要采取暴力冲突的形式"],"answer":2,"answerLetter":"C","explain":"社会革命是推翻旧的社会制度，解放生产力；社会改革是在坚持社会制度的前提下，对生产关系和 上层建筑进行调整，同样是为了解放生产力，二者都是解决社会基本矛盾的方式。A选项，改革不以夺取国家 政权为目的；B选项，革命改变社会制度根本性质；D选项，革命一般采取暴力冲突形式。"},{"id":"marx-1-6","globalId":6,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":6,"question":"下下列各项中属于社会心理的是（ ）。","options":["政治与法律","哲学与宗教","科学与艺术","风俗与习惯"],"answer":3,"answerLetter":"D","explain":"社会心理是低层次的社会意识，是自发的、不系统的、不定型的社会意识，表现为人们的感知、情 绪、情感、心态、习俗等。 选项A“政治与法律”、选项B“哲学与宗教”、选项C“科学与艺术”都属于高 层次的、系统的社会意识形式，即社会意识形态。 而选项D“风俗与习惯”是人们在长期社会生活中形成的 ，属于自发的、不系统的社会心理范畴。"},{"id":"marx-1-7","globalId":7,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":7,"question":"“从本质上看,认识是主体对客体的能动反映。”这是一种（ ）。","options":["辩证唯物主义认识论观点","形而上学唯物主义认识论观点","主观唯心主义认识论观点","客观唯心主义认识论观点"],"answer":0,"answerLetter":"A","explain":"辩证唯物主义认识论强调认识是主体在实践基础上对客体的能动反映，既坚持反映论，又强调认识 的能动性。形而上学唯物主义认识论缺乏实践观点和辩证观点，是直观被动的反映论。主观唯心主义和客观 唯心主义认识论都否认认识是对客观世界的反映。"},{"id":"marx-1-8","globalId":8,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":8,"question":"“感觉到了的东西,我们不能立刻理解它,只有理解了的东西才能更深刻地感觉它”,这句话表明（ ）。","options":["感性认识是微不足道的","感性认识是认识的高级阶段","理性认识是唯一可靠的","理性认识是认识的高级阶段"],"answer":3,"answerLetter":"D","explain":"这句话强调了理解（理性认识）对感觉（感性认识）的深化作用，说明理性认识比感性认识更深刻 ，处于认识的高级阶段。A选项说法错误，感性认识是认识的起点并非微不足道；B选项感性认识是低级阶段 ；C选项理性认识和感性认识都有其可靠性，说理性认识唯一可靠太绝对。"},{"id":"marx-1-9","globalId":9,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":9,"question":"“各尽所能，按需分配”是（ ）","options":["原始社会的分配原则","阶级社会的分配原则","社会主义社会的分配原则","共产主义社会的分配原则"],"answer":3,"answerLetter":"D","explain":"原始社会是平均分配；阶级社会分配原则多样但都不是“各尽所能，按需分配” ；社会主义社会是 按劳分配。“各尽所能，按需分配”是共产主义社会生产力高度发达，物质极大丰富，人们思想觉悟极大提 高等前提下实行的分配原则。"},{"id":"marx-1-10","globalId":10,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":10,"question":"先有工程设计图，然后按工程设计图施工，建成大厦。这一事实说明（ ）。","options":["意识在先，物质在后","意识对物质有能动作用","意识对物质有决定作用","物质对意识有决定作用"],"answer":1,"answerLetter":"B","explain":"题干中先有工程设计图（意识范畴），然后按设计图施工建成大厦（物质成果），体现了意识能够 指导人们通过实践把观念的东西变成现实的东西，这是意识对物质具有能动作用的表现。"},{"id":"marx-1-11","globalId":11,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":11,"question":"作为马克思恩格斯一生最重要的理论发现,使得社会主义从空想变成科学的是（ ）。","options":["唯物主义和辩证法学说","无产阶级革命和无产阶级专政学说","唯物史观和剩余价值学说","劳动价值论和剩余价信学说"],"answer":2,"answerLetter":"C","explain":"唯物史观揭示了人类社会发展的一般规律，剩余价值学说揭示了资本主义社会的特殊规律，二者为 科学社会主义的创立奠定了理论基石，使社会主义从空想变为科学。答案选C 。"},{"id":"marx-1-12","globalId":12,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":12,"question":"“从群众中来，到群众中去”的过程，从认识论上看，就是（ ）。","options":["感性认识——理性认识——感性认识的过程","认识——实践——认识的过程","实践——认识——实践的过程","理性认识——感性认识——理性认识的过程"],"answer":2,"answerLetter":"C","explain":"“从群众中来”，就是深入群众，调查研究，把群众分散的无系统的意见集中起来，经过分析和综 合等，形成符合实际情况的工作方针、政策等，这是从实践到认识的过程。 “到群众中去”，就是把从群众 中集中起来的决策、方针、政策等，再回到群众中去宣传解释，使之化为群众的实际行动，并在群众的实践 中检验这些方针、政策的正确性，这是从认识到实践的过程。所以“从群众中来，到群众中去”的过程，从 认识论上看，就是实践——认识——实践的过程。"},{"id":"marx-1-13","globalId":13,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":13,"question":"“感觉只解决现象问题，理论才解决本质问题”，这句话说明（ ）。","options":["感性认识是微不足道的","感性认识有待于发展到理性认识","理性认识是唯一可靠的","理性认识有待于深化为感性认识"],"answer":1,"answerLetter":"B","explain":"题干强调感觉（感性认识）只能解决现象问题，而理论（理性认识）才能解决本质问题，这表明感 性认识有局限性，为了把握事物本质，需要从感性认识上升到理性认识。答案：B 。A选项，感性认识并非微 不足道，它是认识的起点，是有重要作用的，A错误；C选项，理性认识也不一定是唯一可靠的，需要经过实 践检验，C错误；D选项，应该是感性认识有待深化为理性认识，D说法错误。"},{"id":"marx-1-14","globalId":14,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":14,"question":"“过剩资本”的出现是（ ）。","options":["资本积累的前提条件","资本循环的物质基础","资本输出的财力基础","引进资本的必然结果"],"answer":2,"answerLetter":"C","explain":"当大量资本在国内找不到有利可图的投资场所，就形成“过剩资本”，而这些过剩资本会寻求对外 投资，所以“过剩资本”是资本输出的财力基础。"},{"id":"marx-1-15","globalId":15,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":15,"question":"现代生产力系统的渗透性因素是指（ ）。","options":["教育","管理","生产资料","自然科学"],"answer":3,"answerLetter":"D","explain":"现代生产力系统中，自然科学通过渗透到生产力系统的其他要素中转化为现实生产力，是渗透性因 素。教育属于准备性因素，管理是运筹性因素，生产资料是实体性因素。"},{"id":"marx-1-16","globalId":16,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":16,"question":"“绝对运动中包含着相对静止，相对静止中包含着绝对运动”，这是一种（ ）。","options":["相对主义诡辩论的观点","唯物辩证法的观点","形而上学的观点","客观唯心主义的观点"],"answer":1,"answerLetter":"B","explain":"唯物辩证法认为运动是绝对的、无条件的，静止是相对的、有条件的，绝对运动和相对静止相互依 存、相互渗透，绝对运动中包含相对静止，相对静止中包含绝对运动。 相对主义诡辩论只承认绝对运动，否 认相对静止；形而上学则把静止绝对化，否认运动；客观唯心主义把某种客观精神当作世界本原，这几种观 点都不符合“绝对运动与相对静止相互包含”的表述。"},{"id":"marx-1-17","globalId":17,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":17,"question":"“社会形态的发展是一个自然历史过程”。这句话说的是（ ）。","options":["社会规律和自然规律没有差别","社会发展排斥主体选择的作用","社会发展取决于主体自由选择","社会发展具有不依人的意志为转移的客观规律性"],"answer":3,"answerLetter":"D","explain":"“社会形态的发展是一个自然历史过程”强调社会发展像自然界一样有其客观规律，不依赖人的意 志。A选项社会规律和自然规律有本质差别；B选项社会发展不排斥主体选择作用；C选项社会发展不是取决于 主体自由选择。"},{"id":"marx-1-18","globalId":18,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":18,"question":"“实践、认识、再实践、再认识，这种形式，循环往复以至无穷”体现的是（ ）。","options":["唯心主义辩证法","唯物主义辩证法","朴素唯物主义观点","机械唯物主义观点"],"answer":1,"answerLetter":"B","explain":"“实践、认识、再实践、再认识，循环往复以至无穷”这一认识发展的总规律，体现了认识和实践 的辩证统一，是符合马克思主义唯物辩证法的思想。马克思主义强调实践是认识的基础，认识在实践基础上 不断发展，这是唯物辩证法在认识领域的体现。 唯心主义辩证法强调精神、意识等第一性，与题干强调实践 基础不符；朴素唯物主义用具体物质形态解释世界，机械唯物主义具有机械性、形而上学性等，都与题干这 种认识的辩证发展规律不契合。"},{"id":"marx-1-19","globalId":19,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":19,"question":"“物以稀为贵”，这种现象在商品经济关系中主要是指（ ）。","options":["商品稀少价值就大","使用价值决定价值","供求关系对价格有重要影响","消费者的心理决定价值"],"answer":2,"answerLetter":"C","explain":"“物以稀为贵”强调的是商品因数量稀少，导致市场供求关系变化，进而影响价格。价值由社会必 要劳动时间决定，并非商品稀少程度、使用价值或消费者心理决定。所以该句话体现的是供求关系对价格有 重要影响。答案选C。"},{"id":"marx-1-20","globalId":20,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":20,"question":"相对剩余价值的获得是（ ）。","options":["延长工作日、增加剩余劳动时间的结果","工作日不变、增加必要劳动时间的结果","个别企业提高劳动生产率的结果","全社会劳动生产率普遍提高的结果"],"answer":3,"answerLetter":"D","explain":"D. 全社会劳动生产率普遍提高的结果（正确）相对剩余价值是指在工作日长度不变的条件下，通过 缩短必要劳动时间、相应延长剩余劳动时间而生产的剩余价值。而要缩短必要劳动时间，就必须降低劳动力 的价值（即降低劳动者所需生活资料的价值）。这依赖于全社会劳动生产率的普遍提高（包括生产生活资料 和生产这些生活资料所需生产资料部门的劳动生产率提高）。因此，相对剩余价值是全社会劳动生产率普遍 提高的结果。 A. 延长工作日、增加剩余劳动时间的结果（错误）这是绝对剩余价值的生产方法。通过绝对延长工作日长度 来增加剩余劳动时间，从而获取更多的剩余价值。 B. 工作日不变、增加必要劳动时间的结果（错误）这是一个干扰项。相对剩余价值的前提确实是“工作日不 变”，但它是通过缩短必要劳动时间（而不是增加）来实现的。如果必要劳动时间增加了，剩余劳动时间反 而会减少，剩余价值也会减少。 C. 个别企业提高劳动生产率的结果（错误）个别企业提高劳动生产率，会使该企业生产商品的个别劳动时间 低于社会必要劳动时间，从而获得超额剩余价值。超额剩余价值是相对剩余价值的起点，但个别企业获得的 是超额剩余价值，而不是相对剩余价值。当全社会劳动生产率普遍提高后，超额剩余价值消失，转化为相对 剩余价值。"},{"id":"marx-1-21","globalId":21,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":21,"question":"“狼孩”没有意识,这一事实说明（ ）。","options":["意识是生物长期发展的产物","意识是人脑发展的产物","意识是对客观事物的反映","意识是社会的产物"],"answer":3,"answerLetter":"D","explain":"“狼孩”具备人脑，也有生物进化基础，但因脱离人类社会环境而没有意识，这表明意识的产生离 不开社会环境，强调了意识是社会的产物。"},{"id":"marx-1-22","globalId":22,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":22,"question":"“生活、实践的观点,应该是认识论的首要的和基本的观点”的提出者是（ ）。","options":["马克思","恩格斯","列宁","毛泽东"],"answer":2,"answerLetter":"C","explain":"列宁在《唯物主义和经验批判主义》中提出“生活、实践的观点，应该是认识论的首要的和基本的 观点” 。"},{"id":"marx-1-23","globalId":23,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":23,"question":"“世界不是既成的事物的集合体，而是过程的集合体”。这是一种（ ）。","options":["唯物辩证法的观点","形而上学的观点","相对主义的观点","唯心主义的观点"],"answer":0,"answerLetter":"A","explain":"唯物辩证法强调世界是永恒发展的，一切事物都处在发生、发展和灭亡的过程中，该观点与“世界 是过程的集合体”相符。形而上学用孤立、静止、片面观点看问题；相对主义夸大事物相对性否定绝对性 ；唯心主义认为意识是世界本原。"},{"id":"marx-1-24","globalId":24,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":24,"question":"“哲学家们只是用不同的方式解释世界，问题在于改变世界”的提出者是（ ）。","options":["黑格尔","费尔巴哈","马克思","恩格斯"],"answer":2,"answerLetter":"C","explain":"“哲学家们只是用不同的方式解释世界，问题在于改变世界”是马克思在《关于费尔巴哈的提纲》 中提出的重要观点。它强调了实践的重要性，将哲学从单纯解释世界引向改变世界。"},{"id":"marx-1-25","globalId":25,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":25,"question":"新事物之所以必然战胜旧事物，从根本上说是由于（ ）。","options":["新事物是在旧事物之后产生的","新事物具有旧事物所没有的新形式","新事物具有旧事物所没有的新内容","新事物较旧事物更符合事物发展的必然趋势"],"answer":3,"answerLetter":"D","explain":"新事物必然战胜旧事物的根本原因在于，新事物符合事物发展的必然趋势，具有强大生命力和远大 前途。A选项产生先后不是决定因素；B、C选项新形式和新内容并非根本，关键是符合发展趋势。"},{"id":"marx-1-26","globalId":26,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":26,"question":"“没有理性，眼睛是最坏的见证人”。这句话强调的是（ ）。","options":["仅同事物的现象相符合的不一定是真相","只要同事物的现象相符合的就是真理","只要观察事物的外部联系就能获得真理","只要观察事物的偶然联系就能获得真理"],"answer":0,"answerLetter":"A","explain":"“没有理性，眼睛是最坏的见证人”，意思是光靠感性直观，不经过理性思考，看到的可能并非真 实情况。现象有真相和假象之分，仅与现象符合不一定是真相，需要理性分析。B选项说同现象符合就是真理 太绝对；C只观察外部联系、D只观察偶然联系都难以获得真理。"},{"id":"marx-1-27","globalId":27,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":27,"question":"“圣人不行而知”，这种观点属于（ ）。","options":["唯物主义反映论","旧唯物主义直观反映论","唯心主义先验论","辩证唯物主义能动反映论"],"answer":2,"answerLetter":"C","explain":"“圣人不行而知”意思是圣人不用实践就知晓，这否定了认识来源于实践，认为认识是先于实践和 经验而存在的，属于唯心主义先验论的观点。答案选C。"},{"id":"marx-1-28","globalId":28,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":28,"question":"“天行有常，不为尧存，不为桀亡。”这是说（ ）。","options":["规律仅仅存在于自然界","规律是无法认识和把握的","规律不具有客观普遍性","规律不以人的意志为转移"],"answer":3,"answerLetter":"D","explain":"“天行有常，不为尧存，不为桀亡”意思是大自然的运行有其自身规律，不会因为尧这样的圣君而 存在，也不会因为桀这样的暴君而消失，强调规律不会因人的意志改变，这体现了规律的客观性，不以人的 意志为转移。"},{"id":"marx-1-29","globalId":29,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":29,"question":"“注意分寸”“掌握火候”“适可而止”等说法，都是要在实践中坚持（ ）。","options":["适度原则","辩证否定观","实事求是","科学发展观"],"answer":0,"answerLetter":"A","explain":"“注意分寸”“掌握火候”“适可而止”强调做事要把握好度，不能过度，这体现的是适度原则。"},{"id":"marx-1-30","globalId":30,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":30,"question":"亚当·斯密和大卫·李嘉图是（ ）。","options":["德国古典哲学的代表人物","英国古典政治经济学的代表人物","英国空想社会主义的代表人物","法国空想社会主义的代表人物"],"answer":1,"answerLetter":"B","explain":"亚当·斯密和大卫·李嘉图是在政治经济学领域成就突出，主要活跃于英国。德国古典哲学代表是 康德、黑格尔等；空想社会主义代表人物圣西门、傅立叶等分别来自法国、英国等，但不是亚当·斯密和大 卫·李嘉图。"},{"id":"marx-1-31","globalId":31,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":31,"question":"“作为观念形态的文艺作品，都是一定的社会生活在人类头脑中的反映的产物”，这句话强调的是（ ）。","options":["社会意识根源于社会存在","社会意识具有历史继承性","社会存在根源于社会意识","社会意识具有相对独立性"],"answer":0,"answerLetter":"A","explain":"题干表明文艺作品（社会意识）是社会生活（社会存在）在人头脑中的反映产物，突出社会意识源 于社会存在。"},{"id":"marx-1-32","globalId":32,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":32,"question":"19世纪初期欧洲的空想社会主义者不包括","options":["法国的圣西门","法国的傅立叶","英国的欧文","英国的莫尔"],"answer":3,"answerLetter":"D","explain":"19世纪初期欧洲空想社会主义代表人物是法国的圣西门、傅立叶和英国的欧文 。而莫尔是16世纪早 期空想社会主义者，写有《乌托邦》。答案选D。"},{"id":"marx-1-33","globalId":33,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":33,"question":"把在法律和生产上独立的企业在流通环节统一起来,进行垄断经营的企业组织形式是（ ）。","options":["卡特尔","辛迪加","托拉斯 参考答案：B 【解析】 卡特尔是生产同类产品的企业通过签订协定划分销售市场，规定产量和价格等，企业在生产和法律 上仍保持独立，但在销售方面并非完全统一经营。 辛迪加是同一生产部门的企业通过签订协定，共同采购原 料和销售商品，在流通环节统一起来进行垄断经营，企业在生产和法律上保持独立。 托拉斯是把许多生产同 类产品或与产品经营有密切关系的企业合并组成大的企业，由董事会统一经营管理，参加的企业在生产、法 律上都丧失独立性。答案：B，辛迪加符合在法律和生产上独立的企业在流通环节统一起来进行垄断经营的特 点。 34.辩证法与形而上学在真理观上的对立在于是否承认（ ）。 A.真理具有相对性 B.真理具有客观性 C.真理具有主观性","真理具有绝对性"],"answer":0,"answerLetter":"A","explain":"辩证法认为世界是联系、发展的，承认真理是相对性和绝对性的统一，而形而上学用孤立、静止、 片面的观点看问题，往往否认真理的相对性，二者在真理观上对立在于是否承认真理具有相对性。答案：A 。"},{"id":"marx-1-35","globalId":34,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":35,"question":"揠苗助长”这个寓言说明（ ）。","options":["意识活动具有目的性和计划性","意识活动具有主动创造性","意识能通过指导实践改造客观物质世界","如果违背规律,越是发挥主观能动性,遭受的挫折和失败就越严重"],"answer":3,"answerLetter":"D","explain":"“揠苗助长”是指把苗拔起来，帮助其成长，这违背了禾苗自然生长的规律，最后导致禾苗死亡。 该行为体现出即便发挥主观能动性，但违背规律，就会遭受挫折失败。答案选D。"},{"id":"marx-1-36","globalId":35,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":36,"question":"要开一张包治百病的药方是很荒谬的,因为它违背了（ ）。","options":["任何事物都包含着矛盾的原理","事物的矛盾各有其特点的原理","普遍性存在于特殊性之中的原理","事物之间普遍联系的原理"],"answer":1,"answerLetter":"B","explain":"包治百病意味着忽视了不同疾病的差异，而不同疾病有不同特点，这违背了事物矛盾各有其特点的 原理。"},{"id":"marx-1-37","globalId":36,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":37,"question":"16世纪末，伽利略通过在比萨斜塔所做的自由落体实验，推翻了亚里士多德关于物体的降落速度与物体的 重量成正比的说法。这件事说明（ ）。","options":["真理是对事物及其规律的正确反映","真理是由相对真理走向绝对真理的过程","实践是认识发展的动力","实践是检验认识是否正确的唯一标准"],"answer":3,"answerLetter":"D","explain":"伽利略通过自由落体实验（实践活动），推翻了亚里士多德的错误说法，证明了自己对落体运动规 律的认识是正确的，这体现了实践能够检验认识是否正确，即实践是检验认识是否正确的唯一标准。"},{"id":"marx-1-38","globalId":37,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":38,"question":"19世纪欧洲空想社会主义是马克思主义直接理论来源之一，其代表人物是（ ）。","options":["配第、斯密、李嘉图","拉美特利、爱尔维修、狄德罗","康德、黑格尔、费尔巴哈","圣西门、傅立叶、欧文"],"answer":3,"answerLetter":"D","explain":"19世纪欧洲空想社会主义代表人物是圣西门、傅立叶、欧文 ，所以答案选D。A选项配第、斯密、李 嘉图是英国古典政治经济学代表；B选项拉美特利、爱尔维修、狄德罗是18世纪法国唯物主义哲学家；C选项 康德、黑格尔、费尔巴哈是德国古典哲学代表。"},{"id":"marx-1-39","globalId":38,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":39,"question":"一般而言，经济全球化的主要内容不包括（ ）。","options":["生产全球化","贸易全球化","资本全球化","劳动力流动全球化"],"answer":3,"answerLetter":"D","explain":"经济全球化主要包括生产全球化、贸易全球化和资本全球化。劳动力流动全球化虽存在，但不是经 济全球化主要内容。答案选D。"},{"id":"marx-1-40","globalId":39,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":40,"question":"20世纪后半叶兴起的垄断组织形式主要是（ ）。","options":["卡特尔","辛迪加","混合联合企业","康采恩"],"answer":2,"answerLetter":"C","explain":"20世纪后半叶兴起的垄断组织形式主要是混合联合企业 ，它是一种跨行业多样化经营的垄断组织。 卡特尔、辛迪加、康采恩是早期垄断组织形式。"},{"id":"marx-1-41","globalId":40,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":41,"question":"把马克思主义作为行动的指南，就是要（ ）。","options":["用马克思主义的立场、观点和方法研究解决实际问题","从马克思主义经典著作中寻找解决现实问题的直接答案","把马克思主义当作现成的公式裁剪历史事实","一切从马克思主义的一般原理出发"],"answer":0,"answerLetter":"A","explain":"马克思主义是科学的世界观和方法论，作为行动指南应运用其立场、观点和方法研究解决实际问题 ，A 项正确。B 项，现实问题复杂多样，不能单纯从经典著作找直接答案；C 项，把马克思主义当现成公式 裁剪历史事实，违背实事求是；D 项，应一切从实际出发，而非从马克思主义一般原理出发。"},{"id":"marx-1-42","globalId":41,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":42,"question":"处于垄断地位的大银行在当代资本主义社会中的地位表现在（ ）。","options":["它已掌控了所有银行业务","它已成为社会经济生活中的万能垄断者","它已控制了整个国民经济","它已掌握了国民经济的命脉"],"answer":1,"answerLetter":"B","explain":"在当代资本主义社会，处于垄断地位的大银行凭借其强大的金融实力和广泛的业务网络，渗透到社 会经济生活的各个方面，成为“万能垄断者”。A选项“掌控所有银行业务”表述太绝对；C选项“控制整个 国民经济”不准确，大银行虽影响力大但不能完全控制整个国民经济；D选项掌握国民经济命脉表述不准确 ，大银行主要是在金融领域影响力大。答案：B。"},{"id":"marx-1-43","globalId":42,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":43,"question":"从本质上看，货币是（ ）。","options":["特殊的资本","普通的商品","一般等价物","固定地充当一般等价物的商品"],"answer":3,"answerLetter":"D","explain":"货币的本质是固定地充当一般等价物的商品。货币与普通商品不同，它能表现其他一切商品的价值 ，具有与其他一切商品相交换的能力，是从商品中分离出来的，所以B选项错误。资本是能够带来剩余价值的 价值，货币只有在一定条件下才成为资本，A选项错误。一般等价物在历史上有很多形式，不固定，而货币是 固定充当一般等价物的，C选项表述不准确。"},{"id":"marx-1-44","globalId":43,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":44,"question":"一切唯心主义都主张（ ）。","options":["精神是世界的本原","存在就是被感知","世界是绝对精神的产物","理是天地万物之根"],"answer":0,"answerLetter":"A","explain":"唯心主义的核心观点就是认为精神是第一性的，是世界的本原。B选项“存在就是被感知”是主观唯 心主义观点；C选项“世界是绝对精神的产物”是客观唯心主义代表黑格尔的观点；D选项“理是天地万物之 根”也是客观唯心主义观点。它们都只是唯心主义的具体表现形式，A选项概括了唯心主义的共性主张。答案 ：A"},{"id":"marx-1-45","globalId":44,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":45,"question":"按照辩证唯物主义一元论的根本要求,在工作中必须坚持（ ）。","options":["一切从人的需要出发","一切从主观愿望出发","一切从客观实际出发","一切从理论原则出发"],"answer":2,"answerLetter":"C","explain":"辩证唯物主义一元论强调世界的本原是物质，物质第一性，意识第二性，这就要求我们在工作中要 尊重客观事实，从实际情况出发。A选项从人的需要出发、B选项从主观愿望出发、D选项从理论原则出发，都 忽视了客观实际，是主观主义的做法。而C选项一切从客观实际出发符合辩证唯物主义一元论的要求。答案 ：C"},{"id":"marx-1-46","globalId":45,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":46,"question":"把社会主义本质概括为\"解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕\"的中国 共产党人是（ ）。","options":["毛泽东","刘少奇","周恩来","邓小平"],"answer":3,"answerLetter":"D","explain":"1992年初，邓小平在南方谈话中对社会主义本质作了总结性理论概括，即“解放生产力，发展生产 力，消灭剥削，消除两极分化，最终达到共同富裕” 。"},{"id":"marx-1-47","globalId":46,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":47,"question":"当代，自然科学的发展日新月异，新的科研成果层出不穷。从根本上说，这是由（ ）。","options":["科学家的聪明才智决定的","生产实践的需要决定的","正确的科技政策决定的","环境和资源的状况决定的"],"answer":1,"answerLetter":"B","explain":"实践是认识的基础，实践是认识发展的动力，自然科学属于认识范畴，其发展的根本原因是生产实 践的需要，生产实践不断提出新课题，推动自然科学发展。A选项科学家聪明才智有影响但非根本；C选项科 技政策有促进作用但非根源；D选项环境和资源状况是外部条件并非根本决定因素。"},{"id":"marx-1-48","globalId":47,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":48,"question":"当代国际垄断组织保证其垄断统治和垄断利益的最主要形式是（ ）。","options":["卡特尔和托拉斯","辛迪加和托拉斯","跨国公司和国际垄断同盟","跨国公司和托拉斯"],"answer":2,"answerLetter":"C","explain":"当代国际垄断组织的主要形式是跨国公司和国际垄断同盟 ，它们是保证垄断统治和垄断利益的最主 要形式。而卡特尔、辛迪加、托拉斯是国内垄断组织的形式。答案选C。"},{"id":"marx-1-49","globalId":48,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":49,"question":"按照技术社会形态的划分标准,我们可以把人类历史划分为（ ）。","options":["人的依赖性社会、物的依赖性社会、个人全面发展的社会","渔猎社会、农业社会、工业社会、信息社会","自然经济社会、商品经济社会、产品经济社会","古代社会、近代社会、现代社会"],"answer":1,"answerLetter":"B","explain":"技术社会形态是以生产力和技术发展水平以及与此相适应的产业结构为标准划分的社会形态，包括 渔猎社会、农业社会、工业社会、信息社会 。A选项是根据人的发展状况划分；C选项是根据经济运行形态划 分；D选项划分角度不属技术社会形态范畴。"},{"id":"marx-1-50","globalId":49,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":50,"question":"把实践证实的理论看成是永恒不变的绝对真理,并当成检验其他一切认识是否正确的标准,这是一种（ ）。","options":["唯物辩证法观点","唯理论观点","相对主义诡辩论观点","形而上学观点"],"answer":3,"answerLetter":"D","explain":"题干中把实践证实的理论看成永恒不变的绝对真理，忽视了真理的相对性，用固定不变的标准去衡 量一切，这体现了形而上学用孤立、静止、片面的观点看问题的特点。 唯物辩证法强调用联系、发展、全面 的观点看问题，与题干不符；唯理论片面夸大理性认识的作用，题干重点强调对真理的绝对化看法，并非唯 理论核心观点；相对主义诡辩论则夸大事物的相对性而否定确定性和客观性，也不符合题干表述。答案 ：D.形而上学观点"},{"id":"marx-1-51","globalId":50,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":51,"question":"辩证唯物主义认为，运动和静止的关系属于（ ）。","options":["本质和现象的关系","内容和形式的关系","绝对和相对的关系","可能和现实的关系"],"answer":2,"answerLetter":"C","explain":"辩证唯物主义认为，运动是绝对的，无条件的；静止是相对的，有条件的，运动和静止是绝对和相 对的关系 。"},{"id":"marx-1-52","globalId":51,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":52,"question":"产业资本循环采取的职能形式是（ ）。","options":["生产资本、流通资本和银行资本","生产资本、商业资本和银行资本","货币资本、生产资本和商品资本","货币资本、生产资本和商业资本"],"answer":2,"answerLetter":"C","explain":"产业资本在循环过程中要依次经历三个阶段，相应采取货币资本、生产资本和商品资本三种职能形 式。货币资本为生产剩余价值做准备，生产资本生产剩余价值，商品资本实现剩余价值。所以答案选C 。"},{"id":"marx-1-53","globalId":52,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":53,"question":"凡是承认世界具有统一性的哲学都属于（ ）。","options":["唯物论","唯心论","二元论","一元论"],"answer":3,"answerLetter":"D","explain":"一元论认为世界只有一个本原，承认世界具有统一性，即世界统一于一个本原。唯物论和唯心论都 属于一元论，分别认为世界统一于物质和意识。二元论主张世界有精神和物质两个独立本原，不承认世界的 统一性。所以凡是承认世界具有统一性的哲学都属于一元论。"},{"id":"marx-1-54","globalId":53,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":54,"question":"反映资本家对工人剥削程度的剩余价值率，可表示为（ ）。","options":["m：v","v：m","m：（c+V）","（c+v）：m"],"answer":0,"answerLetter":"A","explain":"剩余价值率是剩余价值（m）和可变资本（v）的比率，它反映资本家对工人的剥削程度。因为可变 资本是用于购买劳动力的资本，工人在劳动过程中创造的剩余价值与可变资本的比例，能体现资本家对工人 的剥削程度。 选项C中m:(c + v)是利润率的表达式，c是不变资本，c + v是总资本，它反映的是资本增殖程 度，而非剥削程度。选项Bv:m和选项D(c + v):m不符合剩余价值率的定义。"},{"id":"marx-1-55","globalId":54,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":55,"question":"标志着科学社会主义理论公开面世的纲领性文件是（ ）。","options":["《共产主义原理》","《共产党宣言》","《哥达纲领批判》","《国家与革命》"],"answer":1,"answerLetter":"B","explain":"《共产党宣言》是马克思和恩格斯为共产主义者同盟起草的纲领，它的发表，标志着科学社会主义 理论公开面世。而A选项《共产主义原理》为《共产党宣言》做了理论准备；C选项《哥达纲领批判》批判拉 萨尔主义，发展科学社会主义；D选项《国家与革命》是列宁关于国家和法学说方面的著作。"},{"id":"marx-1-56","globalId":55,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":56,"question":"产业资本循环中生产剩余价值的阶段是（ ）。","options":["购买阶段","生产阶段","销售阶段","流通阶段"],"answer":1,"answerLetter":"B","explain":"在产业资本循环的购买阶段，资本家购买生产资料和劳动力，为生产剩余价值做准备，此时还未产 生剩余价值，A选项不符合。 生产阶段中，劳动力与生产资料相结合进行生产，工人的劳动创造出包含剩余 价值的商品，所以这个阶段是生产剩余价值的阶段，B选项正确。 销售阶段是把包含剩余价值的商品卖出去 ，实现价值和剩余价值，而不是生产剩余价值，C选项不符合。 流通阶段包括购买阶段和销售阶段，都不直 接生产剩余价值，D选项不符合。"},{"id":"marx-1-57","globalId":56,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":57,"question":"公式W…P…表示的是产业资本循环的（ ）。","options":["购买阶段","生产阶段","销售阶段","流通阶段"],"answer":1,"answerLetter":"B","explain":"产业资本循环有三个阶段，购买阶段是货币资本转化为生产资本，用 G - W 表示；生产阶段是生产 资本转化为商品资本，用 W…P…W' 表示，这里 W 是生产资料和劳动力， P 是生产过程；销售阶段是商品 资本转化为货币资本，用 W' - G' 表示。题干中 W…P… 符合生产阶段的公式表示。"},{"id":"marx-1-58","globalId":57,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":58,"question":"公司金融寡头在经济上的统治主要是通过（ ）。","options":["自由竞争来实现","私人垄断来实现","“参与制”来实现","“个人联合”来实现"],"answer":2,"answerLetter":"C","explain":"金融寡头在经济上的统治主要是通过“参与制”实现，“参与制”是指金融寡头通过掌握一定数量 的股票来层层控制企业的制度。而自由竞争与金融寡头统治无关；私人垄断表述不准确；“个人联合”是金 融寡头在政治上统治的手段。"},{"id":"marx-1-59","globalId":58,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":59,"question":"已购买而尚未使用的生产资料处于资本循环的（ ）。","options":["购买阶段","生产阶段","销售阶段","流通阶段"],"answer":0,"answerLetter":"A","explain":"资本循环包括购买阶段、生产阶段和销售阶段。购买阶段资本家购买生产资料和劳动力，为生产剩 余价值准备条件；生产阶段是生产资料与劳动力结合生产出包含剩余价值的商品；销售阶段是将商品卖出 ，实现价值和剩余价值。已购买而尚未使用的生产资料，表明已完成购买行为，但还未进入生产过程，处于 购买阶段向生产阶段的过渡状态，仍属于资本循环的购买阶段。"},{"id":"marx-1-60","globalId":59,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":60,"question":"产生资本主义经济危机的根源是（ ）。","options":["生产相对过剩","需求绝对减少","资本主义基本矛盾","生产和消费的矛盾"],"answer":2,"answerLetter":"C","explain":"资本主义经济危机根源在于资本主义基本矛盾，即生产的社会化与生产资料资本主义私人占有之间 的矛盾。这一矛盾引发了生产相对过剩等一系列问题。A选项生产相对过剩是经济危机的本质特征而非根源 ；B选项需求绝对减少表述错误；D选项生产和消费的矛盾由资本主义基本矛盾引发，不是根源。"},{"id":"marx-1-61","globalId":60,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":61,"question":"除了剩余价值与可变资本的比率外，剩余价值率还可以表示为（ ）。","options":["剩余劳动时间与必要劳动时间的比率","剩余劳动时间与社会必要劳动时间的比率","可变资本与不变资本的比率","利润与预付总资本的比率"],"answer":0,"answerLetter":"A","explain":"剩余价值率反映资本家对工人的剥削程度，它有两种表示方法。一种是物化劳动表示法，即剩余价 值与可变资本的比率；另一种是活劳动表示法，即剩余劳动时间与必要劳动时间的比率。因为工人的全部劳 动时间分为必要劳动时间和剩余劳动时间，剩余价值就是由工人在剩余劳动时间创造出来的。"},{"id":"marx-1-62","globalId":61,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":62,"question":"马克思主义认为，哲学是（ ）。","options":["人们自发形成的世界观","系统化、理论化的世界观","科学的世界观","无产阶级的世界观"],"answer":1,"answerLetter":"B","explain":"马克思主义认为哲学是系统化、理论化的世界观。自发形成的世界观并非哲学，A 排除；哲学有科 学与非科学之分，并非所有哲学都是科学的世界观，C 排除；无产阶级的世界观只是马克思主义哲学的属性 之一，不能等同于哲学的定义，D 排除。答案：B。"},{"id":"marx-1-63","globalId":62,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":63,"question":"英国古典政治经济学是马克思主义的直接理论来源之一，其代表人物是（ ）。","options":["培根、洛克","斯密、李嘉图","黑格尔、费尔巴哈","圣西门、傅立叶"],"answer":1,"answerLetter":"B","explain":"马克思主义直接理论来源中英国古典政治经济学代表人物是亚当·斯密和大卫·李嘉图。A选项培根 、洛克主要在哲学等领域；C选项黑格尔、费尔巴哈是德国古典哲学代表；D选项圣西门、傅立叶是空想社会 主义代表。"},{"id":"marx-1-64","globalId":63,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":64,"question":"平均利润形成之后,价值规律的作用形式表现为市场价格围绕（ ）。","options":["生产成本上下波动","平均利润上下波动","价值上下波动","生产价格上下波动"],"answer":3,"answerLetter":"D","explain":"平均利润形成后，商品价值就转化为生产价格，生产价格由生产成本加平均利润构成。此时价值规 律作用形式发生变化，市场价格不再围绕价值而是围绕生产价格上下波动。"},{"id":"marx-1-65","globalId":64,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":65,"question":"用于发放工资的货币执行的是货币的（ ）。","options":["价值尺度职能","流通手段职能","支付手段职能","贮藏手段职能"],"answer":2,"answerLetter":"C","explain":"支付手段是指货币用于清偿债务、支付赋税、租金、工资等的职能，发放工资体现了货币延期支付 的特点，属于支付手段职能。"},{"id":"marx-1-66","globalId":65,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":66,"question":"马克思主义认为社会生活在本质上是实践的，这是因为（ ）。","options":["实践主体处于一定的社会关系中","实践具有客观性、能动性和社会历史性","实践是个人日常生活的活动","实践是人类社会产生、存在和发展的基础"],"answer":3,"answerLetter":"D","explain":"马克思主义强调社会生活本质上是实践的，关键在于实践对于人类社会产生、存在和发展起到了基 础性作用。人类通过实践活动创造了自身赖以生存的社会关系、社会结构等。A选项说的是实践主体的特征 ，B选项阐述的是实践本身的特点，C选项对实践的定义过于狭隘。只有D选项准确说明了实践对人类社会的根 本意义。"},{"id":"marx-1-67","globalId":66,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":67,"question":"群众路线的基本出发点和最终归宿是（ ）。","options":["一切为了群众","从群众中来","一切依靠群众","到群众中去"],"answer":0,"answerLetter":"A","explain":"群众路线包括“一切为了群众，一切依靠群众，从群众中来，到群众中去”。“一切为了群众”体 现的是目的，全心全意为人民服务，这是群众路线的基本出发点和最终归宿 。“一切依靠群众”强调力量来 源。“从群众中来，到群众中去”是工作方法。"},{"id":"marx-1-68","globalId":67,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":68,"question":"由于提高劳动强度而生产的剩余价值属于","options":["绝对剩余价值","超额剩余价值","相对剩余价值","超额利润"],"answer":0,"answerLetter":"A","explain":"绝对剩余价值是指在必要劳动时间不变的条件下，通过绝对延长工作日，从而绝对延长剩余劳动时 间来生产出来的剩余价值。此外，提高劳动强度，让工人在同样时间内耗费更多体力与脑力，与延长工作日 效果类似，也属于绝对剩余价值生产。相对剩余价值是在工作日长度不变时，通过缩短必要劳动时间、相应 延长剩余劳动时间获得的；超额剩余价值是个别资本家提高劳动生产率，使商品个别价值低于社会价值的差 额；超额利润是超过平均利润的那部分利润。"},{"id":"marx-1-69","globalId":68,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":69,"question":"从历史上看，暴力革命是社会革命的","options":["唯一形式","基本形式","辅助形式","补充形式"],"answer":1,"answerLetter":"B","explain":"在阶级社会中，暴力革命是社会革命的基本形式。因为统治阶级不会自动让出政权，往往要用暴力 打破旧的国家机器等。非暴力的和平过渡只是在特定条件下才有可能出现，但不是主要的、基本的形式。答 案：B"},{"id":"marx-1-70","globalId":69,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":70,"question":"从资本周转的角度来考察资本的构成，划分为固定资本和流动资本的是（ ）。","options":["生产资本","货币资本","商品资本","流通资本"],"answer":0,"answerLetter":"A","explain":"只有生产资本能从资本周转角度划分为固定资本和流动资本。货币资本、商品资本属于流通资本 ，它们不做这样的划分。"},{"id":"marx-1-71","globalId":70,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":71,"question":"马克思主义是时代的产物。马克思恩格斯所处的历史时代及其提出的各项任务，为马克思主义的产生提供 了","options":["主观条件","客观条件","理论基础","理论前提"],"answer":1,"answerLetter":"B","explain":"马克思恩格斯所处时代及任务是外在的、既定的状况，属于客观范畴，为马克思主义产生提供了客 观条件。主观条件强调人的内在思想等因素；理论基础和理论前提侧重于已有的理论成果，与时代及任务这 种客观背景不符。"},{"id":"marx-1-72","globalId":71,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":72,"question":"由资本主义国家收购部分股权后的私人企业属于（ ）。","options":["国家和私人资本在企业外部的结合","国家和私人资本在企业内部的结合","资本主义国有经济","资本主义私人经济"],"answer":1,"answerLetter":"B","explain":"国家收购部分股权后，国家资本和私人资本在企业内部融合在一起，形成了国家和私人资本在企业 内部的结合这种形式。"},{"id":"marx-1-73","globalId":72,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":73,"question":"当代中国人民为之奋斗的共同理想是（ ）。","options":["建设中国特色社会主义","实现共产主义","彻底消灭剥削","国家自行消亡"],"answer":0,"answerLetter":"A","explain":"建设中国特色社会主义是当代中国人民的共同理想，它把国家的发展、民族的振兴与个人的幸福紧 密联系在一起。共产主义是最高理想，C选项“彻底消灭剥削”和D选项“国家自行消亡”是共产主义社会的 特征，并非当代共同理想。"},{"id":"marx-1-74","globalId":73,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":74,"question":"当代资本主义国家在经济关系方面的一系列新变化表明（ ）。","options":["其社会性质已经根本改变","其基本矛盾已经彻底解决","其阶级对立已经消失","其社会性质发生了部分质变"],"answer":3,"answerLetter":"D","explain":"当代资本主义国家在经济关系等方面虽有新变化，但资本主义私有制基础未变，所以社会性质未根 本改变，基本矛盾未彻底解决，阶级对立也依然存在。不过新变化使得资本主义在自身范围内进行调整，发 生了部分质变。"},{"id":"marx-1-75","globalId":74,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":75,"question":"马克思主义哲学认为，物质的唯一特性是（ ）。","options":["广延性","持续性","可知性","客观实在性"],"answer":3,"answerLetter":"D","explain":"马克思主义哲学强调物质的本质特征，客观实在性是物质区别于意识的根本特性，它不依赖于人的 意识而存在。广延性、持续性属于物质的属性但不是唯一特性，可知性强调物质能被认识，并非物质的唯一 特性。答案：D。"},{"id":"marx-1-76","globalId":75,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":76,"question":"商品生产者要获得更多收益,必须使生产商品的（ ）。","options":["个别劳动时间等于社会必要劳动时间","个别劳动时间低于社会必要劳动时间","个别劳动时间高于社会必要劳动时间","个别劳动时间低于必要劳动时间"],"answer":1,"answerLetter":"B","explain":"商品价值由社会必要劳动时间决定，当个别劳动时间低于社会必要劳动时间时，意味着生产者在同 样时间内生产的商品数量更多，按社会必要劳动时间决定的价值量出售，就能获得更多收益。"},{"id":"marx-1-77","globalId":76,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":77,"question":"当代主要发达资本主义国家处于资本主义发展中的（ ）。","options":["自由竞争资本主义阶段","私人垄断资本主义阶段","一般垄断资本主义阶段","国家垄断资本主义阶段"],"answer":3,"answerLetter":"D","explain":"当代主要发达资本主义国家，国家对经济的干预和调节不断加强，经济运行机制、产业结构等都发 生深刻变化，这些特征符合国家垄断资本主义阶段。在国家垄断资本主义阶段，国家政权与私人垄断资本相 结合，对经济生活进行全面干预和调节。"},{"id":"marx-1-78","globalId":77,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":78,"question":"当代资本主义所发生的许多新变化属于（ ）。","options":["资本主义生产方式的根本改变","资本主义生产关系性质的根本改变","资本主义总量变过程中的爆发式质变","资本主义总量变过程中的阶段性部分质变"],"answer":3,"answerLetter":"D","explain":"当代资本主义虽然有诸多新变化，但资本主义私有制等根本性质未变，只是在其自身范围内的调整 ，属于总量变过程中的阶段性部分质变，并非根本改变或爆发式质变。"},{"id":"marx-1-79","globalId":78,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":79,"question":"马克思主义哲学以前欧洲哲学的全部积极内容，都是马克思主义哲学的理论来源，其中作为马克思主义哲 学直接理论来源的是（ ）。","options":["古希腊罗马哲学","德国古典哲学","近代英国哲学","近代法国哲学"],"answer":1,"answerLetter":"B","explain":"马克思主义哲学的直接理论来源是德国古典哲学，主要是黑格尔辩证法的合理内核与费尔巴哈唯物 主义的基本内核。答案选B。"},{"id":"marx-1-80","globalId":79,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":80,"question":"商品生产者要实现更多的收益必须使（ ）。","options":["个别劳动时间等于社会必要劳动时间","个别劳动时间大于社会必要劳动时间","个别劳动时间小于社会必要劳动时间","个别劳动时间等于倍加的社会必要劳动时间"],"answer":2,"answerLetter":"C","explain":"社会必要劳动时间决定商品价值量，个别劳动时间小于社会必要劳动时间时，商品生产者按社会必 要劳动时间决定的价值量出售商品，能获得额外收益；若个别劳动时间大于社会必要劳动时间，生产者会亏 损。A选项无额外收益，B会亏损，D表述不合理。答案选C，商品生产者要实现更多收益需使个别劳动时间小 于社会必要劳动时间 。 所以答案为C。"},{"id":"marx-2-2","globalId":80,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":2,"question":"与辩证唯物主义认识论相比较，旧唯物主义认识论有两个缺陷，一个是缺乏辩证法的观点，另一个是（ ）。","options":["缺乏实践的观点","缺乏反映论的观点","缺乏一元论的观点","缺乏可知论的观点"],"answer":0,"answerLetter":"A","explain":"旧唯物主义认识论主要的缺陷就是缺乏实践的观点以及辩证法的观点。实践的观点是马克思主义认 识论首要的和基本的观点，旧唯物主义不懂得实践对认识的决定作用。"},{"id":"marx-2-2","globalId":81,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":2,"question":"当代资本主义国家发生了一系列新变化,不属于这些新变化的是（ ）。","options":["工人持股现象的产生","资本社会化趋势的发展","工会组织的产生","社会福利事业的发展"],"answer":2,"answerLetter":"C","explain":"工会组织在19世纪就已产生，并非当代资本主义国家的新变化。而工人持股、资本社会化趋势、社 会福利事业发展是当代资本主义出现的新情况。"},{"id":"marx-2-3","globalId":82,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":3,"question":"矛盾的两种基本属性是（ ）。","options":["同一性和斗争性","统一性和多样性","普遍性和牺牲性","一般性和个别性"],"answer":0,"answerLetter":"A","explain":"矛盾的两种基本属性是同一性和斗争性，这是哲学中关于矛盾的基本知识点。所以答案是A。"},{"id":"marx-2-4","globalId":83,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":4,"question":"商品最本质的因素是（ ）。","options":["使用价值","价值","交换价值","价格"],"answer":1,"answerLetter":"B","explain":"价值是凝结在商品中的无差别的一般人类劳动，它体现着商品生产者之间相互比较劳动耗费量和交 换劳动的社会经济关系，是商品最本质的因素。使用价值是商品的自然属性，是价值的物质承担者；交换价 值是价值的表现形式；价格是价值的货币表现。"},{"id":"marx-2-5","globalId":84,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":5,"question":"德国古典哲学是马克思主义的直接理论来源之一，其代表人物是（ ）。","options":["培根、洛克","圣西门、欧文","黑格尔、费尔巴哈","斯密、李嘉图"],"answer":2,"answerLetter":"C","explain":"德国古典哲学代表人物是黑格尔和费尔巴哈。A选项培根、洛克是英国经验论哲学家；B选项圣西门 、欧文是空想社会主义代表人物；D选项斯密、李嘉图是英国古典政治经济学代表人物。"},{"id":"marx-2-6","globalId":85,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":6,"question":"对世界存在状态问题的不同回答所区分的哲学派别是（ ）。","options":["可知论和不可知论","反映论和先验论","辩证法和形而上学","物主义和唯心主义"],"answer":2,"answerLetter":"C","explain":"辩证法和形而上学是对世界存在状态问题的不同回答。辩证法用联系、发展、全面的观点看世界 ，形而上学用孤立、静止、片面的观点看世界。 A选项可知论和不可知论是对思维和存在是否具有同一性的 不同回答。 B选项反映论和先验论是关于认识的来源等方面的不同观点。 D选项唯物主义和唯心主义是对世 界本原问题的不同回答。"},{"id":"marx-2-7","globalId":86,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":7,"question":"面对消极腐败的东西，我们一定要提高警惕，做到见微知著，防微杜渐。从哲学上看，这是因为（ ）。","options":["矛盾双方在一定条件下相互转化","量变积累到一定程度会引起质变","多种原因引起一个结果","外因通过内因而起作用"],"answer":1,"answerLetter":"B","explain":"“见微知著，防微杜渐”强调的是在消极腐败的事物还处于微小、萌芽状态时就要加以防范，因为 如果任由其发展，微小的量变不断积累，最终会引发质变，产生严重后果。这体现的是量变与质变的辩证关 系。"},{"id":"marx-2-8","globalId":87,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":8,"question":"商业资本家所占有的剩余价值是通过（ ）。","options":["剥削商业店员的具体劳动获得的","剥削商业店员的剩余劳动获得的","剥削产业工人的具体劳动获得的","剥削产业工人的必要劳动获得的"],"answer":1,"answerLetter":"B","explain":"商业资本家通过剥削商业店员的剩余劳动，让商业店员在剩余劳动时间内实现产业资本家让渡给商 业资本家的那部分剩余价值。商业资本家从而占有这部分剩余价值。"},{"id":"marx-2-9","globalId":88,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":9,"question":"在对外经济侵略中，新殖民主义不同于老殖民主义的手法是（ ）。","options":["高价出售工业产品","低价收购原料和初级产品","向外输出“过剩资本”获取高额海外利润","打着“援助”旗号剥削和控制发展中国家"],"answer":3,"answerLetter":"D","explain":"老殖民主义主要通过赤裸裸的军事侵略、直接的殖民统治来掠夺；新殖民主义是在承认殖民地、附 属国形式上政治独立的前提下，通过经济、政治、军事、文化渗透等手段来控制，打着“援助”旗号剥削和 控制发展中国家是新殖民主义典型手法，而A、B、C选项在老殖民主义时期也常用。"},{"id":"marx-2-10","globalId":89,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":10,"question":"商业资本所执行的职能是（ ）。","options":["购买生产资料和劳动力","生产出剩余价值","销售商品，实现价值和剩余价值","贷出货币，投入生产和流通中"],"answer":2,"answerLetter":"C","explain":"商业资本是从产业资本中分离出来，专门从事商品买卖，以获取商业利润为目的的资本形式。其职 能就是通过销售商品，实现商品中的价值和剩余价值。A选项是产业资本购买阶段职能；B选项生产剩余价值 是产业资本生产阶段职能；D选项贷出货币与商业资本职能无关。"},{"id":"marx-2-11","globalId":90,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":11,"question":"在购买阶段,产业资本采取的职能形式是（ ）。","options":["货币资本","生产资本","商品资本","商业资本"],"answer":0,"answerLetter":"A","explain":"产业资本循环的购买阶段，资本家要用货币购买生产资料和劳动力，此时产业资本采取货币资本形 式，为生产剩余价值准备条件。生产资本是在生产阶段的职能形式，商品资本是售卖阶段的职能形式，商业 资本不属于产业资本在循环中特定阶段的职能形式。"},{"id":"marx-2-12","globalId":91,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":12,"question":"分析矛盾的特殊性就是（ ）。","options":["坚持实践的观点","坚持理论联系实际","坚持辩证的否定","坚持具体问题具体分析"],"answer":3,"answerLetter":"D","explain":"矛盾特殊性原理要求我们在分析和解决问题时，不能一概而论，要针对不同情况、不同问题采取不 同方法，也就是要具体问题具体分析。"},{"id":"marx-2-13","globalId":92,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":13,"question":"感性认识和理性认识的区别在于（ ）。","options":["前者源于书本,后者源于实践","前者是可靠的,后者是不可靠的","前者反映事物的现象,后者反映事物的本质","前者来源于直接经验,后者来源于间接经验"],"answer":2,"answerLetter":"C","explain":"感性认识是认识的初级阶段，通过感觉、知觉和表象等形式反映事物的现象；理性认识是认识的高 级阶段，以概念、判断、推理等形式反映事物的本质。A选项，感性认识和理性认识都源于实践；B选项，感 性认识和理性认识都有可靠与不可靠之分；D选项，直接经验和间接经验都可以产生感性认识和理性认识。所 以答案选C。"},{"id":"marx-2-14","globalId":93,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":14,"question":"商业资本资本的职能是（ ）。","options":["购买生产资料和劳动力","创造价值和剩余价值","实现商品的价值和剩余价值","补偿商品买卖的各种费用"],"answer":2,"answerLetter":"C","explain":"商业资本是从产业资本中分离出来，专门从事商品买卖，独立发挥资本职能，以获取商业利润为目 的的一种资本形式。其职能就是通过商品销售，实现商品的价值和剩余价值。A选项是产业资本在生产阶段的 职能；B选项创造价值和剩余价值的是产业资本的生产过程；D选项补偿费用并非商业资本的职能。"},{"id":"marx-2-15","globalId":94,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":15,"question":"在经济全球化过程中，成为垄断资本国际经济组织载体的新的垄断组织形式是（ ）。","options":["混合联合公司","跨国公司","托拉斯","国际垄断联盟"],"answer":1,"answerLetter":"B","explain":"在经济全球化进程中，跨国公司是垄断资本国际经济组织的重要载体。混合联合公司、托拉斯属于 国内垄断组织形式，国际垄断联盟并非垄断资本国际经济组织载体的新形式。"},{"id":"marx-2-16","globalId":95,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":16,"question":"设想没有运动的物质的观点是（ ）。","options":["形而上学唯物主义","朴素唯物主义","主观唯心主义","客观唯心主义"],"answer":0,"answerLetter":"A","explain":"形而上学唯物主义具有机械性等局限性，它割裂了物质和运动的关系，设想没有运动的物质。朴素 唯物主义主要是用具体物质形态解释世界本质；主观唯心主义把人的主观精神当作世界本原；客观唯心主义 把客观精神当作世界本原，这三者与设想没有运动的物质这一观点不相关。"},{"id":"marx-2-17","globalId":96,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":17,"question":"在历史创造者问题上,两种根本对立的观点是（ ）。","options":["群众史观和英雄史观","一元论和二元论","宿命论和唯意志论","唯理论和经验论"],"answer":0,"answerLetter":"A","explain":"在历史创造者问题上，主要存在群众史观和英雄史观这两种根本对立观点。群众史观认为人民群众 是历史创造者，英雄史观则夸大个人作用，忽视人民群众。其他选项B关于世界本原问题，C涉及对历史发展 决定性的不同看法，D是关于认识来源不同观点，均与历史创造者问题无关。"},{"id":"marx-2-18","globalId":97,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":18,"question":"股份公司的经营决策机构是（ ）。","options":["股东大会","董事会","监事","工会"],"answer":1,"answerLetter":"B","explain":"股东大会是股份公司的权力机构，决定公司的重大事项。 董事会是公司的经营决策机构，负责执 行股东大会的决议，对公司的经营管理进行决策。 监事主要负责监督公司的经营管理活动，检查公司财务等 ，不是经营决策机构。 工会是维护职工合法权益的组织，与公司经营决策无关。"},{"id":"marx-2-19","globalId":98,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":19,"question":"认识的真理性,就是检验认识是否同（ ）。","options":["已被实践证实的理论相符合","大多数人的主观愿望相符合","客观事物及其规律相符合","党的路线、方针、政策相符合"],"answer":2,"answerLetter":"C","explain":"真理是人们对客观事物及其规律的正确反映，认识的真理性在于检验认识是否与客观事物及其规律 相符合。A选项以已被实践证实的理论为标准不具有根源性；B选项以大多数人主观愿望为标准是主观的，不 是真理标准；D选项党的路线方针政策也是基于对客观规律的认识制定的，不是最终检验标准。"},{"id":"marx-2-20","globalId":99,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":20,"question":"社会必要劳动时间是以（ ）。","options":["具体劳动为尺度的","简单劳动为尺度的","复杂劳动为尺度的","个别劳动为尺度的"],"answer":1,"answerLetter":"B","explain":"社会必要劳动时间的衡量需有统一标准，简单劳动是每个没有任何专长的普通人都能从事的劳动 ，具有普遍性和统一性，所以社会必要劳动时间是以简单劳动为尺度的。复杂劳动要换算为简单劳动，具体 劳动创造使用价值与衡量社会必要劳动时间无关，个别劳动也不能作为社会必要劳动时间的尺度。"},{"id":"marx-2-21","globalId":100,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":21,"question":"在垄断资本主义阶段,占统治地位的资本是（ ）。","options":["工业资本","银行资本","商业资本","金融资本"],"answer":3,"answerLetter":"D","explain":"在垄断资本主义阶段，工业垄断资本和银行垄断资本融合形成金融资本，金融资本成为占统治地位 的资本。"},{"id":"marx-2-22","globalId":101,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":22,"question":"共产主义社会的显著特征和一面旗帜是（ ）。","options":["各尽所能，平均分配","各尽所能，公平分配","各尽所能，按劳分配","各尽所能，按需分配"],"answer":3,"answerLetter":"D","explain":"共产主义社会生产力高度发达，物质财富极大丰富，实行各尽所能、按需分配。“各尽所能，按需 分配”体现了共产主义社会的本质特征，是共产主义社会的显著特征和一面旗帜。平均分配不符合共产主义 特点；公平分配表述宽泛不准确；按劳分配是社会主义社会分配方式。"},{"id":"marx-2-23","globalId":102,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":23,"question":"货币转化为资本的决定性条件是在流通中购买到（ ）。","options":["生产资料","劳动力","劳动资料","劳动对象"],"answer":1,"answerLetter":"B","explain":"货币转化为资本的关键在于能带来剩余价值，劳动力商品具有独特的使用价值，其使用能创造出比 自身价值更大的价值，为资本家带来剩余价值，所以货币转化为资本的决定性条件是在流通中购买到劳动力 。"},{"id":"marx-2-24","globalId":103,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":24,"question":"认识的主体和客体之间最基本的关系是（ ）。","options":["反映与被反映的认识关系","改造与被改造的实践关系","需要与满足需要的价值关系","创造与被创造的主从关系"],"answer":1,"answerLetter":"B","explain":"实践是认识的基础，认识主体和客体之间首先是改造与被改造的实践关系，在此基础上才产生认识 关系等其他关系。"},{"id":"marx-2-25","globalId":104,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":25,"question":"社会存在是指（ ）。","options":["社会物质生活条件","社会物质财富总和","社会各种关系总和","社会各种要素总和"],"answer":0,"answerLetter":"A","explain":"社会存在是指社会物质生活条件的总和，主要包括地理环境、人口因素和物质生产方式。B选项社会 物质财富总和表述不准确；C选项社会各种关系总和强调的是关系，并非社会存在本质；D选项社会各种要素 总和过于宽泛。A选项符合社会存在定义。"},{"id":"marx-2-26","globalId":105,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":26,"question":"在马克思主义看来,人的本质（ ）。","options":["是由人的文化素质决定的","是由人的心理素质决定的","是由人的社会属性决定的","是由人的自然属性决定的"],"answer":2,"answerLetter":"C","explain":"马克思主义认为人有自然属性和社会属性，而社会属性是人的本质属性，它决定了人的本质。因为 人是社会关系的总和，在社会中形成和发展。"},{"id":"marx-2-27","globalId":106,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":27,"question":"构成资本家全部职能资本的是（ ）。","options":["产业资本和借贷资本","商业资本和借贷资本","生产资本和借贷资本","产业资本和商业资本"],"answer":3,"answerLetter":"D","explain":"职能资本是对剩余价值的生产和实现，实际发挥了职能作用的资本。产业资本在生产领域生产剩余 价值，商业资本在流通领域实现剩余价值，它们都实际发挥职能作用。而借贷资本是为获取利息而暂时贷给 职能资本家使用的货币资本，它不直接发挥生产或实现剩余价值的职能。"},{"id":"marx-2-28","globalId":107,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":28,"question":"在内容和形式的矛盾运动中（ ）。","options":["内容是相对稳定的，形式是活跃易变的","内容是活跃易变的，形式是相对稳定的","内容的变化总是落后于形式的变化","内容和形式都处在不停的显著变动中"],"answer":1,"answerLetter":"B","explain":"内容决定形式，内容是活跃易变的，形式依赖于内容，并随着内容的发展而发展，相对稳定。所以 内容活跃易变，形式相对稳定。"},{"id":"marx-2-29","globalId":108,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":29,"question":"社会基本矛盾有两对,它们之间是（ ）。","options":["相互孤立的关系","相互平行的关系","相互决定的关系","相互制约的关系"],"answer":3,"answerLetter":"D","explain":"社会基本矛盾的两对矛盾即生产力和生产关系的矛盾、经济基础和上层建筑的矛盾。这两对矛盾不 是孤立的，生产力和生产关系的矛盾决定并制约着经济基础和上层建筑的矛盾，而经济基础和上层建筑的矛 盾也影响着生产力和生产关系的矛盾，它们相互制约，共同推动社会发展。"},{"id":"marx-2-30","globalId":109,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":30,"question":"在平均利润率不变、借贷供求大体平衡的条件下，影响利息率的最重要因素是（ ）。","options":["社会心理因素","习惯和法律传统","历史和道德因素","商品市场的供需状况"],"answer":1,"answerLetter":"B","explain":"在平均利润率不变、借贷供求大体平衡时，习惯和法律传统成为影响利息率的重要因素，这是由长 期经济社会发展形成的。社会心理因素对利息率影响较小；历史和道德因素相对间接，不如习惯和法律传统 直接；商品市场供需状况主要影响商品价格等，和利息率关系不大。"},{"id":"marx-2-31","globalId":110,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":31,"question":"股份公司的组织结构一般包括权力机构、经营决策机构和监督机构三部分，与之相应的具体组织形式是 （ ）。","options":["股东会、董事会、监事会","董事会、理事会、职代会","股东会、理事会、监事会","董事会、监事会、职代会"],"answer":0,"answerLetter":"A","explain":"股份公司权力机构是股东会，它决定公司重大事项；经营决策机构是董事会，负责公司日常经营决 策；监督机构是监事会，对公司经营管理等进行监督。B选项中理事会在职代会一般不是股份公司这三类典型 对应组织形式；C选项理事会不合适；D选项职代会不属于这三类标准组织形式。所以应选A。"},{"id":"marx-2-32","globalId":111,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":32,"question":"既承认社会发展的客观规律,又承认主体选择的作用,这种观点属于（ ）。","options":["折中主义观点","相对主义观点","历史唯物主义观点","历史唯心主义观点"],"answer":2,"answerLetter":"C","explain":"历史唯物主义认为社会发展有其客观规律，同时，人的活动又具有能动作用，主体能够在遵循客观 规律的基础上进行选择。 折中主义是把各种不同的观点无原则地拼凑在一起的做法，题干观点并非如此，A 项错误。 相对主义片面夸大事物和认识的相对性，否定事物和认识的确定性、客观性，与题干不符，B 项错 误。 历史唯心主义否认社会发展的客观规律，夸大主体选择作用，与题干不符，D 项错误。"},{"id":"marx-2-33","globalId":112,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":33,"question":"认识我国改革开放和社会主义现代化建设的形势，我们要分清主流和支流，要看主流，同时又不忽略支流 。这里依据的哲学道理是（ ）。","options":["矛盾的普遍性和特殊性辩证关系的原理","主要矛盾和次要矛盾辩证关系的原理","矛盾的主要方面和次要方面辩证关系的原理","事物变化的内因和外因辩证关系的原理"],"answer":2,"answerLetter":"C","explain":"题干强调认识形势要分清主流和支流，主流和支流对应的是矛盾的主要方面和次要方面。矛盾主要 方面决定事物性质，要抓住主流，同时不能忽视次要方面。A选项矛盾普遍性和特殊性强调共性与个性；B选 项主要矛盾和次要矛盾针对的是不同矛盾，题干说的是同一矛盾不同方面；D选项内因和外因与主流支流无关 。所以选C。"},{"id":"marx-2-34","globalId":113,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":34,"question":"社会主义革命在一国或数国首先胜利理论立足于（ ）。","options":["马克思恩格斯著作中的科学预言","资本主义发展不平衡规律","巴黎公社的原则","生产力决定论"],"answer":1,"answerLetter":"B","explain":"列宁根据资本主义发展不平衡规律，得出社会主义革命可能在一国或数国首先胜利的结论。马克思 恩格斯认为社会主义革命将在几个主要资本主义国家同时发生，A 不符合。巴黎公社原则与社会主义革命在 一国或数国首先胜利理论并无直接关联，C 排除。生产力决定论不能直接得出这一结论，D 排除。"},{"id":"marx-2-35","globalId":114,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":35,"question":"社会主义国家要坚持社会主义方向,就必须坚持（ ）。","options":["公有制为主体、全民所有制为主导","不断进行社会主义革命","实行计划经济体制","实行市场经济体制"],"answer":0,"answerLetter":"A","explain":"社会主义公有制是社会主义经济制度的基础，坚持社会主义方向，必须坚持公有制为主体、全民所 有制为主导，它决定着社会主义的性质和发展方向。选项B“不断进行社会主义革命”表述不准确，社会主义 制度建立后重点是建设等；计划经济体制和市场经济体制只是资源配置手段，不是社会主义方向的本质决定 因素。"},{"id":"marx-2-36","globalId":115,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":36,"question":"在商品赊购赊销中,到期偿还货款时货币所执行的职能是（ ）。","options":["价值尺度","流通手段","支付手段","贮藏手段"],"answer":2,"answerLetter":"C","explain":"支付手段是指货币用于清偿债务、支付赋税、租金、工资等的职能。在商品赊购赊销中，到期偿还 货款属于清偿债务，此时货币执行的是支付手段职能。价值尺度是衡量商品价值大小；流通手段是一手交钱 一手交货；贮藏手段是把货币当作财富贮藏起来。"},{"id":"marx-2-37","globalId":116,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":37,"question":"假象同真相一样，也是客观存在的。这是一种（ ）。","options":["辩证法的观点","唯物辩证法的观点","形而上学的观点","主观唯心主义的观点"],"answer":1,"answerLetter":"B","explain":"唯物辩证法认为现象分为真相和假象，二者都是客观存在的，都是事物本质的表现形式。所以“假 象同真相一样，也是客观存在的”这体现的是唯物辩证法的观点。"},{"id":"marx-2-38","globalId":117,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":38,"question":"任何科学真理都不能穷尽对事物的认识，都是随着实践的发展而发展的。这说明真理都具有（ ）。","options":["客观性","相对性","绝对性","全面性"],"answer":1,"answerLetter":"B","explain":"真理的相对性是指真理的有条件性、有限性，包括广度和深度上的有限。题干中说科学真理不能穷 尽对事物认识且随实践发展，体现了真理在广度和深度上并非绝对完善，是有条件和有限的，这符合真理相 对性的特点。"},{"id":"marx-2-39","globalId":118,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":39,"question":"社会主义国家政权的领导核心是（ ）。","options":["工人阶级及其群众组织","工人阶级的先锋队共产党","工农联盟","无产阶级专政机关"],"answer":1,"answerLetter":"B","explain":"在社会主义国家，工人阶级的先锋队共产党代表最广大人民根本利益，是政权领导核心，带领人民 进行社会主义建设等各项事业。A选项工人阶级群众组织并非领导核心；C选项工农联盟是阶级基础；D选项无 产阶级专政机关是实施专政职能的机构，不是领导核心。"},{"id":"marx-2-40","globalId":119,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":40,"question":"在上层建筑的各种要素中，居于主导地位的是（ ）。","options":["艺术","宗教","政治","哲学"],"answer":2,"answerLetter":"C","explain":"上层建筑分为政治上层建筑和观念上层建筑，政治上层建筑是在一定意识形态指导下建立起来的 ，是统治阶级意志的体现，在整个上层建筑中居于主导地位。政治属于政治上层建筑范畴，而艺术、宗教、 哲学属于观念上层建筑，所以政治在上层建筑各种要素中居于主导地位。"},{"id":"marx-2-41","globalId":120,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":41,"question":"广义的共产主义社会包含（ ）。","options":["社会主义社会和共产主义社会","商品经济社会和产品经济社会","社会主义初级阶段和高级阶段","社会主义第一阶段和高级阶段"],"answer":0,"answerLetter":"A","explain":"广义的共产主义社会包含社会主义社会和共产主义社会两个阶段，社会主义是共产主义的低级阶段 。"},{"id":"marx-2-42","globalId":121,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":42,"question":"价值规律是（ ）。","options":["自然经济的基本规律","商品经济的基本规律","资本主义经济的基本规律","社会主义经济的基本规律"],"answer":1,"answerLetter":"B","explain":"价值规律贯穿商品经济的全过程，它体现着商品经济发展运动过程的必然趋势，是商品经济的基本 规律。自然经济、资本主义经济、社会主义经济都包含在商品经济范畴内，但价值规律不是自然经济、资本 主义经济、社会主义经济单独特有的基本规律。"},{"id":"marx-2-43","globalId":122,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":43,"question":"任何真理都是具体的,包罗万象的真理是不存在的。这是因为真理具有（ ）。","options":["绝对性","相对性","全面性","片面性"],"answer":1,"answerLetter":"B","explain":"真理的相对性表明，真理所反映的对象是有条件的、有限的，任何真理都只是对特定事物一定程度 、一定层次的正确认识，并非包罗万象。题干强调不存在包罗万象的真理，正是体现了真理的相对性。 真理 的绝对性强调真理的客观性、世界的可知性等，与题干表述不符。全面性和片面性不是真理的特性。"},{"id":"marx-2-44","globalId":123,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":44,"question":"社会主义核心价值观兼顾了国家、社会、个人三者的价值愿望与追求，其中从个人层面对社会主义核心价 值观基本理念的凝练表达是（ ）。","options":["富强、民主、文明、和谐","自由、平等、法治","爱国、敬业、诚信、友善？","厚德、包容、求是、创新"],"answer":2,"answerLetter":"C","explain":"社会主义核心价值观中，国家层面是富强、民主、文明、和谐；社会层面是自由、平等、公正、法 治；个人层面是爱国、敬业、诚信、友善。"},{"id":"marx-2-45","globalId":124,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":45,"question":"合称为流通资本的两种资本是（ ）。","options":["不变资本与可变资本","固定资本与流动资本","货币资本与商品资本","产业资本与商业资本"],"answer":2,"answerLetter":"C","explain":"流通资本是指在产业资本循环中同生产资本既相对立又相关联、专门执行流通职能的那一部分资本 ，包括货币资本和商品资本。"},{"id":"marx-2-46","globalId":125,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":46,"question":"价值规律作用的表观形式是（ ）。","options":["商品价格围绕价值波动","商品价格经常低于价值","价值围绕商品价格波动","商品价格往往高于价值"],"answer":0,"answerLetter":"A","explain":"价值规律的表现形式是商品价格受供求关系的影响，围绕价值上下波动。B选项价格经常低于价值、 D选项价格往往高于价值都不准确，只是价格波动的部分情况；C选项价值围绕价格波动说法错误，应是价格 围绕价值波动。"},{"id":"marx-2-47","globalId":126,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":47,"question":"商品的二因素指的是（ ）。","options":["使用价值和剩余价值","使用价值和交换价值","价值和使用价值","价值和交换价值"],"answer":2,"answerLetter":"C","explain":"商品是用来交换的能满足人们某种需要的劳动产品，具有使用价值和价值两个因素。使用价值是商 品能满足人们某种需要的属性，即商品的有用性；价值是凝结在商品中的无差别的一般人类劳动。交换价值 是一种使用价值同另一种使用价值相交换的量的关系或比例，价值是交换价值的基础，交换价值是价值的表 现形式，剩余价值是雇佣工人创造的被资本家无偿占有的超过劳动力价值的价值。所以商品二因素是价值和 使用价值。"},{"id":"marx-2-48","globalId":127,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":48,"question":"在社会意识中,思想体系是（ ）。","options":["低级层次的社会意识","高级层次的社会意识","有阶级性的社会意识","无阶级性的社会意识"],"answer":1,"answerLetter":"B","explain":"社会意识从层次上分为社会心理和思想体系。社会心理是低层次的、自发的社会意识，思想体系是 高层次的、自觉的、系统化、理论化的社会意识。同时，思想体系并非都有阶级性，像自然科学等思想体系 就无阶级性，所以C、D选项不准确。"},{"id":"marx-2-49","globalId":128,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":49,"question":"价值增值产生于资本循环的（ ）。","options":["购买阶段","生产阶段","销售阶段","运输阶段"],"answer":1,"answerLetter":"B","explain":"资本循环的生产阶段中，劳动力与生产资料相结合进行生产，工人创造出包含剩余价值的商品，实 现价值增值。购买阶段为生产准备条件，销售阶段实现商品价值，运输阶段不属于资本循环基本阶段。答案 ：B"},{"id":"marx-2-50","globalId":129,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":50,"question":"在苏维埃俄国领导实行战时共产主义政策的主要负责人是（ ）。","options":["列宁","斯大林","布哈林","托洛斯基"],"answer":0,"answerLetter":"A","explain":"战时共产主义政策是在苏俄面临严峻的战争形势等背景下，由列宁领导实施的，旨在集中全国资源 保障战争胜利。答案选A。"},{"id":"marx-2-51","globalId":130,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":51,"question":"建设社会主义先进文化，对传统文化必须批判地继承。这种态度依据的哲学道理是（ ）。","options":["世界是过程集合体的原理","新事物必然战胜旧事物的原理","内容决定形式的原理","辨证的否定的原理"],"answer":3,"answerLetter":"D","explain":"辩证的否定原理强调事物的否定是自我否定，是事物发展环节和联系环节的统一，实质是“扬弃 ”，即既克服又保留。对传统文化批判地继承，就是取其精华、去其糟粕，体现了辩证否定观中既克服旧事 物消极内容又保留积极内容的“扬弃”思想。"},{"id":"marx-2-52","globalId":131,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":52,"question":"阶级产生的根本前提是（ ）。","options":["用暴力掠夺他人财产","人的本质是现实具体的","人的本质是后天形成的","由于产品分配不公出现两极分化"],"answer":3,"answerLetter":"D","explain":"阶级产生的根本前提是社会分工、私有制出现，使得产品分配不公进而出现两极分化。A选项暴力掠 夺不是根本前提；B、C选项关于人的本质的描述与阶级产生无关。"},{"id":"marx-2-53","globalId":132,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":53,"question":"劳动力商品使用价值的特殊性是（ ）。","options":["能生产出具有使用价值的物品","能生产出具有价值的物品","仅能生产出自身价值","能生产出大于自身价值的价值"],"answer":3,"answerLetter":"D","explain":"劳动力商品使用价值的特殊性在于它不仅能创造出自身价值，还能创造出比自身价值更大的价值 ，即剩余价值。选项A和B表述不够体现劳动力商品使用价值特殊性，C项仅能生产自身价值说法错误。 答案 ：D"},{"id":"marx-2-54","globalId":133,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":54,"question":"社会历史发展的决定性是指（ ）。","options":["历史决定论","历史被动论","历史宿命论","历史意志论"],"answer":0,"answerLetter":"A","explain":"社会历史发展的决定性强调社会历史发展具有自身固有的客观规律性，这与历史决定论观点相符 ，历史决定论承认社会历史发展受客观规律支配。 历史被动论强调人在历史面前完全被动，忽视人的主观能 动性，不符合社会历史发展决定性的内涵。 历史宿命论将历史发展归结为不可抗拒的命运，带有迷信色彩 ，与基于客观规律的社会历史发展决定性不同。 历史意志论过分夸大个人意志对历史的作用，也不符合社会 历史发展决定性基于客观规律的本质。"},{"id":"marx-2-55","globalId":134,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":55,"question":"私人劳动和社会劳动形成的条件是（ ）。","options":["技术进步和生产资料公有制","技术进步和生产资料私有制","社会分工和生产资料公有制","社会分工和生产资料私有制"],"answer":3,"answerLetter":"D","explain":"社会分工使得生产者之间相互联系、相互依存，每个生产者的劳动都是社会总劳动的一部分，这是 私人劳动转化为社会劳动的前提条件。 生产资料私有制决定了生产者的劳动具有私人性质，生产什么、生产 多少都由私人决定。所以私人劳动和社会劳动形成的条件是社会分工和生产资料私有制。"},{"id":"marx-2-56","globalId":135,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":56,"question":"在唯物辩证法看来,发展的实质是（ ）。","options":["事物数量的增加","事物的一切运动变化","事物根本性质的变化","新事物的产生和旧事物的灭亡"],"answer":3,"answerLetter":"D","explain":"唯物辩证法中，发展不是简单的事物数量增加，A选项事物数量增加不一定是发展，比如单纯的人 口数量增加，不一定意味着社会发展。 事物的一切运动变化不一定是发展，B选项，像物体位置的机械移动 等简单变化不属于发展。 事物根本性质的变化可能是倒退，不一定是发展，C选项，比如生物的病变导致根 本性质变化，并非是发展。 发展的实质是新事物的产生和旧事物的灭亡，新事物符合客观规律、具有强大生 命力和远大前途，它代替旧事物是历史的必然，这体现了发展的前进上升趋势。"},{"id":"marx-2-57","globalId":136,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":57,"question":"理论联系实际是（ ）。","options":["马克思主义理论特征？","学习马克思主义的目的","马克思主义活的灵魂？","学习马克思主义的方法"],"answer":3,"answerLetter":"D","explain":"理论联系实际强调将马克思主义理论与实际相结合，它是学习马克思主义的重要方法，通过联系实 际能更好理解和运用马克思主义。A选项马克思主义理论特征是科学性与革命性等；B选项学习马克思主义目 的是为了改造世界等；C选项马克思主义活的灵魂是具体问题具体分析。"},{"id":"marx-2-58","globalId":137,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":58,"question":"社会形态最基本的划分法之一是（ ）。","options":["意识形态划分法","经济社会形态划分法","文化形态划分法","政治形态划分法"],"answer":1,"answerLetter":"B","explain":"社会形态最基本划分法有经济社会形态划分法和技术社会形态划分法。经济社会形态划分法侧重从 生产关系角度划分，对认识社会发展规律等很重要。而意识形态、文化、政治形态划分法并非社会形态最基 本划分法。"},{"id":"marx-2-59","globalId":138,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":59,"question":"私人垄断资本同资产阶级国家政权相结合形成（ ）。","options":["垄断资本主义","国家资本主义","国家垄断资本主义","金融资本主义"],"answer":2,"answerLetter":"C","explain":"私人垄断资本与资产阶级国家政权相结合，就产生了国家垄断资本主义 。垄断资本主义范围宽泛 ；国家资本主义是资本与国家政权结合但并非私人垄断资本与政权结合这种特定形式；金融资本主义强调金 融资本占主导，与题干表述不符。"},{"id":"marx-2-60","globalId":139,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":60,"question":"在物质和运动的关系问题上,唯心主义的错误在于（ ）。","options":["否认物质的绝对运动","夸大相对静止的存在","否认物质是运动的主体","主张没有运动的物质"],"answer":2,"answerLetter":"C","explain":"唯心主义在物质和运动关系上，往往脱离物质谈运动，认为是精神等非物质的东西在运动，即否认 物质是运动的主体。 A选项否认物质的绝对运动，更多是形而上学的观点，不是唯心主义在物质和运动关系 上的典型错误。 B选项夸大相对静止的存在也是形而上学的表现，并非唯心主义在物质和运动关系上的关键 错误。 D选项主张没有运动的物质是形而上学的观点，不符合唯心主义特点。"},{"id":"marx-2-61","globalId":140,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":61,"question":"阶级作为一种社会现象首先是一个（ ）。","options":["经济范畴","政治范畴","文化范畴","交往范畴"],"answer":0,"answerLetter":"A","explain":"阶级是根据人们在社会经济结构中所处地位不同而划分的，经济因素是划分阶级的基础，所以阶级 首先是一个经济范畴。"},{"id":"marx-2-62","globalId":141,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":62,"question":"理性认识的三种形式是（ ）。","options":["概念、判断、推理","感觉、知觉、表象","抽象、具体、再抽象","分析、归纳、综合"],"answer":0,"answerLetter":"A","explain":"理性认识是认识的高级阶段，其三种形式为概念、判断、推理 。B选项感觉、知觉、表象是感性认 识的形式。C、D选项并非理性认识的形式。"},{"id":"marx-2-63","globalId":142,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":63,"question":"社会意识具有复杂的结构，从其主体的角度看可分为（ ）。","options":["社会心理和思想体系","意识形态和非意识形态","个体意识和群体意识","先进意识和落后意识"],"answer":2,"answerLetter":"C","explain":"题目强调从主体角度对社会意识分类。A选项是从社会意识高低层次角度分；B选项是从是否反映经 济基础角度分；D选项并非标准分类方式。C选项个体意识和群体意识是从主体角度（个体与群体）划分的。"},{"id":"marx-2-64","globalId":143,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":64,"question":"私人垄断资本主义阶段,社会经济生活中的万能垄断者是（ ）。","options":["垄断的工业资本家","垄断的银行资本家","垄断的商业资本家","垄断的农业资本家"],"answer":1,"answerLetter":"B","explain":"在私人垄断资本主义阶段，银行由普通的中介人变成了万能的垄断者。银行资本与工业资本融合形 成金融资本，银行垄断资本地位上升。答案选B。"},{"id":"marx-2-65","globalId":144,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":65,"question":"在意识问题上，唯心主义的错误在于（ ）。","options":["忽视意识的主观特征","抹煞意识的主观特征","夸大意识的能动作用","否认意识的能动作用"],"answer":2,"answerLetter":"C","explain":"唯心主义在意识问题上，往往脱离物质基础，过分强调意识对物质的决定作用，也就是夸大了意识 的能动作用。"},{"id":"marx-2-66","globalId":145,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":66,"question":"揭示事物的发展状态和形式的规律是（ ）。","options":["对立统一规律","质量互变规律","否定之否定规律","本质决定现象规律"],"answer":1,"answerLetter":"B","explain":"质量互变规律揭示了事物发展的状态和形式，量变是事物数量的增减和场所的变更，体现了事物发 展的连续性；质变是事物根本性质的变化，是事物由一种质态向另一种质态的飞跃，体现了事物发展连续性 的中断。量变和质变相互转化、相互渗透，揭示了事物发展是连续性和阶段性的统一，也就是事物发展的状 态和形式。 对立统一规律揭示了事物发展的源泉和动力。 否定之否定规律揭示了事物发展的方向和道路。 “本质决定现象规律”不属于唯物辩证法的基本规律。"},{"id":"marx-2-67","globalId":146,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":67,"question":"利息的本质是（ ）。","options":["剩余价值的特殊转化形式","平均利润的特殊转化形式","使用借贷资本支付的报酬","使用产业资本支付的报酬"],"answer":0,"answerLetter":"A","explain":"利息是职能资本家使用借贷资本而让渡给借贷资本家的一部分剩余价值，其本质是剩余价值的特殊 转化形式。答案：A 。"},{"id":"marx-2-68","globalId":147,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":68,"question":"揭示事物发展趋势和道路的规律是（ ）。","options":["否定之否定规律","质量互变规律","对立统一规律","内容和形式相互作用规律"],"answer":0,"answerLetter":"A","explain":"否定之否定规律揭示了事物发展的方向和道路，它表明事物发展是前进性和曲折性的统一，呈现螺 旋式上升或波浪式前进的趋势。 质量互变规律揭示了事物发展变化的状态和形式。 对立统一规律揭示了事 物发展的源泉和动力。 内容和形式相互作用规律主要阐述内容与形式之间的辩证关系，并非揭示事物发展趋 势和道路。"},{"id":"marx-2-69","globalId":148,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":69,"question":"两条根本对立的认识路线是（ ）。","options":["可知论和不可知论","唯物主义反映论和唯心主义先验论","主观唯心主义认识和客观唯心主义认识论","能动革命的反映论和直观被动的反映论"],"answer":1,"answerLetter":"B","explain":"哲学上两条根本对立的认识路线，是围绕认识的本质问题展开，即认识是从物到感觉和思想，还是 从思想和感觉到物。唯物主义反映论坚持从物到感觉和思想，认为认识是主体对客体的反映；唯心主义先验 论坚持从思想和感觉到物，把认识看作是先于物质、先于实践经验的东西。所以两条根本对立的认识路线是 唯物主义反映论和唯心主义先验论。"},{"id":"marx-2-70","globalId":149,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":70,"question":"社会主义的分配原则是（ ）。","options":["按劳分配","按需分配","按生产要素分配","按资分配"],"answer":0,"answerLetter":"A","explain":"社会主义的分配原则是按劳分配，它是在生产资料社会主义公有制条件下，对社会总产品作各项必 要的社会扣除以后，按照个人提供给社会的劳动的数量和质量分配个人消费品。按需分配是共产主义社会高 级阶段的分配方式；按生产要素分配是市场经济条件下的一种分配方式；按资分配是资本主义的分配方式之 一。"},{"id":"marx-2-71","globalId":150,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":71,"question":"土地价格是（ ）。","options":["地价值的货币表现","级差地租的货币表现","利息的资本化","地租的资本化"],"answer":3,"answerLetter":"D","explain":"土地本身没有价值，土地价格是地租收入的资本化，即把地租看作是银行存款利息，按照一定的利 息率倒算出的资本量就是土地价格。"},{"id":"marx-2-72","globalId":151,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":72,"question":"在真理的检验标准问题上，下列各项中说法正确的是（ ）。","options":["多数人认可的就是真理","个人觉得有用的就是真理","少数人坚持的就是真理","在实践中证实的才是真理"],"answer":3,"answerLetter":"D","explain":"真理的检验标准是实践，实践是检验真理的唯一标准。A选项多数人认可不一定是真理，可能存在群 体认知错误；B选项个人觉得有用带有很强的主观性，不能作为真理标准；C选项少数人坚持也不一定是真理 。只有D选项符合实践是检验真理唯一标准这一正确观点。"},{"id":"marx-2-73","globalId":152,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":73,"question":"两种商品相互交换的量的关系或比例就是商品的","options":["价值","价格","使用价值","交换价值"],"answer":3,"answerLetter":"D","explain":"交换价值首先表现为一种使用价值同另一种使用价值相交换的量的关系或比例 。价值是凝结在商品 中的无差别的人类劳动，它决定交换价值。价格是价值的货币表现。使用价值是商品能满足人们某种需要的 属性。题干描述的是交换价值的概念。"},{"id":"marx-2-74","globalId":153,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":74,"question":"社会主义的根本任务是（ ）。","options":["解放和发展生产力","巩固无产阶级专政","坚持和改善党的领导","发展社会主义民主法制"],"answer":0,"answerLetter":"A","explain":"社会主义的根本任务是解放和发展生产力。这是基于生产力在社会发展中的决定性作用，以及社会 主义本质要求等多方面得出的。只有不断解放和发展生产力，才能解决社会主义初级阶段的主要矛盾，实现 社会主义的目标。其他选项巩固无产阶级专政、坚持和改善党的领导、发展社会主义民主法制虽然对社会主 义建设很重要，但不是根本任务。"},{"id":"marx-2-75","globalId":154,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":75,"question":"为获取高额垄断利润，垄断组织在采购原材料时大多采取（ ）。","options":["垄断高价","垄断低价","浮动价格","固定价格"],"answer":1,"answerLetter":"B","explain":"垄断组织为获取高额垄断利润，在销售商品时会采用垄断高价，而在采购原材料等生产要素时则会 采取垄断低价，以降低成本，增加利润。"},{"id":"marx-2-76","globalId":155,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":76,"question":"在真理问题上坚持辩证法，就是要承认任何真理都是（ ）。","options":["客观性和主观性的统一","主观性和相对性的统一","客观性和绝对性的统一","绝对性和相对性的统一"],"answer":3,"answerLetter":"D","explain":"真理具有客观性，这是真理的本质属性。同时真理又具有绝对性和相对性，是绝对性和相对性的统 一。承认真理是绝对性和相对性的统一，体现了在真理问题上坚持辩证法。因为只强调绝对性，会走向僵化 ；只强调相对性，会走向相对主义，所以要辩证看待。"},{"id":"marx-2-77","globalId":156,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":77,"question":"社会主义革命可以在一国或数国首先胜利理论的提出者是（ ）。","options":["马克思","列宁","斯大林","毛泽东"],"answer":1,"answerLetter":"B","explain":"列宁基于对帝国主义阶段资本主义经济政治发展不平衡规律的深刻认识，提出社会主义革命可以在 一国或数国首先胜利的理论。马克思和恩格斯所处时代认为社会主义革命将在几个主要资本主义国家同时发 生。斯大林和毛泽东主要是在列宁之后推动社会主义实践等发展。"},{"id":"marx-2-78","globalId":157,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":78,"question":"唯物辩证法的总特征是（ ）。","options":["联系和发展的观点","量变和质变的观点","对立统一的观点","辩证否定的观点"],"answer":0,"answerLetter":"A","explain":"唯物辩证法认为世界是普遍联系和永恒发展的，联系和发展的观点是贯穿唯物辩证法其他规律和范 畴的主线，是唯物辩证法的总特征。B选项量变和质变是揭示事物发展状态和形式的规律；C选项对立统一规 律是唯物辩证法的实质和核心；D选项辩证否定观是事物自身的否定，是联系和发展的环节。答案：A 。"},{"id":"marx-2-79","globalId":158,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":79,"question":"在资本主义社会，决定劳动力价值的因素中一般不包括（ ）。","options":["生存资料的价值","生产资料的价值","延续和养育后代所需的费用","必要的教育培训费用"],"answer":1,"answerLetter":"B","explain":"劳动力价值包括维持劳动者自身生存所必需的生活资料价值（对应A项）、劳动者繁育后代所必需的 生活资料价值（对应C项）、劳动者接受教育和训练所支出的费用（对应D项）。生产资料价值主要与商品生 产等相关，并非决定劳动力价值的因素。"},{"id":"marx-2-80","globalId":159,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":80,"question":"近几十年来垄断组织国际化的最主要形式是（ ）。","options":["国际卡特尔","国际辛迪加","国际康采恩","跨国公司"],"answer":3,"answerLetter":"D","explain":"在垄断组织国际化形式中，跨国公司凭借其在全球生产、销售、研发等方面的布局与掌控力，成为 近几十年来垄断组织国际化最主要形式。国际卡特尔、国际辛迪加主要是早期的国际垄断同盟形式，国际康 采恩相对也不如跨国公司在当代垄断组织国际化中占据主导。"},{"id":"marx-2-81","globalId":160,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":81,"question":"列宁的物质定义表明，客观实在性是（ ）。","options":["生命物质的共性","自然物质的共性","有形物质的共性","一切物质的共性"],"answer":3,"answerLetter":"D","explain":"列宁的物质定义指出物质是标志客观实在的哲学范畴，这种客观实在是人通过感觉感知的，它不依 赖于我们的感觉而存在，为我们的感觉所复写、摄影、反映。这表明客观实在性是一切物质的共性，不局限 于生命物质、自然物质或有形物质。"},{"id":"marx-2-82","globalId":161,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":82,"question":"社会主义革命胜利以后,首先要经过（ ）。","options":["从资本主义向社会主义过渡的阶段","社会主义初级阶段","共产主义第一阶段","战时共产主义阶段"],"answer":0,"answerLetter":"A","explain":"社会主义革命胜利后，一般会经历从资本主义向社会主义过渡的阶段，对生产资料私有制进行改造 等，为社会主义制度的全面建立奠定基础。社会主义初级阶段是我国在生产力落后、商品经济不发达条件下 建设社会主义必然要经历的特定阶段，并非所有社会主义革命胜利后都直接进入此阶段；共产主义第一阶段 即社会主义阶段，但题干问的是首先经历的阶段；战时共产主义是苏俄在特定战争时期的政策，不具有普遍 适用性。"},{"id":"marx-2-83","globalId":162,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":83,"question":"近朱者赤，近墨者黑。这句话强调的是（ ）。","options":["内因是事物发展变化的根据","外部条件对事物发展变化有重要影响","外因通过内因而起作用","外因和内因共同推动事物发展"],"answer":1,"answerLetter":"B","explain":"“近朱者赤，近墨者黑”意思是靠着朱砂的变红，靠着墨的变黑，强调的是周围环境（外部条件 ）对人的影响。所以这句话强调的是外部条件对事物发展变化有重要影响，答案选B。"},{"id":"marx-2-84","globalId":163,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":84,"question":"列宁对于无产阶级革命的重大理论贡献是（ ）。","options":["提出了战时共产主义政策","提出了新经济政策","提出了利用资本主义发展社会主义的理论","提出了社会主义革命将首先在一国或数国胜利的理论"],"answer":3,"answerLetter":"D","explain":"列宁突破了马克思主义关于无产阶级革命将在几个主要资本主义国家同时发生的设想，提出了社会 主义革命将首先在一国或数国胜利的理论，这是对无产阶级革命的重大理论贡献。A选项战时共产主义政策、 B选项新经济政策、C选项利用资本主义发展社会主义理论主要是关于社会主义建设方面。"},{"id":"marx-2-85","globalId":164,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":85,"question":"生产关系范畴反映的是人与人之间的（ ）。","options":["经济关系","政治关系","思想关系","血缘关系"],"answer":0,"answerLetter":"A","explain":"生产关系是人们在物质资料的生产过程中形成的社会关系，它是生产方式的社会形式，本质上是人 与人之间的经济关系。"},{"id":"marx-2-86","globalId":165,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":86,"question":"真理具有客观性，被称为客观真理，是因为（ ）。","options":["真理是事物发展的客观规律","真理是对事物及其规律的正确反映","真理是不依赖于意识的客观实在","真理是大多数人承认的客观事实"],"answer":1,"answerLetter":"B","explain":"真理的客观性在于它是对客观事物及其规律的正确反映。真理反映的内容是客观的，不以人的意志 为转移。 A选项，真理不是客观规律本身，而是对规律的正确反映。 C选项，不依赖于意识的客观实在是物 质，不是真理。 D选项，真理不是由多数人承认决定的，即使少数人掌握，只要是对事物及其规律的正确反 映，也是真理。"},{"id":"marx-2-87","globalId":166,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":87,"question":"垄断利润的获得，主要是通过（ ）。","options":["自由竞争实现的","市场调节实现的","垄断价格实现的","行政干预实现的"],"answer":2,"answerLetter":"C","explain":"垄断利润主要是通过垄断价格来实现的，垄断价格包括垄断高价和垄断低价。垄断企业凭借其垄断 地位规定垄断价格，从而获得大大超过平均利润的高额利润。自由竞争时期不存在垄断利润，市场调节和行 政干预并非垄断利润获取的主要方式。"},{"id":"marx-2-88","globalId":167,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":88,"question":"下列不属于19世纪初欧洲空想社会主义者的是（ ）。","options":["傅里叶","圣西门","康德","欧文"],"answer":2,"answerLetter":"C","explain":"19世纪初欧洲空想社会主义者主要代表是圣西门、傅里叶和欧文 。康德是德国古典哲学的创始人 ，不属于空想社会主义者。答案选C。"},{"id":"marx-2-89","globalId":168,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":89,"question":"正确发挥意识能动作用的前提是（ ）。","options":["个人积极性的充分调动","集体智慧的充分发挥","对保守思想的彻底克服","对客观规律的正确反映"],"answer":3,"answerLetter":"D","explain":"意识能动作用的发挥受客观规律的制约，只有正确认识和遵循客观规律，才能正确发挥意识能动作 用。选项A个人积极性、B集体智慧、C克服保守思想都不是发挥意识能动作用的前提。前提是对客观规律的正 确反映。"},{"id":"marx-2-90","globalId":169,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":90,"question":"可知论与不可知论的对立在于是否承认（ ）。","options":["人的认识是先于经验而获得的","思维能够正确地认识现实世界","人的认识是从外部世界得来的","思维能够能动地认识现实世界"],"answer":1,"answerLetter":"B","explain":"可知论认为思维能够正确认识现实世界，不可知论则认为思维不能正确认识现实世界，二者对立的 关键就在于对思维能否正确认识现实世界的不同看法。"},{"id":"marx-2-91","globalId":170,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":91,"question":"马克思主义产生于（ ）。","options":["19世纪20年代","19世纪40年代","19世纪60年代","19世纪80年代"],"answer":1,"answerLetter":"B","explain":"19世纪40年代，资本主义矛盾尖锐，工人运动兴起，马克思和恩格斯批判继承前人理论成果，创立 马克思主义。答案选B。"},{"id":"marx-2-92","globalId":171,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":92,"question":"剩余价值率和利润率的关系是（ ）。","options":["剩余价值率等于利润率","剩余价值率大于利润率","剩余价值率小于利润率","剩余价值率与利润率成反比"],"answer":1,"answerLetter":"B","explain":"剩余价值率是剩余价值与可变资本的比率，即 ；利润率是剩余价值与全部预付资本的比率，即 。因为全部预付资本（c + v）大于可变资本（v），在分子（剩余价值m）相同的情况下，分母越大，比值越 小。所以剩余价值率大于利润率。"},{"id":"marx-2-93","globalId":172,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":93,"question":"客观实在性是（ ）。","options":["自然物质的个性","一切物质的共性","物质的具体形态","物质的存在形式"],"answer":1,"answerLetter":"B","explain":"客观实在性是物质的唯一特性，它概括了宇宙间一切客观存在着的事物和现象的共同本质，是一切 物质的共性。自然物质只是物质的一部分，不能代表一切，A 错误；物质具体形态多样，客观实在性不是指 具体形态，C 错误；物质存在形式是运动等，不是客观实在性，D 错误。"},{"id":"marx-2-94","globalId":173,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":94,"question":"马克思主义的创始人是（ ）。","options":["马克思和李嘉图","马克思和圣西门","马克思和费尔巴哈","马克思和恩格斯"],"answer":3,"answerLetter":"D","explain":"马克思主义是由马克思和恩格斯共同创立的学说体系。李嘉图是英国古典政治经济学代表人物；圣 西门是空想社会主义者；费尔巴哈是旧唯物主义哲学家，他们都不是马克思主义创始人。"},{"id":"marx-2-95","globalId":174,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":95,"question":"剩余价值与利润从数量上看（ ）。","options":["前者大于后者","前者小于后者","两者相等","两者的大小无法判断"],"answer":2,"answerLetter":"C","explain":"利润本质上就是剩余价值，是剩余价值的转化形式。当剩余价值被看作是全部预付资本的产物时 ，就转化为利润。所以剩余价值与利润在数量上是相等的。"},{"id":"marx-2-96","globalId":175,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":96,"question":"下列不属于生产时间的是（ ）。","options":["生产资料采购时间","原材料储备时间","停工时间","自然力作用于产品的时间"],"answer":0,"answerLetter":"A","explain":"生产时间包括劳动时间、自然力独立作用于劳动对象的时间、生产资料储备时间以及正常的停工时 间。而生产资料采购时间属于流通时间，并非生产时间范畴。"},{"id":"marx-2-97","globalId":176,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":97,"question":"支付工资的货币执行的是货币的（ ）。","options":["价值尺度职能","流通手段职能","支付手段职能","贮藏手段职能"],"answer":2,"answerLetter":"C","explain":"支付工资时，货币并非用于衡量商品价值（不是价值尺度），也不是一手交钱一手交货的即时交易 （不是流通手段），更不是把货币当作财富储存起来（不是贮藏手段），而是用于清偿债务、支付赋税、租 金、工资等，这体现的是货币的支付手段职能。"},{"id":"marx-2-98","globalId":177,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":98,"question":"垄断利润的水平一般会","options":["低于平均利润","高于平均利润","等于平均利润","等于成本价格"],"answer":1,"answerLetter":"B","explain":"垄断企业凭借其垄断地位，通过限制产量、提高价格等手段获取高额利润。与自由竞争时期各企业 只能获得平均利润不同，垄断企业能长期获得大大超过平均利润的高额利润。"},{"id":"marx-2-99","globalId":178,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":99,"question":"下列各项包含矛盾双方相互依存相互转化的辩证法思想的是（ ）。","options":["千里之行，始于足下","千里之堤，溃于蚁穴","月晕而风，础润而雨","物极必反，相反相成"],"answer":3,"answerLetter":"D","explain":"A选项“千里之行，始于足下”强调量变是质变的必要准备，体现量变与质变关系。 B选项“千里 之堤，溃于蚁穴”说明量变积累到一定程度会引发质变，是量变与质变原理。 C选项“月晕而风，础润而雨 ”是对自然现象联系的一种描述，体现联系的观点。 D选项“物极必反”表明事物发展到极端会向相反方向 转化，“相反相成”说明矛盾双方既对立又统一，相互依存、相互转化，符合题意。"},{"id":"marx-2-100","globalId":179,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":100,"question":"只要再多走一小步,真理便会变成谬误,这句话说的是（ ）。","options":["真理和谬误相互依存","真理和谬误相互包含","真理和谬误相互排斥","真理和谬误在一定条件下可以相互转化"],"answer":3,"answerLetter":"D","explain":"“再多走一小步，真理便会变成谬误”强调了在特定条件变化（多走一小步这个条件改变）时，真 理就向谬误转变，体现的是真理和谬误在一定条件下的相互转化。"},{"id":"marx-2-101","globalId":180,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":101,"question":"垄断利润就其本质而言，来源于（ ）。","options":["劳动者创造的剩余价值","垄断组织的垄断地位","垄断组织的海外掠夺","垄断组织的垄断资本的实力"],"answer":0,"answerLetter":"A","explain":"垄断利润的来源归根结底是工人阶级和其他劳动人民创造的剩余价值，以及其他劳动者创造的一部 分价值。垄断地位、海外掠夺、垄断资本实力只是获取垄断利润的条件或途径，并非本质来源。"},{"id":"marx-2-102","globalId":181,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":102,"question":"马克思主义认识论认为,认识的本质是（ ）。","options":["主体对客体的直观反映","主体对客体的自由创造","主体对客体的能动反映","主体对客体的简单摹写"],"answer":2,"answerLetter":"C","explain":"马克思主义认识论强调认识是主体在实践基础上对客体的能动反映。A选项直观反映忽略了能动作用 ；B选项自由创造说法不准确，认识基于实践和对客体的反映并非随意创造；D选项简单摹写也没有体现出能 动性。"},{"id":"marx-2-103","globalId":182,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":103,"question":"实行垄断价格的根本目的是为了（ ）。","options":["最大限度占领市场","最大限度降低成本","获取高额垄断利润","获取行业控制权力"],"answer":2,"answerLetter":"C","explain":"垄断企业通过垄断价格，在高价出售产品和低价购买生产资料过程中，使价值和剩余价值实现有利 于垄断资本的再分配，其根本目的就是获取高额垄断利润。"},{"id":"marx-2-104","globalId":183,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":104,"question":"下列各项属于感性认识基本形式的是（ ）。","options":["感觉","概念","判断","推理"],"answer":0,"answerLetter":"A","explain":"感性认识是认识的初级阶段，包括感觉、知觉和表象三种形式。而概念、判断、推理是理性认识的 三种形式。"},{"id":"marx-3-3","globalId":184,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":3,"question":"质量互变规律揭示了（ ）。","options":["事物发展的原因和结果","事物发展的状态和过程","事物发展的趋势和道路","事物发展的源泉和动力"],"answer":1,"answerLetter":"B","explain":"质量互变规律主要阐述事物发展是量变与质变的统一，量变和质变是事物发展变化存在的两种基本 状态，揭示事物发展的状态和形式。"},{"id":"marx-3-2","globalId":185,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":2,"question":"垄断资本家在售卖商品时，一般都会采用（ ）。","options":["垄断高价","垄断低价","市场价格","计划价"],"answer":0,"answerLetter":"A","explain":"垄断资本家为获取高额垄断利润，在售卖商品时往往会凭借其垄断地位，把价格定得远远高于商品 价值，即采用垄断高价。"},{"id":"marx-3-3","globalId":186,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":3,"question":"马克思主义认为，阶级消灭和国家消亡是在（ ）。","options":["社会主义革命中实现的","社会主义初级阶段实现的","社会主义高级阶段实现的","共产主义社会实现的"],"answer":3,"answerLetter":"D","explain":"马克思主义认为，共产主义社会是人类社会发展的最高形态，到那时物质财富极大丰富，人们精神 境界极大提高，实现按需分配，阶级对立和国家存在的经济基础消失，阶级消灭和国家消亡。所以阶级消灭 和国家消亡在共产主义社会实现。"},{"id":"marx-3-4","globalId":187,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":4,"question":"实践作为一种感性物质活动，强调的是（ ）。","options":["实践具有客观物质性","实践具有主观性","实践具有能动性","实践具有历史性"],"answer":0,"answerLetter":"A","explain":"感性物质活动意味着实践是由现实的客观物质要素构成，受客观物质条件的制约，体现了实践具有 客观物质性。"},{"id":"marx-3-5","globalId":188,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":5,"question":"下列各项属于社会基本矛盾的是（ ）。","options":["生产力和生产关系的矛盾","社会存在和社会意识的矛盾","人口增长和资源匮乏的矛盾","发展经济和保护环境的矛盾"],"answer":0,"answerLetter":"A","explain":"社会基本矛盾是指贯穿社会发展过程始终，规定社会发展过程的基本性质和基本趋势，并对社会历 史发展起根本的推动作用的矛盾，生产力和生产关系、经济基础和上层建筑的矛盾是社会基本矛盾，A选项符 合。社会存在和社会意识是历史观基本问题涉及范畴，并非基本矛盾；C、D选项属于具体社会问题引发的矛 盾，并非社会基本矛盾。"},{"id":"marx-3-6","globalId":189,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":6,"question":"主张意识第一性、物质第二性的是（ ）。","options":["辩证法观点","形而上学观点","唯物主义观点","唯心主义观点"],"answer":3,"answerLetter":"D","explain":"哲学的基本派别中，唯心主义认为意识第一性、物质第二性，物质依赖意识而存在。唯物主义则主 张物质第一性、意识第二性。辩证法和形而上学是关于世界状态的不同观点，与物质和意识谁为第一性无关 。答案：D。"},{"id":"marx-3-7","globalId":190,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":7,"question":"垄断资本主义发展的两个阶段是（ ）。","options":["私人垄断资本主义与一般垄断资木主义","私人垄断资本主义与国家垄断资本主义","私人垄断资本主义与国际垄断资本主义","国家垄断资本主义与国际垄断资本主义"],"answer":1,"answerLetter":"B","explain":"垄断资本主义发展经历了私人垄断资本主义和国家垄断资本主义两个阶段。私人垄断资本主义是在 生产集中和资本集中基础上形成的，随着矛盾发展，国家政权与垄断资本相结合形成国家垄断资本主义。答 案是B。"},{"id":"marx-3-8","globalId":191,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":8,"question":"马克思主义认为，决定人的本质的是（ ）。","options":["人的心理素质","人的文化素质","人的社会属性","人的自然属性"],"answer":2,"answerLetter":"C","explain":"马克思主义强调人是社会关系的总和，人的本质不是单个人所固有的抽象物，在其现实性上，它是 一切社会关系的总和，这突出了人的社会属性对决定人本质的关键作用。自然属性是人和动物共有的，心理 素质和文化素质是在社会生活中形成，都不能决定人的本质。"},{"id":"marx-3-9","globalId":192,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":9,"question":"垄断资本主义国家的金融资本是指（ ）。","options":["资本主义国家中处于垄断地位的银行资本","资本主义国家金融领域中流通的所有资本的总和","资本主义国家银行和非银行金融机构资本的总和","垄断的工业资本和银行资本融合形成的资本"],"answer":3,"answerLetter":"D","explain":"金融资本是垄断资本主义阶段居统治地位的资本形式，它是由垄断的工业资本和银行资本，通过金 融联系、资本参与和人事参与，融合或混合生长构成的一种新的资本形式。"},{"id":"marx-3-10","globalId":193,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":10,"question":"马克思主义认为,垄断资本主义发展的历史趋势是（ ）。","options":["生产资料公有制代替生产资料私有制","生产资料私有制代替生产资料公有制","全世界实行垄断资本主义","全世界实行自由竞争资本主义"],"answer":0,"answerLetter":"A","explain":"马克思主义基于对社会发展规律以及资本主义基本矛盾的分析，认为资本主义向社会主义过渡具有 历史必然性。社会主义以生产资料公有制为基础，所以垄断资本主义发展的历史趋势是生产资料公有制代替 生产资料私有制。"},{"id":"marx-3-11","globalId":194,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":11,"question":"实现意识对物质反作用的根本途径是（ ）。","options":["学习书本知识","进行社会调查","参加社会实践","研究实际情况"],"answer":2,"answerLetter":"C","explain":"意识对物质反作用要通过实践才能实现，实践是连接主观与客观的桥梁，只有参加社会实践，才能 将意识转化为改变物质世界的现实力量。而学习书本知识、进行社会调查、研究实际情况都只是实践的部分 环节或准备，不是根本途径。"},{"id":"marx-3-12","globalId":195,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":12,"question":"下列各项正确表述商品含义的是（ ）。","options":["具有使用价值的物品","具有稀缺性的物品","为自己而生产的有用物品","为交换而生产的有用物品"],"answer":3,"answerLetter":"D","explain":"商品是用于交换的劳动产品，首先要是有用的物品（具有使用价值），且是为交换而生产。A选项仅 强调使用价值，没突出交换；B选项稀缺性不是商品定义关键；C选项为自己生产不用于交换，不是商品。D选 项准确表述了商品为交换而生产且有用。"},{"id":"marx-3-13","globalId":196,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":13,"question":"唯物史观和唯心史观在历史创造者问题上的根本对立在于是否承认（ ）。","options":["个人在历史发展中的作用","思想动机在社会发展中的作用","人民群众是推动历史发展的决定力量","剥削阶级代表人物在历史发展中的作用"],"answer":2,"answerLetter":"C","explain":"唯物史观认为人民群众是历史的创造者，是推动历史发展的决定力量；唯心史观则认为少数英雄人 物是历史创造者。二者在历史创造者问题上的根本对立就在于是否承认人民群众是推动历史发展的决定力量 。"},{"id":"marx-3-14","globalId":197,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":14,"question":"下列各项正确说明感性认识和理性认识联系的是（ ）。","options":["理性认识依赖于感性认识？","感性认识可以自动上升到理性认识","感性认识依赖于理性认识？","理性认识可以自动回归到感性认识"],"answer":0,"answerLetter":"A","explain":"感性认识是认识的初级阶段，是对事物表面现象的认识；理性认识是认识的高级阶段，是对事物本 质和规律的认识。 理性认识依赖于感性认识，因为感性认识是理性认识的基础，没有感性认识提供的原材料 ，理性认识就成了无源之水、无本之木，A选项正确。 感性认识要上升到理性认识，需要通过科学的思维方 法，如分析与综合、归纳与演绎等，不是自动上升的，B选项错误。 是理性认识依赖感性认识，而不是感性 认识依赖理性认识，C选项错误。 理性认识回到实践中去指导实践，而不是自动回归到感性认识，D选项错误 。"},{"id":"marx-3-15","globalId":198,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":15,"question":"资本各形态中能划分为固定资本和流动资本的是（ ）。","options":["生产资本","货币资本","商品资本","借贷资本"],"answer":0,"answerLetter":"A","explain":"只有生产资本能依据价值周转方式不同划分为固定资本和流动资本，货币资本、商品资本属于产业 资本循环的职能形式，借贷资本是生息资本的一种形式，它们都不能做此划分。答案：A。"},{"id":"marx-3-16","globalId":199,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":16,"question":"垄断资本主义阶段占统治地位的资本是（ ）。","options":["工业资本","银行资本","金融资本","商业资本"],"answer":2,"answerLetter":"C","explain":"在垄断资本主义阶段，工业垄断资本和银行垄断资本融合形成金融资本，金融资本在经济、政治等 各方面占据统治地位。答案选C。"},{"id":"marx-3-17","globalId":200,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":17,"question":"垄断资本主义社会大体可分为（ ）。","options":["一般垄断资本主义和私人垄断资本主义两个阶段","私人垄断资本主义和国家垄断资本主义两个阶段","一般垄断资本主义、私人垄断资本主义和国家垄断资本主义三个阶段","私人垄断资本主义、国家垄断资本主义和国际垄断资本主义三个阶段"],"answer":1,"answerLetter":"B","explain":"垄断资本主义发展经历了私人垄断资本主义和国家垄断资本主义两个阶段 。在这一发展过程中，先 是私人垄断资本占据主导，后来随着资本主义矛盾加剧，国家政权与垄断资本结合，形成国家垄断资本主义 。"},{"id":"marx-3-18","globalId":201,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":18,"question":"资本输出的两种基本形式是（ ）。","options":["借贷资本和生产资本输出","借贷资本和商品资本输出","生产资本和商品资本输出","货币资本和生产资本输出"],"answer":0,"answerLetter":"A","explain":"资本输出的基本形式有借贷资本输出和生产资本输出。商品资本输出不属于资本输出基本形式，货 币资本是产业资本循环中的一种职能形式，并非资本输出基本形式。"},{"id":"marx-3-19","globalId":202,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":19,"question":"垄断组织获取垄断利润的主要形式是（ ）。","options":["垄断价格","个人联合","参与制","资本输出"],"answer":0,"answerLetter":"A","explain":"垄断组织获取垄断利润主要通过垄断价格，垄断价格包括垄断高价和垄断低价。个人联合是金融寡 头在政治上统治的手段；参与制是金融寡头在经济上统治的方式；资本输出是垄断资本主义经济扩张的重要 手段。"},{"id":"marx-3-20","globalId":203,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":20,"question":"社会总产品从实物形态上按其最终用途可以划分为（ ）。","options":["劳动资料和劳动对象","劳动工具和劳动对象","劳动工具和消费资料","生产资料和消费资料"],"answer":3,"answerLetter":"D","explain":"社会总产品从实物形态按最终用途划分，主要就是用于生产继续进行的生产资料和满足人们生活消 费的消费资料。A选项劳动资料和劳动对象是生产资料的构成部分，并非按最终用途的划分；B选项劳动工具 属于劳动资料，和劳动对象一样，都不是按最终用途对社会总产品的划分；C选项劳动工具属于生产资料范畴 ，划分不完整。答案：D。"},{"id":"marx-3-21","globalId":204,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":21,"question":"社会总产品是社会各个物质生产部门在一定时期（通常是一年）内生产的（ ）。","options":["全部剩余价值的总和","全部生产资料的总和","全部物质资料的总和","全部消费资料的总和"],"answer":2,"answerLetter":"C","explain":"社会总产品指社会各物质生产部门在一定时期（通常为一年）内所生产的全部物质资料的总和。A选 项剩余价值只是产品价值一部分；B选项生产资料只是物质资料一部分；D选项消费资料也只是物质资料一部 分。"},{"id":"marx-3-22","globalId":205,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":22,"question":"我国坚持独立自主、自力更生和对外开放方针的理论基础是（ ）。","options":["量变和质变辩证关系的原理","内容和形式辩证关系的原理","肯定和否定辩证关系的原理","内因和外因辩证关系的原理"],"answer":3,"answerLetter":"D","explain":"独立自主、自力更生强调的是自身内部的力量，这是事物发展的内因。 对外开放是借助外部的有 利条件，属于事物发展的外因。 我国坚持这一方针，正是基于内因是事物发展的根据，外因是事物发展的条 件，外因通过内因起作用的内因和外因辩证关系原理。"},{"id":"marx-3-23","globalId":206,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":23,"question":"英国古典经济学的代表人物是（ ）。","options":["培根和洛克","黑格尔和费尔巴哈","斯密和李嘉图","圣西门和傅立叶"],"answer":2,"answerLetter":"C","explain":"A选项中培根和洛克是英国的哲学家等，并非古典经济学代表人物。 B选项黑格尔和费尔巴哈是德 国古典哲学的代表人物。 C选项，亚当·斯密和大卫·李嘉图是英国古典经济学的杰出代表，他们对古典经 济学理论体系的建立和发展作出重要贡献。 D选项圣西门和傅立叶是空想社会主义的代表人物。"},{"id":"marx-3-24","globalId":207,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":24,"question":"资本有机构成可以表示为（ ）。","options":["生产资本与流通资本的比率","产业资本与商业资本的比率","不变资本与可变资本的比率","固定资本与流动资本的比率"],"answer":2,"answerLetter":"C","explain":"资本有机构成是由资本技术构成决定并反映技术构成变化的资本价值构成，通常用不变资本与可变 资本的比率（c:v）来表示。所以答案是C。"},{"id":"marx-3-25","globalId":208,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":25,"question":"马克思所说未来社会的第一阶段是指（ ）。","options":["社会主义革命时期","向社会主义过渡时期","社会主义初级阶段","社会主义社会"],"answer":3,"answerLetter":"D","explain":"马克思所说未来社会的第一阶段指的是社会主义社会。马克思设想未来社会有两个阶段，第一阶段 是社会主义社会，高级阶段是共产主义社会。A选项社会主义革命时期主要是进行推翻旧制度建立新政权的阶 段；B选项向社会主义过渡时期是从资本主义向社会主义转变的阶段；C选项社会主义初级阶段是我国在生产 力落后、商品经济不发达条件下建设社会主义必然要经历的特定阶段，它不等同于马克思所说未来社会第一 阶段的宽泛概念。"},{"id":"marx-3-26","globalId":209,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":26,"question":"生产不再下降,失业不再增加,企业倒闭停止。这种状态属于本主义再生产周期中的（ ）。","options":["危机阶段","萧条阶段","复苏阶段","高涨阶段"],"answer":1,"answerLetter":"B","explain":"危机阶段的特点是生产猛烈下降，失业急剧增加，企业大量倒闭等，所以A选项不符合。 萧条阶段 的特征是生产不再下降，失业不再增加，企业倒闭停止，但整个经济生活还未全面恢复，题干描述符合萧条 阶段的特点。 复苏阶段生产逐渐回升，就业日益增多等，与题干单纯不再下降、增加等表述不符，C选项排 除。 高涨阶段生产迅速扩张，市场繁荣等，和题干描述不匹配，D选项排除。"},{"id":"marx-3-27","globalId":210,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":27,"question":"资本主义不同生产部门之间的竞争会导致（ ）。","options":["社会必要劳动时间的变化","平均利润的形成","资本主义生产关系本质的变化","全社会的利润总量小于剩余价值总量"],"answer":1,"answerLetter":"B","explain":"不同生产部门之间竞争的手段是资本转移，即把资本从利润率低的部门转移到利润率高的部门，这 种竞争会导致各部门利润率趋于平均化，从而形成平均利润。"},{"id":"marx-3-28","globalId":211,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":28,"question":"人类社会的基本矛盾是（ ）。","options":["人与自然、个人与社会之间的矛盾","先进与落后、创新与守旧之间的矛盾","生产力与生产关系、经济基础与上层建筑之间的矛盾","社会存在与社会意识、物质文明和精神文明之间的矛盾"],"answer":2,"answerLetter":"C","explain":"生产力与生产关系、经济基础与上层建筑之间的矛盾是贯穿人类社会始终的基本矛盾。这两对矛盾 运动推动着人类社会的发展变化。"},{"id":"marx-3-29","globalId":212,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":29,"question":"生产方式是（ ）。","options":["地理环境和人口因素的统一","社会存在和社会意识的统一","经济基础和上层建筑的统一","生产力和生产关系的统一"],"answer":3,"answerLetter":"D","explain":"生产方式是人类借以向自然界谋取必需的生活资料的方式，它包括生产力和生产关系两个方面，是 特定的生产力和生产关系的统一。A选项地理环境和人口因素是社会存在的内容；B选项社会存在与社会意识 相对；C选项经济基础和上层建筑的统一构成社会形态。"},{"id":"marx-3-30","globalId":213,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":30,"question":"我们实现人生价值的最终归宿是（ ）。","options":["社会主义共同理想","共产主义远大理想","天下大同的社会理想","克己奉公的道德理想"],"answer":1,"answerLetter":"B","explain":"共产主义远大理想体现了对全人类解放和每个人自由全面发展的追求，代表了人类最美好的未来 ，是实现人生价值的最终归宿。其他选项，社会主义共同理想是阶段性理想；“天下大同”并非马克思主义 语境下科学表述；克己奉公道德理想主要侧重于道德层面，不能作为实现人生价值最终归宿。"},{"id":"marx-3-31","globalId":214,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":31,"question":"资本主义国家调控经济的主要手段是（ ）。","options":["经济手段和经济计划","经济手段和法律手段","行政手段和经济计划","法律手段和经济计划"],"answer":1,"answerLetter":"B","explain":"资本主义国家对经济的调控手段，主要是经济手段和法律手段，辅之以计划指导和必要的行政手段 。经济手段通过调节经济变量影响市场主体行为；法律手段为经济运行提供规范和保障。"},{"id":"marx-3-32","globalId":215,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":32,"question":"无产阶级政党的组织原则是（ ）。","options":["集体领导制","首长负责制","集体问责制","民主集中制"],"answer":3,"answerLetter":"D","explain":"无产阶级政党的组织原则是民主集中制，它既能充分发扬党内民主，又能实行正确的集中，保证党 意志统一和行动一致。"},{"id":"marx-3-33","globalId":216,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":33,"question":"资本主义国家向某个濒临破产的私人企业注入一定量的国有资本，使之能继续生存下去，此时这个企业的 性质属于","options":["资本主义国有经济","资本主义私有经济","资本主义国有资本和私人资本在企业内部的结合","资本主义国有资本和私人资本在企业外部的结合"],"answer":2,"answerLetter":"C","explain":"国家向濒临破产私人企业注入国有资本，意味着企业内既有国有资本又有私人资本，属于国有资本 和私人资本在企业内部结合。"},{"id":"marx-3-34","globalId":217,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":34,"question":"资本主义商业利润的本质与真正来源是（ ）。","options":["商品在流通过程中的加价","商业店员创造的剩余价值","产业工人创造的一部分剩余价值","商业店员实现的剩余价值"],"answer":2,"answerLetter":"C","explain":"商业利润是产业资本家让渡给商业资本家的一部分剩余价值，这部分剩余价值是产业工人在生产过 程中创造的。商业店员从事单纯商品买卖活动不创造价值和剩余价值，但能实现商品价值和剩余价值。所以 商业利润本质和真正来源是产业工人创造的一部分剩余价值。"},{"id":"marx-3-35","globalId":218,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":35,"question":"社会主义建设的领导核心是（ ）。","options":["工人阶级","工人阶级和全体劳动人民","马克思主义政党","社会主义国家的政府"],"answer":2,"answerLetter":"C","explain":"马克思主义政党是社会主义建设的领导核心，因为党能够把握社会发展规律，制定正确的路线方针 政策，凝聚人民力量等。而工人阶级是领导阶级，全体劳动人民是依靠力量，社会主义国家政府是执行具体 事务的机构，它们都不能等同于领导核心。"},{"id":"marx-3-36","globalId":219,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":36,"question":"下列活动中属于最基本的实践形式的是（ ）。","options":["物质生产活动","处理社会关系活动","科学实验活动","艺术表演活动"],"answer":0,"answerLetter":"A","explain":"实践的基本形式有物质生产实践、处理社会关系的实践、科学实验实践。其中物质生产活动是人类 最基本的实践活动，因为它是人类社会存在和发展的基础，为其他实践活动提供物质基础。答案：A 。"},{"id":"marx-3-37","globalId":220,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":37,"question":"无产阶级专政的最终目标是（ ）。","options":["巩固和发展无产阶级政权","建设社会主义新型民主","消灭剥削进入无阶级社会","巩固和发展社会主义公有制"],"answer":2,"answerLetter":"C","explain":"无产阶级专政的最终目标是消灭剥削、消灭阶级，进入到无阶级社会。选项A巩固和发展无产阶级政 权是阶段性目标；选项B建设社会主义新型民主是实现最终目标过程中的重要任务；选项D巩固和发展社会主 义公有制是实现最终目标的手段之一。只有消灭剥削进入无阶级社会才是最终目标。"},{"id":"marx-3-38","globalId":221,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":38,"question":"资本主义简单再生产实现的条件下，第二部类产品的总价值应等于（ ）。","options":["第一部类工人和资本家消耗的消费资料价值总和","第二部类工人和资本家消耗的消费资料价值总和","两大部类工人和资本家消耗的消费资料价值总和","两大部类工人和资本家消耗的生产资料价值总和"],"answer":2,"answerLetter":"C","explain":"在资本主义简单再生产条件下，社会总产品实现的基本条件是Ⅰ(v + m)=Ⅱc，由此可以引申出Ⅱ(c + v + m)=Ⅰ(v + m)+Ⅱ(v + m)，也就是第二部类产品的总价值等于两大部类工人和资本家消耗的消费资料 价值总和，因为Ⅰ(v + m)是第一部类工人和资本家用于消费的部分，Ⅱ(v + m)是第二部类工人和资本家用 于消费的部分。"},{"id":"marx-3-39","globalId":222,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":39,"question":"下列选项属于经济社会形态的是（ ）。","options":["渔猎社会","工业社会","信息社会","封建社会"],"answer":3,"answerLetter":"D","explain":"经济社会形态是以生产关系的性质为标准划分的社会形态，封建社会是基于特定生产关系性质的社 会形态。渔猎社会、工业社会、信息社会是按照生产力和技术发展水平以及产业结构特征划分的社会形态。 答案选D。"},{"id":"marx-3-40","globalId":223,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":40,"question":"物质资料的生产方式是（ ）。","options":["生产资料与消费资料的统一","劳动资料与劳动对象的统一","生产力与生产关系的统一","劳动者与劳动工具的统一"],"answer":2,"answerLetter":"C","explain":"物质资料生产方式是人类社会存在和发展的基础，它包括生产力和生产关系两个方面，生产力是生 产方式的物质内容，生产关系是生产方式的社会形式，二者有机统一。"},{"id":"marx-3-41","globalId":224,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":41,"question":"资本主义简单再生产实现的条件下，第一部类生产的全部产品的总价值应等于（ ）。","options":["第一部类消耗的生产资料的价值总和","第二部类消耗的生产资料的价值总和","两大部类消耗的生产资料的价值总和","两大部类消耗的生活资料的价值总和"],"answer":2,"answerLetter":"C","explain":"在资本主义简单再生产条件下，第一部类生产的全部产品的总价值要满足两大部类对生产资料的需 求，即第一部类生产的全部产品的总价值应等于两大部类消耗的生产资料的价值总和。"},{"id":"marx-3-42","globalId":225,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":42,"question":"资本主义社会的发展大体分为（ ）。","options":["分工、协作和机器大工业三个阶段","自由竞争和垄断两个阶段","私人垄断、国家垄断和国际垄断三个阶段","私人垄断和国家垄断两个阶段"],"answer":1,"answerLetter":"B","explain":"资本主义社会发展经历自由竞争资本主义和垄断资本主义两个大阶段。A选项分工等阶段表述的是生 产形式发展，不是资本主义社会发展阶段。C、D选项中国家垄断、国际垄断等都属于垄断资本主义阶段的细 分，并非资本主义社会发展的两大基本阶段。"},{"id":"marx-3-43","globalId":226,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":43,"question":"社会主义由空想变为科学的标志性著作是（ ）。","options":["《资本论》","《德意志意识形态》","《共产党宣言》","《反杜林论》"],"answer":2,"answerLetter":"C","explain":"《共产党宣言》的发表，标志着科学社会主义的诞生，它使社会主义从空想变为科学。《资本论》 主要是深入剖析资本主义经济规律；《德意志意识形态》对唯物史观有重要阐述；《反杜林论》全面系统地 阐述了马克思主义理论体系。"},{"id":"marx-3-44","globalId":227,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":44,"question":"社会资本在生产的核心问题是（ ）。","options":["剩余价值的实现问题","国民收入的实现问题","社会总产品的实现问题","国民生产总值的实现问题"],"answer":2,"answerLetter":"C","explain":"社会资本再生产的核心问题是社会总产品的实现问题，包括价值补偿和实物补偿。因为只有社会总 产品都能销售出去，重新获得价值补偿，并买到新的生产资料和生活资料，社会资本再生产才能顺利进行。"},{"id":"marx-3-45","globalId":228,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":45,"question":"下列选项属于马克思主义三个组成部分之一的是（ ）。","options":["马克思主义政治学","马克思主义哲学","马克思主义伦理学","马克思主义社会学"],"answer":1,"answerLetter":"B","explain":"马克思主义由马克思主义哲学、马克思主义政治经济学和科学社会主义三部分组成。B选项马克思主 义哲学符合。答案：B 。"},{"id":"marx-3-46","globalId":229,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":46,"question":"下列选项属于意识形态的是（ ）。","options":["语言学","逻辑学","数学","哲学"],"answer":3,"answerLetter":"D","explain":"意识形态是反映社会经济关系、阶级关系的社会意识形式。语言学、逻辑学、数学是对客观世界的 中性描述，不具有阶级性，不属于意识形态。而哲学是系统化、理论化的世界观，反映一定阶级的利益和要 求，属于意识形态。"},{"id":"marx-3-47","globalId":230,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":47,"question":"资本主义的意识形态（ ）。","options":["只具有历史进步性","只具有阶级局限性","既无历史进步性也无阶级局限性","既有历史进步性又有阶级局限性"],"answer":3,"answerLetter":"D","explain":"资本主义意识形态在反对封建专制等方面起到过推动社会进步的作用，具有历史进步性；但它本质 上是为资产阶级利益服务的，代表资产阶级的意志，具有阶级局限性。所以资本主义意识形态既有历史进步 性又有阶级局限性。"},{"id":"marx-3-48","globalId":231,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":48,"question":"资本主义地租是（ ）。","options":["农产品价值低于生产价格的差额","土地所有者得到的平均利润","超过平均利润的超额利润","农业工人创造的全部剩余价值"],"answer":2,"answerLetter":"C","explain":"资本主义地租是农业资本家租种土地所有者的土地而缴纳给土地所有者的、由农业工人创造的超过 平均利润的那部分剩余价值，即超额利润。"},{"id":"marx-3-49","globalId":232,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":49,"question":"资本主义利息的本质是（ ）。","options":["货币资本使用权的价格","剩余价值的特殊转化形式","借贷资本的报酬","平均利润的特殊转化形式"],"answer":1,"answerLetter":"B","explain":"利息是职能资本家使用借贷资本而让渡给借贷资本家的一部分剩余价值。所以资本主义利息的本质 是剩余价值的特殊转化形式。"},{"id":"marx-3-50","globalId":233,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":50,"question":"资本主义再生产的特征是（ ）。","options":["简单再生产","扩大再生产","粗放型再生产","集约型再生产"],"answer":1,"answerLetter":"B","explain":"资本主义再生产的特征是扩大再生产。资本家为了获取更多剩余价值和在竞争中取胜，不会满足于 简单再生产，而是会不断扩大生产规模，进行扩大再生产。"},{"id":"marx-3-51","globalId":234,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":51,"question":"下列关于股份资本的表述中不正确的是（ ）。","options":["它使资本的形式由单个资本变为联合资本","它带有社会资本的性质","它是资本主义生产关系的一次自我“扬弃”","它没有突破单个私人资本的局限性"],"answer":3,"answerLetter":"D","explain":"股份资本把许多单个资本联合起来，由单个资本变为联合资本，所以A选项表述正确。 股份资本不 再是单个私人资本，带有社会资本性质，B选项表述正确。 股份资本一定程度上突破了单个私人资本局限性 ，对资本主义生产关系进行了自我“扬弃”，C选项表述正确。 股份资本突破了单个私人资本的局限性，D选 项说没有突破，表述错误。"},{"id":"marx-3-52","globalId":235,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":52,"question":"下列选项中，反映实践对认识具有决定作用的是（ ）。","options":["芳林新叶催陈叶，流水前波让后波","沉舟侧畔千帆过，病树前头万木春","勿以恶小而为之，勿以善小而不为","纸上得来终觉浅，绝知此事要躬行"],"answer":3,"answerLetter":"D","explain":"A、B选项体现的是发展的观点，新事物代替旧事物；C选项强调的是量变和质变的关系。D选项“纸 上得来终觉浅，绝知此事要躬行”意思是从书本上得到的知识毕竟比较肤浅，要透彻地认识事物还必须亲自 实践，体现了实践对认识具有决定作用。"},{"id":"marx-3-53","globalId":236,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":53,"question":"下列选项中，属于君主立宪制类型的是（ ）。","options":["合议制和专制独裁制","合议制和二元君主制","议会君主制和二元君主制","专制独裁制和二元君主制"],"answer":2,"answerLetter":"C","explain":"君主立宪制主要分为议会君主制和二元君主制。合议制一般用于描述行政机关的组织形式等，与君 主立宪制分类无关，专制独裁制和君主立宪制是不同的政治体制类型。所以答案选C。"},{"id":"marx-3-54","globalId":237,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":54,"question":"资本主义国家的民主制度存在形式上平等而事实上不平等的矛盾，根本原因在于","options":["宪法是由资产阶级制定的","民主的原则是与实践相脱节的","劳动人民不能参与国家政权的管理","民主权利的实现受到资本主义生产资料私有制的限制"],"answer":3,"answerLetter":"D","explain":"经济基础决定上层建筑，资本主义生产资料私有制是资本主义社会的经济基础，这一私有制决定了 在资本主义民主制度下，民主权利的实现必然受到限制，导致形式上平等而事实上不平等。A选项宪法由谁制 定不是根本原因；B选项民主原则与实践脱节是表现而非根本原因；C选项劳动人民并非完全不能参与国家政 权管理，只是在私有制下参与程度有限，且这也不是根本原因。"},{"id":"marx-3-55","globalId":238,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":55,"question":"资本主义企业的生产成本是（ ）。","options":["不变资本价值与剩余价值之和","可变资本价值与剩余价值之和","流动资本与剩余价值之和","不变资本价值和可变资本价值之和"],"answer":3,"answerLetter":"D","explain":"资本主义企业生产成本是生产单位商品所耗费的不变资本与可变资本之和。因为这两部分资本是生 产过程中实际耗费的，用于补偿生产过程中的资本消耗。而剩余价值是工人创造的被资本家无偿占有的超过 劳动力价值的价值，不包含在生产成本内。流动资本包含可变资本以及部分不变资本，但这种表述不准确。 所以答案选D。"},{"id":"marx-3-56","globalId":239,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":56,"question":"资本主义造就的埋葬自身的社会力量是（ ）。","options":["无产阶级","科学技术","巨大的社会财富","社会化的生产力"],"answer":0,"answerLetter":"A","explain":"无产阶级是随着资本主义生产方式的产生发展而逐渐形成壮大的，他们受剥削压迫最深，最具革命 性，代表先进生产力和社会发展方向，是资本主义制度的掘墓人。而科学技术、巨大社会财富并非埋葬资本 主义的社会力量，社会化生产力只是为埋葬资本主义提供了物质基础，真正起关键推动作用的社会力量是无 产阶级。"},{"id":"marx-3-57","globalId":240,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":57,"question":"下列选项中，正确表述了认识的客体的含义的是（ ）。","options":["认识的客体是主体实践和认识的对象","认识的客体是主体创造出来的对象","认识的客体是一切客观事物","认识的客体是整个外部自然界"],"answer":0,"answerLetter":"A","explain":"认识的客体是主体实践和认识活动所指向的对象。B选项主体不能创造客体；C选项并非一切客观事 物都是认识客体，只有进入主体实践和认识范围的才是；D选项整个外部自然界太宽泛，只有与主体发生联系 的部分才是认识客体。"},{"id":"marx-3-58","globalId":241,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":58,"question":"下列关于人的本质的表述中，正确的是（ ）。","options":["人的本质不是后天的而是先天的","人的本质不是具体的而是抽象的","人的本质不是变化的而是永恒的","在阶级社会里人的本质是有阶级性的"],"answer":3,"answerLetter":"D","explain":"人的本质是一切社会关系的总和。人是在后天的社会生活和社会实践中形成自身本质的，不是先天 的，A 错误。 人的本质是具体的，因为社会关系是多样且具体的，不是抽象的，B 错误。 社会关系是不断 变化发展的，所以人的本质也是变化的，不是永恒不变的，C 错误。 在阶级社会中，社会关系具有阶级性 ，这就决定了人的本质具有阶级性，D 正确。"},{"id":"marx-3-59","globalId":242,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":59,"question":"下列选项中，正确表述了实践含义的是（ ）。","options":["实践是主体纯主观的精神性活动","实践是主观创造客观世界的活动","实践是主体应付外部环境的活动","实践是主体改造和探索客体的社会性物质活动"],"answer":3,"answerLetter":"D","explain":"实践是人类能动地改造世界的社会性的物质活动。A选项说实践是纯主观精神活动错误；B选项主观 不能直接创造客观世界；C选项应付外部环境不是实践本质。只有D符合实践的定义。"},{"id":"marx-3-60","globalId":243,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":60,"question":"下列观点中，属于辩证唯物主义认识论区别于其他一切认识论的最基本观点的是（ ）。","options":["实践是认识的基础","认识是主体对客体的反映","世界是可以认识的","认识是辩证发展的过程"],"answer":0,"answerLetter":"A","explain":"辩证唯物主义认识论强调实践在认识中的基础地位，实践是认识的来源、动力、目的和检验标准 ，这是其区别于其他认识论的最基本观点。B选项很多认识论都认同认识是主体对客体的反映；C选项可知论 都认为世界可认识；D选项一些哲学也有认识辩证发展的观点，但都不如实践是认识的基础这一观点凸显辩证 唯物主义认识论的独特性。"},{"id":"marx-3-61","globalId":244,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":61,"question":"下列选项中属于上层建筑两大组成部分的是（ ）。","options":["政治思想和法律思想","政治制度和法律制度","政治法律思想和道德观念","政治法律制度和社会意识形态"],"answer":3,"answerLetter":"D","explain":"上层建筑由政治上层建筑和观念上层建筑组成。政治法律制度属于政治上层建筑，社会意识形态属 于观念上层建筑。"},{"id":"marx-3-62","globalId":245,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":62,"question":"下列选项中属于最基本的实践活动的是（ ）。","options":["社会管理活动","科学实验活动","社会改革活动","物质生产活动"],"answer":3,"answerLetter":"D","explain":"物质生产活动是人类最基本的实践活动，因为它是人类社会存在和发展的基础，为其他实践活动提 供物质基础。其他选项如社会管理活动、科学实验活动、社会改革活动等都依赖于物质生产活动。"},{"id":"marx-3-63","globalId":246,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":63,"question":"下列资本形式中不属于职能资本的是（ ）。","options":["产业资本","商业资本","借贷资本","农业资本"],"answer":2,"answerLetter":"C","explain":"职能资本是对剩余价值的生产和实现，实际发挥了职能作用的资本。产业资本在生产领域生产剩余 价值，商业资本在流通领域实现剩余价值，农业资本也在农业生产等实际生产经营过程中发挥作用，属于职 能资本。 借贷资本是为了取得利息而暂时贷给职能资本家使用的货币资本，它不直接参与生产和流通等职能 活动，只是凭借资本所有权获取利息，不属于职能资本。"},{"id":"marx-3-64","globalId":247,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":64,"question":"作为认识的初级阶段，感性认识的三种形式是（ ）。","options":["概念、判断、推理","感觉、知觉、表象","分析、归纳、综合","识记、联想、假说"],"answer":1,"answerLetter":"B","explain":"感性认识是认识的初级阶段，它的三种形式是感觉、知觉、表象 。A选项概念、判断、推理是理性 认识形式；C选项分析、归纳、综合属于思维方法；D选项识记、联想、假说不属于认识的形式分类。"},{"id":"marx-3-65","globalId":248,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":65,"question":"作为真理的马克思主义是发展的，与时俱进的，这是因为真理具有（ ）。","options":["相对性","能动性","绝对性","普遍性"],"answer":0,"answerLetter":"A","explain":"真理的相对性表明真理是有条件的、有限的。由于客观世界是不断发展的，社会实践也是不断发展 的，所以基于实践基础上的真理也要不断发展，与时俱进。马克思主义作为真理，也要随着时代、实践、科 学发展而不断发展，这体现了真理的相对性。 真理不具有能动性，能动性一般指意识的能动性，B选项错误 。 真理的绝对性强调真理的客观性、无条件性等，与马克思主义与时俱进的发展关系不大，C选项不符合。 普遍性不是真理的特性，D选项错误。"},{"id":"marx-3-66","globalId":249,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":66,"question":"《共产党宣言》的作者是（ ）。","options":["马克思、恩格斯","列宁、斯大林","卢森堡、拉法格","毛泽东"],"answer":0,"answerLetter":"A","explain":"《共产党宣言》是马克思和恩格斯为共产主义者同盟起草的纲领，是两人合作的成果。所以答案是 A。"},{"id":"marx-3-67","globalId":250,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":67,"question":"19世纪初期欧洲空想社会主义的代表人物不包括","options":["法国的圣西门？","法国的傅立叶","英国的欧文？？","德国的黑格尔"],"answer":3,"answerLetter":"D","explain":"19世纪初期欧洲空想社会主义代表人物是法国的圣西门、傅立叶和英国的欧文。而黑格尔是德国古 典哲学的代表人物，并非空想社会主义代表。答案选D。"},{"id":"marx-3-68","globalId":251,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":68,"question":"白菜、韭菜、芹菜、菠菜与蔬菜的关系属于（ ）。","options":["部分与整体的关系","个性与共性的关系","现象与本质的关系","形式与内容的关系"],"answer":1,"answerLetter":"B","explain":"白菜、韭菜、芹菜、菠菜等是具体的蔬菜种类，它们具有各自独特的特点。而蔬菜是对这一类可食 用植物的统称，包含了白菜、韭菜等各种具体蔬菜的共同特征。所以白菜、韭菜等具体蔬菜与蔬菜之间是个 性与共性的关系。"},{"id":"marx-3-69","globalId":252,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":69,"question":"辩证唯物主义认为,认识的本质是（ ）。","options":["主体对客体的直观反映","绝对观念的显现","主体对客体的能动反映","神秘天意的启示"],"answer":2,"answerLetter":"C","explain":"辩证唯物主义强调认识是在实践基础上主体对客体的能动反映。A选项直观反映忽略了能动作用 ；B选项绝对观念的显现是客观唯心主义观点；D选项神秘天意的启示也是客观唯心主义，与辩证唯物主义相 悖。"},{"id":"marx-3-70","globalId":253,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":70,"question":"辩证法和形而上学的区别在于如何回答","options":["世界的本质是什么的问题？","世界可否被认识的问题","世界的存在是怎样的问题？","世界有否统一性的问题"],"answer":2,"answerLetter":"C","explain":"辩证法和形而上学探讨的是世界的存在状态和发展方式等问题，即世界是怎样存在的。A选项世界本 质是什么的问题，是唯物主义和唯心主义的分歧点；B选项世界可否被认识是可知论和不可知论的区别；D选 项世界有否统一性是一元论和二元论的差别。只有C选项符合辩证法（用联系、发展、全面观点看世界存在 ）和形而上学（用孤立、静止、片面观点看世界存在）的区别。"},{"id":"marx-3-71","globalId":254,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":71,"question":"辩证唯物主义认为，物质的唯一特性是（ ）。","options":["广延性","持续性","客观实在性","可知性"],"answer":2,"answerLetter":"C","explain":"辩证唯物主义强调物质是不依赖于人的意识，并能为人的意识所反映的客观实在，客观实在性是物 质区别于意识的唯一特性。广延性、持续性等是物质的一些属性，但不是唯一特性，可知性强调物质能被认 识，并非物质的唯一特性。"},{"id":"marx-3-72","globalId":255,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":72,"question":"一种理论是不是真理，根本之点是看它（ ）。","options":["是否与已有的理论相一致","是否与客观实际相一致","是否说得清楚明白","是否被大多数人承认"],"answer":1,"answerLetter":"B","explain":"真理是人们对于客观事物及其规律的正确认识，所以一种理论是不是真理关键要看是否与客观实际 相一致。A选项与已有理论一致不一定就是真理，已有理论也可能有误；C选项说得清楚明白不代表就是真理 ；D选项被大多数人承认也不一定是真理，比如曾经很多人认为“地心说”正确，但实际并非如此。答案 ：B。"},{"id":"marx-3-73","globalId":256,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":73,"question":"德国古典哲学是马克思主义哲学的直接理论来源。马克思恩格斯批判地吸取了黑格尔哲学的（ ）。","options":["唯物主义思想","辩证法思想","可知论思想","决定论思想"],"answer":1,"answerLetter":"B","explain":"马克思恩格斯批判地吸取了黑格尔辩证法的合理内核，以及费尔巴哈唯物主义的基本内核，从而创 立了马克思主义哲学。黑格尔哲学最突出的贡献是辩证法。"},{"id":"marx-3-74","globalId":257,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":74,"question":"地理环境是（ ）。","options":["社会制度性质的决定性因素","社会经济结构的划分依据","社会形态更替的决定力量","社会存在发展的必要条件"],"answer":3,"answerLetter":"D","explain":"地理环境是社会存在和发展的必要条件，它能影响社会发展速度，但不是社会制度性质、社会经济 结构划分以及社会形态更替的决定性力量。生产力和生产关系的矛盾运动等才是这些方面的关键决定因素。"},{"id":"marx-3-75","globalId":258,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":75,"question":"依据价值周转方式的不同,资本可划分为（ ）。","options":["固定资本和流动资本","不变资本和可变资本","固定资本和可变资本","流动资本和不变资本"],"answer":0,"answerLetter":"A","explain":"根据价值周转方式不同，资本分为固定资本和流动资本。固定资本价值是逐步转移到产品中，流动 资本价值是一次性转移到产品中。而不变资本和可变资本是依据在剩余价值生产中作用不同划分的。"},{"id":"marx-3-76","globalId":259,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":76,"question":"依据劳动二重性原理,具体劳动（ ）。","options":["创造新价值","创造剩余价值","创造超额剩余价值","创造使用价值"],"answer":3,"answerLetter":"D","explain":"劳动二重性指具体劳动和抽象劳动。具体劳动是生产不同使用价值的不同性质和不同形式的劳动 ，它创造商品的使用价值；抽象劳动创造新价值、剩余价值、超额剩余价值。"},{"id":"marx-3-77","globalId":260,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":77,"question":"不变资本和可变资本数量构成上的比例是资本的","options":["有机构成","价值构成","技术构成","数量构成"],"answer":1,"answerLetter":"B","explain":"资本价值构成是指不变资本和可变资本数量构成上的比例。资本技术构成是由生产技术决定的生产 资料和劳动力之间的量的比例。资本有机构成是由资本技术构成决定并反映技术构成变化的资本价值构成。 题干强调不变资本与可变资本数量构成比例，所以是价值构成。"},{"id":"marx-3-78","globalId":261,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":78,"question":"除《哲学的贫困》外，标志马克思主义公开问世的经典著作是（ ）。","options":["《关于费尔巴哈的提纲》","《德意志意识形态》","《共产党宣言》","《资本论》"],"answer":2,"answerLetter":"C","explain":"《共产党宣言》的发表，标志着马克思主义的公开问世 ，它全面系统地阐述了科学社会主义理论 。答案选C。"},{"id":"marx-3-79","globalId":262,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":79,"question":"共产主义社会的分配原则是（ ）。","options":["按劳分配","按需分配","平均分配","定量分配"],"answer":1,"answerLetter":"B","explain":"共产主义社会生产力高度发达，物质财富极大丰富，人们的思想觉悟极大提高，能够实行按需分配 ，即按照每个人的实际需要分配产品。按劳分配是社会主义社会的分配原则，平均分配在历史上一些特定时 期存在但不是共产主义分配原则，定量分配也不符合共产主义分配特点。"},{"id":"marx-3-80","globalId":263,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":80,"question":"共产主义的本质因素是（ ）。","options":["实现生产资料公有制","人民生活富裕","实行按需分配","人的自由而全面发展"],"answer":3,"answerLetter":"D","explain":"共产主义社会的本质是实现人的自由全面发展，这是共产主义社会最根本的特征和本质因素。生产 资料公有制、按需分配是共产主义社会的经济特征，人民生活富裕是社会主义的追求目标之一，但这些都不 是共产主义的本质因素。答案：D。"},{"id":"marx-3-81","globalId":264,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":81,"question":"以劳动力形式存在的那部分资本是（ ）。","options":["不变资本","可变资本","固定资本","流通资本"],"answer":1,"answerLetter":"B","explain":"以生产资料形式存在的资本，在生产过程中不改变自己的价值量，叫不变资本；以劳动力形式存在 的资本，在生产过程中发生了价值增殖，叫可变资本。固定资本是指以厂房、机器、设备等劳动资料形式存 在的生产资本；流通资本是指处于流通领域中的货币资本和商品资本。所以以劳动力形式存在的那部分资本 是可变资本。"},{"id":"marx-3-82","globalId":265,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":82,"question":"部门平均劳动生产率提高之后，会导致单位商品的价值量（ ）。","options":["增加","降低","不变","无法判断"],"answer":1,"answerLetter":"B","explain":"单位商品价值量由社会必要劳动时间决定，部门平均劳动生产率提高意味着生产单位商品的社会必 要劳动时间缩短，所以单位商品价值量降低。"},{"id":"marx-3-83","globalId":266,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":83,"question":"除了商业资本和产业资本的分工，商业资本独立化的条件还有（ ）。","options":["商业资本和借贷资本的分工","商业资本家有独立的投资","存在独立的商业活动","存在出卖劳动力为生的商业店员"],"answer":1,"answerLetter":"B","explain":"【标准答案：B】"},{"id":"marx-3-84","globalId":267,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":84,"question":"股票价格是股息收入的资本化，这表明（ ）。","options":["股票价格等于股票票面额","股票这种商品是有价值的","股票价格的变动唯一取决于股息收入","股票价格与股息成正比变化，与存款利息率成反比变化"],"answer":3,"answerLetter":"D","explain":"股票价格=股息/存款利息率，所以股票价格与股息成正比，与存款利息率成反比。A选项，股票价格 一般不等于票面额；B选项，股票本身无价值，只是凭证；C选项，股票价格变动不唯一取决于股息收入。答 案：D"},{"id":"marx-3-85","globalId":268,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":85,"question":"雇佣工人在剩余劳动时间创造的是（ ）。","options":["商品的使用价值","商品的价值","资本家无偿占有的剩余价值","劳动力的价值"],"answer":2,"answerLetter":"C","explain":"雇佣工人的劳动时间分为必要劳动时间和剩余劳动时间。在必要劳动时间内创造劳动力自身的价值 ，在剩余劳动时间内创造被资本家无偿占有的剩余价值。商品使用价值是具体劳动创造的，商品价值是由必 要劳动时间和剩余劳动时间共同创造的价值总和。"},{"id":"marx-3-86","globalId":269,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":86,"question":"意识的起源和认识的起源是（ ）。","options":["一致的","不一致的","同时的","不同时的"],"answer":0,"answerLetter":"A","explain":"意识起源于物质世界长期发展以及人类社会的产生，而认识起源于实践，实践是人类有意识有目的 的活动，从根本上来说意识起源和认识起源都与人类社会及实践相关，本质上是一致的。"},{"id":"marx-3-87","globalId":270,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":87,"question":"判断一种观点是非对错的标准是（ ）。","options":["以伟人之是非为是非","以吾心之是非为是非","以众人的意见定是非","以实践中是否达到预想效果定是非"],"answer":3,"answerLetter":"D","explain":"实践是检验真理的唯一标准，判断一种观点对错应看其在实践中是否达到预想效果。A 选项以伟人 是非为标准，忽视了伟人也可能出错；B 选项以个人内心为标准过于主观；C 选项众人意见不一定就是正确 的，可能存在从众等不合理情况。"},{"id":"marx-3-88","globalId":271,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":88,"question":"从较长时期看,再生产劳动力所必需的消费资料的物质内容（ ）。","options":["不会有很大变化","会不断扩大","会不断缩小","只能有小幅度微调"],"answer":1,"answerLetter":"B","explain":"随着社会生产力的发展和社会进步，人们的生活水平会逐步提高，对消费资料的质量、种类等需求 也会增加，所以从较长时期看，再生产劳动力所必需的消费资料的物质内容会不断扩大。答案选B。"},{"id":"marx-3-89","globalId":272,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":89,"question":"从性质上看，发达资本主义国家对发展中国家的“经济援助”是（ ）。","options":["帮助发展中国家克服经济困难的一种方式","新殖民主义的一种方式","扼杀发展中国家经济发展的手段","促进发展中国家经济独立的工具"],"answer":1,"answerLetter":"B","explain":"发达资本主义国家对发展中国家的“经济援助”，并非真心帮助发展中国家发展经济，其背后往往 隐藏着政治、经济等多方面的利益诉求，是一种新殖民主义手段，目的是继续控制发展中国家。"},{"id":"marx-3-90","globalId":273,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":90,"question":"马克思主义认为,资本主义意识形态（ ）。","options":["只具有历史进步性","既有历史进步性又有阶级局限性","只具有阶级局限性","既无历史进步性又无阶级局限性"],"answer":1,"answerLetter":"B","explain":"资本主义意识形态在反对封建主义时起过积极作用，具有历史进步性；但它本质是维护资产阶级利 益，为资本主义制度服务，又有阶级局限性。"},{"id":"marx-3-91","globalId":274,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":91,"question":"从理论上讲，股票的价格（ ）。","options":["同股息成正比，同利息率成反比","同股息成反比，同利息率成正比","同股息和利息率都成正比","同股息和利息率都成反比"],"answer":0,"answerLetter":"A","explain":"股票价格=股息/利息率，从这个公式可以看出，股息越高，股票价格越高，二者成正比；利息率越 高，股票价格越低，二者成反比。"},{"id":"marx-3-92","globalId":275,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":92,"question":"从政治经济学的角度看，当代资本主义国家中那些掌握了国民经济命脉、财力雄厚、进行跨部门经营、对 社会生活各方面有巨大影响的大财团的资本属于","options":["工业资本？","商业资本？","金融资本？","银行资本"],"answer":2,"answerLetter":"C","explain":"金融资本是由工业垄断资本和银行垄断资本融合在一起而形成的一种垄断资本，掌握国民经济命脉 、进行跨部门经营等是金融资本的典型特征。大财团通常就是金融资本的代表。"},{"id":"marx-3-93","globalId":276,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":93,"question":"人的本质在其现实性上是（ ）。","options":["人的道德品性","人的经济地位","人的价值追求","一切社会关系的总和"],"answer":3,"answerLetter":"D","explain":"马克思指出人的本质不是单个人所固有的抽象物，在其现实性上，它是一切社会关系的总和。这一 观点强调人是处于社会关系网络中的，而非由道德品性、经济地位或价值追求单方面决定。"},{"id":"marx-3-94","globalId":277,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":94,"question":"从现象到本质,从不甚深刻的本质到更深刻的本质,说的是认识的（ ）。","options":["辩证运动","绝对运动","相对运动","辩证否定"],"answer":0,"answerLetter":"A","explain":"认识是一个不断深化的过程，从现象到本质，再到更深刻本质，这体现了认识的辩证发展。认识的 辩证运动包括从实践到认识，再从认识到实践的多次反复和不断发展，这种从浅层次本质到深层次本质的推 进符合认识辩证运动的特点。 绝对运动、相对运动主要侧重于描述物体在空间中的运动状态，与认识的深化 过程无关。 辩证否定强调事物自身的否定、发展和联系环节，与认识从现象到本质这种深化过程的直接关联 性不大。"},{"id":"marx-3-95","globalId":278,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":95,"question":"从作用上看，国家垄断资本主义对国民经济的调节和管理（ ）。","options":["维护了全社会的利益","维护了全体资本家的利益","维护了垄断资产阶级的整体利益","维护了全体私有者的利益"],"answer":2,"answerLetter":"C","explain":"国家垄断资本主义是私人垄断资本和国家政权相结合的垄断资本主义，其目的是为了维护垄断资产 阶级的利益。它不可能维护全社会、全体资本家（非垄断资本家利益难以保障）以及全体私有者利益，主要 是维护垄断资产阶级整体利益。"},{"id":"marx-3-96","globalId":279,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":96,"question":"马克思主义是一个具有内在逻辑联系的科学体系，其中处于核心地位的是（ ）。","options":["辩证唯物主义","历史唯物主义","政治经济学","科学社会主义"],"answer":3,"answerLetter":"D","explain":"马克思主义哲学（辩证唯物主义和历史唯物主义）是科学的世界观和方法论，政治经济学是马克思 主义的具体应用和论证，而科学社会主义是马克思主义的核心，它指明了无产阶级革命的目标和方向，体现 了马克思主义的根本价值和追求。"},{"id":"marx-3-97","globalId":280,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":97,"question":"有的哲学家认为,天地万物都是元气构成的,一切有形物体的生长毁灭都是元气聚散的结果。这是一种（ ）。","options":["朴素唯物主义观点","机械唯物主义观点","主观唯心主义观点","客观唯心主义观点"],"answer":0,"answerLetter":"A","explain":"该哲学家将天地万物归结为具体的物质形态“元气”，这符合古代朴素唯物主义把世界本原归结为 某种或某几种具体物质形态的特点。"},{"id":"marx-3-98","globalId":281,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":98,"question":"从小脱离社会、在狼群中生存的“狼孩”没有意识,这一事实说明（ ）。","options":["意识是生物长期进化的结果","意识是社会的产物","意识是人脑的机能","意识是人脑对客观世界的反映"],"answer":1,"answerLetter":"B","explain":"“狼孩”虽有人脑，但因从小脱离社会而没有意识，这表明意识的产生离不开社会环境，强调了意 识是社会的产物。"},{"id":"marx-3-99","globalId":282,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":99,"question":"单位商品价值量与劳动生产率的关系是（ ）。","options":["二者成正比","二者成反比","二者总按相同比例变化","二者总按不同比例变化"],"answer":1,"answerLetter":"B","explain":"劳动生产率提高，生产单位商品耗费的社会必要劳动时间减少，单位商品价值量降低，所以单位商 品价值量与劳动生产率成反比。"},{"id":"marx-3-100","globalId":283,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":100,"question":"马克思主义哲学认为，人们追求符合客观实际的认识，归根到底是为了？","options":["把握事物现象","揭示事物本质","追求自我实现？","改造客观世界"],"answer":3,"answerLetter":"D","explain":"马克思主义哲学强调认识世界的目的是为了改造世界。把握事物现象和揭示事物本质都属于认识世 界的范畴，而追求自我实现并非马克思主义哲学所强调的认识目的核心。所以归根到底人们追求符合客观实 际的认识是为了改造客观世界。"},{"id":"marx-3-101","globalId":284,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":101,"question":"商品经济成为最普遍的、占统治地位的经济形式的社会形态是（ ）。","options":["原始社会","奴隶社会","封建社会","资本主义社会"],"answer":3,"answerLetter":"D","explain":"在原始社会、奴隶社会、封建社会，自然经济占主导地位，商品经济只是处于从属地位。到了资本 主义社会，商品经济得到充分发展，成为最普遍、占统治地位的经济形式。"},{"id":"marx-3-102","globalId":285,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":102,"question":"有人把个别的、局部的经验当作普遍真理，到处搬用，否认科学理论的指导意义。这在认识论上犯了类 似于（ ）。","options":["唯理论的错误","经验论的错误","唯心主义先验论的错误","直观被动反映论的错误"],"answer":1,"answerLetter":"B","explain":"题干中把个别的、局部经验当作普遍真理，过分夸大经验作用，忽视科学理论，这是经验论的特点 。经验论夸大经验认识作用，贬低理性认识。"},{"id":"marx-3-103","globalId":286,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":103,"question":"有人认为，只有写到书本上的理论才是真实可靠的，因而不顾实际情况，死搬书本上的教条。这在认识 论上犯了（ ）。","options":["类似唯心主义先验论的错误","类似直观被动反映论的错误","类似经验论的错误","类似唯理论的错误"],"answer":3,"answerLetter":"D","explain":"唯理论片面强调理性认识的可靠性，认为只有理性认识是可靠的，而感性认识是不可靠的，不顾实 际情况，死搬书本教条，就是过于相信理性的书本理论，属于类似唯理论的错误。 唯心主义先验论强调认识 先于物质、先于实践经验，题干未体现。直观被动反映论主要是旧唯物主义在认识上的缺陷，强调对事物直 观、被动的反映，与题干不符。经验论则片面强调感性经验的重要性，轻视理性认识，也与题干不符。答案 ：D"},{"id":"marx-3-104","globalId":287,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":104,"question":"当代主要资本主义国家经济发展的新形式和新特征是（ ）。","options":["国家垄断取代私人垄断","私人垄断取代国家垄断","自由竞争取代私人垄断","自由竞争取代国家垄断"],"answer":0,"answerLetter":"A","explain":"在当代，资本主义国家经济发展中，国家对经济的干预和调节不断加强，国家垄断资本主义得到广 泛发展，国家垄断在一定程度上取代私人垄断占据主导地位。所以答案是A 。"},{"id":"marx-3-105","globalId":288,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":105,"question":"当前世界金融危机中,资本主义国家向私人企业注入一部分资金属于（ ）。","options":["建立资本主义国有经济和国有企业的一种方式","国家和私人资本在企业内部结合的一种方式","国家和私人资本在企业外部结合的一种方式","资本主义国家实行经济计划的一种方式"],"answer":1,"answerLetter":"B","explain":"资本主义国家向私人企业注入资金，意味着国家资本和私人资本在企业内部融合，这种形式改变了 企业资本构成。"},{"id":"marx-3-106","globalId":289,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":106,"question":"矛盾的斗争性是指（ ）。","options":["矛盾双方相互依存","矛盾双方相互渗透","矛盾双方相互排斥","矛盾双方在一定条件下相互转化"],"answer":2,"answerLetter":"C","explain":"矛盾的斗争性强调的是矛盾双方相互对立、相互排斥的属性。 选项A“矛盾双方相互依存”和选项 B“矛盾双方相互渗透”体现的是矛盾的同一性中矛盾双方相互联系的方面。 选项D“矛盾双方在一定条件下 相互转化”也是矛盾同一性的表现。"},{"id":"marx-3-107","globalId":290,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":107,"question":"商品资本职能转化为商业资本职能的条件，除了商人有独立的投资外还必须有（ ）。","options":["商业资本家和产业资本家之间的分工","商业资本家和借贷资本家之间的分工","商业资本家和银行资本家之间的分工","商业资本家和商业店员之间的分工"],"answer":0,"answerLetter":"A","explain":"商品资本职能转化为商业资本职能需要两个条件，一是商人有独立投资，二是商业资本家和产业资 本家之间形成分工。产业资本家专注生产，商业资本家专门从事商品买卖。而其他选项中商业资本家与借贷 资本家、银行资本家、商业店员之间的分工并非商品资本职能转化为商业资本职能的必要条件。"},{"id":"marx-3-108","globalId":291,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":108,"question":"在21世纪到来的前夕，英国广播公司（BBC）在全球范围举行过一次“千年思想家”网上评选，结果高居 榜首的是马克思。马克思主义之所以至今仍受到人们的普遍关注，充满生机和活力，是因为（ ）。","options":["它完成了对各种客观事物的认识","它正确反映了社会发展规律并具有与时俱进的理论品质","它是检验人们各种认识是否正确的标准","它对人们的各种实践活动都有具体的指导作用"],"answer":1,"answerLetter":"B","explain":"马克思主义能一直受关注有活力，主要是因为其自身科学性，正确反映社会发展规律，且能与时俱 进适应时代发展。A选项说完成对各种客观事物认识，过于绝对，认识是不断发展的；C选项实践才是检验认 识正确与否的标准，不是马克思主义；D选项马克思主义提供的是一般指导，不是对各种实践活动都有具体指 导。"},{"id":"marx-3-109","globalId":292,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":109,"question":"党的十七大报告指出:“要始终把实现好、维护好、发展好最广大人民的根本利益作为党和国家一切工作 的出发点和落脚点。”这体现了马克思主义政党的（ ）。","options":["阶级性质","组织原则","根本宗旨","政治纲领"],"answer":2,"answerLetter":"C","explain":"马克思主义政党的根本宗旨是全心全意为人民服务，把实现好、维护好、发展好最广大人民的根本 利益作为党和国家一切工作的出发点和落脚点，正是这一根本宗旨的体现。 A选项阶级性质强调政党代表的 阶级属性，题干未突出此方面；B选项组织原则如民主集中制等，题干未涉及；D选项政治纲领是政党为实现 其政治目标而提出的政治主张和行动方案，题干主要强调的是对人民利益的重视，并非政治纲领内容。答案 ：C"},{"id":"marx-3-110","globalId":293,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":110,"question":"在必要劳动时间不变的情况下，将工作日延长所生产出的剩余价值是（ ）。","options":["绝对剩余价值","相对剩余价值","超额剩余价值","平均剩余价值"],"answer":0,"answerLetter":"A","explain":"绝对剩余价值是在必要劳动时间不变的条件下，通过延长工作日从而绝对延长剩余劳动时间所生产 的剩余价值；相对剩余价值是在工作日长度不变时，通过缩短必要劳动时间相对延长剩余劳动时间生产的剩 余价值；超额剩余价值是个别资本家提高劳动生产率，使商品个别价值低于社会价值而多得的那部分剩余价 值。题干说在必要劳动时间不变，延长工作日生产的剩余价值，符合绝对剩余价值定义。"},{"id":"marx-3-111","globalId":294,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":111,"question":"当代资本主义国家经济关系的一系列新变化表明（ ）。","options":["其社会性质已发生本质改变","其基本矛盾已得到彻底解决","其社会发生了阶段性的部分质变","其社会主要矛盾得到了根本缓解"],"answer":2,"answerLetter":"C","explain":"当代资本主义国家经济关系虽有新变化，但资本主义私有制未变，所以社会性质未发生本质改变 ，基本矛盾也未彻底解决，社会主要矛盾也没有根本缓解。不过，这些新变化确实使资本主义社会在自身范 围内发生了阶段性的部分质变。"},{"id":"marx-4-4","globalId":295,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":4,"question":"矛盾是事物发展的动力，这说明事物发展的根本原因是（ ）。","options":["事物的内部矛盾","事物的特殊矛盾","事物的外部矛盾？","事物的主要矛盾"],"answer":0,"answerLetter":"A","explain":"唯物辩证法认为，事物发展的动力和源泉是矛盾，而推动事物发展的根本原因在于事物的内部矛盾 ，外部矛盾是事物发展的条件，特殊矛盾和主要矛盾并非事物发展根本原因的准确表述。"},{"id":"marx-4-2","globalId":296,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":2,"question":"商业利润的来源是（ ）。","options":["商品流通中的贱买贵卖","商业店员和产业工人创造的剩余价值","产业工人创造的剩余价值","商业店员创造的剩余价值"],"answer":2,"answerLetter":"C","explain":"商业利润本质上是产业工人在生产过程中创造的剩余价值的一部分。商业资本家通过剥削商业店员 的剩余劳动，来实现产业资本家让渡给他们的那部分剩余价值。A选项贱买贵卖只是商业利润实现的途径，并 非来源；商业店员的劳动不创造剩余价值，只是实现剩余价值，所以B、D选项错误。"},{"id":"marx-4-3","globalId":297,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":3,"question":"在必要劳动时间和劳动生产率不变的条件下增加剩余价值生产的方法是（ ）。","options":["绝对剩余价值生产","相对剩余价值生产","超额剩余价值生产","平均剩余价值生产"],"answer":0,"answerLetter":"A","explain":"绝对剩余价值是指在必要劳动时间不变的条件下，通过绝对延长工作日，从而绝对延长剩余劳动时 间来生产出来的剩余价值。题干强调在必要劳动时间和劳动生产率不变条件下增加剩余价值生产，符合绝对 剩余价值生产概念。 相对剩余价值生产是在工作日长度不变时，通过缩短必要劳动时间，相对延长剩余劳动 时间获得，不符合题干“必要劳动时间不变”条件。 超额剩余价值是个别资本家通过提高劳动生产率，使自 己商品的个别价值低于社会价值而比一般资本家多得的那部分剩余价值，与题干条件不符。 不存在“平均剩 余价值生产”这种说法。"},{"id":"marx-4-4","globalId":298,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":4,"question":"地理环境在社会发展中的作用是（ ）。","options":["影响社会结构的划分","影响社会发展的速度","决定社会制度的性质","决定社会形态的更替"],"answer":1,"answerLetter":"B","explain":"地理环境是社会存在和发展的必要条件，能影响社会发展速度，比如良好的地理环境利于生产开展 从而加快发展，恶劣地理环境可能阻碍发展。但它不能决定社会制度性质、社会形态更替，也并非影响社会 结构划分的关键因素。"},{"id":"marx-4-5","globalId":299,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":5,"question":"对立统一规律揭示了（ ）。","options":["事物发展的方向和道路","事物发展的源泉和动力","事物发展的状态和过程","事物发展的趋向和走势"],"answer":1,"answerLetter":"B","explain":"对立统一规律认为矛盾双方既对立又统一推动事物发展，所以它揭示的是事物发展的源泉和动力。 而A选项事物发展的方向和道路是由否定之否定规律揭示；C选项事物发展的状态和过程是质量互变规律揭示 。D选项表述不准确。"},{"id":"marx-4-6","globalId":300,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":6,"question":"矛盾有两个基本属性，一个是同一性，另一个是（ ）。","options":["客观性","普遍性","特殊性","斗争性"],"answer":3,"answerLetter":"D","explain":"矛盾的两个基本属性是同一性和斗争性 。这是哲学中关于矛盾的基本知识点。所以答案选D。"},{"id":"marx-4-7","globalId":301,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":7,"question":"商业资本家对商业店员的剥削主要体现在无偿占有（ ）。","options":["店员销售商品的劳动所创造的全部价值","店员销售商品的劳动所实现的全部价值","店员必要劳动实现的价值","店员剩余劳动实现的剩余价值"],"answer":3,"answerLetter":"D","explain":"商业店员的劳动分为必要劳动和剩余劳动。在必要劳动时间内实现的价值，补偿商业资本家支付给 店员的工资；在剩余劳动时间内实现的剩余价值，被商业资本家无偿占有。商业资本家剥削店员主要是占有 其剩余劳动实现的剩余价值，而不是销售商品劳动创造或实现的全部价值，也不是必要劳动实现的价值。答 案：D"},{"id":"marx-4-8","globalId":302,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":8,"question":"在当前社会主义初级阶段，我国人民的历史使命和共同理想是（ ）。","options":["实现共产主义","建设中国特色社会主义","实现平均分配","实现全人类的彻底解放"],"answer":1,"answerLetter":"B","explain":"在社会主义初级阶段，我国人民的历史使命和共同理想是建设中国特色社会主义。实现共产主义是 最高理想；实现平均分配不符合我国分配政策导向，是不现实的；实现全人类的彻底解放是共产主义远大目 标的内涵之一，但不是社会主义初级阶段的共同理想。"},{"id":"marx-4-9","globalId":303,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":9,"question":"地理环境在社会发展中的作用主要通过（ ）。","options":["对个体心理素质的影响实现","对物质生产的影响实现","对个体生理结构的影响实现","对民族气质的影响实现"],"answer":1,"answerLetter":"B","explain":"地理环境是社会物质生活的必要条件之一，其作用主要是通过对物质生产的影响来实现的，物质生 产是人类社会存在和发展的基础。"},{"id":"marx-4-10","globalId":304,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":10,"question":"第二次世界大战后，新发展起来的国际垄断组织是（ ）。","options":["跨国公司","国际卡特尔","国际辛迪加","国际托拉斯"],"answer":0,"answerLetter":"A","explain":"第二次世界大战后，跨国公司成为新发展起来的国际垄断组织形式。国际卡特尔、国际辛迪加、国 际托拉斯在二战前就已存在且发展，二战后跨国公司迅速发展并成为主要国际垄断组织形式。"},{"id":"marx-4-11","globalId":305,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":11,"question":"对思维与存在的同一性问题的不同回答区分了（ ）。","options":["唯物主义和唯心主义","辩证法和形而上学","可知论和不可知论","反映论和先验论"],"answer":2,"answerLetter":"C","explain":"思维与存在的同一性问题探讨的是思维能否正确认识存在，对这一问题肯定回答的是可知论，否定 回答的是不可知论。A选项唯物主义和唯心主义是对思维和存在何者为第一性的不同回答来区分；B选项辩证 法和形而上学是对世界是怎样存在的不同回答区分；D选项反映论和先验论主要围绕认识的来源等方面区分。 答案：C。"},{"id":"marx-4-12","globalId":306,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":12,"question":"那种主张“天赋的才能”“天生的心灵禀赋”的观点属于（ ）。","options":["唯心主义先验论","旧唯物论的直观反映论","唯物主义反映论","辩证唯物论的能动反映论"],"answer":0,"answerLetter":"A","explain":"题干强调“天赋”“天生”，即认为人的认识和才能是先于实践、先于物质而存在的，这符合唯心 主义先验论的特点，它主张认识来源于人先天的精神。"},{"id":"marx-4-13","globalId":307,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":13,"question":"商业资本所获得的利润相当于（ ）。","options":["平均利润","超额利润","垄断利润","企业利润"],"answer":0,"answerLetter":"A","explain":"商业资本是在流通领域中独立发挥作用的资本形式，商业资本家投资商业，目的是为了获取利润 ，且商业资本作为一种与产业资本并列的独立资本形式，也要获得平均利润，否则商业资本家就会转移资本 。"},{"id":"marx-4-14","globalId":308,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":14,"question":"在对外经济侵略中，最具新殖民主义特点的做法是（ ）。","options":["高价推销工业品和高科技产品","低价收购初级产品和原材料","实行“对外援助”","大量对外输出“过剩资本”"],"answer":2,"answerLetter":"C","explain":"新殖民主义打着“援助”旗号，通过经济、政治等手段控制发展中国家，“对外援助”表面是帮助 ，实际藏有控制目的，是新殖民主义特点做法。而A、B选项是传统殖民主义在贸易方面手段，D选项大量对外 输出“过剩资本”是垄断资本主义经济特征之一，但不是最具新殖民主义特点做法。"},{"id":"marx-4-15","globalId":309,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":15,"question":"第二次世界大战后，主要资本主义国家的经济发展进入到（ ）。","options":["自由竞争资本主义阶段","垄断竞争资本主义阶段","私人垄断资本主义阶段","国家垄断资本主义阶段"],"answer":3,"answerLetter":"D","explain":"第二次世界大战后，由于新科技革命等因素，资本主义国家对经济生活进行全面干预和调节，使国 家垄断资本主义得到迅速发展并在经济生活中占据主导地位。"},{"id":"marx-4-16","globalId":310,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":16,"question":"对外国文化要有分析、有选择、有批判地借鉴和吸收,这种态度体现的哲学道理是（ ）。","options":["对立统一的原理","辩证否定的原理","内容和形式关系的原理","原因和结果关系的原理四"],"answer":1,"answerLetter":"B","explain":"辩证否定观强调事物的否定是自身的否定，是事物发展和联系的环节，实质是“扬弃”，即既克服 又保留。对外国文化有分析、有选择、有批判地借鉴和吸收，就是取其精华、去其糟粕，这符合辩证否定观 的要求。而对立统一原理强调矛盾双方的相互对立与统一；内容和形式关系原理侧重于内容决定形式等方面 ；原因和结果关系原理关注因果联系。均与题干对外国文化的态度不符。"},{"id":"marx-4-17","globalId":311,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":17,"question":"能动反映论区别于机械反映论的根本标志是（ ）。","options":["肯定思维能正确地反映存在","认为认识过程是纯粹的观念创造","肯定思维对存在的决定作用","认为认识过程是反映和创造的统一"],"answer":3,"answerLetter":"D","explain":"能动反映论强调认识过程不仅是对客观世界的简单摹写，更是一种创造性的活动，把实践引入认识 论，认识过程是反映和创造的统一。 机械反映论把认识看成是照镜子式的、直观被动的反映，忽视了人的主 观能动性。能动反映论与机械反映论的根本区别就在于是否承认认识过程是反映和创造的统一。"},{"id":"marx-4-18","globalId":312,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":18,"question":"第一次工业革命时期，英美等主要资本主义国家处于","options":["自由竞争资本主义阶段？","私人垄断资本主义阶段","一般垄断资本主义阶段？","国家垄断资本主义阶段"],"answer":0,"answerLetter":"A","explain":"第一次工业革命时期，资本主义生产力迅速发展，在经济运行中强调自由竞争、自由贸易等原则 ，此时处于自由竞争资本主义阶段。 私人垄断资本主义阶段、一般垄断资本主义阶段（一般垄断即私人垄断 ）是在19世纪末20世纪初第二次工业革命后逐渐形成的。 国家垄断资本主义阶段是在20世纪30年代后，特别 是二战后得到广泛发展。"},{"id":"marx-4-19","globalId":313,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":19,"question":"对物质和意识哪个是第一性问题的不同回答，形成了哲学上的两大基本派别。这两大基本派别是（ ）。","options":["唯物主义和唯心主义","辩证法和形而上学","一元论和二元论","可知论和不可知论"],"answer":0,"answerLetter":"A","explain":"哲学的基本问题是思维和存在的关系问题，也就是意识和物质的关系问题。对物质和意识哪个是第 一性问题的不同回答，划分出唯物主义（认为物质第一性）和唯心主义（认为意识第一性）两大基本派别 。"},{"id":"marx-4-20","globalId":314,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":20,"question":"能够划分为固定资产和流动资本形态的是（ ）。","options":["流通资本","商品资本","货币资本","生产资本"],"answer":3,"answerLetter":"D","explain":"只有生产资本能依据价值周转方式不同，划分为固定资本和流动资本。流通资本是处于流通领域的 资本，商品资本、货币资本属于流通资本，它们都不能进行这样的划分。"},{"id":"marx-4-21","globalId":315,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":21,"question":"商业资本执行的是（ ）。","options":["产业资本中商品资本的职能","产业资本中货币资本的职能","产业资本中生产资本的职能","产业资本中流通资本的职能"],"answer":0,"answerLetter":"A","explain":"商业资本是从产业资本中分离出来，专门从事商品买卖，独立发挥资本职能，以获取商业利润为目 的的一种资本形式。它执行的是产业资本循环中商品资本的职能，通过销售商品实现价值和剩余价值。答案 选A。"},{"id":"marx-4-22","globalId":316,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":22,"question":"在国际共产主义运动史上,第一个无产阶级政党是（ ）。","options":["共产主义者间盟","德国社会民主工党","中国共产党","俄国社会民主工党"],"answer":0,"answerLetter":"A","explain":"共产主义者同盟是世界上第一个无产阶级政党，1847 年 6 月在伦敦成立。德国社会民主工党成立 于 1869 年；中国共产党成立于 1921 年；俄国社会民主工党成立于 1898 年 ，均晚于共产主义者同盟。答 案：A"},{"id":"marx-4-23","globalId":317,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":23,"question":"年利润率的计算公式是（ ）。","options":["年利润量／年预付可变资本","年利润量／年预付不变资本","年剩余价值量／年预付可变资本","年剩余价值量／年预付总资本"],"answer":3,"answerLetter":"D","explain":"年利润率是年剩余价值量与年预付总资本的比率。年利润量本质上就是年剩余价值量，年利润率反 映预付总资本的增值程度。选项A是年剩余价值率的一种形式（年剩余价值量与年预付可变资本的比率 ），B选项计算无意义，C是年剩余价值率。只有D符合年利润率公式。"},{"id":"marx-4-24","globalId":318,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":24,"question":"商业资本执行的是产业资本中（ ）。","options":["货币资本的职能","生产资本的职能","流通资本的职能","商品资本的职能"],"answer":3,"answerLetter":"D","explain":"商业资本是从产业资本中分离出来，专门从事商品买卖，独立发挥资本职能，以获取商业利润为目 的的一种资本形式。它执行的是产业资本循环中商品资本的职能，即销售商品，实现价值和剩余价值。答案 选D。"},{"id":"marx-4-25","globalId":319,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":25,"question":"在国家垄断资本主义阶段之前，资本主义处于（ ）。","options":["自由竞争资本主义阶段","私人垄断资本主义阶段","垄断竞争资本主义阶段","金融垄断资本主义阶段"],"answer":1,"answerLetter":"B","explain":"资本主义发展经历了自由竞争资本主义和垄断资本主义两个阶段，垄断资本主义又分为私人垄断资 本主义和国家垄断资本主义。所以在国家垄断资本主义阶段之前是私人垄断资本主义阶段。"},{"id":"marx-4-26","globalId":320,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":26,"question":"否定之否定规律揭示了（ ）。","options":["事物的发展是必然性和偶然性的统一","事物的发展是量变和质变的统一","事物的发展是前进性和曲折性的统一","矛盾是事物发展的动力和源泉"],"answer":2,"answerLetter":"C","explain":"否定之否定规律表明，事物发展的方向是前进的，因为每一次否定都是对旧事物的扬弃，推动事物 向更高阶段发展；而发展的道路是曲折的，会经历肯定 - 否定 - 否定之否定的过程，不是直线上升的。 A选项事物发展是必然性和偶然性的统一，主要涉及唯物辩证法的范畴，与否定之否定规律无关。 B选项量变 和质变的统一是质量互变规律的内容。 D选项矛盾是事物发展的动力和源泉是对立统一规律的内容。"},{"id":"marx-4-27","globalId":321,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":27,"question":"根据邓小平的概括，下列选项不属于社会主义本质的是（ ）。","options":["解放生产力，发展生产力","消灭剥削，消除两极分化","允许个别人先富起来","最终达到共同富裕"],"answer":2,"answerLetter":"C","explain":"社会主义本质是解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕。“允许 个别人先富起来”是实现共同富裕的一种途径和手段，并非社会主义本质内容。"},{"id":"marx-4-28","globalId":322,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":28,"question":"年剩余价值率是（ ）。","options":["剩余价值与可变资本之比","剩余价值与不变资本之比","一年内剩余价值总量与一年预付可变资本之比","一年内剩余价值总量与一年预付总资本之比"],"answer":2,"answerLetter":"C","explain":"年剩余价值率是衡量一年内预付可变资本的增殖程度，是一年内剩余价值总量与一年预付可变资本 之比。A选项是剩余价值率的概念；B选项无对应经济概念；D选项是年利润率概念。"},{"id":"marx-4-29","globalId":323,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":29,"question":"改革不仅存在于社会主义社会中，而且存在于其他社会形态中。这说明改革具有","options":["主体能动性","历史局限性","普遍性","特殊性"],"answer":2,"answerLetter":"C","explain":"题干强调改革在多种社会形态中都存在，体现的是改革普遍存在于不同社会形态，即改革具有普遍 性。"},{"id":"marx-4-30","globalId":324,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":30,"question":"根据价值周转方式的不同，资本家的生产资本可以划分为（ ）。","options":["不变资本和可变资本","固定资本和流动资本","商品资本和流通资本","个别资本和社会资本"],"answer":1,"answerLetter":"B","explain":"生产资本根据价值周转方式不同分为固定资本和流动资本。固定资本价值逐步转移，流动资本价值 一次性转移。A选项不变资本和可变资本是按在剩余价值生产中作用不同划分；C选项商品资本是产业资本循 环阶段之一，流通资本概念不准确；D选项个别资本和社会资本是从资本运动角度划分。"},{"id":"marx-4-31","globalId":325,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":31,"question":"农产品的社会生产价格由（ ）。","options":["优等地的生产条件决定","中等地的生产条件决定","劣等地的生产条件决定","各类土地的平均生产条件决定"],"answer":2,"answerLetter":"C","explain":"因为如果农产品社会生产价格由优等地或中等地生产条件决定，劣等地就会退出生产，农产品产量 就会减少，价格上升，所以农产品社会生产价格只能由劣等地生产条件决定，这样才能保证劣等地也投入生 产，满足社会对农产品的需求。"},{"id":"marx-4-32","globalId":326,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":32,"question":"上世纪下半叶，从第二次世界大战结束后到冷战结束前，西方主要发达资本主义国家处于","options":["自由竞争资本主义阶段","私人垄断资本主义阶段","国家垄断资本主义","国家垄断资本主义阶段"],"answer":3,"answerLetter":"D","explain":"【标准答案：D】"},{"id":"marx-4-33","globalId":327,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":33,"question":"在经济危机和萧条阶段，资本主义国家向私人企业注入一部分国有资金以维持其生存的经济行为属于","options":["建立资本主义国有经济和国有企业的一种方式","国家和私人资本在企业内部结合的一种方式","国家和私人资本在企业外部结合的一种方式","资本主义国家实行经济计划的一种方式"],"answer":1,"answerLetter":"B","explain":"国家向私人企业注入国有资金，这意味着国有资本与私人资本在企业内部实现了融合。"},{"id":"marx-4-34","globalId":328,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":34,"question":"概念、判断、推理是（ ）。","options":["理性认识的三种形式","感性认识的三种形式","社会心理的三种形式","意识形态的三种形式"],"answer":0,"answerLetter":"A","explain":"理性认识是认识的高级阶段，包括概念、判断、推理三种形式。感性认识的三种形式是感觉、知觉 和表象。社会心理和意识形态与概念、判断、推理不属于对应关系。"},{"id":"marx-4-35","globalId":329,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":35,"question":"根据社会意识反映社会存在的程度和特点，可以把社会意识划分为（ ）。","options":["个体意识和群体意识","意识形态和非意识形态","先进意识和落后意识","社会心理和思想体系"],"answer":3,"answerLetter":"D","explain":"社会意识从反映社会存在的程度和特点看，分为社会心理和思想体系。社会心理是低层次、不系统 、不定型的社会意识；思想体系是高层次、系统化、理论化的社会意识。A选项是从主体角度划分；B选项是 从与经济基础关系角度划分；C选项并非按照反映社会存在程度和特点划分。"},{"id":"marx-4-36","globalId":330,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":36,"question":"农业资本家所获得的剩余价值是（ ）。","options":["级差地租","绝对地租","垄断地租","平均利润"],"answer":3,"answerLetter":"D","explain":"农业资本家投资农业，其目的和工业资本家等一样，是为了获取平均利润。农业工人创造的剩余价 值，一部分以地租形式缴纳给土地所有者，另一部分就是农业资本家获得的平均利润。"},{"id":"marx-4-37","globalId":331,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":37,"question":"设想没有物质的运动的观点是（ ）。","options":["朴素唯物主义","机械唯物主义","不可知论","唯心主义"],"answer":3,"answerLetter":"D","explain":"物质和运动是不可分割的，物质是运动的载体，运动是物质的根本属性和存在方式。 设想没有物 质的运动，那就把运动看作是脱离物质的独立存在，这实际上是将精神、意识等非物质的东西当作运动的主 体，属于唯心主义观点。"},{"id":"marx-4-38","globalId":332,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":38,"question":"在劳动资料这一复杂系统中，最能标志生产力发展水平的是（ ）。","options":["运输设备","传动装置","动力系统","生产工具"],"answer":3,"answerLetter":"D","explain":"生产工具是劳动资料中最主要、最具有决定意义的因素，它直接体现了人们改造自然的深度和广度 ，是衡量生产力发展水平的客观尺度。而运输设备、传动装置、动力系统虽也是劳动资料组成部分，但相比 之下，生产工具对生产力发展水平的标志作用更为突出。"},{"id":"marx-4-39","globalId":333,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":39,"question":"感性认识的三种形式是（ ）。","options":["感觉、概念、判断","概念、判断、推理","感觉、知觉、表象","感觉、知觉、推理"],"answer":2,"answerLetter":"C","explain":"感性认识是认识的初级阶段，它是人们通过感官获得的关于事物的现象、外部联系的认识，其三种 形式为感觉、知觉和表象。A选项中概念属于理性认识；B选项概念、判断、推理均是理性认识形式；D选项推 理属于理性认识。所以答案选C。"},{"id":"marx-4-40","globalId":334,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":40,"question":"根据是否承认世界的统一性,可以把哲学派别划分为（ ）。","options":["唯物论和唯心论","一元论和二元论","可知论和不可知论","辦证法和形而上学"],"answer":1,"answerLetter":"B","explain":"对世界统一性问题的不同回答区分出一元论和二元论。一元论承认世界有一个统一的本原，二元论 则认为世界有两个相互独立的本原。 A选项唯物论和唯心论是根据对物质和意识何者为第一性的回答划分的 。 C选项可知论和不可知论是根据对思维和存在是否具有同一性的回答划分的。 D选项辩证法和形而上学是 对世界是怎样存在的不同回答，辩证法用联系、发展、全面的观点看问题，形而上学用孤立、静止、片面的 观点看问题。"},{"id":"marx-4-41","globalId":335,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":41,"question":"农业资本家在同一块土地上连续追加投资,使劳动生产率提高所获得的剩余价值属于（ ）。","options":["级差地租I","级差地租Ⅱ","绝对地租","垄断利润"],"answer":1,"answerLetter":"B","explain":"级差地租Ⅱ是由于在同一块土地上连续追加投资的劳动生产率不同而形成的级差地租。题干中农业 资本家在同一块土地连续追加投资提高劳动生产率获得的剩余价值符合级差地租Ⅱ的概念。"},{"id":"marx-4-42","globalId":336,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":42,"question":"共产主义社会的两个阶段是指（ ）。","options":["社会主义社会和共产主义社会","过渡阶段和社会主义社会","社会主义初级阶段和高级阶段","共产主义社会初级阶段和高级阶段分"],"answer":0,"answerLetter":"A","explain":"马克思把共产主义社会划分为第一阶段和高级阶段，列宁把共产主义社会第一阶段称为社会主义社 会 ，所以共产主义社会两个阶段指社会主义社会和共产主义社会（这里共产主义社会指的是共产主义社会高 级阶段）。"},{"id":"marx-4-43","globalId":337,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":43,"question":"构成商品价格基础的是（ ）。","options":["使用价值","价值","商品供给","商品需求"],"answer":1,"answerLetter":"B","explain":"价值决定价格，价格是价值的货币表现，所以构成商品价格基础的是价值。而使用价值是商品能满 足人们某种需要的属性，与价格基础无关；商品供给和需求影响价格，但不是价格基础。"},{"id":"marx-4-44","globalId":338,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":44,"question":"货币转化为资本的前提是（ ）。","options":["货币在运动中发生了价值增值","货币投入流通带来剩余价值","货币所有者购买到劳动力商品","货币可以购买到生产资料"],"answer":2,"answerLetter":"C","explain":"劳动力商品具有能创造比自身价值更大价值的特点，货币所有者购买到劳动力商品，才可能实现价 值增值，从而使货币转化为资本。"},{"id":"marx-4-45","globalId":339,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":45,"question":"认识的主体和客体之间最基础性的关系是（ ）。","options":["认识关系","实践关系","相互依存的关系","相互作用的关系"],"answer":1,"answerLetter":"B","explain":"实践是认识的基础，认识的主体和客体之间首先是改造与被改造的实践关系，这是最基础性的关系 ，其他关系都基于此。"},{"id":"marx-4-46","globalId":340,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":46,"question":"社会改革和社会革命都根源于（ ）。","options":["生产力和生产关系的矛盾","社会存在和社会意识的矛盾","人口增长和资源匮乏的矛盾","创新意识和传统观念的矛盾"],"answer":0,"answerLetter":"A","explain":"生产力和生产关系的矛盾是社会基本矛盾，是社会发展的根本动力，社会改革与社会革命都是为了 解决这一矛盾，推动社会发展。社会存在和社会意识的矛盾虽也是社会基本矛盾，但不是社会改革和革命根 源；人口增长和资源匮乏、创新意识和传统观念的矛盾不属于社会基本矛盾，不是社会改革和革命根源。答 案：A"},{"id":"marx-4-47","globalId":341,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":47,"question":"在马克思主义理论体系中，科学社会主义是其（ ）。","options":["理论基础","核心内容","指导原则","前提条件"],"answer":1,"answerLetter":"B","explain":"马克思主义主要包括马克思主义哲学、马克思主义政治经济学和科学社会主义三大部分。马克思主 义哲学是理论基础，马克思主义政治经济学是运用马克思主义哲学对资本主义的理论剖析，科学社会主义则 是在两者基础上得出的关于未来社会的构想，是核心内容，指明了奋斗目标和发展方向。所以答案是B。"},{"id":"marx-4-48","globalId":342,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":48,"question":"集中体现着共产主义社会主要特征和本质要求的原则标志是（ ）。","options":["各尽所能，按需分配","各尽所能，按才能分配","各尽所能，按劳分配","各尽所能，按地位分配"],"answer":0,"answerLetter":"A","explain":"“各尽所能、按需分配”不只是一个个人消费品分配方式，而是一个集中体现着共产主义社会主要 特征和本质要求的原则标志。按劳分配是社会主义社会分配方式，按才能、按地位分配不符合共产主义理念 。答案：A 。"},{"id":"marx-4-49","globalId":343,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":49,"question":"认识事物的最根本方法是（ ）。","options":["普遍联系法","阶级分析法","矛盾分析法","具体分析法"],"answer":2,"answerLetter":"C","explain":"矛盾是事物发展的源泉和动力，矛盾分析法是认识事物最根本的方法，它能帮助我们从本质上认识 事物及事物间的关系。A选项普遍联系法强调事物相互联系；B选项阶级分析法主要用于分析阶级社会中的现 象；D选项具体分析法侧重于具体问题具体对待，但都不如矛盾分析法根本。"},{"id":"marx-4-50","globalId":344,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":50,"question":"社会革命的基本形式是（ ）。","options":["和平发展","暴力革命","渐进改革","文化宣传"],"answer":1,"answerLetter":"B","explain":"社会革命是阶级斗争的最高表现，暴力革命是社会革命的基本形式。因为统治阶级不会自动退出历 史舞台，只有通过暴力革命，才能推翻反动统治阶级，实现社会形态的根本变革。和平发展、渐进改革多属 于社会改良，不能从根本上改变社会制度。文化宣传是革命的辅助手段，并非基本形式。"},{"id":"marx-4-51","globalId":345,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":51,"question":"古希腊哲学家克拉底鲁否认相对静止的存在,认为世界万物像一阵旋风,瞬息万变,不可捉摸。这是一种 （ ）。","options":["相对主义诡辩论观点","形而上学观点","唯物辩证法观点","庸俗唯物主义观点"],"answer":0,"answerLetter":"A","explain":"克拉底鲁否认相对静止，只承认绝对运动，这使得事物失去了质的稳定性和确定性，陷入了只强调 运动的相对性而忽视相对静止的错误，这正是相对主义诡辩论的特征。形而上学是用孤立、静止、片面的观 点看问题；唯物辩证法坚持联系、发展、全面，承认绝对运动和相对静止统一；庸俗唯物主义把意识直接归 结为物质，与题干描述不符。答案：A.相对主义诡辩论观点"},{"id":"marx-4-52","globalId":346,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":52,"question":"既承认历史发展的决定性又承认历史发展的选择性，这属于","options":["历史唯物论观点","相对主义观点","历史循环论观点","折衷主义观点"],"answer":0,"answerLetter":"A","explain":"历史唯物论认为社会历史发展具有客观规律性（即决定性），同时在一定程度上人的主体选择性也 发挥作用。 相对主义夸大事物和认识的相对性，否定确定性和客观性。 历史循环论把历史看成周而复始的 循环运动，否定社会进步。 折衷主义是把各种不同的观点无原则地拼凑在一起。答案：A 。既承认历史发展 决定性又承认选择性，符合历史唯物论观点。"},{"id":"marx-4-53","globalId":347,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":53,"question":"认识是主体对客体的能动反映。这是一种（ ）。","options":["辩证唯物主义认识论观点","机械唯物主义认识论观点","主观唯心主义认识论观点","客观唯心主义认识论观点"],"answer":0,"answerLetter":"A","explain":"辩证唯物主义认识论认为认识是主体对客体的能动反映。它强调认识过程中主体的能动性以及认识 与实践的辩证关系。 机械唯物主义认识论把认识看成是直观的、消极被动的反映，不承认主体的能动作用。 主观唯心主义认识论把认识看作是主观自生的，是心灵的自由创造物。 客观唯心主义认识论把认识看作是来 自“客观精神”的启示或赋予。"},{"id":"marx-4-54","globalId":348,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":54,"question":"在平均利润形成以前，资本有机构成高的部门，它的利润率一般（ ）。","options":["高于社会平均水平","低于社会平均水平","等于社会平均水平","等于其剩余价值率"],"answer":1,"answerLetter":"B","explain":"资本有机构成高意味着在该部门总资本中，不变资本所占比重较大，可变资本所占比重较小。在剩 余价值率相同的条件下，可变资本是剩余价值的源泉，可变资本占比小，该部门创造的剩余价值相对较少 ，进而利润率相对较低。而平均利润形成前，资本有机构成高的部门利润率一般低于社会平均水平。"},{"id":"marx-4-55","globalId":349,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":55,"question":"关于马克思主义的产生，下列说法错误的是（ ）。","options":["马克思主义是历史时代的产物","马克思主义是实践经验的总结","马克思主义是科学成果的升华","马克思主义是先天智慧的结晶"],"answer":3,"answerLetter":"D","explain":"马克思主义是在特定历史时代背景下，基于实践经验总结以及对当时科学成果升华而产生的，并非 先天智慧结晶，它是在社会发展和人类实践过程中形成的。"},{"id":"marx-4-56","globalId":350,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":56,"question":"既承认社会形态发展的客观规律又承认人的自觉活动的作用,这种观点属于（ ）。","options":["历史唯物论观点","唯意志论观点","折衷主义观点","机械决定论观点"],"answer":0,"answerLetter":"A","explain":"历史唯物论既强调社会形态发展是有客观规律的，这是不以人的意志为转移的，同时也承认人的自 觉活动对社会发展有能动作用。 唯意志论片面夸大了人的意志的作用，否定社会发展的客观规律。 折衷主 义是把各种不同的观点无原则地拼凑在一起。 机械决定论只承认客观规律性，否认人的自觉能动性。答案 ：A"},{"id":"marx-4-57","globalId":351,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":57,"question":"认识主体具有的突出特点是（ ）。","options":["能动性","被动性","消极性","积极性"],"answer":0,"answerLetter":"A","explain":"认识主体是指处于一定社会关系中从事实践活动和认识活动的人，人在认识过程中不是被动、消极 地反映对象，而是积极主动地去认识和改造世界，能动性是认识主体突出特点。"},{"id":"marx-4-58","globalId":352,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":58,"question":"社会主义根本的和首要的任务是（ ）。","options":["解放和发展生产力","加强无产阶级专政","巩固共产党的领导","镇压资产阶级的反抗"],"answer":0,"answerLetter":"A","explain":"社会主义的根本任务是解放和发展生产力，这是由社会主义的本质决定的，只有解放和发展生产力 ，才能提高人民生活水平，体现社会主义制度优越性等。而其他选项如加强无产阶级专政、巩固共产党领导 并非首要和根本任务，镇压资产阶级反抗不符合社会主义发展阶段特点。"},{"id":"marx-4-59","globalId":353,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":59,"question":"在前苏联推行所谓“社会主义苏联模式”的领导人是（ ）。","options":["列宁","斯大林","布哈林","托洛斯基"],"answer":1,"answerLetter":"B","explain":"“社会主义苏联模式”指苏联在斯大林领导下，按照斯大林的规划所确立起来的国家政治经济体制 。列宁时期是苏俄探索社会主义建设道路阶段，尚未形成该模式。布哈林、托洛斯基并非推行“社会主义苏 联模式”的领导人。答案选B。"},{"id":"marx-4-60","globalId":354,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":60,"question":"关于社会分工的产生，下列表述中正确的是（ ）。","options":["社会分工是私有制的产物","社会分工是商品经济的产物","社会分工是资本主义的产物","社会分工是生产力发展的产物"],"answer":3,"answerLetter":"D","explain":"生产力的发展促使人们的生产活动专业化，从而产生了社会分工。私有制、商品经济、资本主义都 是在社会分工之后，在一定条件下出现的，它们不是社会分工产生的原因。所以社会分工是生产力发展的产 物。"},{"id":"marx-4-61","globalId":355,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":61,"question":"既坚持历史决定论又承认主体选择的作用，这属于（ ）。","options":["历史唯物论观点","相对主义观点","诡辩论观点","折衷主义观点"],"answer":0,"answerLetter":"A","explain":"历史唯物论认为社会历史发展有其客观规律性，同时也承认人的主体选择性。主体选择性是在遵循 历史发展规律基础上的选择。相对主义、诡辩论、折衷主义都不能正确处理历史决定论与主体选择的关系。 相对主义否定事物的确定性和稳定性；诡辩论以虚假论据、欺诈的方式进行似是而非的论证；折衷主义把各 种不同观点无原则地拼凑在一起。所以既坚持历史决定论又承认主体选择作用属于历史唯物论观点。"},{"id":"marx-4-62","globalId":356,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":62,"question":"认识主体与认识客体之间最基本的关系是（ ）。","options":["改造与被改造的关系","相互依存的关系","反映与被反映的关系","相互作用的关系"],"answer":0,"answerLetter":"A","explain":"认识主体与认识客体多种关系中，实践关系即改造与被改造关系是最基本的，因为认识是在实践基 础上发生的，只有通过改造世界才能更好地认识世界。"},{"id":"marx-4-63","globalId":357,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":63,"question":"关于社会主义民主，下列不正确的选项是（ ）。","options":["人类社会最高类型的民主","绝大多数人的民主","人民群众完全自由","人民群众当家作主"],"answer":2,"answerLetter":"C","explain":"社会主义民主是人类社会最高类型的民主，是绝大多数人的民主，本质是人民群众当家作主。而 “人民群众完全自由”这种说法错误，自由是相对的，要在法律等规范内享有自由，不存在完全不受限制的 自由。"},{"id":"marx-4-64","globalId":358,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":64,"question":"在社会发展中起决定作用的是（ ）。","options":["人和自然的矛盾","剥削阶级和被剥削阶级的矛盾","先进思想和落后思想的矛盾","生产力和生产关系的矛盾"],"answer":3,"answerLetter":"D","explain":"生产力和生产关系的矛盾是人类社会基本矛盾之一，生产力决定生产关系，生产关系反作用于生产 力，这一矛盾运动推动着人类社会从低级向高级发展，在社会发展中起决定作用。A选项人和自然的矛盾并非 对社会发展起决定作用；B选项剥削阶级和被剥削阶级的矛盾是特定社会阶段的矛盾，不是根本决定因素 ；C选项先进思想和落后思想的矛盾属于社会意识层面的矛盾，不起决定作用。"},{"id":"marx-4-65","globalId":359,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":65,"question":"黑格尔、费尔巴哈是（ ）。","options":["德国古典哲学的代表人物","英国古典政治经济学的代表人物","英国空想社会主义的代表人物","法国空想社会主义的代表人物"],"answer":0,"answerLetter":"A","explain":"黑格尔和费尔巴哈是德国哲学家，在德国古典哲学发展中有重要地位。德国古典哲学是马克思主义 的理论来源之一。而英国古典政治经济学代表人物如亚当·斯密等，英国、法国空想社会主义代表人物分别 有欧文、圣西门、傅立叶等。"},{"id":"marx-4-66","globalId":360,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":66,"question":"商品的使用价值反映的是（ ）。","options":["人与人的关系","人与自然的关系","生产关系","交换关系"],"answer":1,"answerLetter":"B","explain":"使用价值是商品能满足人们某种需要的属性，即商品的有用性。它是商品的自然属性，体现的是人 与自然的关系。比如粮食能充饥，这种满足人对食物需求的属性，是基于粮食本身的自然特质，和自然条件 相关，而非人与人之间的社会关系等。"},{"id":"marx-4-67","globalId":361,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":67,"question":"实现意识能动作用的根本途径是（ ）。","options":["学习科学理论","投身社会实践","了解实际情况","制定周密计划"],"answer":1,"answerLetter":"B","explain":"意识能动作用的实现必须通过人们的实践活动，实践是连接主观与客观的桥梁，只有投身社会实践 ，才能将意识转化为现实。而学习科学理论、了解实际情况、制定周密计划都只是为实践做准备，本身不能 直接实现意识能动作用。"},{"id":"marx-4-68","globalId":362,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":68,"question":"在社会主义思想史上，标志着科学社会主义理论公开面世的第一个纲领性文件是（ ）。","options":["《共产党宣言》","《法兰西内战》","《社会主义从空想到科学的发展》","《哥达纲领批判》"],"answer":0,"answerLetter":"A","explain":"《共产党宣言》是科学社会主义理论公开面世的第一个纲领性文件，它系统阐述了科学社会主义基 本原理，为无产阶级革命提供了理论指导。"},{"id":"marx-4-69","globalId":363,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":69,"question":"坚持马克思主义哲学的认识路线，就必须在工作中坚持","options":["一切从实际出发","—切从主观的愿望出发","一切从理论出发","—切从臆造的规律出发"],"answer":0,"answerLetter":"A","explain":"马克思主义哲学认识路线强调物质第一性，意识第二性，认识是对客观世界的反映。所以要从客观 实际出发。而B从主观愿望、C从理论、D从臆造规律出发，都违背了从客观实际出发的要求。"},{"id":"marx-4-70","globalId":364,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":70,"question":"商品价值的实体是（ ）。","options":["使用价值","交换价值","具体劳动","抽象劳动"],"answer":3,"answerLetter":"D","explain":"商品价值是凝结在商品中的无差别的一般人类劳动，即抽象劳动。具体劳动形成商品的使用价值 ，交换价值是价值的表现形式，使用价值是商品能满足人们某种需要的属性。所以商品价值的实体是抽象劳 动。"},{"id":"marx-4-71","globalId":365,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":71,"question":"20世纪后半期垄断组织发展的新形式是（ ）。","options":["辛迪加","卡特尔","托拉斯","混合联合"],"answer":3,"answerLetter":"D","explain":"20世纪后半期，垄断组织在形式上有了新发展，混合联合公司成为主要形式。而辛迪加、卡特尔、 托拉斯是垄断组织较早期的形式。"},{"id":"marx-4-72","globalId":366,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":72,"question":"在生产力和生产关系这对矛盾中（ ）。","options":["生产力的性质决定生产关系的性质","生产力的变化落后于生产关系的变化","生产关系总是适应生产力的发展水平","生产关系可以超越生产力的发展水平"],"answer":0,"answerLetter":"A","explain":"生产力决定生产关系，生产力的性质决定生产关系的性质 ，有什么样的生产力就有什么样的生产关 系与之相适应。生产关系会适应生产力，但并非总是适应，生产关系变化滞后于生产力变化，且不能超越生 产力发展水平。所以A正确。"},{"id":"marx-4-73","globalId":367,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":73,"question":"货币转化为资本的决定性条件是，货币的所有者在流通中购买到（ ）。","options":["劳动工具","劳动力","劳动场所","劳动对象"],"answer":1,"answerLetter":"B","explain":"货币转化为资本的关键在于能够带来剩余价值。劳动力商品具有独特的使用价值，它在使用过程中 不仅能创造出自身价值，还能创造出比自身价值更大的价值，即剩余价值。而劳动工具、劳动场所、劳动对 象只是生产过程中的物质要素，本身不能使货币转化为资本。"},{"id":"marx-4-74","globalId":368,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":74,"question":"检验认识的真理性，就是要检验人们的认识是否（ ）。","options":["与多数人的愿望和要求相符合","与已被实践证明的理论相符合","与客观事物及其规律相符合","与党的路线方针政策相符合"],"answer":2,"answerLetter":"C","explain":"真理是人们对客观事物及其规律的正确反映，检验认识的真理性，就是看认识是否与客观事物及其 规律相符合。多数人的愿望、已有的理论、党的路线方针政策都不能作为检验真理的标准，只有实践才能检 验认识是否符合客观事物及其规律。"},{"id":"marx-4-75","globalId":369,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":75,"question":"商品交换中价值与价格的关系表现为（ ）。","options":["价格总是高于价值","价格总是低于价值","价格总是等于价值","价格总是围绕价值上下波动"],"answer":3,"answerLetter":"D","explain":"价值是凝结在商品中的无差别的人类劳动，价格是价值的货币表现。在商品交换中，受供求关系等 因素影响，价格与价值并非总是相等。 当供大于求时，价格会低于价值；当供小于求时，价格会高于价值。 但从长期和总体来看，价格围绕价值上下波动，这是价值规律的表现形式。"},{"id":"marx-4-76","globalId":370,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":76,"question":"世界观是（ ）。","options":["人们对整个世界的根本看法和观点","人们对精神世界的根本看法和观点","人们对物质世界的根本看法和观点","人们对外部世界的根本看法和观点"],"answer":0,"answerLetter":"A","explain":"世界观是人们对整个世界以及人与世界关系的总的看法和根本观点，这里的世界既包括物质世界也 包括精神世界等，是整体的世界概念。答案选A 。"},{"id":"marx-4-77","globalId":371,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":77,"question":"劳动力的价值决定有一个重要特点,即（ ）。","options":["它由其生产的剩余价值决定","它由其使用价值决定","它包含历史和道德因素","它包含习惯和法律因素"],"answer":2,"answerLetter":"C","explain":"劳动力价值包括维持劳动者自身生存、养活家属及劳动者接受教育和训练所支出的费用。不同国家 或同一国家不同时期，因社会经济文化条件等不同，这些费用存在差异，所以劳动力价值包含历史和道德因 素。A选项，劳动力价值不是由剩余价值决定；B选项，使用价值不能决定劳动力价值；D选项习惯和法律因素 不是劳动力价值决定的重要特点。"},{"id":"marx-4-78","globalId":372,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":78,"question":"社会历史发展的动力有多种，但最基本的动力是（ ）。","options":["阶级斗争","社会改革","科学技术革命","社会基本矛盾"],"answer":3,"answerLetter":"D","explain":"社会基本矛盾（生产力和生产关系、经济基础和上层建筑的矛盾）贯穿于人类社会发展过程的始终 ，并规定了社会发展过程中各种社会形态、社会制度的基本性质，是推动社会发展的最基本动力。阶级斗争 是阶级社会发展的直接动力；社会改革是推动社会发展的又一重要动力；科学技术革命是推动经济和社会发 展的强大杠杆。答案选D。"},{"id":"marx-4-79","globalId":373,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":79,"question":"事物发展的动力和源泉是（ ）。","options":["事物的内部矛盾","事物的外部矛盾","事物的主要矛盾","矛盾的主要方面"],"answer":0,"answerLetter":"A","explain":"唯物辩证法认为，事物发展的动力和源泉是内部矛盾。内部矛盾是事物变化发展的根据，外部矛盾 是事物变化发展的条件，主要矛盾决定事物发展进程，矛盾主要方面决定事物性质。"},{"id":"marx-4-80","globalId":374,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":80,"question":"在苏维埃俄国提出并领导实施新经济政策的是（ ）。","options":["列宁","斯大林","布哈林","托洛斯基"],"answer":0,"answerLetter":"A","explain":"新经济政策是1921 年列宁领导苏维埃俄国开始实施的政策，旨在解决战时共产主义政策带来的危机 ，恢复和发展经济。答案：A。"},{"id":"marx-4-81","globalId":375,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":81,"question":"阶级消灭和国家消亡是在（ ）。","options":["社会主义革命中实现的","社会主义初级阶段实现的","无产阶级专政建立后实现的","共产主义社会实现的"],"answer":3,"answerLetter":"D","explain":"共产主义社会是人类最理想的社会形态，在共产主义社会，生产力高度发展，物质财富极大丰富 ，阶级对立和阶级差别将最终消失，作为阶级统治工具的国家也会自行消亡。而社会主义革命、社会主义初 级阶段以及无产阶级专政建立后，都还未达到阶级完全消灭和国家完全消亡的程度。"},{"id":"marx-4-82","globalId":376,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":82,"question":"社会意识具有复杂而精微的结构。从反映社会存在的程度和特点来看，社会意识包括","options":["社会心理和思想体系","意识形态和非意识形态","个体意识和群体意识","主流意识和非主流意识"],"answer":0,"answerLetter":"A","explain":"从反映社会存在的程度和特点看，社会意识分为社会心理和思想体系。社会心理是低层次、不系统 、不定型的社会意识；思想体系是高层次、系统化、理论化的社会意识。B选项是从对经济基础的关系角度划 分；C选项是从意识主体角度划分；D选项并非从反映社会存在程度和特点划分。"},{"id":"marx-4-83","globalId":377,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":83,"question":"斯密和李嘉图是（ ）。","options":["德国古典哲学的代表人物","英国古典政治经济学的代表人物","英国空想社会主义的代表人物","法国空想社会主义的代表人物"],"answer":1,"answerLetter":"B","explain":"斯密和李嘉图是英国古典政治经济学的重要代表人物，在政治经济学领域有着突出贡献。德国古典 哲学代表人物如康德等；空想社会主义代表人物如圣西门、傅立叶、欧文等。"},{"id":"marx-4-84","globalId":378,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":84,"question":"在运动和静止关系问题上，只承认绝对运动，否认相对静止的观点属于（ ）。","options":["唯物辩证法","形而上学","相对主义诡辩论","主观唯心主义"],"answer":2,"answerLetter":"C","explain":"相对主义诡辩论片面夸大事物的相对性，只承认绝对运动，否认相对静止，会导致对事物认识的不 确定性和随意性。唯物辩证法既承认绝对运动又承认相对静止；形而上学往往否认运动，只承认静止；主观 唯心主义强调主观精神决定一切，与运动静止关系无直接关联。"},{"id":"marx-4-85","globalId":379,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":85,"question":"揭示事物发展动力和源泉的规律是（ ）。","options":["对立统一规律","质量互变规律","内容和形式相互作用规律","否定之否定规律"],"answer":0,"answerLetter":"A","explain":"对立统一规律揭示了事物发展的动力和源泉。矛盾双方既对立又统一，推动事物的发展。质量互变 规律揭示事物发展的状态和形式；否定之否定规律揭示事物发展的方向和道路；内容和形式相互作用规律不 属于唯物辩证法三大规律，主要说明内容与形式的辩证关系。所以选A。"},{"id":"marx-4-86","globalId":380,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":86,"question":"利息率的变动区间是在（ ）。","options":["平均利润率和零之间","剩余价值和零之间","利润率和零之间","年剩余价值和零之间"],"answer":0,"answerLetter":"A","explain":"利息是平均利润的一部分，利息率不能高于平均利润率，否则职能资本家无利可图不会借贷；利息 率也不能为零，否则借贷资本所有者不会贷出资本。所以利息率变动区间在平均利润率和零之间。"},{"id":"marx-4-87","globalId":381,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":87,"question":"社会主义从一国向多国发展壮大起始于（ ）。","options":["第一次世界大战以后","第二次世界大战以后","中国社会主义革命以后","古巴社会主义革命以后"],"answer":1,"answerLetter":"B","explain":"第二次世界大战后，社会主义在世界范围内获得大发展，从一国实践发展为多国实践，形成了社会 主义阵营。所以社会主义从一国向多国发展壮大起始于第二次世界大战以后。"},{"id":"marx-4-88","globalId":382,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":88,"question":"提出社会主义革命同时胜利论的是（ ）。","options":["马克思恩格斯","列宁","斯大林","毛泽东"],"answer":0,"answerLetter":"A","explain":"马克思和恩格斯基于当时的历史条件，提出社会主义革命将在几个主要资本主义国家“同时发生 ”并取得胜利的理论。列宁根据帝国主义时代资本主义经济政治发展不平衡的规律，提出社会主义革命可能 在一国或数国首先取得胜利。斯大林、毛泽东主要是在社会主义建设等方面有诸多理论贡献。答案：A。"},{"id":"marx-4-89","globalId":383,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":89,"question":"在真理标准问题上坚持辩证法，就是要承认实践标准（ ）。","options":["既是抽象的又是具体的","既是必然的又是偶然的","既是普遍的又是特殊的","既是绝对的又是相对的"],"answer":3,"answerLetter":"D","explain":"实践作为检验真理的标准，具有确定性（绝对性）和不确定性（相对性）。确定性（绝对性）是指 实践是检验真理的唯一标准，凡经过实践证明了的一切认识都是客观真理，都具有不可推翻的性质；不确定 性（相对性）是指实践在一定历史条件下是有限的，具体的实践活动对于真理的检验具有一定的局限性。在 真理标准问题上坚持辩证法，就要看到实践标准的这两重属性，即既是绝对的又是相对的。"},{"id":"marx-4-90","globalId":384,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":90,"question":"杰出人物在历史上的作用表现为（ ）。","options":["定程度上推动社会的发展","摆脱历史条件的制约","改变历史发展的规律","决定历史时代的特点"],"answer":0,"answerLetter":"A","explain":"杰出人物能在一定程度上推动社会发展，A 正确；杰出人物不能摆脱历史条件制约，B 错；历史发 展规律具有客观性，无法改变，C 错；杰出人物不能决定历史时代特点，时代特点由当时的经济、政治等诸 多因素决定，D 错。"},{"id":"marx-4-91","globalId":385,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":91,"question":"两种商品可以按一定比例相互交换的原因，在于它们","options":["有不同的使用价值","都是具体劳动的产物","对人们有共同的效应","在生产中都耗费了一般的人类劳动"],"answer":3,"answerLetter":"D","explain":"两种商品能按一定比例交换，是因为它们具有价值，而价值是凝结在商品中的无差别的一般人类劳 动。选项A不同使用价值是商品交换的前提而非按比例交换原因；选项B具体劳动创造使用价值，不是按比例 交换的关键；选项C共同效应类似使用价值层面，不是按比例交换依据。选项D指出生产中耗费一般人类劳动 ，即具有价值，这才是能按比例交换的原因。"},{"id":"marx-4-92","globalId":386,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":92,"question":"社会主义的根本的和首要的任务是（ ）。","options":["解放和发展生产力","建立和完善社会主义公有制","建设社会主义的政治文明","建设社会主义的精神文明"],"answer":0,"answerLetter":"A","explain":"生产力是社会发展的最根本动力，社会主义本质是解放生产力，发展生产力，消灭剥削，消除两极 分化，最终达到共同富裕。所以社会主义根本和首要任务是解放和发展生产力。"},{"id":"marx-4-93","globalId":387,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":93,"question":"脱离实践的理论是空洞的理论；没有理论指导的实践是盲目的实践。这句话强调的是（ ）。","options":["认识过程中摹写与创造的统一","认识过程中感性与理性的统一","认识过程中真理与价值的统一","认识过程中理论与实践的统一"],"answer":3,"answerLetter":"D","explain":"题干前半句强调理论不能脱离实践，后半句强调实践需要理论指导，整体突出的是理论和实践相互 依存、不可分割，即认识过程中理论与实践的统一。"},{"id":"marx-4-94","globalId":388,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":94,"question":"在真理观上坚持辩证法,就必须承认（ ）。","options":["真理的内容是客观的,形式是主观的","真理既具有绝对性,又貝有相对性","真理既是正确的,又包含错误因素","真理既具有普遍性,又具有多样性检验"],"answer":1,"answerLetter":"B","explain":"辩证法强调用联系、发展、全面的观点看问题。在真理观上坚持辩证法，就是要看到真理是一个不 断发展的过程，具有两重属性，即绝对性和相对性。绝对真理和相对真理是相互依存、相互包含、相互转化 的，这体现了辩证法的观点。 选项A只是阐述了真理的客观性和主观性的方面，没有体现辩证法关于发展等 方面的要求。 选项C表述错误，真理和错误有明确界限，真理不包含错误因素。 选项D中真理普遍性表述不 准确，且真理多样性说法错误，真理是对客观事物及其规律的正确反映，不存在多样性的问题。"},{"id":"marx-4-95","globalId":389,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":95,"question":"借贷资本是（ ）。","options":["与产业资本、商业资本相同的职能资本","与商业资本、银行资本相同的流通资本","从职能资本运动中分离出来的特殊资本形式","与其他职能资本家获得同样利润的资本形式"],"answer":2,"answerLetter":"C","explain":"借贷资本是从职能资本（产业资本和商业资本）运动中分离出来的特殊资本形式，它不执行职能资 本那样的生产和实现剩余价值等职能。A选项说与职能资本相同错误；B选项中银行资本不是流通资本概念 ，且借贷资本与商业资本、银行资本性质不同；D选项借贷资本获得的是利息，职能资本家获得平均利润，二 者不同。"},{"id":"marx-4-96","globalId":390,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":96,"question":"金、银、铜、铁、铝等同金属的关系属于（ ）。","options":["部分与整体的关系","个别与一般的关系","现象与本质的关系","形式与内容的关系"],"answer":1,"answerLetter":"B","explain":"金、银、铜、铁、铝等是具体的金属种类，而金属是对它们共同属性的概括。个别金属体现了金属 这一“一般”概念的特征，所以它们是个别与一般的关系。答案选B。"},{"id":"marx-4-97","globalId":391,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":97,"question":"列宁称之为“社会主义的最充分的物质准备”、“社会主义的前阶”的是（ ）。","options":["自由竞争资本主义","私人垄断资本主义","国家垄断资本主义","国际垄断资本主义"],"answer":2,"answerLetter":"C","explain":"国家垄断资本主义阶段，国家对经济进行全面干预调节，使生产、资本等方面出现新变化，为社会 主义准备了更充分物质条件。私人垄断主要还是垄断组织自身发展，自由竞争资本主义离社会主义物质准备 更远，国际垄断资本主义是国家垄断发展的延伸，基础仍是国家垄断资本主义。所以列宁称国家垄断资本主 义是“社会主义的最充分的物质准备”“社会主义的前阶”。"},{"id":"marx-4-98","globalId":392,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":98,"question":"唯物辩证法的总特征有两个，一个是联系的观点，另一个是（ ）。","options":["发展的观点","对立统一的观点","实践的观点","辩证否定的观点"],"answer":0,"answerLetter":"A","explain":"唯物辩证法总特征是联系和发展，这是其区别于其他哲学的重要特点。对立统一是唯物辩证法实质 和核心；实践观点是马克思主义哲学首要的基本观点；辩证否定观是辩证法的内容之一，但非总特征。所以 应选发展的观点。"},{"id":"marx-4-99","globalId":393,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":99,"question":"在资本主义社会,垄断组织销售产品时多采取（ ）。","options":["垄断高价","垄断低价","社会生产价格","市场价格"],"answer":0,"answerLetter":"A","explain":"垄断组织目的是获取高额垄断利润，销售产品时会凭借其垄断地位尽可能抬高价格，多采取垄断高 价。"},{"id":"marx-4-100","globalId":394,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":100,"question":"唯物辩证法认为，发展的实质是（ ）。","options":["事物数量的增加","事物位置的移动","事物性质的变化","新事物的产生和旧事物的灭亡"],"answer":3,"answerLetter":"D","explain":"唯物辩证法中发展不是简单的数量增加、位置移动或性质变化，这些可能只是变化但不一定是发展 。发展强调的是事物由低级向高级、由简单向复杂、由无序向有序的前进和上升运动，其实质是新事物的产 生和旧事物的灭亡。"},{"id":"marx-4-101","globalId":395,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":101,"question":"在资本主义社会中,利润率是（ ）。","options":["剩余价值与可变资本的比率","剩余价值与不变资本的比率","剩余价值与预付总资本的比率","剩余价值与预付流通资本的比率"],"answer":2,"answerLetter":"C","explain":"利润率是剩余价值与预付总资本的比率。预付总资本包含不变资本和可变资本等。A选项剩余价值与 可变资本的比率是剩余价值率；B选项表述错误；D选项预付流通资本只是预付总资本一部分，不是利润率定 义。"},{"id":"marx-4-102","globalId":396,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":102,"question":"经济危机的周期爆发,使资本主义再生产也具有了周期性。资本主义再生产周期中决定性的阶段是（ ）。","options":["危机阶段","萧条阶段","复苏阶段","高涨阶段"],"answer":0,"answerLetter":"A","explain":"危机阶段是资本主义再生产周期的决定性阶段，它既是上一周期的终点，又是新周期的起点。在危 机阶段，经济矛盾集中爆发，生产急剧下降等。"},{"id":"marx-4-103","globalId":397,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":103,"question":"列宁所提出的社会主义革命在一国或数国首先胜利的理论立足于（ ）。","options":["马克思恩格斯的科学预言","巴黎公社原则","资本主义发展不平衡规律","生产力决定论"],"answer":2,"answerLetter":"C","explain":"列宁根据资本主义发展不平衡规律，得出社会主义革命在一国或数国首先胜利的结论。资本主义发 展不平衡使得有的国家发展较快，有的较慢，矛盾尖锐程度不同，从而为一国或数国首先胜利创造了条件。 马克思恩格斯认为社会主义革命将在几个主要资本主义国家同时发生，A选项不符；巴黎公社原则主要强调无 产阶级专政等方面，与本题联系不大，B排除；生产力决定论不能直接得出社会主义革命在一国或数国首先胜 利的结论，D排除。"},{"id":"marx-4-104","globalId":398,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":104,"question":"生产关系是指人们在物质生产过程中结成的（ ）。","options":["社会关系","经济关系","交往关系","竞争关系"],"answer":1,"answerLetter":"B","explain":"生产关系本质上是人们在物质生产过程中形成的经济关系。从概念定义出发，生产关系侧重经济层 面。"},{"id":"marx-4-105","globalId":399,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":105,"question":"唯物辩证法提供的最根本的认识方法是（ ）。","options":["逻辑分析法","阶级分析法","矛盾分析法","精神分析法"],"answer":2,"answerLetter":"C","explain":"唯物辩证法的实质和核心是对立统一规律，也就是矛盾规律。矛盾分析法是认识事物的根本方法 ，因为它揭示了事物发展的源泉和动力，贯穿于唯物辩证法其他规律和范畴之中。 逻辑分析法侧重于思维的 逻辑规则等，并非唯物辩证法最根本认识方法；阶级分析法是分析社会阶级关系等的方法，不属于唯物辩证 法范畴；精神分析法是心理学领域弗洛伊德等创立的分析精神层面的方法，和唯物辩证法无关。"},{"id":"marx-4-106","globalId":400,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":106,"question":"在资本主义社会中，银行资本家所获得的利润率水平（ ）。","options":["大体与借贷资本家获得的利息率水平相同","大体与职能资本家获得的平均利润率水平相同","大大高于职能资本家获得的平均利润率水平","大大低于职能资本家获得的平均利润率水平"],"answer":1,"answerLetter":"B","explain":"银行资本家投资于银行业，其目的也是获取利润，而且获得的利润也应相当于平均利润，这是由部 门之间的竞争和资本的自由转移实现的。所以银行资本家所获利润率大体与职能资本家获得的平均利润率水 平相同。"},{"id":"marx-4-107","globalId":401,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":107,"question":"决定股票价格的基本因素是（ ）。","options":["股息和贷款利息率","股息和汇率","股息和存款利息率","存款利息率和贷款利息率"],"answer":2,"answerLetter":"C","explain":"股票价格与股息成正比，与存款利息率成反比，股息和存款利息率是决定股票价格的基本因素。答 案：C"},{"id":"marx-4-108","globalId":402,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":108,"question":"列宁提出社会主义可能在一国或数国首先胜利的理论依据是（ ）。","options":["资本主义必然灭亡社会主义必然胜利的规律","帝国主义时代资本主义政治经济发展不平衡的规律","资本主义国家无产阶级与资产阶级斗争的规律","生产关系必须适合生产力发展要求的规律"],"answer":1,"answerLetter":"B","explain":"列宁依据帝国主义时代资本主义政治经济发展不平衡的规律，得出社会主义可能在一国或数国首先 胜利的结论。资本主义政治经济发展不平衡使得一些国家相对薄弱，为社会主义革命突破提供了机会。答案 ：B"},{"id":"marx-4-109","globalId":403,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":109,"question":"生产力发展水平的主要标志是（ ）。","options":["生产工具","运输工具","通讯设备","包装设备"],"answer":0,"answerLetter":"A","explain":"生产工具直接作用于劳动对象，它的发展水平是衡量生产力发展水平的客观尺度，是生产力发展水 平的主要标志。而运输工具、通讯设备、包装设备等只是生产过程中的辅助工具或设备，不能像生产工具那 样直接体现生产力的核心发展程度。"},{"id":"marx-4-110","globalId":404,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":110,"question":"唯物辩证法有两个总特征，一个是普遍联系的观点，另一个是（ ）。","options":["质量互变的观点","永恒发展的观点","对立统一的观点","辩证否定的观点"],"answer":1,"answerLetter":"B","explain":"唯物辩证法的两个总特征是普遍联系和永恒发展。质量互变、对立统一、辩证否定是唯物辩证法的 规律和范畴，并非总特征。"},{"id":"marx-4-111","globalId":405,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":111,"question":"真理的发展是一个（ ）。","options":["从主观真理走向客观真理的过程","从局部真理走向全面真理的过程","从具体真理走向抽象真理的过程","从相对真理走向绝对真理的过程"],"answer":3,"answerLetter":"D","explain":"真理具有相对性和绝对性，是相对性和绝对性的统一。真理的发展就是不断从相对真理走向绝对真 理的过程。不存在主观真理，A 错；真理并非简单从局部到全面，B 不准确；真理是具体的，不存在从具体 走向抽象，C 错。"},{"id":"marx-4-112","globalId":406,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":112,"question":"决定利息量的因素是（ ）。","options":["银行自有资本总额和平均利润率","银行自有资本总额和利息率","借贷资本总额和平均利润率","借贷资本总额和利息率"],"answer":3,"answerLetter":"D","explain":"利息量取决于借贷资本总额和利息率，利息量=借贷资本总额×利息率 。平均利润率影响的是利率 的高低范围等，但不是直接决定利息量的因素；银行自有资本总额与利息量计算并无直接关系。"},{"id":"marx-4-113","globalId":407,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":113,"question":"垄断的工业资本和垄断的银行资本融合或混合生长所构成的资本是（ ）。","options":["股份资本","金融资本","商业资本","虚拟资本"],"answer":1,"answerLetter":"B","explain":"金融资本就是垄断的工业资本和垄断的银行资本融合或混合生长构成的资本。A选项股份资本是通过 发行股票的方式筹集起来的企业资本；C选项商业资本是从产业资本中分离出来，专门从事商品买卖，独立发 挥资本职能的资本；D选项虚拟资本是以有价证券形式存在，并能给持有者带来一定收益的资本。"},{"id":"marx-4-114","globalId":408,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":114,"question":"生产力范畴反映的是（ ）。","options":["人与人之间的经济关系","人与人之间的政治关系","人与自然之间的关系","人与人之间的思想关系"],"answer":2,"answerLetter":"C","explain":"生产力是人类利用自然、改造自然的能力，所以它反映的是人与自然之间的关系。"},{"id":"marx-4-115","globalId":409,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":115,"question":"唯物辩证法有两个总特征，一个是永恒发展的观点，另一个是（ ）。","options":["普遍联系的观点","对立统一的观点","质量互变的观点","辩证否定的观点"],"answer":0,"answerLetter":"A","explain":"唯物辩证法总特征是普遍联系和永恒发展，所以另一个总特征就是普遍联系的观点。"},{"id":"marx-4-116","globalId":410,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":116,"question":"真理都是具体的,包罗万象的真理是不存在的。这说明任何真理都具有（ ）。","options":["全面性","相对性","绝对性","客观性"],"answer":1,"answerLetter":"B","explain":"真理的相对性表明真理是有条件的、有限的。因为真理都是具体的，不是包罗万象的，意味着真理 在广度和深度上都是有限的，有其适用范围，这体现了真理的相对性。 全面性不是真理的特性；真理绝对性 强调真理的客观性和世界可知性等，与题干表述不符；客观性指真理内容是客观的，题干强调的不是客观性 。"},{"id":"marx-4-117","globalId":411,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":117,"question":"决定人口生产的发展方向和基本趋势的是（ ）。","options":["地理环境","物质生产","风俗习惯","人伦道德"],"answer":1,"answerLetter":"B","explain":"物质生产从根本上决定了人口生产的发展方向和基本趋势，物质生产方式制约着人口生产的社会形 式、人口数量和质量等。地理环境、风俗习惯、人伦道德虽对人口生产有影响，但并非起决定作用。"},{"id":"marx-4-118","globalId":412,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":118,"question":"垄断的工业资本和银行资本融合生长构成（ ）。","options":["国家垄断资本","金融资本","私人垄断资本","借贷资本"],"answer":1,"answerLetter":"B","explain":"垄断的银行资本和垄断的工业资本融合生长，形成金融资本。"},{"id":"marx-4-119","globalId":413,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":119,"question":"生产要素的购买时间属于资本周转过程中的（ ）。","options":["生产时间","流通时间","劳动时间","停工时间"],"answer":1,"answerLetter":"B","explain":"资本周转过程包括生产时间和流通时间。生产要素购买是在市场上进行，属于资本处于流通领域的 活动，所以生产要素的购买时间属于流通时间。"},{"id":"marx-4-120","globalId":414,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":120,"question":"唯物辩证法与形而上学根本对立和斗争的焦点在于，是否承认（ ）。","options":["联系具有复杂多样性","新事物必然战胜旧事物","质变是量变的必然结果","矛盾是事物发展的动力"],"answer":3,"answerLetter":"D","explain":"唯物辩证法和形而上学的根本对立焦点在于对事物发展动力的不同看法。唯物辩证法认为矛盾是事 物发展的动力，而形而上学否认矛盾的存在。A选项联系的复杂多样性、B选项新事物战胜旧事物、C选项质变 与量变关系，都不是二者对立焦点。"},{"id":"marx-4-121","globalId":415,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":121,"question":"生产资料的购买时间属于（ ）。","options":["运输时间","劳动时间","非劳动时间","流通时间"],"answer":3,"answerLetter":"D","explain":"流通时间是指产业资本停留在流通领域内的时间，包括购买时间和销售时间。生产资料购买属于产 业资本在流通领域的活动，所以生产资料的购买时间属于流通时间。 运输时间是产品运输过程的时间，与生 产资料购买时间概念不同；劳动时间是劳动者运用劳动资料作用于劳动对象生产出某种产品所需要的时间 ，和购买生产资料时间无关；非劳动时间包含自然力独立作用于劳动对象的时间等，也不涉及生产资料购买 时间。"},{"id":"marx-4-122","globalId":416,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":122,"question":"唯物辩证法与形而上学在真理观上的对立，表现在是否承认（ ）。","options":["真理具有客观性","真理具有相对性","真理中包含着错误","真理来源于主观创造"],"answer":1,"answerLetter":"B","explain":"唯物辩证法坚持用联系、发展、全面的观点看问题，形而上学用孤立、静止、片面的观点看问题。 在真理观上，唯物辩证法认为真理是发展的，具有相对性，是不断发展变化的，这体现了辩证法发展的观点 。而形而上学往往把真理看成是绝对不变的。 A选项真理具有客观性是唯物主义真理观都承认的，不是唯物 辩证法与形而上学在真理观上的对立点。 C选项真理和错误有严格界限，真理中不包含错误，该说法本身错 误。 D选项真理来源于实践，而不是主观创造，该说法错误。"},{"id":"marx-4-123","globalId":417,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":123,"question":"真理是没有阶级性的，在真理面前人人平等。这是因为（ ）。","options":["真理就是客观规律，与人的阶级地位无关","真理具有客观性，包含着不依赖于人类的客观内容","真理是绝对性和相对性的统一，是不断发展的","真理是具体的，都有其适用的条件和范围"],"answer":1,"answerLetter":"B","explain":"真理具有客观性，它包含着不依赖于主体、不依赖于人类的客观内容，正是因为这种客观性，决定 了真理没有阶级性，在真理面前人人平等。A选项真理并不完全等同于客观规律；C选项真理绝对性和相对性 统一强调的是真理的发展特性，与在真理面前人人平等的原因无关；D选项真理的具体性强调适用条件范围 ，也不是在真理面前人人平等的原因。"},{"id":"marx-4-124","globalId":418,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":124,"question":"科学社会主义思想史上的第一个纲领性文件是（ ）。","options":["《德意志意识形态》","《关于费尔巴哈的提纲》","《共产党宣言》","《哥达纲领批判》"],"answer":2,"answerLetter":"C","explain":"《共产党宣言》是科学社会主义思想史上第一个纲领性文件，它系统阐述了科学社会主义理论，为 无产阶级运动提供了科学理论指导 。而A选项《德意志意识形态》主要是阐述历史唯物主义；B选项《关于费 尔巴哈的提纲》是马克思主义新世界观的天才萌芽；D选项《哥达纲领批判》批判拉萨尔主义，进一步丰富了 科学社会主义学说。答案：C 。"},{"id":"marx-4-125","globalId":419,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":125,"question":"马克思主义把人类社会的发展划分为五种社会形态，这种划分法所依据的标准是（ ）。","options":["意识形态的不同性质","生产关系的不同性质","生产力的不同水平","人的发展的不同状况"],"answer":1,"answerLetter":"B","explain":"马克思主义以生产关系的不同性质为标准，将人类社会发展划分为原始社会、奴隶社会、封建社会 、资本主义社会、共产主义社会五种社会形态。生产力是根本决定力量，但划分社会形态依据的直接标准是 生产关系。"},{"id":"marx-4-126","globalId":420,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":126,"question":"剩余价值的唯一源泉是工人的（ ）。","options":["具体劳动","必要劳动","个别劳动","剩余劳动"],"answer":3,"answerLetter":"D","explain":"剩余价值是雇佣工人所创造的并被资本家无偿占有的超过劳动力价值的那部分价值。工人的剩余劳 动是创造剩余价值的源泉，具体劳动创造使用价值，必要劳动补偿劳动力价值，个别劳动不直接与剩余价值 的产生有特定联系。"},{"id":"marx-4-127","globalId":421,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":127,"question":"下列不属于当代资本主义国家经济结构新变化的是（ ）。","options":["高科技产业的大发展","产业工人的大幅增加","第三产业的大发展","信息产业的兴起"],"answer":1,"answerLetter":"B","explain":"当代资本主义国家经济结构新变化主要体现在高科技产业、第三产业、信息产业等兴起和发展。随 着科技进步与产业结构调整，产业工人数量是逐渐减少而非大幅增加。答案选B。"},{"id":"marx-4-128","globalId":422,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":128,"question":"正确认识和评价杰出人物的历史作用,应该坚持（ ）。","options":["历史主义的原则和精神分析的方法","现实主义的原则和精神分析的方法","历史主义的原则和阶级分析的方法","现实主义的原则和阶级分析的方法"],"answer":2,"answerLetter":"C","explain":"评价杰出人物历史作用，需将其置于特定历史背景，这就是历史主义原则；同时，在阶级社会中 ，人物活动受阶级制约，所以要用阶级分析方法。精神分析主要用于心理学领域，现实主义原则与评价杰出 人物历史作用关联不大。"},{"id":"marx-4-129","globalId":423,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":129,"question":"马克思主义的革命性既表现为它具有彻底的批判精神，又表现为它具有","options":["完整的理论体系","严密的逻辑结构","鲜明的政治立场","崇高的社会理想"],"answer":2,"answerLetter":"C","explain":"马克思主义的革命性，集中表现为它的彻底的批判精神和鲜明的政治立场。马克思主义代表无产阶 级和广大人民的根本利益，具有鲜明政治立场，这与革命性紧密相关。而完整理论体系、严密逻辑结构体现 的是马克思主义科学性等方面，崇高社会理想主要强调对未来社会的构想，并非直接体现革命性。"},{"id":"marx-4-130","globalId":424,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":130,"question":"剩余价值转化为利润，是由于把剩余价值看作是（ ）。","options":["不变资本的产物","可变资本的产物","全部预付资本的产物","全部所费资本的产物"],"answer":2,"answerLetter":"C","explain":"当把剩余价值看作是全部预付资本（包括不变资本和可变资本）的产物时，剩余价值就转化为利润 。因为资本家投入的全部预付资本都参与生产过程，他们会认为利润是所有投入资本带来的，而不是仅把可 变资本看作产生剩余价值的唯一因素。不变资本在生产中不发生价值增殖，可变资本才是产生剩余价值的源 泉，但资本家不这么认为，他们把剩余价值当成全部预付资本带来的收益。"},{"id":"marx-4-131","globalId":425,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":131,"question":"垄断利润的真正来源于（ ）。","options":["垄断行为所创造的更多市场价值","垄断势力在自由市场上的巧取豪夺","工人阶级和劳动人民所创造的剩余价值","生产和非生产领域劳动者共同创造的物质财富"],"answer":2,"answerLetter":"C","explain":"垄断利润归根结底来自工人阶级和劳动人民所创造的剩余价值。垄断企业通过垄断价格出售产品等 手段，将其他企业工人创造的一部分剩余价值和小生产者创造的一部分价值转化为垄断利润，同时还包括对 本国无产阶级和其他劳动人民剥削的加强获得更多剩余价值。"},{"id":"marx-4-132","globalId":426,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":132,"question":"马克思主义的根本理论特征是（ ）。","options":["科学性和革命性的统","逻辑性和历史性的统","自然观和历史观的统","世界观和方法论的统"],"answer":0,"answerLetter":"A","explain":"马克思主义具有科学性，它是对客观世界特别是人类社会本质和规律的正确反映；同时具有革命性 ，它是无产阶级和广大人民群众推翻旧世界、建设新世界的理论，科学性与革命性的统一是马克思主义的根 本理论特征。"},{"id":"marx-4-133","globalId":427,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":133,"question":"剩余价值转化为利润后，商品价值表现为（ ）。","options":["不变资本与可变资本之和","不变资本与剩余价值之和","生产成本与利润之和","生产成本与平均利润之和"],"answer":2,"answerLetter":"C","explain":"当剩余价值转化为利润后，商品价值原本的“不变资本 + 可变资本 + 剩余价值”形式，就表现为 “生产成本（不变资本 + 可变资本） + 利润”。"},{"id":"marx-4-134","globalId":428,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":134,"question":"下列各项不属于共产主义社会基本特征的是（ ）。","options":["生产力高度发展和物质财富极大丰富","实行社会公有制和按需分配","计划经济和市场经济相结合","人的自由而全面发展"],"answer":2,"answerLetter":"C","explain":"共产主义社会生产力高度发达，物质财富极大丰富，实行社会公有制，按需分配，人的自由全面发 展是共产主义社会中人的发展状态。而计划经济与市场经济相结合是社会主义经济体制特点，并非共产主义 社会基本特征。"},{"id":"marx-4-135","globalId":429,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":135,"question":"直接经验和间接经验的关系是（ ）。","options":["认识中内容和形式的关系","认识中“源”和“流”的关系","感性认识和理性认识的关系","实践和理论的关系"],"answer":1,"answerLetter":"B","explain":"直接经验是通过亲身实践获得的知识，间接经验是从他人或书本等途径获取的知识。实践是认识的 来源，直接经验是认识的“源”，间接经验归根结底也源于实践，是认识的“流”。"},{"id":"marx-4-136","globalId":430,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":136,"question":"垄断利润和垄断价格的出现","options":["使价值规律在某些领域不起作用","使价值规律作用的形式发生变化","否定了价值规律","改变了价值规律的内涵"],"answer":1,"answerLetter":"B","explain":"价值规律是商品经济的基本规律，只要存在商品生产和商品交换，价值规律就必然起作用。垄断利 润和垄断价格的出现，并没有否定价值规律，也没有改变价值规律的内涵。 只是在垄断条件下，价值规律作 用的形式发生了变化，即市场价格围绕垄断价格上下波动。"},{"id":"marx-4-137","globalId":431,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":137,"question":"马克思主义的最高社会理想是（ ）。","options":["消灭等级制度，实现人人平等","推翻资本主义，实现共产主义","消灭贫富悬殊，实行平均主义","取消按资分配，实行按劳分配"],"answer":1,"answerLetter":"B","explain":"马克思主义致力于实现以劳动人民为主体的最广大人民的根本利益，其最高社会理想是推翻资本主 义，实现共产主义，共产主义社会是物质财富极大丰富、人民精神境界极大提高、每个人自由而全面发展的 社会。A选项“消灭等级制度，实现人人平等”不够全面准确表述马克思主义最高理想；C选项“平均主义 ”不符合马克思主义理念，共产主义并非平均主义；D选项“取消按资分配，实行按劳分配”只是共产主义社 会分配方式的描述，不能完整概括最高理想。"},{"id":"marx-4-138","globalId":432,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":138,"question":"时间和空间既是绝对的、无限的是相对的、有限的。这是一种","options":["诡辩论的观点？？？","辩证唯物主义的观点","实用至受的观点？？？","形而上学的观点"],"answer":1,"answerLetter":"B","explain":"辩证唯物主义认为时间和空间是绝对性与相对性、无限性与有限性的辩证统一。一方面，时间和空 间作为物质运动的存在形式，它们的客观实在性是不变的、无条件的，因而是绝对的；物质世界在时间和空 间上又是无限的。另一方面，时间和空间的具体特性受物质运动的具体特性所制约，是随着物质运动的变化 而变化的，因而是相对的；具体事物在时间和空间上又是有限的。 诡辩论往往片面夸大相对性而否定绝对性 等；实用主义主要强调有用即真理；形而上学用孤立、静止、片面的观点看问题，均不符合对时空这种辩证 认识。"},{"id":"marx-4-139","globalId":433,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":139,"question":"下列各项既属于不变资本又属于流动资本的是（ ）。","options":["以生产工具形式存在的资本","以劳动对象形式存在的资本","以劳动力形式存在的资本","以厂房设备形式存在的资本"],"answer":1,"answerLetter":"B","explain":"不变资本是指在生产过程中不改变自己价值量的资本，可变资本是改变价值量的资本，劳动力属于 可变资本，所以C排除。 流动资本是一次投入、一次收回，固定资本是多次投入、多次收回。生产工具、厂 房设备属于固定资本，A、D排除。 劳动对象是一次投入生产过程，价值一次性转移，既属于不变资本（不改 变价值量）又属于流动资本（一次投入一次收回）。"},{"id":"marx-4-140","globalId":434,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":140,"question":"纸上得来终觉浅，绝知此事要躬行。”这句话强调的是（ ）。","options":["直接经验是知识的唯一来源","书本知识是根本不可靠的","间接经验是知识的唯一来源","真理是在实践中检验和发展的"],"answer":3,"answerLetter":"D","explain":"“纸上得来终觉浅，绝知此事要躬行”意思是从书本上获取的知识比较浅显，要透彻地认识事物还 必须亲自实践。这突出了实践对认识的重要性，真理需要在实践中去检验和发展。A选项直接经验不是知识唯 一来源，还有间接经验；B选项书本知识并非根本不可靠；C选项间接经验不是唯一来源。"},{"id":"marx-4-141","globalId":435,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":141,"question":"马克思主义认识论认为，真理的发展是一个（ ）。","options":["从主观真理走向客观真理的过程","从局部真理走向全面真理的过程","从相对真理走向绝对真理的过程","从具体真理走向抽象真理的过程"],"answer":2,"answerLetter":"C","explain":"马克思主义认识论认为，真理具有相对性和绝对性，是二者的统一。真理的发展是不断从相对真理 走向绝对真理的过程。相对真理是指在一定条件下对事物的一定程度、一定层次的正确认识，它有待于扩展 和深化；绝对真理是指真理的无条件性、无限性。人类认识是一个不断深化的过程，是从相对真理走向绝对 真理、接近绝对真理的永无止境的过程。 A选项，真理本身就是客观的，不存在从主观真理走向客观真理。 B选项，局部真理走向全面真理表述不准确，不是马克思主义关于真理发展的核心观点。 D选项，真理是具体 的，不是从具体走向抽象，这种表述错误。"},{"id":"marx-4-142","globalId":436,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":142,"question":"实践作为检验真理的标准，既具有确定性，又具有（ ）。","options":["普遍性","特殊性","不确定性","绝对性"],"answer":2,"answerLetter":"C","explain":"实践作为检验真理的标准具有确定性（绝对性）和不确定性（相对性）。确定性是指实践是检验真 理的唯一标准等；不确定性指实践对真理的检验是一个过程，受一定历史条件制约等。所以这里应选不确定 性。"},{"id":"marx-4-143","globalId":437,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":143,"question":"下列各项属于技术社会形态序列的是（ ）。","options":["原始社会","农业社会","封建社会","资本主义社会"],"answer":1,"answerLetter":"B","explain":"技术社会形态是以生产力和技术发展水平以及与此相适应的产业结构为标准划分的社会形态。农业 社会是按照技术发展水平及产业结构划分的，是以农业技术和农业产业为主导的社会形态。 而原始社会、封 建社会、资本主义社会属于以生产关系性质为标准划分的社会形态，即经济社会形态序列。"},{"id":"marx-4-144","globalId":438,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":144,"question":"中国共产党的思想路线的核心是（ ）。","options":["一切从实际出发","理论联系实际","实事求是","在实践中检验真理和发展真理"],"answer":2,"answerLetter":"C","explain":"中国共产党的思想路线是一切从实际出发，理论联系实际，实事求是，在实践中检验真理和发展真 理。其中，实事求是是党的思想路线的核心，它贯穿于思想路线的各个方面 ，其他三个方面都围绕“实事求 是”展开。"},{"id":"marx-4-145","globalId":439,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":145,"question":"垄断资本实现其经济上统治的方式是（ ）。","options":["股份制","合作制","垄断制","参与制"],"answer":3,"answerLetter":"D","explain":"垄断资本在经济上统治主要是通过“参与制”实现的，“参与制”是指金融寡头通过掌握一定数量 的股票来层层控制企业的制度。"},{"id":"marx-4-146","globalId":440,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":146,"question":"实现共产主义社会的根本条件和基础是（ ）。","options":["社会生产力的高度发展","人与人关系的高度和谐","人的思想觉悟的极大提高","自然生态环境的极大改善"],"answer":0,"answerLetter":"A","explain":"生产力决定生产关系，经济基础决定上层建筑。共产主义是一种更高级的社会形态，要实现它，需 要有坚实的物质基础，这就依赖于社会生产力的高度发展。只有生产力高度发展，才能为共产主义社会的建 立提供足够的物质财富等条件。"},{"id":"marx-4-147","globalId":441,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":147,"question":"下列各项属于因果联系的是（ ）。","options":["风来雨至,电闪雷鸣","冬去春来,夏尽秋至","摩擦生热,热胀冷缩","夜尽昼至,昼尽夜来"],"answer":2,"answerLetter":"C","explain":"因果联系是指事物之间存在引起和被引起的关系。 A选项中，风来雨至、电闪雷鸣，风不是雨产生 的必然原因，电闪和雷鸣也并非严格因果关系，它们常是伴随大气变化等其他因素同时出现。 B选项冬去春 来、夏尽秋至，以及D选项夜尽昼至、昼尽夜来，这些都是地球公转、自转引起的周期性自然现象，并非因果 联系中那种严格的引起和被引起关系。 C选项摩擦生热，摩擦是生热的原因，热胀冷缩中温度变化是物体体 积变化的原因，存在引起和被引起的关系，属于因果联系。"},{"id":"marx-4-148","globalId":442,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":148,"question":"资本的价值构成是指（ ）。","options":["固定资本和流动资本的比例","所用资本和所费资本的比例","生产资料和劳动力的比例","不变资本和可变资本的比例"],"answer":3,"answerLetter":"D","explain":"资本价值构成是指资本在价值形态上由不变资本和可变资本所构成的数量比例。C选项生产资料和劳 动力的比例是资本的技术构成。A选项固定资本和流动资本是按资本周转方式划分。B选项所用资本和所费资 本比例与资本构成概念不同。"},{"id":"marx-4-149","globalId":443,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":149,"question":"资本的有机构成可表示为（ ）。","options":["c v","m c","m","m v"],"answer":0,"answerLetter":"A","explain":"【标准答案：A】"},{"id":"marx-4-150","globalId":444,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":150,"question":"垄断资本主义国家事实上的主宰者是（ ）。","options":["产业资本家","商业资本家","大土地所有者","金融寡头"],"answer":3,"answerLetter":"D","explain":"在垄断资本主义阶段，金融寡头凭借其在经济领域的统治地位进而掌控国家政权等各方面，成为垄 断资本主义国家事实上的主宰者。产业资本家、商业资本家、大土地所有者都不具备这样全面主宰的地位。"},{"id":"marx-4-151","globalId":445,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":151,"question":"马克思主义认为，世界的真正统一性在于它的（ ）。","options":["广延性","存在性","物质性","可知性"],"answer":2,"answerLetter":"C","explain":"马克思主义哲学认为，纷繁复杂、无限多样的世界具有共同的本质，即物质性，世界统一于物质。 广延性是物质的一种属性，不能等同于世界统一性；存在性概念宽泛，不能准确体现世界统一基础；可知性 强调人对世界的认识，与世界统一性无关。"},{"id":"marx-4-152","globalId":446,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":152,"question":"人们正确发挥主观能动作用的根本途径是（ ）。","options":["认识客观规律","制定周密计划","依靠广大群众","参加社会实践"],"answer":3,"answerLetter":"D","explain":"社会实践是人类认识和改造世界的基础活动。只有通过社会实践，人们才能接触到客观事物，进而 认识客观规律，并将对规律的认识应用于改造世界的活动中，正确发挥主观能动作用。认识客观规律只是前 提，制定周密计划要基于实践，依靠广大群众也要通过实践来实现主观能动作用的发挥。"},{"id":"marx-4-153","globalId":447,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":153,"question":"唯物史观认为，地理环境是（ ）。","options":["社会物质生活的必要条件？","经济社会形态的划分依据？","社会形态更替的决定力量？","技术社会形态的划分依据"],"answer":0,"answerLetter":"A","explain":"地理环境是社会存在和发展的必要条件，为人类提供生存和发展的自然条件，影响生产部门的分布 和发展方向等。经济社会形态划分依据是生产关系，社会形态更替决定力量是生产力与生产关系、经济基础 与上层建筑的矛盾运动，技术社会形态划分依据是生产力和技术发展水平。所以选A。"},{"id":"marx-4-154","globalId":448,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":154,"question":"下列各项正确说明意识本质的是（ ）。","options":["意识是人脑对客观世界的反映","意识是独立于物质的精神实体","意识是人的纯粹主观创造","意识是感性认识和理性认识的产物"],"answer":0,"answerLetter":"A","explain":"意识的本质是客观内容和主观形式的统一，是人脑对客观世界的反映。 B选项，意识依赖于物质 ，不能独立于物质存在，所以B错误。 C选项，意识不是纯粹主观创造的，它来源于客观世界，所以C错误。 D选项，意识是物质世界长期发展的产物，也是社会实践的产物，并非感性认识和理性认识的产物，所以D错 误。"},{"id":"marx-4-155","globalId":449,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":155,"question":"资本国际化进程大体是（ ）。","options":["从货币资本、生产资本到商品资本的国际化","从借贷资本、产业资本到商业资本的国际化","从商业资本、借贷资本到产业资本的国际化","从商品资本、货币资本到生产资本的国际化"],"answer":2,"answerLetter":"C","explain":"资本国际化是资本主义生产方式发展到一定阶段的必然现象，其进程是与资本主义发展阶段相适应 的。在资本主义发展过程中，商业资本首先实现国际化，随着资本主义发展，借贷资本走向国际化，到了垄 断资本主义阶段，产业资本大规模国际化。"},{"id":"marx-4-156","globalId":450,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":156,"question":"人民群众创造历史的活动受历史条件的制约。这种观点是说（ ）。","options":["人民群众不能推动社会形态的更替","人民群众不能随心所欲地创造历史","人民群众不是社会发展的决定力量","人民群众不是社会历史活动的主体"],"answer":1,"answerLetter":"B","explain":"人民群众创造历史活动受历史条件制约，意味着其创造活动不能脱离当时的历史环境，不能随心所 欲。A选项人民群众是推动社会形态更替的重要力量；C选项人民群众是社会发展的决定力量；D选项人民群众 是社会历史活动的主体。"},{"id":"marx-4-157","globalId":451,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":157,"question":"唯物史观认为，杰出人物的出现是（ ）。","options":["历史命运的安排","纯粹的历史必然","时代发展的需要","纯粹的历史偶然"],"answer":2,"answerLetter":"C","explain":"唯物史观强调，杰出人物是适应时代发展需要而产生的。时代发展面临特定任务与矛盾，需要杰出 人物引领推动。杰出人物的出现既非命运安排这种唯心说法，也不是纯粹必然或偶然，而是必然性与偶然性 的统一，其中时代发展的需要这一必然性起关键作用。"},{"id":"marx-4-158","globalId":452,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":158,"question":"下列各项中，强调认识来源于实践的是？","options":["不积跬步，无以至千里？","蝉噪林愈静，鸟鸣山更幽","不积小流，无以成江海？","近水知鱼性，近山识鸟音"],"answer":3,"answerLetter":"D","explain":"A和C选项强调积累的重要性；B选项体现的是矛盾的对立统一；D选项“近水知鱼性，近山识鸟音 ”意思是靠近水才能了解鱼的习性，靠近山才能识别鸟的声音，说明要通过实践（接近水和山这些实践活动 ）才能获得对鱼性和鸟音的认识，强调认识来源于实践。"},{"id":"marx-4-159","globalId":453,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":159,"question":"资本家提高劳动生产率的直接目的是（ ）。","options":["生产绝对剩余价值","获取超额剩余价值","生产相对剩余价值","降低劳动力价值"],"answer":1,"answerLetter":"B","explain":"个别资本家提高劳动生产率，使自己商品的个别价值低于社会价值，从而在竞争中获得额外的剩余 价值，即超额剩余价值。 生产绝对剩余价值主要靠延长工作日等手段，不是提高劳动生产率的直接目的。 相对剩余价值是整个社会劳动生产率提高的结果，不是个别资本家提高劳动生产率的直接目的。 降低劳动力 价值是整个社会劳动生产率提高带来的，不是个别资本家提高劳动生产率的直接目的。"},{"id":"marx-4-160","globalId":454,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":160,"question":"垄断资本主义为向社会主义过渡准备的物质基础是（ ）。","options":["资本主义议会制度","国家管理经济职能","社会化大生产","经济全球化"],"answer":2,"answerLetter":"C","explain":"垄断资本主义时期，生产社会化、资本社会化和管理社会化都达到了很高程度，为向社会主义过渡 准备了最充分的物质基础即社会化大生产。资本主义议会制度是政治形式，与物质基础无关；国家管理经济 职能是一种手段，并非物质基础；经济全球化是世界经济发展趋势，不是向社会主义过渡的物质基础。答案 ：C"},{"id":"marx-4-161","globalId":455,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":161,"question":"人民群众是历史的创造者。这是因为人民群众是社会变革的决定力量，还因为（ ）。","options":["人民群众是社会物质财富和精神财富的创造者","人民群众的一切活动都能推动历史进步","人民群众的愿望要求都是天然合理的","民群众的活动是不受历史条件制约的"],"answer":0,"answerLetter":"A","explain":"人民群众是历史创造者，体现在他们是社会物质财富和精神财富创造者，同时是社会变革决定力量 ，A选项正确。B中“一切活动”表述错误，部分活动可能违背历史发展规律，不能推动进步；C“愿望要求都 是天然合理”过于绝对，有的不合理；D人民群众活动受历史条件制约。"},{"id":"marx-4-162","globalId":456,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":162,"question":"唯物史观认为，人的本质在其现实性上是（ ）。","options":["人的价值追求","人的政治立场","人的情感态度","人的一切社会关系的总和"],"answer":3,"answerLetter":"D","explain":"唯物史观强调人的本质不是单个人所固有的抽象物，在其现实性上，它是一切社会关系的总和。这 一观点从社会关系的角度全面、深刻地揭示了人的本质，而A选项人的价值追求、B选项人的政治立场、C选项 人的情感态度都只是人的某一方面特征，不能全面涵盖人的本质。"},{"id":"marx-4-163","globalId":457,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":163,"question":"下列各项中，属于辩证唯物主义认识论区别于旧唯物主义认识论的观点是（ ）。","options":["认识客体具有客观性的观点","认识是主体对客体的反映的观点","物质世界可以认识的观点","实践是认识的基础的观点"],"answer":3,"answerLetter":"D","explain":"辩证唯物主义认识论强调实践是认识的基础，实践对认识具有决定作用，这是旧唯物主义认识论所 没有的。旧唯物主义认识论不懂得实践在认识中的作用。A、B、C选项是二者共有的观点。"},{"id":"marx-4-164","globalId":458,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":164,"question":"唯物主义认识论和唯心主义认识论的根本区别是（ ）。","options":["前者是可知论,后者是不可知论","前者是能动反映论,后者是机械反映论","前者是反映论,后者是先验论","前者是唯理论,后者是经验论"],"answer":2,"answerLetter":"C","explain":"唯物主义认识论坚持反映论，认为认识是主体对客体的反映，认识来源于客观世界。 唯心主义认 识论坚持先验论，认为认识先于物质、先于实践经验，是先天就有的。这是二者的根本区别。"},{"id":"marx-4-165","globalId":459,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":165,"question":"意识对于人的生理活动具有一定影响作用，这表明（ ）。","options":["意识对物质具有能动性","意识是客观事物本身","意识对物质具有决定性","意识是人脑的机能"],"answer":0,"answerLetter":"A","explain":"意识对人的生理活动有影响，体现了意识能够反作用于人体生理，这是意识对物质具有能动作用的 表现之一。B选项意识不是客观事物本身，是对客观事物的主观反映；C选项物质决定意识，不是意识决定物 质；D选项意识是人脑机能表述正确，但与题干强调的意识对生理活动影响这一能动作用不符。"},{"id":"marx-4-166","globalId":460,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":166,"question":"资本循环中起决定性作用的阶段是（ ）。","options":["购买阶段","生产阶段","销售阶段","流通阶段"],"answer":1,"answerLetter":"B","explain":"资本循环包括购买、生产、销售三个阶段。生产阶段是资本家使用购买来的劳动力和生产资料进行 生产，生产出包含剩余价值的商品，这一阶段直接创造价值和剩余价值，对资本循环起决定性作用。购买阶 段为生产准备条件，销售阶段实现商品价值和剩余价值，但都不如生产阶段关键。答案：B。"},{"id":"marx-4-167","globalId":461,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":167,"question":"垄断组织实行垄断价格的根本目的是为了","options":["扩大市场份额","降低生产成本","获取高额垄断利润","获取平均利润"],"answer":2,"answerLetter":"C","explain":"垄断组织作为垄断资本主义阶段的经济组织形式，其核心目标就是凭借垄断地位获取高额利润。实 行垄断价格是其达成这一目标的重要手段。而扩大市场份额、降低生产成本并非根本目的，平均利润也不是 垄断组织追求的，它们追求的是大大高于平均利润的高额垄断利润。"},{"id":"marx-4-168","globalId":462,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":168,"question":"社会总产品的两大部类是指（ ）。","options":["生产资料部类和消费资料部类","劳动资料部类和劳动对象部类","可变资本部类和不变资本部类","固定资本部类和流动资本部类"],"answer":0,"answerLetter":"A","explain":"社会总产品从实物形态按最终用途划分，可分为生产资料和消费资料，相应地社会生产便分为生产 生产资料的第一部类和生产消费资料的第二部类。"},{"id":"marx-4-169","globalId":463,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":169,"question":"唯物主义与唯心主义的区别在于如何问答","options":["世界的本质是什么的问题","世界可否被认识的问题","世界的存在是怎样的问题","世界统一性的问题"],"answer":0,"answerLetter":"A","explain":"唯物主义和唯心主义是对世界本质的不同回答。唯物主义认为物质是世界的本原，唯心主义认为意 识是世界的本原，二者分歧在于对世界本质是什么的问题的回答。B选项世界可否被认识涉及的是可知论与不 可知论；C选项世界的存在怎样是辩证法和形而上学探讨的内容；D选项世界统一性问题包含在对世界本质的 探讨中，但不如A选项直接准确。"},{"id":"marx-4-170","globalId":464,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":170,"question":"银行利润的本质是（ ）。","options":["生产部门的雇佣工人所创造的剩余价值","银行雇员创造的剩余价值","银行收取的贷款利息","银行收取的服务费"],"answer":0,"answerLetter":"A","explain":"银行利润来源于贷款利息和存款利息的差额，其本质和产业利润一样，都是产业工人创造的剩余价 值的转化形式。银行利润归根结底是生产部门的雇佣工人所创造的剩余价值。银行雇员的劳动虽也有一定作 用，但他们的劳动不创造价值和剩余价值。贷款利息只是银行利润的来源形式，不是本质。银行收取的服务 费同样只是利润来源的一部分形式，不是本质。"},{"id":"marx-4-171","globalId":465,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":171,"question":"资本循环中实现价值增值的阶段是（ ）。","options":["购买阶段","生产阶段","销售阶段","运输阶段"],"answer":1,"answerLetter":"B","explain":"在资本循环的生产阶段，资本家让劳动力与生产资料相结合进行生产，工人的劳动创造出包含剩余 价值的商品，实现了价值增值。购买阶段是为生产剩余价值做准备，销售阶段是实现商品价值和剩余价值。 运输阶段不属于资本循环的基本阶段。答案：B。"},{"id":"marx-4-172","globalId":466,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":172,"question":"马克思把人类社会历史划分为依次更替的五种社会形态：原始社会、奴隶社会、封建社会、资本主义社 会、共产主义社会（社会主义社会是它的第一阶段）。五种社会形态划分的依据是（ ）。","options":["人的发展状况","地理环境的状况","生产力的水平","生产关系的性质"],"answer":3,"answerLetter":"D","explain":"马克思划分五种社会形态的依据是生产关系的性质，不同的生产关系性质决定了社会形态的不同。 生产力水平是影响社会发展的重要因素，但不是划分社会形态的直接依据；人的发展状况、地理环境状况与 社会形态划分依据无关。"},{"id":"marx-4-173","globalId":467,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":173,"question":"社会总产品是社会各个物质生产部门在一定时期（通常是一年）内生产的（ ）。","options":["全部生产资料的总和","全部消费资料的总和","全部物质资料的总和","全部剩余价值的总和"],"answer":2,"answerLetter":"C","explain":"社会总产品指社会各个物质生产部门在一定时期内（通常为一年）所生产出来的全部物质资料的总 和。它既包括生产资料，也包括消费资料。A只提到生产资料，B只提到消费资料，D剩余价值总和概念不符。"},{"id":"marx-4-174","globalId":468,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":174,"question":"唯心史观在历史创造者问题上的根本错误在于（ ）。","options":["否认个人在历史发展中的作用","否认思想动机在历史发展中的作用","否认少数英雄人物是推动历史发展的决定力量","否认广大人民群众是推动历史发展的决定力量"],"answer":3,"answerLetter":"D","explain":"唯心史观从意识决定物质出发，往往夸大英雄人物或精神力量的作用，而忽视甚至否认人民群众对 历史发展的决定作用。答案选D。因为唯心史观的根本错误就是颠倒社会存在和社会意识关系，在历史创造者 问题上，就是否认人民群众的决定作用 。"},{"id":"marx-4-175","globalId":469,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":175,"question":"银行资本家的自有资本的银行利润在数量上通常（ ）。","options":["高于平均利润","等于平均利润","与平均利润无关","相当于平均利润"],"answer":3,"answerLetter":"D","explain":"银行资本家投资银行业，也要求获得平均利润，否则会转移资本到其他行业。银行利润在数量上通 常相当于平均利润。"},{"id":"marx-4-176","globalId":470,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":176,"question":"资本有机构成的提高一般是以","options":["社会总资本的增大为前提","生产资料的增大为前提","流通资本的增大为前提","单个资本的增大为前提"],"answer":3,"answerLetter":"D","explain":"资本有机构成提高意味着不变资本在总资本中所占比重增大，可变资本比重相对减少。而单个资本 增大，才能有更多资金用于购置先进生产设备等不变资本，从而推动资本有机构成提高。社会总资本增大不 一定直接带来单个企业资本有机构成提高；生产资料增大若没有单个资本增大的支撑难以实现资本有机构成 提高；流通资本增大与资本有机构成提高没有直接关联。"},{"id":"marx-4-177","globalId":471,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":177,"question":"马克思说，资本主义“不自觉地为一个更高级的生产形势创造物质条件”，它的“历史人物和存在理由 ”是（ ）。","options":["发明创造新科技成果","发展社会劳动生产力","生产先进的机器设备","建立完善的市场经济"],"answer":2,"answerLetter":"C","explain":"【标准答案：C】"},{"id":"marx-4-178","globalId":472,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":178,"question":"我国坚持走自己的路,建设中国特色社会主义伟大实践的理论基础是（ ）。","options":["矛盾的主要方面和次要方面辩证关系的原理","矛盾的普遍性和特殊性辩证关系的原理","主要矛盾和次要矛盾辩证关系的原理","事物的量变和质变辩证关系的原理"],"answer":1,"answerLetter":"B","explain":"矛盾的普遍性和特殊性辩证关系原理是马克思主义普遍真理同各国具体实际相结合的哲学基础。建 设中国特色社会主义，一方面要坚持社会主义的一般特征和基本原则，这体现了矛盾的普遍性；另一方面 ，又要结合中国的实际情况，体现中国特色，这体现了矛盾的特殊性。所以矛盾的普遍性和特殊性辩证关系 原理是建设中国特色社会主义伟大实践的理论基础。"},{"id":"marx-4-179","globalId":473,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":179,"question":"资本主义国家的政体主要有（ ）。","options":["两党制和多党制两种","君主立宪制和民主共和制两种","一党制、两党制和多党制三种","君主立宪制、民主共和制和专制独裁制三种"],"answer":1,"answerLetter":"B","explain":"资本主义国家政体主要围绕权力组织形式划分。君主立宪制是以君主为国家元首但君主权力受宪法 限制；民主共和制是国家权力机关和国家元首由选举产生。而选项A中两党制和多党制是政党制度，并非政体 ；选项C同样说的是政党制度；选项D中专制独裁制不符合资本主义国家普遍的政治特征，资本主义国家大多 遵循民主政治原则。"},{"id":"marx-4-180","globalId":474,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":180,"question":"资本周转速度与周转次数之间（ ）。","options":["成正比例关系","成反比例关系","按同比例变化","无直接联系"],"answer":0,"answerLetter":"A","explain":"资本周转速度是指资本在一定时期内的周转次数，周转次数越多，资本周转速度就越快，所以资本 周转速度与周转次数成正比例关系。"},{"id":"marx-4-181","globalId":475,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":181,"question":"人类认识发展的根本动力是（ ）。","options":["兴趣爱好","社会实践","求知欲望","好奇心理"],"answer":1,"answerLetter":"B","explain":"社会实践是人类认识发展的根本动力。实践为认识提供新课题，推动认识在探索和解决新课题中向 前发展；实践锻炼和提高主体的认识能力。而兴趣爱好、求知欲望、好奇心理虽然对认识发展有一定作用 ，但都不是根本动力。"},{"id":"marx-4-182","globalId":476,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":182,"question":"生产方式包括（ ）。","options":["劳动者和劳动工具两个方面","地理环境和人口因素两个方面","生产力和生产关系两个方面","经济基础和上层建筑两个方面"],"answer":2,"answerLetter":"C","explain":"生产方式是人类借以向自然界谋取必需的生活资料的方式，它包括生产力和生产关系两个方面，生 产力是生产方式的物质内容，生产关系是生产方式的社会形式。A选项劳动者和劳动工具只是生产力的部分要 素；B选项地理环境和人口因素属于社会存在，但不是生产方式；D选项经济基础和上层建筑构成社会形态。"},{"id":"marx-4-183","globalId":477,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":183,"question":"我们党制定和执行独立自主、自力更生以及对外开放方针的理论基础是（ ）。","options":["矛盾的同一性和斗争性辩证关系的原理","事物发展的内因和外因辩证关系的原理","矛盾的普遍性和特殊性辩证关系的原理","事物发展的量变和质变辩证关系的原理"],"answer":1,"answerLetter":"B","explain":"内因是事物发展变化的根据，外因是事物发展变化的条件，外因通过内因而起作用。我国坚持独立 自主、自力更生是重视内因，对外开放是重视外因，所以理论基础是事物发展的内因和外因辩证关系原理。"},{"id":"marx-4-184","globalId":478,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":184,"question":"资本主义国家对国民经济的管理和调节，主要依靠（ ）。","options":["经济手段","法律手段","行政手段","计划手段"],"answer":0,"answerLetter":"A","explain":"在资本主义国家对国民经济管理调节中，经济手段具有诱导性、间接性等特点，能通过市场机制影 响经济主体行为，是主要方式。法律手段、行政手段、计划手段也会用，但重要性和使用频率不如经济手段 。"},{"id":"marx-4-185","globalId":479,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":185,"question":"资本主义商业店员所从事的商品买卖活动（ ）。","options":["创造商品的价值和使用价值","实现商品的价值和使用价值","创造商品的价格剩余价值","实现商品的价值和剩余价值"],"answer":3,"answerLetter":"D","explain":"商业店员从事商品买卖活动，本身不创造价值和剩余价值，但通过他们的劳动能实现商品的价值和 剩余价值。"},{"id":"marx-4-186","globalId":480,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":186,"question":"人类社会的基本矛盾有两对，一对是生产力和生产关系的矛盾，另一对是（ ）。","options":["社会存在和社会意识的矛盾","剥削阶级和被剥削阶级的矛盾","经济基础和上层建筑的矛盾","先进思想和落后思想的矛盾"],"answer":2,"answerLetter":"C","explain":"人类社会基本矛盾包含生产力与生产关系的矛盾、经济基础与上层建筑的矛盾。A选项社会存在与社 会意识是历史观基本问题；B选项剥削阶级和被剥削阶级矛盾是特定社会阶段阶级矛盾；D选项先进思想和落 后思想矛盾不属于社会基本矛盾。"},{"id":"marx-4-187","globalId":481,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":187,"question":"生产关系包括多方面的内容，其中起决定作用的是（ ）。","options":["人们在生产中的相互关系","生产资料的所有制形式","产品的分配方式","产品的交换方式"],"answer":1,"answerLetter":"B","explain":"生产资料所有制形式决定着生产中人与人的关系、产品分配方式等，是生产关系的基础，起决定作 用。答案：B 。"},{"id":"marx-4-188","globalId":482,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":188,"question":"无产阶级专政的实质就是（ ）。","options":["无产阶级作为统治阶级掌握国家政权","消灭剥削、消灭阶级，最终实现共产主义","镇压敌对阶级的反抗","领导和组织社会主义建设"],"answer":0,"answerLetter":"A","explain":"无产阶级专政的实质，就是无产阶级作为统治阶级掌握国家政权 。其他选项是无产阶级专政的任务 等方面，并非实质。"},{"id":"marx-4-189","globalId":483,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":189,"question":"资本主义国家主要的政体形式是（ ）。","options":["君主立宪制和民主共和制","君主立宪制、民主共和制和专制独裁制","两党制和多党制","一党制、两党制和多党制"],"answer":0,"answerLetter":"A","explain":"政体形式指的是国家政权的组织形式。资本主义国家主要的政体形式为君主立宪制（如英国）和民 主共和制（如美国） 。 选项B中专制独裁制不属于资本主义国家普遍的、主要的政体形式，资本主义国家宣 扬民主等理念，专制独裁不符合其主流政治形态。 选项C和D中两党制、多党制、一党制属于政党制度，并非 政体形式，与题目所问不符。"},{"id":"marx-4-190","globalId":484,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":190,"question":"资本主义商业企业的利润率应大体相当于（ ）。","options":["剩余价值率","平均利润率","银行的贷款利率","银行的存款利率"],"answer":1,"answerLetter":"B","explain":"在资本主义经济中，商业资本家投资商业，其目的也是获取利润，商业利润是商业资本家从事商业 经营活动所获得的利润，商业资本家获得的利润率应大体相当于平均利润率，否则资本就会在不同部门之间 流动，直至形成平均利润率。"},{"id":"marx-4-191","globalId":485,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":191,"question":"社会主义民主的本质是（ ）。","options":["人民当家作主","解放和发展生产力","消灭剥削和压迫","促进人的自由全面发展"],"answer":0,"answerLetter":"A","explain":"社会主义民主是人民的民主，其本质就是人民当家作主，人民是国家的主人。B选项解放和发展生产 力是社会主义的根本任务；C选项消灭剥削和压迫是社会主义的目标之一；D选项促进人的自由全面发展是共 产主义的价值目标。"},{"id":"marx-4-192","globalId":486,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":192,"question":"下列说法中，属于正确发挥人的主观能动性的是（ ）。","options":["人有多大胆，地有多大产","不怕做不到，就怕想不到","纸上谈兵，画饼充饥","量力而行，尽力而为"],"answer":3,"answerLetter":"D","explain":"A、B选项夸大了主观能动性，忽视客观规律；C选项只是空想，没有实际行动去发挥主观能动性。 D选项既考虑到从实际出发（量力而行），又强调充分发挥主观能动性（尽力而为），是正确发挥主观能动性 的体现。"},{"id":"marx-4-193","globalId":487,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":193,"question":"资本主义商业资本执行的是产业资本的（ ）。","options":["货币资本职能","商品资本职能","生产资本职能","流通资本职能"],"answer":1,"answerLetter":"B","explain":"商业资本是从产业资本中分离出来，专门从事商品买卖，独立发挥资本职能，以获取商业利润为目 的的一种资本形式。它执行的是产业资本循环中的商品资本职能，通过销售商品实现商品价值和剩余价值。"},{"id":"marx-4-194","globalId":488,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":194,"question":"社会主义社会的改革是（ ）。","options":["社会主义基本经济制度的改变","社会土义核心价值观的根本改变","社会主义基本政治制度的改变","社会主义制度的自我完善和发展"],"answer":3,"answerLetter":"D","explain":"社会主义社会的改革是在坚持社会主义基本制度的前提下，对生产关系和上层建筑中不适应生产力 发展的部分进行调整和变革，目的是为了更好地推动社会主义的发展，并非改变社会主义的基本经济制度、 政治制度以及核心价值观，而是社会主义制度的自我完善和发展。"},{"id":"marx-4-195","globalId":489,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":195,"question":"下列选项属于马克思主义三个主要组成部分之一的是（ ）。","options":["马克思主义政治学","科学社会主义","马克思主义伦理学","空想社会主义"],"answer":1,"answerLetter":"B","explain":"马克思主义三个主要组成部分是马克思主义哲学、马克思主义政治经济学和科学社会主义 。选项 A马克思主义政治学、C马克思主义伦理学不属于这三个主要部分；D空想社会主义是科学社会主义的理论来源 ，并非马克思主义主要组成部分。"},{"id":"marx-4-196","globalId":490,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":196,"question":"资本主义的国有资本和国有经济一般不参与（ ）。","options":["基础设施的建设","战略性科学研究","普通消费品生产","公共产品生产"],"answer":2,"answerLetter":"C","explain":"资本主义国有资本和国有经济主要投向私人资本不愿投入或无力承担、但对国民经济发展至关重要 的领域，像基础设施建设、战略性科学研究、公共产品生产等，这些领域投资大、周期长、收益慢。而普通 消费品生产盈利性相对较好，私人资本愿意且有能力进行，国有资本一般不参与。"},{"id":"marx-4-197","globalId":491,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":197,"question":"资本主义经济危机产生的根源是（ ）。","options":["资本主义生产方式的基本矛盾","社会两大部类的比例失调","商品供给和需求的矛盾","国家宏观调控的缺失"],"answer":0,"answerLetter":"A","explain":"资本主义经济危机根源在于资本主义生产方式基本矛盾，即生产的社会化与生产资料资本主义私人 占有之间的矛盾，这是资本主义自身无法克服的矛盾。而B社会两大部类比例失调、C商品供给和需求矛盾、 D国家宏观调控缺失都是经济危机的表现或影响因素，并非根源。"},{"id":"marx-4-198","globalId":492,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":198,"question":"资本主义生产部门之间的竞争形成（ ）。","options":["商品价值","生产成本","剩余价值","平均利润"],"answer":3,"answerLetter":"D","explain":"资本主义生产部门之间竞争的结果是使各部门的利润率趋于平均化，形成平均利润率，进而形成平 均利润。商品价值是由生产商品的社会必要劳动时间决定的；生产成本是生产单位商品所耗费的不变资本和 可变资本之和；剩余价值是雇佣工人创造的被资本家无偿占有的超过劳动力价值的价值，它们都不是生产部 门之间竞争形成的。"},{"id":"marx-4-199","globalId":493,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":199,"question":"资本主义的生产成本不应包括（ ）。","options":["工人的工资","原材料费用","机器设备的折旧费","机器设备未折旧部分"],"answer":3,"answerLetter":"D","explain":"资本主义生产成本是生产单位商品所耗费的不变资本与可变资本之和。A选项工人工资属于可变资本 ；B选项原材料费用和C选项机器设备折旧费属于不变资本。而机器设备未折旧部分不构成当前商品生产的实 际耗费，不计入生产成本。"},{"id":"marx-4-200","globalId":494,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":200,"question":"资本主义经济中，农业资本家获得的剩余价值是（ ）。","options":["级差地租","绝对地租","平均利润","利息"],"answer":2,"answerLetter":"C","explain":"在资本主义经济中，农业资本家投资农业，其目的也是为了获得与其他行业大致相同的收益，即平 均利润。农业工人创造的剩余价值，一部分以地租形式（包括级差地租和绝对地租）交给土地所有者，另一 部分则被农业资本家占有，这部分就是平均利润。利息与农业资本家获得的剩余价值无直接关系。"},{"id":"marx-4-201","globalId":495,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":201,"question":"资本主义生产的成本不包括（ ）。","options":["工人的工资","原材料的耗费","固定资本的折旧费","固定资本未折旧的部分"],"answer":3,"answerLetter":"D","explain":"资本主义生产成本是生产单位商品所耗费的不变资本与可变资本之和。工人工资属于可变资本；原 材料耗费和固定资本折旧费属于不变资本。而固定资本未折旧部分不构成当前商品生产已耗费的成本。答案 ：D"},{"id":"marx-4-202","globalId":496,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":202,"question":"下列各项中，正确说明意识能动性的是（ ）。","options":["人有多大胆，地有多大产","不怕做不到，就怕想不到","纸上谈兵，画饼充饥","量力而行，尽力而为"],"answer":3,"answerLetter":"D","explain":"意识能动性是指意识能动地反映世界和通过实践改造世界的能力和作用，既要尊重客观规律，又要 充分发挥主观能动性。 A选项“人有多大胆，地有多大产”、B选项“不怕做不到，就怕想不到”夸大了意识 的能动作用，忽视了客观规律。 C选项“纸上谈兵，画饼充饥”只是停留在意识层面，没有通过实践去改造 世界，不能正确体现意识能动性。 D选项“量力而行，尽力而为”既考虑到客观实际（量力而行），又强调 发挥主观能动性（尽力而为），正确说明了意识能动性。"},{"id":"marx-4-203","globalId":497,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":203,"question":"资本主义经济中的计划管理（ ）。","options":["消除了资本主义的生产无政府状态","能够自觉保持社会再生产的比例关系","阻碍了生产的发展和经济结构的优化","可以对经济周期进行一定的调节与控制"],"answer":3,"answerLetter":"D","explain":"资本主义的计划管理是在资本主义私有制基础上进行的，不能从根本上消除生产无政府状态和自觉 保持社会再生产比例关系，A、B 选项错误；计划管理在一定程度上能促进生产发展和经济结构优化，并非阻 碍，C 错误；资本主义的计划管理可以在一定程度上对经济周期进行调节与控制 。"},{"id":"marx-4-204","globalId":498,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":204,"question":"资本主义相对过剩人口是指（ ）。","options":["劳动力供给超过资本对劳动力的需求而出现的过剩人口","人口增长超过生活资料的增长而出现的过剩人口","人口增长超过生产资料的增长而出现的过剩人口","人口增长超过资本增长而出现的过剩人口"],"answer":0,"answerLetter":"A","explain":"资本主义相对过剩人口是指劳动力供给超过了资本对它的需求，从而形成相对多余的人口。这是资 本主义特有的人口规律，并非人口增长与生活资料、生产资料、资本增长简单对比的问题。"},{"id":"marx-4-205","globalId":499,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":205,"question":"下列各项中正确说明真理问题的是（ ）。","options":["真理是有价值的","有用即真理","真理是永恒的","真理是万能的"],"answer":0,"answerLetter":"A","explain":"A选项正确，真理具有价值性，能指导实践满足人的需求。B选项“有用即真理”是实用主义真理观 ，把价值等同于真理，错误。C选项真理是具体的有条件的，不是永恒不变的，该说法错误。D选项真理不是 万能的，说法过于绝对。"},{"id":"marx-4-206","globalId":500,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":206,"question":"下列选项中，表示要坚持适度原则的是（ ）。","options":["因地制宜","对症下药","注意分寸","实事求是"],"answer":2,"answerLetter":"C","explain":"“注意分寸”强调做事要把握好度，不能过度或不及，体现适度原则。“因地制宜”是根据不同地 方特点采取合适办法；“对症下药”是针对具体病症用药，强调具体问题具体分析；“实事求是”强调从实 际出发探寻规律。"},{"id":"marx-4-207","globalId":501,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":207,"question":"资本主义国家的国体是（ ）。","options":["议会民主制","君主立宪制","资产阶级专政","总统共和制"],"answer":2,"answerLetter":"C","explain":"国体指的是国家的阶级本质，即社会各阶级在国家中的地位。资本主义国家是资产阶级掌握政权 ，其国体是资产阶级专政。而议会民主制、君主立宪制、总统共和制都属于政体，是国家政权的组织形式。"},{"id":"marx-4-208","globalId":502,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":208,"question":"资本主义民主共和制国家中掌握立法权的是（ ）。","options":["国家元首","政府","法院","议会"],"answer":3,"answerLetter":"D","explain":"在资本主义民主共和制国家，议会是立法机关，掌握立法权；国家元首主要履行礼仪性等职责；政 府掌握行政权；法院掌握司法权。所以答案是D议会。"},{"id":"marx-4-209","globalId":503,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":209,"question":"资本主义再生产周期四个阶段的顺序一般为（ ）。","options":["萧条—危机—复苏—高涨","复苏—高涨—危机—萧条","危机—萧条—复苏—高涨","高涨—萧条—危机—复苏"],"answer":2,"answerLetter":"C","explain":"资本主义再生产周期一般是从危机开始，经历萧条阶段，经济缓慢恢复进入复苏阶段，之后走向高 涨，又为下一次危机埋下伏笔，所以顺序是危机—萧条—复苏—高涨。"},{"id":"marx-4-210","globalId":504,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":210,"question":"下列关于利息率的表述中不正确的是（ ）。","options":["它的最低界限不能等于零","通常在平均利润率和零之间变动","由国家的习惯和法律传统决定","与平均利润率和企业利润率按相同比例变动"],"answer":3,"answerLetter":"D","explain":"利息率的高低有一定界限，其最低界限不能等于零，否则借贷资本家无利可图，A 选项正确； 利 息是平均利润的一部分，所以利息率通常在平均利润率和零之间变动，B 选项正确； 利息率在一定程度上受 国家习惯和法律传统等因素影响，C 选项正确； 利息率与平均利润率有关，但企业利润率较为复杂，受多种 因素影响，利息率并非与企业利润率按相同比例变动，D 选项错误。"},{"id":"marx-4-211","globalId":505,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":211,"question":"下列关于人的本质的表述，只涉及人与动物根本区别的是（ ）。","options":["劳动是人的本质","人的需要即人的本质","人的本质是人的全部属性的总和","人的本质是人的自然属性的总和"],"answer":0,"answerLetter":"A","explain":"劳动创造了人，劳动是人类生存和发展的基础，也是人与动物的根本区别，A选项符合。B选项人的 需要并非人与动物根本区别；C选项人的全部属性总和表述宽泛，未突出与动物根本区别；D选项人的本质主 要是社会属性，并非自然属性总和。"},{"id":"marx-4-212","globalId":506,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":212,"question":"下列关于人的本质的说法中不正确的是（ ）。","options":["人的本质是发展变化的","人的本质是现实具体的","人的本质是后天形成的","人的本质是人人相同的"],"answer":3,"answerLetter":"D","explain":"人的本质是一切社会关系的总和。由于不同人的社会关系不同，所以人的本质不是人人相同的。同 时，社会关系是不断发展变化的，所以人的本质是发展变化的；在特定社会关系中形成的人的本质也是现实 具体的，并且是在后天社会生活实践中形成的。"},{"id":"marx-4-213","globalId":507,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":213,"question":"下列选项中，正确表述一个完整认识过程的是（ ）。","options":["感觉——知觉——表象","概念——判断——推理","实践——认识——实践","意识——物质——意识"],"answer":2,"answerLetter":"C","explain":"认识过程是在实践基础上由感性认识上升到理性认识，再由理性认识回到实践的过程，即实践 - 认识 - 实践。 A选项“感觉 - 知觉 - 表象”是感性认识的三种形式。 B选项“概念 - 判断 - 推理”是理 性认识的三种形式。 D选项“意识 - 物质 - 意识”表述错误，辩证唯物主义认识论强调实践在认识过程中 的基础地位，应是实践 - 认识 - 实践。"},{"id":"marx-4-214","globalId":508,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":214,"question":"下列关于生产力和生产关系的表述中，不正确的是（ ）。","options":["生产力的性质决定生产关系的性质","生产力的发展决定生产关系的改变","生产关系对生产力具有巨大的反作用","生产关系总是适应生产力的发展要求"],"answer":3,"answerLetter":"D","explain":"生产力决定生产关系，生产关系反作用于生产力，但生产关系并不总是适应生产力发展要求，当生 产关系不适应生产力时，就会阻碍生产力发展。"},{"id":"marx-4-215","globalId":509,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":215,"question":"下列选项中不属于马克思主义直接理论来源的是（ ）。","options":["德国古典哲学","法国启蒙思想","英国古典经济学","英法两国空想社会主义学说"],"answer":1,"answerLetter":"B","explain":"马克思主义直接理论来源是德国古典哲学、英国古典政治经济学和英法两国空想社会主义学说。法 国启蒙思想不属于其直接理论来源。答案选B。"},{"id":"marx-4-216","globalId":510,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":216,"question":"下列关于意识起源的正确说法是（ ）。","options":["意识是主观自生的","意识是自然界长期发展的产物","意识是人脑的机能","意识是客观世界的主观映像"],"answer":1,"answerLetter":"B","explain":"选项A，意识不是主观自生的，它是物质世界长期发展的产物，A错误。 选项B，意识是自然界长期 发展的产物，同时也是社会历史的产物，该选项阐述了意识起源，正确。 选项C，“意识是人脑的机能”强 调的是意识产生的生理基础，不是起源，C不符合题意。 选项D，“意识是客观世界的主观映像”说明的是意 识的本质，不是起源，D不符合题意。"},{"id":"marx-4-217","globalId":511,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":217,"question":"下列选项中属于共产主义社会显著特征的是（ ）。","options":["按生产要素分配","各尽所能，按劳分配","按能力大小分配","各尽所能，按需分配"],"answer":3,"answerLetter":"D","explain":"共产主义社会生产力高度发达，物质财富极大丰富，人们的思想觉悟极大提高，实行各尽所能、按 需分配，不再按生产要素、能力大小分配，按劳分配是社会主义社会分配方式。所以答案是D。"},{"id":"marx-4-218","globalId":512,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":218,"question":"下列观点中属于客观唯心主义的是（ ）。","options":["天地万物皆在吾心中","存在就是被感知","物是感觉的集合","万物是“绝对精神”的体现"],"answer":3,"answerLetter":"D","explain":"客观唯心主义把客观精神（如上帝、理念、绝对精神等）看作世界的主宰和本原。 A选项“天地万 物皆在吾心中”，强调万物在“吾心”，是主观唯心主义，把人的主观精神当作世界本原。 B选项“存在就 是被感知”，以人的感知来判定存在，属于主观唯心主义。 C选项“物是感觉的集合”，将物归结为感觉集 合，也是主观唯心主义。 D选项“万物是‘绝对精神’的体现”，把“绝对精神”这一客观精神当作万物的 本原，属于客观唯心主义。"},{"id":"marx-4-219","globalId":513,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":219,"question":"下列选项中属于意识形态的是（ ）。","options":["哲学","逻辑学","语言学","物理学"],"answer":0,"answerLetter":"A","explain":"意识形态是指反映一定社会经济形态、从而也反映一定阶级或社会集团的利益和要求的观念体系。 哲学具有强烈的阶级性，是系统化理论化的世界观，属于意识形态。而逻辑学、语言学、物理学是对客观世 界的一般性规律的总结，不具有阶级性，不属于意识形态。"},{"id":"marx-4-220","globalId":514,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":220,"question":"资产阶级道德观的基本原则是（ ）。","options":["利己主义","拜金主义","自由主义","享乐主义"],"answer":0,"answerLetter":"A","explain":"资产阶级道德观从个人主义出发，以利己主义为基本原则，将个人利益置于首位。拜金主义、自由 主义、享乐主义是资产阶级道德观在不同方面的表现，并非基本原则。"},{"id":"marx-4-221","globalId":515,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":221,"question":"资产阶级民主制的核心和主要标志是（ ）。","options":["议会制","三权分立制","普选制","多党制"],"answer":0,"answerLetter":"A","explain":"在资产阶级民主制中，议会是国家的立法机关和权力中心，它集中体现了资产阶级民主制的原则和 特征，所以议会制是资产阶级民主制的核心和主要标志。答案：A。"},{"id":"marx-4-222","globalId":516,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":222,"question":"自然规律与社会规律的区别在于（ ）。","options":["前者是客观的,后者是主观的","前者是绝对的,后者是相对的","前者是通过自然力量相互作用实现的,后者是通过人的自觉活动实现的","前者是不以人的意志为转移的,后者是可以随人的意志改变而改变的"],"answer":2,"answerLetter":"C","explain":"自然规律和社会规律都是客观的，不以人的意志为转移，不存在主观或可随人意志改变、绝对相对 之分。自然规律通过自然力量相互作用实现，社会规律通过人的自觉活动实现，这是二者重要区别。"},{"id":"marx-4-223","globalId":517,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":223,"question":"作为人类社会发展的最高社会形态，共产主义社会的物质基础是（ ）。","options":["与任何繁荣的封建社会相当的社会生产力","与一般资本主义社会相当的社会生产力","与发达资本主义国家相当的社会生产力","远远高于以往一切社会的高度发达的社会生产力"],"answer":3,"answerLetter":"D","explain":"共产主义是人类社会发展的最高形态，其物质基础必然要远超以往社会。以往社会包括封建社会、 一般资本主义社会以及发达资本主义国家所处的生产力水平。共产主义社会需要远远高于以往一切社会的高 度发达的社会生产力作为支撑，才能实现按需分配等特征。答案选D。"},{"id":"marx-4-224","globalId":518,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":224,"question":"自由竞争资本主义时期，资本主义国家对外经济联系的主要方式是（ ）。","options":["商品资本输出","借贷资本输出","生产资本输出","货币资本输出"],"answer":0,"answerLetter":"A","explain":"在自由竞争资本主义时期，资本主义国家经济实力相对有限，主要依靠商品输出获取利润和拓展市 场。而借贷资本输出、生产资本输出等大规模资本输出形式是在垄断资本主义阶段才占据重要地位。货币资 本输出表述不准确，不属于主要方式。答案：A 。"},{"id":"marx-4-225","globalId":519,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":225,"question":"作为马克思恩格斯一生最重要的理论发现，使社会主义从空想变成科学的是（ ）。","options":["唯物论和辩证法学说","唯物论和劳动价值学说","唯物史观和剩余价值学说","唯物史观和阶级斗争学说"],"answer":2,"answerLetter":"C","explain":"唯物史观揭示了人类社会发展的一般规律，剩余价值学说揭示了资本主义社会发展的特殊规律，二 者为科学社会主义的创立奠定了理论基础，使社会主义从空想变为科学。答案：C。"},{"id":"marx-4-226","globalId":520,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":226,"question":"作为认识和实践活动的承担者，认识主体所具有的突出特点是（ ）。","options":["能动性","社会性","历史性","客观性"],"answer":0,"answerLetter":"A","explain":"认识主体是指认识和实践活动的承担者，人作为认识主体，与动物消极适应自然不同，具有能动地 反映和改造世界的能力，能动性是其突出特点。"}]) : [{"id":"marx-1-1","globalId":1,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":1,"question":"学习马克思主义的根本方法是（ ）。","options":["精读马列原著","把握基本原理","理论联系实际","深入调查研究"],"answer":2,"answerLetter":"C","explain":"马克思主义是指导实践的科学理论，只有将理论与实际相结合，才能真正理解和运用马克思主义 ，所以理论联系实际是学习马克思主义的根本方法。"},{"id":"marx-1-2","globalId":2,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":2,"question":"规律具有两个特点，一个是普遍性，另一个是（ ）","options":["客观性","变动性","社会性","能动性"],"answer":0,"answerLetter":"A","explain":"规律是事物运动发展中的本质的、必然的、稳定的联系。规律具有普遍性和客观性，客观性是规律 的根本特点，不以人的意志为转移。变动性、社会性、能动性都不属于规律特点。答案选A。"},{"id":"marx-1-3","globalId":3,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":3,"question":"“白马非马”这一诡辩命题的错误在于割裂了（ ）。","options":["现象和本质的联系","局部和整体的联系","个别和一般的联系","量变和质变的联系"],"answer":2,"answerLetter":"C","explain":"“白马”是个别、具体的马，“马”是一般、抽象的概念，代表所有马的共性。“白马非马”说白 马不是马，就是把个别（白马）和一般（马）的联系割裂了。"},{"id":"marx-1-4","globalId":4,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":4,"question":"“存在就是被感知”这种观点属于（ ）。","options":["朴素唯物主义","形而上学唯物主义","主观唯心主义","客观唯心主义"],"answer":2,"answerLetter":"C","explain":"“存在就是被感知”强调个人的感知决定事物的存在，把人的主观精神当作世界的本原，这符合主 观唯心主义的特征。"},{"id":"marx-1-5","globalId":5,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":5,"question":"“革命是解放生产力，改革也是解放生产力”。这一论断表明社会改革与社会革命（ ）","options":["都以夺取国家政权为目的","都不改变社会制度的根本性质","都是要解决社会基本矛盾","都不需要采取暴力冲突的形式"],"answer":2,"answerLetter":"C","explain":"社会革命是推翻旧的社会制度，解放生产力；社会改革是在坚持社会制度的前提下，对生产关系和 上层建筑进行调整，同样是为了解放生产力，二者都是解决社会基本矛盾的方式。A选项，改革不以夺取国家 政权为目的；B选项，革命改变社会制度根本性质；D选项，革命一般采取暴力冲突形式。"},{"id":"marx-1-6","globalId":6,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":6,"question":"下下列各项中属于社会心理的是（ ）。","options":["政治与法律","哲学与宗教","科学与艺术","风俗与习惯"],"answer":3,"answerLetter":"D","explain":"社会心理是低层次的社会意识，是自发的、不系统的、不定型的社会意识，表现为人们的感知、情 绪、情感、心态、习俗等。 选项A“政治与法律”、选项B“哲学与宗教”、选项C“科学与艺术”都属于高 层次的、系统的社会意识形式，即社会意识形态。 而选项D“风俗与习惯”是人们在长期社会生活中形成的 ，属于自发的、不系统的社会心理范畴。"},{"id":"marx-1-7","globalId":7,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":7,"question":"“从本质上看,认识是主体对客体的能动反映。”这是一种（ ）。","options":["辩证唯物主义认识论观点","形而上学唯物主义认识论观点","主观唯心主义认识论观点","客观唯心主义认识论观点"],"answer":0,"answerLetter":"A","explain":"辩证唯物主义认识论强调认识是主体在实践基础上对客体的能动反映，既坚持反映论，又强调认识 的能动性。形而上学唯物主义认识论缺乏实践观点和辩证观点，是直观被动的反映论。主观唯心主义和客观 唯心主义认识论都否认认识是对客观世界的反映。"},{"id":"marx-1-8","globalId":8,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":8,"question":"“感觉到了的东西,我们不能立刻理解它,只有理解了的东西才能更深刻地感觉它”,这句话表明（ ）。","options":["感性认识是微不足道的","感性认识是认识的高级阶段","理性认识是唯一可靠的","理性认识是认识的高级阶段"],"answer":3,"answerLetter":"D","explain":"这句话强调了理解（理性认识）对感觉（感性认识）的深化作用，说明理性认识比感性认识更深刻 ，处于认识的高级阶段。A选项说法错误，感性认识是认识的起点并非微不足道；B选项感性认识是低级阶段 ；C选项理性认识和感性认识都有其可靠性，说理性认识唯一可靠太绝对。"},{"id":"marx-1-9","globalId":9,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":9,"question":"“各尽所能，按需分配”是（ ）","options":["原始社会的分配原则","阶级社会的分配原则","社会主义社会的分配原则","共产主义社会的分配原则"],"answer":3,"answerLetter":"D","explain":"原始社会是平均分配；阶级社会分配原则多样但都不是“各尽所能，按需分配” ；社会主义社会是 按劳分配。“各尽所能，按需分配”是共产主义社会生产力高度发达，物质极大丰富，人们思想觉悟极大提 高等前提下实行的分配原则。"},{"id":"marx-1-10","globalId":10,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":10,"question":"先有工程设计图，然后按工程设计图施工，建成大厦。这一事实说明（ ）。","options":["意识在先，物质在后","意识对物质有能动作用","意识对物质有决定作用","物质对意识有决定作用"],"answer":1,"answerLetter":"B","explain":"题干中先有工程设计图（意识范畴），然后按设计图施工建成大厦（物质成果），体现了意识能够 指导人们通过实践把观念的东西变成现实的东西，这是意识对物质具有能动作用的表现。"},{"id":"marx-1-11","globalId":11,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":11,"question":"作为马克思恩格斯一生最重要的理论发现,使得社会主义从空想变成科学的是（ ）。","options":["唯物主义和辩证法学说","无产阶级革命和无产阶级专政学说","唯物史观和剩余价值学说","劳动价值论和剩余价信学说"],"answer":2,"answerLetter":"C","explain":"唯物史观揭示了人类社会发展的一般规律，剩余价值学说揭示了资本主义社会的特殊规律，二者为 科学社会主义的创立奠定了理论基石，使社会主义从空想变为科学。答案选C 。"},{"id":"marx-1-12","globalId":12,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":12,"question":"“从群众中来，到群众中去”的过程，从认识论上看，就是（ ）。","options":["感性认识——理性认识——感性认识的过程","认识——实践——认识的过程","实践——认识——实践的过程","理性认识——感性认识——理性认识的过程"],"answer":2,"answerLetter":"C","explain":"“从群众中来”，就是深入群众，调查研究，把群众分散的无系统的意见集中起来，经过分析和综 合等，形成符合实际情况的工作方针、政策等，这是从实践到认识的过程。 “到群众中去”，就是把从群众 中集中起来的决策、方针、政策等，再回到群众中去宣传解释，使之化为群众的实际行动，并在群众的实践 中检验这些方针、政策的正确性，这是从认识到实践的过程。所以“从群众中来，到群众中去”的过程，从 认识论上看，就是实践——认识——实践的过程。"},{"id":"marx-1-13","globalId":13,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":13,"question":"“感觉只解决现象问题，理论才解决本质问题”，这句话说明（ ）。","options":["感性认识是微不足道的","感性认识有待于发展到理性认识","理性认识是唯一可靠的","理性认识有待于深化为感性认识"],"answer":1,"answerLetter":"B","explain":"题干强调感觉（感性认识）只能解决现象问题，而理论（理性认识）才能解决本质问题，这表明感 性认识有局限性，为了把握事物本质，需要从感性认识上升到理性认识。答案：B 。A选项，感性认识并非微 不足道，它是认识的起点，是有重要作用的，A错误；C选项，理性认识也不一定是唯一可靠的，需要经过实 践检验，C错误；D选项，应该是感性认识有待深化为理性认识，D说法错误。"},{"id":"marx-1-14","globalId":14,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":14,"question":"“过剩资本”的出现是（ ）。","options":["资本积累的前提条件","资本循环的物质基础","资本输出的财力基础","引进资本的必然结果"],"answer":2,"answerLetter":"C","explain":"当大量资本在国内找不到有利可图的投资场所，就形成“过剩资本”，而这些过剩资本会寻求对外 投资，所以“过剩资本”是资本输出的财力基础。"},{"id":"marx-1-15","globalId":15,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":15,"question":"现代生产力系统的渗透性因素是指（ ）。","options":["教育","管理","生产资料","自然科学"],"answer":3,"answerLetter":"D","explain":"现代生产力系统中，自然科学通过渗透到生产力系统的其他要素中转化为现实生产力，是渗透性因 素。教育属于准备性因素，管理是运筹性因素，生产资料是实体性因素。"},{"id":"marx-1-16","globalId":16,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":16,"question":"“绝对运动中包含着相对静止，相对静止中包含着绝对运动”，这是一种（ ）。","options":["相对主义诡辩论的观点","唯物辩证法的观点","形而上学的观点","客观唯心主义的观点"],"answer":1,"answerLetter":"B","explain":"唯物辩证法认为运动是绝对的、无条件的，静止是相对的、有条件的，绝对运动和相对静止相互依 存、相互渗透，绝对运动中包含相对静止，相对静止中包含绝对运动。 相对主义诡辩论只承认绝对运动，否 认相对静止；形而上学则把静止绝对化，否认运动；客观唯心主义把某种客观精神当作世界本原，这几种观 点都不符合“绝对运动与相对静止相互包含”的表述。"},{"id":"marx-1-17","globalId":17,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":17,"question":"“社会形态的发展是一个自然历史过程”。这句话说的是（ ）。","options":["社会规律和自然规律没有差别","社会发展排斥主体选择的作用","社会发展取决于主体自由选择","社会发展具有不依人的意志为转移的客观规律性"],"answer":3,"answerLetter":"D","explain":"“社会形态的发展是一个自然历史过程”强调社会发展像自然界一样有其客观规律，不依赖人的意 志。A选项社会规律和自然规律有本质差别；B选项社会发展不排斥主体选择作用；C选项社会发展不是取决于 主体自由选择。"},{"id":"marx-1-18","globalId":18,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":18,"question":"“实践、认识、再实践、再认识，这种形式，循环往复以至无穷”体现的是（ ）。","options":["唯心主义辩证法","唯物主义辩证法","朴素唯物主义观点","机械唯物主义观点"],"answer":1,"answerLetter":"B","explain":"“实践、认识、再实践、再认识，循环往复以至无穷”这一认识发展的总规律，体现了认识和实践 的辩证统一，是符合马克思主义唯物辩证法的思想。马克思主义强调实践是认识的基础，认识在实践基础上 不断发展，这是唯物辩证法在认识领域的体现。 唯心主义辩证法强调精神、意识等第一性，与题干强调实践 基础不符；朴素唯物主义用具体物质形态解释世界，机械唯物主义具有机械性、形而上学性等，都与题干这 种认识的辩证发展规律不契合。"},{"id":"marx-1-19","globalId":19,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":19,"question":"“物以稀为贵”，这种现象在商品经济关系中主要是指（ ）。","options":["商品稀少价值就大","使用价值决定价值","供求关系对价格有重要影响","消费者的心理决定价值"],"answer":2,"answerLetter":"C","explain":"“物以稀为贵”强调的是商品因数量稀少，导致市场供求关系变化，进而影响价格。价值由社会必 要劳动时间决定，并非商品稀少程度、使用价值或消费者心理决定。所以该句话体现的是供求关系对价格有 重要影响。答案选C。"},{"id":"marx-1-20","globalId":20,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":20,"question":"相对剩余价值的获得是（ ）。","options":["延长工作日、增加剩余劳动时间的结果","工作日不变、增加必要劳动时间的结果","个别企业提高劳动生产率的结果","全社会劳动生产率普遍提高的结果"],"answer":3,"answerLetter":"D","explain":"D. 全社会劳动生产率普遍提高的结果（正确）相对剩余价值是指在工作日长度不变的条件下，通过 缩短必要劳动时间、相应延长剩余劳动时间而生产的剩余价值。而要缩短必要劳动时间，就必须降低劳动力 的价值（即降低劳动者所需生活资料的价值）。这依赖于全社会劳动生产率的普遍提高（包括生产生活资料 和生产这些生活资料所需生产资料部门的劳动生产率提高）。因此，相对剩余价值是全社会劳动生产率普遍 提高的结果。 A. 延长工作日、增加剩余劳动时间的结果（错误）这是绝对剩余价值的生产方法。通过绝对延长工作日长度 来增加剩余劳动时间，从而获取更多的剩余价值。 B. 工作日不变、增加必要劳动时间的结果（错误）这是一个干扰项。相对剩余价值的前提确实是“工作日不 变”，但它是通过缩短必要劳动时间（而不是增加）来实现的。如果必要劳动时间增加了，剩余劳动时间反 而会减少，剩余价值也会减少。 C. 个别企业提高劳动生产率的结果（错误）个别企业提高劳动生产率，会使该企业生产商品的个别劳动时间 低于社会必要劳动时间，从而获得超额剩余价值。超额剩余价值是相对剩余价值的起点，但个别企业获得的 是超额剩余价值，而不是相对剩余价值。当全社会劳动生产率普遍提高后，超额剩余价值消失，转化为相对 剩余价值。"},{"id":"marx-1-21","globalId":21,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":21,"question":"“狼孩”没有意识,这一事实说明（ ）。","options":["意识是生物长期发展的产物","意识是人脑发展的产物","意识是对客观事物的反映","意识是社会的产物"],"answer":3,"answerLetter":"D","explain":"“狼孩”具备人脑，也有生物进化基础，但因脱离人类社会环境而没有意识，这表明意识的产生离 不开社会环境，强调了意识是社会的产物。"},{"id":"marx-1-22","globalId":22,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":22,"question":"“生活、实践的观点,应该是认识论的首要的和基本的观点”的提出者是（ ）。","options":["马克思","恩格斯","列宁","毛泽东"],"answer":2,"answerLetter":"C","explain":"列宁在《唯物主义和经验批判主义》中提出“生活、实践的观点，应该是认识论的首要的和基本的 观点” 。"},{"id":"marx-1-23","globalId":23,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":23,"question":"“世界不是既成的事物的集合体，而是过程的集合体”。这是一种（ ）。","options":["唯物辩证法的观点","形而上学的观点","相对主义的观点","唯心主义的观点"],"answer":0,"answerLetter":"A","explain":"唯物辩证法强调世界是永恒发展的，一切事物都处在发生、发展和灭亡的过程中，该观点与“世界 是过程的集合体”相符。形而上学用孤立、静止、片面观点看问题；相对主义夸大事物相对性否定绝对性 ；唯心主义认为意识是世界本原。"},{"id":"marx-1-24","globalId":24,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":24,"question":"“哲学家们只是用不同的方式解释世界，问题在于改变世界”的提出者是（ ）。","options":["黑格尔","费尔巴哈","马克思","恩格斯"],"answer":2,"answerLetter":"C","explain":"“哲学家们只是用不同的方式解释世界，问题在于改变世界”是马克思在《关于费尔巴哈的提纲》 中提出的重要观点。它强调了实践的重要性，将哲学从单纯解释世界引向改变世界。"},{"id":"marx-1-25","globalId":25,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":25,"question":"新事物之所以必然战胜旧事物，从根本上说是由于（ ）。","options":["新事物是在旧事物之后产生的","新事物具有旧事物所没有的新形式","新事物具有旧事物所没有的新内容","新事物较旧事物更符合事物发展的必然趋势"],"answer":3,"answerLetter":"D","explain":"新事物必然战胜旧事物的根本原因在于，新事物符合事物发展的必然趋势，具有强大生命力和远大 前途。A选项产生先后不是决定因素；B、C选项新形式和新内容并非根本，关键是符合发展趋势。"},{"id":"marx-1-26","globalId":26,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":26,"question":"“没有理性，眼睛是最坏的见证人”。这句话强调的是（ ）。","options":["仅同事物的现象相符合的不一定是真相","只要同事物的现象相符合的就是真理","只要观察事物的外部联系就能获得真理","只要观察事物的偶然联系就能获得真理"],"answer":0,"answerLetter":"A","explain":"“没有理性，眼睛是最坏的见证人”，意思是光靠感性直观，不经过理性思考，看到的可能并非真 实情况。现象有真相和假象之分，仅与现象符合不一定是真相，需要理性分析。B选项说同现象符合就是真理 太绝对；C只观察外部联系、D只观察偶然联系都难以获得真理。"},{"id":"marx-1-27","globalId":27,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":27,"question":"“圣人不行而知”，这种观点属于（ ）。","options":["唯物主义反映论","旧唯物主义直观反映论","唯心主义先验论","辩证唯物主义能动反映论"],"answer":2,"answerLetter":"C","explain":"“圣人不行而知”意思是圣人不用实践就知晓，这否定了认识来源于实践，认为认识是先于实践和 经验而存在的，属于唯心主义先验论的观点。答案选C。"},{"id":"marx-1-28","globalId":28,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":28,"question":"“天行有常，不为尧存，不为桀亡。”这是说（ ）。","options":["规律仅仅存在于自然界","规律是无法认识和把握的","规律不具有客观普遍性","规律不以人的意志为转移"],"answer":3,"answerLetter":"D","explain":"“天行有常，不为尧存，不为桀亡”意思是大自然的运行有其自身规律，不会因为尧这样的圣君而 存在，也不会因为桀这样的暴君而消失，强调规律不会因人的意志改变，这体现了规律的客观性，不以人的 意志为转移。"},{"id":"marx-1-29","globalId":29,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":29,"question":"“注意分寸”“掌握火候”“适可而止”等说法，都是要在实践中坚持（ ）。","options":["适度原则","辩证否定观","实事求是","科学发展观"],"answer":0,"answerLetter":"A","explain":"“注意分寸”“掌握火候”“适可而止”强调做事要把握好度，不能过度，这体现的是适度原则。"},{"id":"marx-1-30","globalId":30,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":30,"question":"亚当·斯密和大卫·李嘉图是（ ）。","options":["德国古典哲学的代表人物","英国古典政治经济学的代表人物","英国空想社会主义的代表人物","法国空想社会主义的代表人物"],"answer":1,"answerLetter":"B","explain":"亚当·斯密和大卫·李嘉图是在政治经济学领域成就突出，主要活跃于英国。德国古典哲学代表是 康德、黑格尔等；空想社会主义代表人物圣西门、傅立叶等分别来自法国、英国等，但不是亚当·斯密和大 卫·李嘉图。"},{"id":"marx-1-31","globalId":31,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":31,"question":"“作为观念形态的文艺作品，都是一定的社会生活在人类头脑中的反映的产物”，这句话强调的是（ ）。","options":["社会意识根源于社会存在","社会意识具有历史继承性","社会存在根源于社会意识","社会意识具有相对独立性"],"answer":0,"answerLetter":"A","explain":"题干表明文艺作品（社会意识）是社会生活（社会存在）在人头脑中的反映产物，突出社会意识源 于社会存在。"},{"id":"marx-1-32","globalId":32,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":32,"question":"19世纪初期欧洲的空想社会主义者不包括","options":["法国的圣西门","法国的傅立叶","英国的欧文","英国的莫尔"],"answer":3,"answerLetter":"D","explain":"19世纪初期欧洲空想社会主义代表人物是法国的圣西门、傅立叶和英国的欧文 。而莫尔是16世纪早 期空想社会主义者，写有《乌托邦》。答案选D。"},{"id":"marx-1-33","globalId":33,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":33,"question":"把在法律和生产上独立的企业在流通环节统一起来,进行垄断经营的企业组织形式是（ ）。","options":["卡特尔","辛迪加","托拉斯 参考答案：B 【解析】 卡特尔是生产同类产品的企业通过签订协定划分销售市场，规定产量和价格等，企业在生产和法律 上仍保持独立，但在销售方面并非完全统一经营。 辛迪加是同一生产部门的企业通过签订协定，共同采购原 料和销售商品，在流通环节统一起来进行垄断经营，企业在生产和法律上保持独立。 托拉斯是把许多生产同 类产品或与产品经营有密切关系的企业合并组成大的企业，由董事会统一经营管理，参加的企业在生产、法 律上都丧失独立性。答案：B，辛迪加符合在法律和生产上独立的企业在流通环节统一起来进行垄断经营的特 点。 34.辩证法与形而上学在真理观上的对立在于是否承认（ ）。 A.真理具有相对性 B.真理具有客观性 C.真理具有主观性","真理具有绝对性"],"answer":0,"answerLetter":"A","explain":"辩证法认为世界是联系、发展的，承认真理是相对性和绝对性的统一，而形而上学用孤立、静止、 片面的观点看问题，往往否认真理的相对性，二者在真理观上对立在于是否承认真理具有相对性。答案：A 。"},{"id":"marx-1-35","globalId":34,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":35,"question":"揠苗助长”这个寓言说明（ ）。","options":["意识活动具有目的性和计划性","意识活动具有主动创造性","意识能通过指导实践改造客观物质世界","如果违背规律,越是发挥主观能动性,遭受的挫折和失败就越严重"],"answer":3,"answerLetter":"D","explain":"“揠苗助长”是指把苗拔起来，帮助其成长，这违背了禾苗自然生长的规律，最后导致禾苗死亡。 该行为体现出即便发挥主观能动性，但违背规律，就会遭受挫折失败。答案选D。"},{"id":"marx-1-36","globalId":35,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":36,"question":"要开一张包治百病的药方是很荒谬的,因为它违背了（ ）。","options":["任何事物都包含着矛盾的原理","事物的矛盾各有其特点的原理","普遍性存在于特殊性之中的原理","事物之间普遍联系的原理"],"answer":1,"answerLetter":"B","explain":"包治百病意味着忽视了不同疾病的差异，而不同疾病有不同特点，这违背了事物矛盾各有其特点的 原理。"},{"id":"marx-1-37","globalId":36,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":37,"question":"16世纪末，伽利略通过在比萨斜塔所做的自由落体实验，推翻了亚里士多德关于物体的降落速度与物体的 重量成正比的说法。这件事说明（ ）。","options":["真理是对事物及其规律的正确反映","真理是由相对真理走向绝对真理的过程","实践是认识发展的动力","实践是检验认识是否正确的唯一标准"],"answer":3,"answerLetter":"D","explain":"伽利略通过自由落体实验（实践活动），推翻了亚里士多德的错误说法，证明了自己对落体运动规 律的认识是正确的，这体现了实践能够检验认识是否正确，即实践是检验认识是否正确的唯一标准。"},{"id":"marx-1-38","globalId":37,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":38,"question":"19世纪欧洲空想社会主义是马克思主义直接理论来源之一，其代表人物是（ ）。","options":["配第、斯密、李嘉图","拉美特利、爱尔维修、狄德罗","康德、黑格尔、费尔巴哈","圣西门、傅立叶、欧文"],"answer":3,"answerLetter":"D","explain":"19世纪欧洲空想社会主义代表人物是圣西门、傅立叶、欧文 ，所以答案选D。A选项配第、斯密、李 嘉图是英国古典政治经济学代表；B选项拉美特利、爱尔维修、狄德罗是18世纪法国唯物主义哲学家；C选项 康德、黑格尔、费尔巴哈是德国古典哲学代表。"},{"id":"marx-1-39","globalId":38,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":39,"question":"一般而言，经济全球化的主要内容不包括（ ）。","options":["生产全球化","贸易全球化","资本全球化","劳动力流动全球化"],"answer":3,"answerLetter":"D","explain":"经济全球化主要包括生产全球化、贸易全球化和资本全球化。劳动力流动全球化虽存在，但不是经 济全球化主要内容。答案选D。"},{"id":"marx-1-40","globalId":39,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":40,"question":"20世纪后半叶兴起的垄断组织形式主要是（ ）。","options":["卡特尔","辛迪加","混合联合企业","康采恩"],"answer":2,"answerLetter":"C","explain":"20世纪后半叶兴起的垄断组织形式主要是混合联合企业 ，它是一种跨行业多样化经营的垄断组织。 卡特尔、辛迪加、康采恩是早期垄断组织形式。"},{"id":"marx-1-41","globalId":40,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":41,"question":"把马克思主义作为行动的指南，就是要（ ）。","options":["用马克思主义的立场、观点和方法研究解决实际问题","从马克思主义经典著作中寻找解决现实问题的直接答案","把马克思主义当作现成的公式裁剪历史事实","一切从马克思主义的一般原理出发"],"answer":0,"answerLetter":"A","explain":"马克思主义是科学的世界观和方法论，作为行动指南应运用其立场、观点和方法研究解决实际问题 ，A 项正确。B 项，现实问题复杂多样，不能单纯从经典著作找直接答案；C 项，把马克思主义当现成公式 裁剪历史事实，违背实事求是；D 项，应一切从实际出发，而非从马克思主义一般原理出发。"},{"id":"marx-1-42","globalId":41,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":42,"question":"处于垄断地位的大银行在当代资本主义社会中的地位表现在（ ）。","options":["它已掌控了所有银行业务","它已成为社会经济生活中的万能垄断者","它已控制了整个国民经济","它已掌握了国民经济的命脉"],"answer":1,"answerLetter":"B","explain":"在当代资本主义社会，处于垄断地位的大银行凭借其强大的金融实力和广泛的业务网络，渗透到社 会经济生活的各个方面，成为“万能垄断者”。A选项“掌控所有银行业务”表述太绝对；C选项“控制整个 国民经济”不准确，大银行虽影响力大但不能完全控制整个国民经济；D选项掌握国民经济命脉表述不准确 ，大银行主要是在金融领域影响力大。答案：B。"},{"id":"marx-1-43","globalId":42,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":43,"question":"从本质上看，货币是（ ）。","options":["特殊的资本","普通的商品","一般等价物","固定地充当一般等价物的商品"],"answer":3,"answerLetter":"D","explain":"货币的本质是固定地充当一般等价物的商品。货币与普通商品不同，它能表现其他一切商品的价值 ，具有与其他一切商品相交换的能力，是从商品中分离出来的，所以B选项错误。资本是能够带来剩余价值的 价值，货币只有在一定条件下才成为资本，A选项错误。一般等价物在历史上有很多形式，不固定，而货币是 固定充当一般等价物的，C选项表述不准确。"},{"id":"marx-1-44","globalId":43,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":44,"question":"一切唯心主义都主张（ ）。","options":["精神是世界的本原","存在就是被感知","世界是绝对精神的产物","理是天地万物之根"],"answer":0,"answerLetter":"A","explain":"唯心主义的核心观点就是认为精神是第一性的，是世界的本原。B选项“存在就是被感知”是主观唯 心主义观点；C选项“世界是绝对精神的产物”是客观唯心主义代表黑格尔的观点；D选项“理是天地万物之 根”也是客观唯心主义观点。它们都只是唯心主义的具体表现形式，A选项概括了唯心主义的共性主张。答案 ：A"},{"id":"marx-1-45","globalId":44,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":45,"question":"按照辩证唯物主义一元论的根本要求,在工作中必须坚持（ ）。","options":["一切从人的需要出发","一切从主观愿望出发","一切从客观实际出发","一切从理论原则出发"],"answer":2,"answerLetter":"C","explain":"辩证唯物主义一元论强调世界的本原是物质，物质第一性，意识第二性，这就要求我们在工作中要 尊重客观事实，从实际情况出发。A选项从人的需要出发、B选项从主观愿望出发、D选项从理论原则出发，都 忽视了客观实际，是主观主义的做法。而C选项一切从客观实际出发符合辩证唯物主义一元论的要求。答案 ：C"},{"id":"marx-1-46","globalId":45,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":46,"question":"把社会主义本质概括为\"解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕\"的中国 共产党人是（ ）。","options":["毛泽东","刘少奇","周恩来","邓小平"],"answer":3,"answerLetter":"D","explain":"1992年初，邓小平在南方谈话中对社会主义本质作了总结性理论概括，即“解放生产力，发展生产 力，消灭剥削，消除两极分化，最终达到共同富裕” 。"},{"id":"marx-1-47","globalId":46,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":47,"question":"当代，自然科学的发展日新月异，新的科研成果层出不穷。从根本上说，这是由（ ）。","options":["科学家的聪明才智决定的","生产实践的需要决定的","正确的科技政策决定的","环境和资源的状况决定的"],"answer":1,"answerLetter":"B","explain":"实践是认识的基础，实践是认识发展的动力，自然科学属于认识范畴，其发展的根本原因是生产实 践的需要，生产实践不断提出新课题，推动自然科学发展。A选项科学家聪明才智有影响但非根本；C选项科 技政策有促进作用但非根源；D选项环境和资源状况是外部条件并非根本决定因素。"},{"id":"marx-1-48","globalId":47,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":48,"question":"当代国际垄断组织保证其垄断统治和垄断利益的最主要形式是（ ）。","options":["卡特尔和托拉斯","辛迪加和托拉斯","跨国公司和国际垄断同盟","跨国公司和托拉斯"],"answer":2,"answerLetter":"C","explain":"当代国际垄断组织的主要形式是跨国公司和国际垄断同盟 ，它们是保证垄断统治和垄断利益的最主 要形式。而卡特尔、辛迪加、托拉斯是国内垄断组织的形式。答案选C。"},{"id":"marx-1-49","globalId":48,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":49,"question":"按照技术社会形态的划分标准,我们可以把人类历史划分为（ ）。","options":["人的依赖性社会、物的依赖性社会、个人全面发展的社会","渔猎社会、农业社会、工业社会、信息社会","自然经济社会、商品经济社会、产品经济社会","古代社会、近代社会、现代社会"],"answer":1,"answerLetter":"B","explain":"技术社会形态是以生产力和技术发展水平以及与此相适应的产业结构为标准划分的社会形态，包括 渔猎社会、农业社会、工业社会、信息社会 。A选项是根据人的发展状况划分；C选项是根据经济运行形态划 分；D选项划分角度不属技术社会形态范畴。"},{"id":"marx-1-50","globalId":49,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":50,"question":"把实践证实的理论看成是永恒不变的绝对真理,并当成检验其他一切认识是否正确的标准,这是一种（ ）。","options":["唯物辩证法观点","唯理论观点","相对主义诡辩论观点","形而上学观点"],"answer":3,"answerLetter":"D","explain":"题干中把实践证实的理论看成永恒不变的绝对真理，忽视了真理的相对性，用固定不变的标准去衡 量一切，这体现了形而上学用孤立、静止、片面的观点看问题的特点。 唯物辩证法强调用联系、发展、全面 的观点看问题，与题干不符；唯理论片面夸大理性认识的作用，题干重点强调对真理的绝对化看法，并非唯 理论核心观点；相对主义诡辩论则夸大事物的相对性而否定确定性和客观性，也不符合题干表述。答案 ：D.形而上学观点"},{"id":"marx-1-51","globalId":50,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":51,"question":"辩证唯物主义认为，运动和静止的关系属于（ ）。","options":["本质和现象的关系","内容和形式的关系","绝对和相对的关系","可能和现实的关系"],"answer":2,"answerLetter":"C","explain":"辩证唯物主义认为，运动是绝对的，无条件的；静止是相对的，有条件的，运动和静止是绝对和相 对的关系 。"},{"id":"marx-1-52","globalId":51,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":52,"question":"产业资本循环采取的职能形式是（ ）。","options":["生产资本、流通资本和银行资本","生产资本、商业资本和银行资本","货币资本、生产资本和商品资本","货币资本、生产资本和商业资本"],"answer":2,"answerLetter":"C","explain":"产业资本在循环过程中要依次经历三个阶段，相应采取货币资本、生产资本和商品资本三种职能形 式。货币资本为生产剩余价值做准备，生产资本生产剩余价值，商品资本实现剩余价值。所以答案选C 。"},{"id":"marx-1-53","globalId":52,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":53,"question":"凡是承认世界具有统一性的哲学都属于（ ）。","options":["唯物论","唯心论","二元论","一元论"],"answer":3,"answerLetter":"D","explain":"一元论认为世界只有一个本原，承认世界具有统一性，即世界统一于一个本原。唯物论和唯心论都 属于一元论，分别认为世界统一于物质和意识。二元论主张世界有精神和物质两个独立本原，不承认世界的 统一性。所以凡是承认世界具有统一性的哲学都属于一元论。"},{"id":"marx-1-54","globalId":53,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":54,"question":"反映资本家对工人剥削程度的剩余价值率，可表示为（ ）。","options":["m：v","v：m","m：（c+V）","（c+v）：m"],"answer":0,"answerLetter":"A","explain":"剩余价值率是剩余价值（m）和可变资本（v）的比率，它反映资本家对工人的剥削程度。因为可变 资本是用于购买劳动力的资本，工人在劳动过程中创造的剩余价值与可变资本的比例，能体现资本家对工人 的剥削程度。 选项C中m:(c + v)是利润率的表达式，c是不变资本，c + v是总资本，它反映的是资本增殖程 度，而非剥削程度。选项Bv:m和选项D(c + v):m不符合剩余价值率的定义。"},{"id":"marx-1-55","globalId":54,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":55,"question":"标志着科学社会主义理论公开面世的纲领性文件是（ ）。","options":["《共产主义原理》","《共产党宣言》","《哥达纲领批判》","《国家与革命》"],"answer":1,"answerLetter":"B","explain":"《共产党宣言》是马克思和恩格斯为共产主义者同盟起草的纲领，它的发表，标志着科学社会主义 理论公开面世。而A选项《共产主义原理》为《共产党宣言》做了理论准备；C选项《哥达纲领批判》批判拉 萨尔主义，发展科学社会主义；D选项《国家与革命》是列宁关于国家和法学说方面的著作。"},{"id":"marx-1-56","globalId":55,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":56,"question":"产业资本循环中生产剩余价值的阶段是（ ）。","options":["购买阶段","生产阶段","销售阶段","流通阶段"],"answer":1,"answerLetter":"B","explain":"在产业资本循环的购买阶段，资本家购买生产资料和劳动力，为生产剩余价值做准备，此时还未产 生剩余价值，A选项不符合。 生产阶段中，劳动力与生产资料相结合进行生产，工人的劳动创造出包含剩余 价值的商品，所以这个阶段是生产剩余价值的阶段，B选项正确。 销售阶段是把包含剩余价值的商品卖出去 ，实现价值和剩余价值，而不是生产剩余价值，C选项不符合。 流通阶段包括购买阶段和销售阶段，都不直 接生产剩余价值，D选项不符合。"},{"id":"marx-1-57","globalId":56,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":57,"question":"公式W…P…表示的是产业资本循环的（ ）。","options":["购买阶段","生产阶段","销售阶段","流通阶段"],"answer":1,"answerLetter":"B","explain":"产业资本循环有三个阶段，购买阶段是货币资本转化为生产资本，用 G - W 表示；生产阶段是生产 资本转化为商品资本，用 W…P…W' 表示，这里 W 是生产资料和劳动力， P 是生产过程；销售阶段是商品 资本转化为货币资本，用 W' - G' 表示。题干中 W…P… 符合生产阶段的公式表示。"},{"id":"marx-1-58","globalId":57,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":58,"question":"公司金融寡头在经济上的统治主要是通过（ ）。","options":["自由竞争来实现","私人垄断来实现","“参与制”来实现","“个人联合”来实现"],"answer":2,"answerLetter":"C","explain":"金融寡头在经济上的统治主要是通过“参与制”实现，“参与制”是指金融寡头通过掌握一定数量 的股票来层层控制企业的制度。而自由竞争与金融寡头统治无关；私人垄断表述不准确；“个人联合”是金 融寡头在政治上统治的手段。"},{"id":"marx-1-59","globalId":58,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":59,"question":"已购买而尚未使用的生产资料处于资本循环的（ ）。","options":["购买阶段","生产阶段","销售阶段","流通阶段"],"answer":0,"answerLetter":"A","explain":"资本循环包括购买阶段、生产阶段和销售阶段。购买阶段资本家购买生产资料和劳动力，为生产剩 余价值准备条件；生产阶段是生产资料与劳动力结合生产出包含剩余价值的商品；销售阶段是将商品卖出 ，实现价值和剩余价值。已购买而尚未使用的生产资料，表明已完成购买行为，但还未进入生产过程，处于 购买阶段向生产阶段的过渡状态，仍属于资本循环的购买阶段。"},{"id":"marx-1-60","globalId":59,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":60,"question":"产生资本主义经济危机的根源是（ ）。","options":["生产相对过剩","需求绝对减少","资本主义基本矛盾","生产和消费的矛盾"],"answer":2,"answerLetter":"C","explain":"资本主义经济危机根源在于资本主义基本矛盾，即生产的社会化与生产资料资本主义私人占有之间 的矛盾。这一矛盾引发了生产相对过剩等一系列问题。A选项生产相对过剩是经济危机的本质特征而非根源 ；B选项需求绝对减少表述错误；D选项生产和消费的矛盾由资本主义基本矛盾引发，不是根源。"},{"id":"marx-1-61","globalId":60,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":61,"question":"除了剩余价值与可变资本的比率外，剩余价值率还可以表示为（ ）。","options":["剩余劳动时间与必要劳动时间的比率","剩余劳动时间与社会必要劳动时间的比率","可变资本与不变资本的比率","利润与预付总资本的比率"],"answer":0,"answerLetter":"A","explain":"剩余价值率反映资本家对工人的剥削程度，它有两种表示方法。一种是物化劳动表示法，即剩余价 值与可变资本的比率；另一种是活劳动表示法，即剩余劳动时间与必要劳动时间的比率。因为工人的全部劳 动时间分为必要劳动时间和剩余劳动时间，剩余价值就是由工人在剩余劳动时间创造出来的。"},{"id":"marx-1-62","globalId":61,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":62,"question":"马克思主义认为，哲学是（ ）。","options":["人们自发形成的世界观","系统化、理论化的世界观","科学的世界观","无产阶级的世界观"],"answer":1,"answerLetter":"B","explain":"马克思主义认为哲学是系统化、理论化的世界观。自发形成的世界观并非哲学，A 排除；哲学有科 学与非科学之分，并非所有哲学都是科学的世界观，C 排除；无产阶级的世界观只是马克思主义哲学的属性 之一，不能等同于哲学的定义，D 排除。答案：B。"},{"id":"marx-1-63","globalId":62,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":63,"question":"英国古典政治经济学是马克思主义的直接理论来源之一，其代表人物是（ ）。","options":["培根、洛克","斯密、李嘉图","黑格尔、费尔巴哈","圣西门、傅立叶"],"answer":1,"answerLetter":"B","explain":"马克思主义直接理论来源中英国古典政治经济学代表人物是亚当·斯密和大卫·李嘉图。A选项培根 、洛克主要在哲学等领域；C选项黑格尔、费尔巴哈是德国古典哲学代表；D选项圣西门、傅立叶是空想社会 主义代表。"},{"id":"marx-1-64","globalId":63,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":64,"question":"平均利润形成之后,价值规律的作用形式表现为市场价格围绕（ ）。","options":["生产成本上下波动","平均利润上下波动","价值上下波动","生产价格上下波动"],"answer":3,"answerLetter":"D","explain":"平均利润形成后，商品价值就转化为生产价格，生产价格由生产成本加平均利润构成。此时价值规 律作用形式发生变化，市场价格不再围绕价值而是围绕生产价格上下波动。"},{"id":"marx-1-65","globalId":64,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":65,"question":"用于发放工资的货币执行的是货币的（ ）。","options":["价值尺度职能","流通手段职能","支付手段职能","贮藏手段职能"],"answer":2,"answerLetter":"C","explain":"支付手段是指货币用于清偿债务、支付赋税、租金、工资等的职能，发放工资体现了货币延期支付 的特点，属于支付手段职能。"},{"id":"marx-1-66","globalId":65,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":66,"question":"马克思主义认为社会生活在本质上是实践的，这是因为（ ）。","options":["实践主体处于一定的社会关系中","实践具有客观性、能动性和社会历史性","实践是个人日常生活的活动","实践是人类社会产生、存在和发展的基础"],"answer":3,"answerLetter":"D","explain":"马克思主义强调社会生活本质上是实践的，关键在于实践对于人类社会产生、存在和发展起到了基 础性作用。人类通过实践活动创造了自身赖以生存的社会关系、社会结构等。A选项说的是实践主体的特征 ，B选项阐述的是实践本身的特点，C选项对实践的定义过于狭隘。只有D选项准确说明了实践对人类社会的根 本意义。"},{"id":"marx-1-67","globalId":66,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":67,"question":"群众路线的基本出发点和最终归宿是（ ）。","options":["一切为了群众","从群众中来","一切依靠群众","到群众中去"],"answer":0,"answerLetter":"A","explain":"群众路线包括“一切为了群众，一切依靠群众，从群众中来，到群众中去”。“一切为了群众”体 现的是目的，全心全意为人民服务，这是群众路线的基本出发点和最终归宿 。“一切依靠群众”强调力量来 源。“从群众中来，到群众中去”是工作方法。"},{"id":"marx-1-68","globalId":67,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":68,"question":"由于提高劳动强度而生产的剩余价值属于","options":["绝对剩余价值","超额剩余价值","相对剩余价值","超额利润"],"answer":0,"answerLetter":"A","explain":"绝对剩余价值是指在必要劳动时间不变的条件下，通过绝对延长工作日，从而绝对延长剩余劳动时 间来生产出来的剩余价值。此外，提高劳动强度，让工人在同样时间内耗费更多体力与脑力，与延长工作日 效果类似，也属于绝对剩余价值生产。相对剩余价值是在工作日长度不变时，通过缩短必要劳动时间、相应 延长剩余劳动时间获得的；超额剩余价值是个别资本家提高劳动生产率，使商品个别价值低于社会价值的差 额；超额利润是超过平均利润的那部分利润。"},{"id":"marx-1-69","globalId":68,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":69,"question":"从历史上看，暴力革命是社会革命的","options":["唯一形式","基本形式","辅助形式","补充形式"],"answer":1,"answerLetter":"B","explain":"在阶级社会中，暴力革命是社会革命的基本形式。因为统治阶级不会自动让出政权，往往要用暴力 打破旧的国家机器等。非暴力的和平过渡只是在特定条件下才有可能出现，但不是主要的、基本的形式。答 案：B"},{"id":"marx-1-70","globalId":69,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":70,"question":"从资本周转的角度来考察资本的构成，划分为固定资本和流动资本的是（ ）。","options":["生产资本","货币资本","商品资本","流通资本"],"answer":0,"answerLetter":"A","explain":"只有生产资本能从资本周转角度划分为固定资本和流动资本。货币资本、商品资本属于流通资本 ，它们不做这样的划分。"},{"id":"marx-1-71","globalId":70,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":71,"question":"马克思主义是时代的产物。马克思恩格斯所处的历史时代及其提出的各项任务，为马克思主义的产生提供 了","options":["主观条件","客观条件","理论基础","理论前提"],"answer":1,"answerLetter":"B","explain":"马克思恩格斯所处时代及任务是外在的、既定的状况，属于客观范畴，为马克思主义产生提供了客 观条件。主观条件强调人的内在思想等因素；理论基础和理论前提侧重于已有的理论成果，与时代及任务这 种客观背景不符。"},{"id":"marx-1-72","globalId":71,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":72,"question":"由资本主义国家收购部分股权后的私人企业属于（ ）。","options":["国家和私人资本在企业外部的结合","国家和私人资本在企业内部的结合","资本主义国有经济","资本主义私人经济"],"answer":1,"answerLetter":"B","explain":"国家收购部分股权后，国家资本和私人资本在企业内部融合在一起，形成了国家和私人资本在企业 内部的结合这种形式。"},{"id":"marx-1-73","globalId":72,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":73,"question":"当代中国人民为之奋斗的共同理想是（ ）。","options":["建设中国特色社会主义","实现共产主义","彻底消灭剥削","国家自行消亡"],"answer":0,"answerLetter":"A","explain":"建设中国特色社会主义是当代中国人民的共同理想，它把国家的发展、民族的振兴与个人的幸福紧 密联系在一起。共产主义是最高理想，C选项“彻底消灭剥削”和D选项“国家自行消亡”是共产主义社会的 特征，并非当代共同理想。"},{"id":"marx-1-74","globalId":73,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":74,"question":"当代资本主义国家在经济关系方面的一系列新变化表明（ ）。","options":["其社会性质已经根本改变","其基本矛盾已经彻底解决","其阶级对立已经消失","其社会性质发生了部分质变"],"answer":3,"answerLetter":"D","explain":"当代资本主义国家在经济关系等方面虽有新变化，但资本主义私有制基础未变，所以社会性质未根 本改变，基本矛盾未彻底解决，阶级对立也依然存在。不过新变化使得资本主义在自身范围内进行调整，发 生了部分质变。"},{"id":"marx-1-75","globalId":74,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":75,"question":"马克思主义哲学认为，物质的唯一特性是（ ）。","options":["广延性","持续性","可知性","客观实在性"],"answer":3,"answerLetter":"D","explain":"马克思主义哲学强调物质的本质特征，客观实在性是物质区别于意识的根本特性，它不依赖于人的 意识而存在。广延性、持续性属于物质的属性但不是唯一特性，可知性强调物质能被认识，并非物质的唯一 特性。答案：D。"},{"id":"marx-1-76","globalId":75,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":76,"question":"商品生产者要获得更多收益,必须使生产商品的（ ）。","options":["个别劳动时间等于社会必要劳动时间","个别劳动时间低于社会必要劳动时间","个别劳动时间高于社会必要劳动时间","个别劳动时间低于必要劳动时间"],"answer":1,"answerLetter":"B","explain":"商品价值由社会必要劳动时间决定，当个别劳动时间低于社会必要劳动时间时，意味着生产者在同 样时间内生产的商品数量更多，按社会必要劳动时间决定的价值量出售，就能获得更多收益。"},{"id":"marx-1-77","globalId":76,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":77,"question":"当代主要发达资本主义国家处于资本主义发展中的（ ）。","options":["自由竞争资本主义阶段","私人垄断资本主义阶段","一般垄断资本主义阶段","国家垄断资本主义阶段"],"answer":3,"answerLetter":"D","explain":"当代主要发达资本主义国家，国家对经济的干预和调节不断加强，经济运行机制、产业结构等都发 生深刻变化，这些特征符合国家垄断资本主义阶段。在国家垄断资本主义阶段，国家政权与私人垄断资本相 结合，对经济生活进行全面干预和调节。"},{"id":"marx-1-78","globalId":77,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":78,"question":"当代资本主义所发生的许多新变化属于（ ）。","options":["资本主义生产方式的根本改变","资本主义生产关系性质的根本改变","资本主义总量变过程中的爆发式质变","资本主义总量变过程中的阶段性部分质变"],"answer":3,"answerLetter":"D","explain":"当代资本主义虽然有诸多新变化，但资本主义私有制等根本性质未变，只是在其自身范围内的调整 ，属于总量变过程中的阶段性部分质变，并非根本改变或爆发式质变。"},{"id":"marx-1-79","globalId":78,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":79,"question":"马克思主义哲学以前欧洲哲学的全部积极内容，都是马克思主义哲学的理论来源，其中作为马克思主义哲 学直接理论来源的是（ ）。","options":["古希腊罗马哲学","德国古典哲学","近代英国哲学","近代法国哲学"],"answer":1,"answerLetter":"B","explain":"马克思主义哲学的直接理论来源是德国古典哲学，主要是黑格尔辩证法的合理内核与费尔巴哈唯物 主义的基本内核。答案选B。"},{"id":"marx-1-80","globalId":79,"part":1,"partName":"第一部分 马原核心概念与唯物论","category":"马原专项 · 第一部分 马原核心概念与唯物论","num":80,"question":"商品生产者要实现更多的收益必须使（ ）。","options":["个别劳动时间等于社会必要劳动时间","个别劳动时间大于社会必要劳动时间","个别劳动时间小于社会必要劳动时间","个别劳动时间等于倍加的社会必要劳动时间"],"answer":2,"answerLetter":"C","explain":"社会必要劳动时间决定商品价值量，个别劳动时间小于社会必要劳动时间时，商品生产者按社会必 要劳动时间决定的价值量出售商品，能获得额外收益；若个别劳动时间大于社会必要劳动时间，生产者会亏 损。A选项无额外收益，B会亏损，D表述不合理。答案选C，商品生产者要实现更多收益需使个别劳动时间小 于社会必要劳动时间 。 所以答案为C。"},{"id":"marx-2-2","globalId":80,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":2,"question":"与辩证唯物主义认识论相比较，旧唯物主义认识论有两个缺陷，一个是缺乏辩证法的观点，另一个是（ ）。","options":["缺乏实践的观点","缺乏反映论的观点","缺乏一元论的观点","缺乏可知论的观点"],"answer":0,"answerLetter":"A","explain":"旧唯物主义认识论主要的缺陷就是缺乏实践的观点以及辩证法的观点。实践的观点是马克思主义认 识论首要的和基本的观点，旧唯物主义不懂得实践对认识的决定作用。"},{"id":"marx-2-2","globalId":81,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":2,"question":"当代资本主义国家发生了一系列新变化,不属于这些新变化的是（ ）。","options":["工人持股现象的产生","资本社会化趋势的发展","工会组织的产生","社会福利事业的发展"],"answer":2,"answerLetter":"C","explain":"工会组织在19世纪就已产生，并非当代资本主义国家的新变化。而工人持股、资本社会化趋势、社 会福利事业发展是当代资本主义出现的新情况。"},{"id":"marx-2-3","globalId":82,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":3,"question":"矛盾的两种基本属性是（ ）。","options":["同一性和斗争性","统一性和多样性","普遍性和牺牲性","一般性和个别性"],"answer":0,"answerLetter":"A","explain":"矛盾的两种基本属性是同一性和斗争性，这是哲学中关于矛盾的基本知识点。所以答案是A。"},{"id":"marx-2-4","globalId":83,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":4,"question":"商品最本质的因素是（ ）。","options":["使用价值","价值","交换价值","价格"],"answer":1,"answerLetter":"B","explain":"价值是凝结在商品中的无差别的一般人类劳动，它体现着商品生产者之间相互比较劳动耗费量和交 换劳动的社会经济关系，是商品最本质的因素。使用价值是商品的自然属性，是价值的物质承担者；交换价 值是价值的表现形式；价格是价值的货币表现。"},{"id":"marx-2-5","globalId":84,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":5,"question":"德国古典哲学是马克思主义的直接理论来源之一，其代表人物是（ ）。","options":["培根、洛克","圣西门、欧文","黑格尔、费尔巴哈","斯密、李嘉图"],"answer":2,"answerLetter":"C","explain":"德国古典哲学代表人物是黑格尔和费尔巴哈。A选项培根、洛克是英国经验论哲学家；B选项圣西门 、欧文是空想社会主义代表人物；D选项斯密、李嘉图是英国古典政治经济学代表人物。"},{"id":"marx-2-6","globalId":85,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":6,"question":"对世界存在状态问题的不同回答所区分的哲学派别是（ ）。","options":["可知论和不可知论","反映论和先验论","辩证法和形而上学","物主义和唯心主义"],"answer":2,"answerLetter":"C","explain":"辩证法和形而上学是对世界存在状态问题的不同回答。辩证法用联系、发展、全面的观点看世界 ，形而上学用孤立、静止、片面的观点看世界。 A选项可知论和不可知论是对思维和存在是否具有同一性的 不同回答。 B选项反映论和先验论是关于认识的来源等方面的不同观点。 D选项唯物主义和唯心主义是对世 界本原问题的不同回答。"},{"id":"marx-2-7","globalId":86,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":7,"question":"面对消极腐败的东西，我们一定要提高警惕，做到见微知著，防微杜渐。从哲学上看，这是因为（ ）。","options":["矛盾双方在一定条件下相互转化","量变积累到一定程度会引起质变","多种原因引起一个结果","外因通过内因而起作用"],"answer":1,"answerLetter":"B","explain":"“见微知著，防微杜渐”强调的是在消极腐败的事物还处于微小、萌芽状态时就要加以防范，因为 如果任由其发展，微小的量变不断积累，最终会引发质变，产生严重后果。这体现的是量变与质变的辩证关 系。"},{"id":"marx-2-8","globalId":87,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":8,"question":"商业资本家所占有的剩余价值是通过（ ）。","options":["剥削商业店员的具体劳动获得的","剥削商业店员的剩余劳动获得的","剥削产业工人的具体劳动获得的","剥削产业工人的必要劳动获得的"],"answer":1,"answerLetter":"B","explain":"商业资本家通过剥削商业店员的剩余劳动，让商业店员在剩余劳动时间内实现产业资本家让渡给商 业资本家的那部分剩余价值。商业资本家从而占有这部分剩余价值。"},{"id":"marx-2-9","globalId":88,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":9,"question":"在对外经济侵略中，新殖民主义不同于老殖民主义的手法是（ ）。","options":["高价出售工业产品","低价收购原料和初级产品","向外输出“过剩资本”获取高额海外利润","打着“援助”旗号剥削和控制发展中国家"],"answer":3,"answerLetter":"D","explain":"老殖民主义主要通过赤裸裸的军事侵略、直接的殖民统治来掠夺；新殖民主义是在承认殖民地、附 属国形式上政治独立的前提下，通过经济、政治、军事、文化渗透等手段来控制，打着“援助”旗号剥削和 控制发展中国家是新殖民主义典型手法，而A、B、C选项在老殖民主义时期也常用。"},{"id":"marx-2-10","globalId":89,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":10,"question":"商业资本所执行的职能是（ ）。","options":["购买生产资料和劳动力","生产出剩余价值","销售商品，实现价值和剩余价值","贷出货币，投入生产和流通中"],"answer":2,"answerLetter":"C","explain":"商业资本是从产业资本中分离出来，专门从事商品买卖，以获取商业利润为目的的资本形式。其职 能就是通过销售商品，实现商品中的价值和剩余价值。A选项是产业资本购买阶段职能；B选项生产剩余价值 是产业资本生产阶段职能；D选项贷出货币与商业资本职能无关。"},{"id":"marx-2-11","globalId":90,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":11,"question":"在购买阶段,产业资本采取的职能形式是（ ）。","options":["货币资本","生产资本","商品资本","商业资本"],"answer":0,"answerLetter":"A","explain":"产业资本循环的购买阶段，资本家要用货币购买生产资料和劳动力，此时产业资本采取货币资本形 式，为生产剩余价值准备条件。生产资本是在生产阶段的职能形式，商品资本是售卖阶段的职能形式，商业 资本不属于产业资本在循环中特定阶段的职能形式。"},{"id":"marx-2-12","globalId":91,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":12,"question":"分析矛盾的特殊性就是（ ）。","options":["坚持实践的观点","坚持理论联系实际","坚持辩证的否定","坚持具体问题具体分析"],"answer":3,"answerLetter":"D","explain":"矛盾特殊性原理要求我们在分析和解决问题时，不能一概而论，要针对不同情况、不同问题采取不 同方法，也就是要具体问题具体分析。"},{"id":"marx-2-13","globalId":92,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":13,"question":"感性认识和理性认识的区别在于（ ）。","options":["前者源于书本,后者源于实践","前者是可靠的,后者是不可靠的","前者反映事物的现象,后者反映事物的本质","前者来源于直接经验,后者来源于间接经验"],"answer":2,"answerLetter":"C","explain":"感性认识是认识的初级阶段，通过感觉、知觉和表象等形式反映事物的现象；理性认识是认识的高 级阶段，以概念、判断、推理等形式反映事物的本质。A选项，感性认识和理性认识都源于实践；B选项，感 性认识和理性认识都有可靠与不可靠之分；D选项，直接经验和间接经验都可以产生感性认识和理性认识。所 以答案选C。"},{"id":"marx-2-14","globalId":93,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":14,"question":"商业资本资本的职能是（ ）。","options":["购买生产资料和劳动力","创造价值和剩余价值","实现商品的价值和剩余价值","补偿商品买卖的各种费用"],"answer":2,"answerLetter":"C","explain":"商业资本是从产业资本中分离出来，专门从事商品买卖，独立发挥资本职能，以获取商业利润为目 的的一种资本形式。其职能就是通过商品销售，实现商品的价值和剩余价值。A选项是产业资本在生产阶段的 职能；B选项创造价值和剩余价值的是产业资本的生产过程；D选项补偿费用并非商业资本的职能。"},{"id":"marx-2-15","globalId":94,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":15,"question":"在经济全球化过程中，成为垄断资本国际经济组织载体的新的垄断组织形式是（ ）。","options":["混合联合公司","跨国公司","托拉斯","国际垄断联盟"],"answer":1,"answerLetter":"B","explain":"在经济全球化进程中，跨国公司是垄断资本国际经济组织的重要载体。混合联合公司、托拉斯属于 国内垄断组织形式，国际垄断联盟并非垄断资本国际经济组织载体的新形式。"},{"id":"marx-2-16","globalId":95,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":16,"question":"设想没有运动的物质的观点是（ ）。","options":["形而上学唯物主义","朴素唯物主义","主观唯心主义","客观唯心主义"],"answer":0,"answerLetter":"A","explain":"形而上学唯物主义具有机械性等局限性，它割裂了物质和运动的关系，设想没有运动的物质。朴素 唯物主义主要是用具体物质形态解释世界本质；主观唯心主义把人的主观精神当作世界本原；客观唯心主义 把客观精神当作世界本原，这三者与设想没有运动的物质这一观点不相关。"},{"id":"marx-2-17","globalId":96,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":17,"question":"在历史创造者问题上,两种根本对立的观点是（ ）。","options":["群众史观和英雄史观","一元论和二元论","宿命论和唯意志论","唯理论和经验论"],"answer":0,"answerLetter":"A","explain":"在历史创造者问题上，主要存在群众史观和英雄史观这两种根本对立观点。群众史观认为人民群众 是历史创造者，英雄史观则夸大个人作用，忽视人民群众。其他选项B关于世界本原问题，C涉及对历史发展 决定性的不同看法，D是关于认识来源不同观点，均与历史创造者问题无关。"},{"id":"marx-2-18","globalId":97,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":18,"question":"股份公司的经营决策机构是（ ）。","options":["股东大会","董事会","监事","工会"],"answer":1,"answerLetter":"B","explain":"股东大会是股份公司的权力机构，决定公司的重大事项。 董事会是公司的经营决策机构，负责执 行股东大会的决议，对公司的经营管理进行决策。 监事主要负责监督公司的经营管理活动，检查公司财务等 ，不是经营决策机构。 工会是维护职工合法权益的组织，与公司经营决策无关。"},{"id":"marx-2-19","globalId":98,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":19,"question":"认识的真理性,就是检验认识是否同（ ）。","options":["已被实践证实的理论相符合","大多数人的主观愿望相符合","客观事物及其规律相符合","党的路线、方针、政策相符合"],"answer":2,"answerLetter":"C","explain":"真理是人们对客观事物及其规律的正确反映，认识的真理性在于检验认识是否与客观事物及其规律 相符合。A选项以已被实践证实的理论为标准不具有根源性；B选项以大多数人主观愿望为标准是主观的，不 是真理标准；D选项党的路线方针政策也是基于对客观规律的认识制定的，不是最终检验标准。"},{"id":"marx-2-20","globalId":99,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":20,"question":"社会必要劳动时间是以（ ）。","options":["具体劳动为尺度的","简单劳动为尺度的","复杂劳动为尺度的","个别劳动为尺度的"],"answer":1,"answerLetter":"B","explain":"社会必要劳动时间的衡量需有统一标准，简单劳动是每个没有任何专长的普通人都能从事的劳动 ，具有普遍性和统一性，所以社会必要劳动时间是以简单劳动为尺度的。复杂劳动要换算为简单劳动，具体 劳动创造使用价值与衡量社会必要劳动时间无关，个别劳动也不能作为社会必要劳动时间的尺度。"},{"id":"marx-2-21","globalId":100,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":21,"question":"在垄断资本主义阶段,占统治地位的资本是（ ）。","options":["工业资本","银行资本","商业资本","金融资本"],"answer":3,"answerLetter":"D","explain":"在垄断资本主义阶段，工业垄断资本和银行垄断资本融合形成金融资本，金融资本成为占统治地位 的资本。"},{"id":"marx-2-22","globalId":101,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":22,"question":"共产主义社会的显著特征和一面旗帜是（ ）。","options":["各尽所能，平均分配","各尽所能，公平分配","各尽所能，按劳分配","各尽所能，按需分配"],"answer":3,"answerLetter":"D","explain":"共产主义社会生产力高度发达，物质财富极大丰富，实行各尽所能、按需分配。“各尽所能，按需 分配”体现了共产主义社会的本质特征，是共产主义社会的显著特征和一面旗帜。平均分配不符合共产主义 特点；公平分配表述宽泛不准确；按劳分配是社会主义社会分配方式。"},{"id":"marx-2-23","globalId":102,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":23,"question":"货币转化为资本的决定性条件是在流通中购买到（ ）。","options":["生产资料","劳动力","劳动资料","劳动对象"],"answer":1,"answerLetter":"B","explain":"货币转化为资本的关键在于能带来剩余价值，劳动力商品具有独特的使用价值，其使用能创造出比 自身价值更大的价值，为资本家带来剩余价值，所以货币转化为资本的决定性条件是在流通中购买到劳动力 。"},{"id":"marx-2-24","globalId":103,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":24,"question":"认识的主体和客体之间最基本的关系是（ ）。","options":["反映与被反映的认识关系","改造与被改造的实践关系","需要与满足需要的价值关系","创造与被创造的主从关系"],"answer":1,"answerLetter":"B","explain":"实践是认识的基础，认识主体和客体之间首先是改造与被改造的实践关系，在此基础上才产生认识 关系等其他关系。"},{"id":"marx-2-25","globalId":104,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":25,"question":"社会存在是指（ ）。","options":["社会物质生活条件","社会物质财富总和","社会各种关系总和","社会各种要素总和"],"answer":0,"answerLetter":"A","explain":"社会存在是指社会物质生活条件的总和，主要包括地理环境、人口因素和物质生产方式。B选项社会 物质财富总和表述不准确；C选项社会各种关系总和强调的是关系，并非社会存在本质；D选项社会各种要素 总和过于宽泛。A选项符合社会存在定义。"},{"id":"marx-2-26","globalId":105,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":26,"question":"在马克思主义看来,人的本质（ ）。","options":["是由人的文化素质决定的","是由人的心理素质决定的","是由人的社会属性决定的","是由人的自然属性决定的"],"answer":2,"answerLetter":"C","explain":"马克思主义认为人有自然属性和社会属性，而社会属性是人的本质属性，它决定了人的本质。因为 人是社会关系的总和，在社会中形成和发展。"},{"id":"marx-2-27","globalId":106,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":27,"question":"构成资本家全部职能资本的是（ ）。","options":["产业资本和借贷资本","商业资本和借贷资本","生产资本和借贷资本","产业资本和商业资本"],"answer":3,"answerLetter":"D","explain":"职能资本是对剩余价值的生产和实现，实际发挥了职能作用的资本。产业资本在生产领域生产剩余 价值，商业资本在流通领域实现剩余价值，它们都实际发挥职能作用。而借贷资本是为获取利息而暂时贷给 职能资本家使用的货币资本，它不直接发挥生产或实现剩余价值的职能。"},{"id":"marx-2-28","globalId":107,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":28,"question":"在内容和形式的矛盾运动中（ ）。","options":["内容是相对稳定的，形式是活跃易变的","内容是活跃易变的，形式是相对稳定的","内容的变化总是落后于形式的变化","内容和形式都处在不停的显著变动中"],"answer":1,"answerLetter":"B","explain":"内容决定形式，内容是活跃易变的，形式依赖于内容，并随着内容的发展而发展，相对稳定。所以 内容活跃易变，形式相对稳定。"},{"id":"marx-2-29","globalId":108,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":29,"question":"社会基本矛盾有两对,它们之间是（ ）。","options":["相互孤立的关系","相互平行的关系","相互决定的关系","相互制约的关系"],"answer":3,"answerLetter":"D","explain":"社会基本矛盾的两对矛盾即生产力和生产关系的矛盾、经济基础和上层建筑的矛盾。这两对矛盾不 是孤立的，生产力和生产关系的矛盾决定并制约着经济基础和上层建筑的矛盾，而经济基础和上层建筑的矛 盾也影响着生产力和生产关系的矛盾，它们相互制约，共同推动社会发展。"},{"id":"marx-2-30","globalId":109,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":30,"question":"在平均利润率不变、借贷供求大体平衡的条件下，影响利息率的最重要因素是（ ）。","options":["社会心理因素","习惯和法律传统","历史和道德因素","商品市场的供需状况"],"answer":1,"answerLetter":"B","explain":"在平均利润率不变、借贷供求大体平衡时，习惯和法律传统成为影响利息率的重要因素，这是由长 期经济社会发展形成的。社会心理因素对利息率影响较小；历史和道德因素相对间接，不如习惯和法律传统 直接；商品市场供需状况主要影响商品价格等，和利息率关系不大。"},{"id":"marx-2-31","globalId":110,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":31,"question":"股份公司的组织结构一般包括权力机构、经营决策机构和监督机构三部分，与之相应的具体组织形式是 （ ）。","options":["股东会、董事会、监事会","董事会、理事会、职代会","股东会、理事会、监事会","董事会、监事会、职代会"],"answer":0,"answerLetter":"A","explain":"股份公司权力机构是股东会，它决定公司重大事项；经营决策机构是董事会，负责公司日常经营决 策；监督机构是监事会，对公司经营管理等进行监督。B选项中理事会在职代会一般不是股份公司这三类典型 对应组织形式；C选项理事会不合适；D选项职代会不属于这三类标准组织形式。所以应选A。"},{"id":"marx-2-32","globalId":111,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":32,"question":"既承认社会发展的客观规律,又承认主体选择的作用,这种观点属于（ ）。","options":["折中主义观点","相对主义观点","历史唯物主义观点","历史唯心主义观点"],"answer":2,"answerLetter":"C","explain":"历史唯物主义认为社会发展有其客观规律，同时，人的活动又具有能动作用，主体能够在遵循客观 规律的基础上进行选择。 折中主义是把各种不同的观点无原则地拼凑在一起的做法，题干观点并非如此，A 项错误。 相对主义片面夸大事物和认识的相对性，否定事物和认识的确定性、客观性，与题干不符，B 项错 误。 历史唯心主义否认社会发展的客观规律，夸大主体选择作用，与题干不符，D 项错误。"},{"id":"marx-2-33","globalId":112,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":33,"question":"认识我国改革开放和社会主义现代化建设的形势，我们要分清主流和支流，要看主流，同时又不忽略支流 。这里依据的哲学道理是（ ）。","options":["矛盾的普遍性和特殊性辩证关系的原理","主要矛盾和次要矛盾辩证关系的原理","矛盾的主要方面和次要方面辩证关系的原理","事物变化的内因和外因辩证关系的原理"],"answer":2,"answerLetter":"C","explain":"题干强调认识形势要分清主流和支流，主流和支流对应的是矛盾的主要方面和次要方面。矛盾主要 方面决定事物性质，要抓住主流，同时不能忽视次要方面。A选项矛盾普遍性和特殊性强调共性与个性；B选 项主要矛盾和次要矛盾针对的是不同矛盾，题干说的是同一矛盾不同方面；D选项内因和外因与主流支流无关 。所以选C。"},{"id":"marx-2-34","globalId":113,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":34,"question":"社会主义革命在一国或数国首先胜利理论立足于（ ）。","options":["马克思恩格斯著作中的科学预言","资本主义发展不平衡规律","巴黎公社的原则","生产力决定论"],"answer":1,"answerLetter":"B","explain":"列宁根据资本主义发展不平衡规律，得出社会主义革命可能在一国或数国首先胜利的结论。马克思 恩格斯认为社会主义革命将在几个主要资本主义国家同时发生，A 不符合。巴黎公社原则与社会主义革命在 一国或数国首先胜利理论并无直接关联，C 排除。生产力决定论不能直接得出这一结论，D 排除。"},{"id":"marx-2-35","globalId":114,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":35,"question":"社会主义国家要坚持社会主义方向,就必须坚持（ ）。","options":["公有制为主体、全民所有制为主导","不断进行社会主义革命","实行计划经济体制","实行市场经济体制"],"answer":0,"answerLetter":"A","explain":"社会主义公有制是社会主义经济制度的基础，坚持社会主义方向，必须坚持公有制为主体、全民所 有制为主导，它决定着社会主义的性质和发展方向。选项B“不断进行社会主义革命”表述不准确，社会主义 制度建立后重点是建设等；计划经济体制和市场经济体制只是资源配置手段，不是社会主义方向的本质决定 因素。"},{"id":"marx-2-36","globalId":115,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":36,"question":"在商品赊购赊销中,到期偿还货款时货币所执行的职能是（ ）。","options":["价值尺度","流通手段","支付手段","贮藏手段"],"answer":2,"answerLetter":"C","explain":"支付手段是指货币用于清偿债务、支付赋税、租金、工资等的职能。在商品赊购赊销中，到期偿还 货款属于清偿债务，此时货币执行的是支付手段职能。价值尺度是衡量商品价值大小；流通手段是一手交钱 一手交货；贮藏手段是把货币当作财富贮藏起来。"},{"id":"marx-2-37","globalId":116,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":37,"question":"假象同真相一样，也是客观存在的。这是一种（ ）。","options":["辩证法的观点","唯物辩证法的观点","形而上学的观点","主观唯心主义的观点"],"answer":1,"answerLetter":"B","explain":"唯物辩证法认为现象分为真相和假象，二者都是客观存在的，都是事物本质的表现形式。所以“假 象同真相一样，也是客观存在的”这体现的是唯物辩证法的观点。"},{"id":"marx-2-38","globalId":117,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":38,"question":"任何科学真理都不能穷尽对事物的认识，都是随着实践的发展而发展的。这说明真理都具有（ ）。","options":["客观性","相对性","绝对性","全面性"],"answer":1,"answerLetter":"B","explain":"真理的相对性是指真理的有条件性、有限性，包括广度和深度上的有限。题干中说科学真理不能穷 尽对事物认识且随实践发展，体现了真理在广度和深度上并非绝对完善，是有条件和有限的，这符合真理相 对性的特点。"},{"id":"marx-2-39","globalId":118,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":39,"question":"社会主义国家政权的领导核心是（ ）。","options":["工人阶级及其群众组织","工人阶级的先锋队共产党","工农联盟","无产阶级专政机关"],"answer":1,"answerLetter":"B","explain":"在社会主义国家，工人阶级的先锋队共产党代表最广大人民根本利益，是政权领导核心，带领人民 进行社会主义建设等各项事业。A选项工人阶级群众组织并非领导核心；C选项工农联盟是阶级基础；D选项无 产阶级专政机关是实施专政职能的机构，不是领导核心。"},{"id":"marx-2-40","globalId":119,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":40,"question":"在上层建筑的各种要素中，居于主导地位的是（ ）。","options":["艺术","宗教","政治","哲学"],"answer":2,"answerLetter":"C","explain":"上层建筑分为政治上层建筑和观念上层建筑，政治上层建筑是在一定意识形态指导下建立起来的 ，是统治阶级意志的体现，在整个上层建筑中居于主导地位。政治属于政治上层建筑范畴，而艺术、宗教、 哲学属于观念上层建筑，所以政治在上层建筑各种要素中居于主导地位。"},{"id":"marx-2-41","globalId":120,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":41,"question":"广义的共产主义社会包含（ ）。","options":["社会主义社会和共产主义社会","商品经济社会和产品经济社会","社会主义初级阶段和高级阶段","社会主义第一阶段和高级阶段"],"answer":0,"answerLetter":"A","explain":"广义的共产主义社会包含社会主义社会和共产主义社会两个阶段，社会主义是共产主义的低级阶段 。"},{"id":"marx-2-42","globalId":121,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":42,"question":"价值规律是（ ）。","options":["自然经济的基本规律","商品经济的基本规律","资本主义经济的基本规律","社会主义经济的基本规律"],"answer":1,"answerLetter":"B","explain":"价值规律贯穿商品经济的全过程，它体现着商品经济发展运动过程的必然趋势，是商品经济的基本 规律。自然经济、资本主义经济、社会主义经济都包含在商品经济范畴内，但价值规律不是自然经济、资本 主义经济、社会主义经济单独特有的基本规律。"},{"id":"marx-2-43","globalId":122,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":43,"question":"任何真理都是具体的,包罗万象的真理是不存在的。这是因为真理具有（ ）。","options":["绝对性","相对性","全面性","片面性"],"answer":1,"answerLetter":"B","explain":"真理的相对性表明，真理所反映的对象是有条件的、有限的，任何真理都只是对特定事物一定程度 、一定层次的正确认识，并非包罗万象。题干强调不存在包罗万象的真理，正是体现了真理的相对性。 真理 的绝对性强调真理的客观性、世界的可知性等，与题干表述不符。全面性和片面性不是真理的特性。"},{"id":"marx-2-44","globalId":123,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":44,"question":"社会主义核心价值观兼顾了国家、社会、个人三者的价值愿望与追求，其中从个人层面对社会主义核心价 值观基本理念的凝练表达是（ ）。","options":["富强、民主、文明、和谐","自由、平等、法治","爱国、敬业、诚信、友善？","厚德、包容、求是、创新"],"answer":2,"answerLetter":"C","explain":"社会主义核心价值观中，国家层面是富强、民主、文明、和谐；社会层面是自由、平等、公正、法 治；个人层面是爱国、敬业、诚信、友善。"},{"id":"marx-2-45","globalId":124,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":45,"question":"合称为流通资本的两种资本是（ ）。","options":["不变资本与可变资本","固定资本与流动资本","货币资本与商品资本","产业资本与商业资本"],"answer":2,"answerLetter":"C","explain":"流通资本是指在产业资本循环中同生产资本既相对立又相关联、专门执行流通职能的那一部分资本 ，包括货币资本和商品资本。"},{"id":"marx-2-46","globalId":125,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":46,"question":"价值规律作用的表观形式是（ ）。","options":["商品价格围绕价值波动","商品价格经常低于价值","价值围绕商品价格波动","商品价格往往高于价值"],"answer":0,"answerLetter":"A","explain":"价值规律的表现形式是商品价格受供求关系的影响，围绕价值上下波动。B选项价格经常低于价值、 D选项价格往往高于价值都不准确，只是价格波动的部分情况；C选项价值围绕价格波动说法错误，应是价格 围绕价值波动。"},{"id":"marx-2-47","globalId":126,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":47,"question":"商品的二因素指的是（ ）。","options":["使用价值和剩余价值","使用价值和交换价值","价值和使用价值","价值和交换价值"],"answer":2,"answerLetter":"C","explain":"商品是用来交换的能满足人们某种需要的劳动产品，具有使用价值和价值两个因素。使用价值是商 品能满足人们某种需要的属性，即商品的有用性；价值是凝结在商品中的无差别的一般人类劳动。交换价值 是一种使用价值同另一种使用价值相交换的量的关系或比例，价值是交换价值的基础，交换价值是价值的表 现形式，剩余价值是雇佣工人创造的被资本家无偿占有的超过劳动力价值的价值。所以商品二因素是价值和 使用价值。"},{"id":"marx-2-48","globalId":127,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":48,"question":"在社会意识中,思想体系是（ ）。","options":["低级层次的社会意识","高级层次的社会意识","有阶级性的社会意识","无阶级性的社会意识"],"answer":1,"answerLetter":"B","explain":"社会意识从层次上分为社会心理和思想体系。社会心理是低层次的、自发的社会意识，思想体系是 高层次的、自觉的、系统化、理论化的社会意识。同时，思想体系并非都有阶级性，像自然科学等思想体系 就无阶级性，所以C、D选项不准确。"},{"id":"marx-2-49","globalId":128,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":49,"question":"价值增值产生于资本循环的（ ）。","options":["购买阶段","生产阶段","销售阶段","运输阶段"],"answer":1,"answerLetter":"B","explain":"资本循环的生产阶段中，劳动力与生产资料相结合进行生产，工人创造出包含剩余价值的商品，实 现价值增值。购买阶段为生产准备条件，销售阶段实现商品价值，运输阶段不属于资本循环基本阶段。答案 ：B"},{"id":"marx-2-50","globalId":129,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":50,"question":"在苏维埃俄国领导实行战时共产主义政策的主要负责人是（ ）。","options":["列宁","斯大林","布哈林","托洛斯基"],"answer":0,"answerLetter":"A","explain":"战时共产主义政策是在苏俄面临严峻的战争形势等背景下，由列宁领导实施的，旨在集中全国资源 保障战争胜利。答案选A。"},{"id":"marx-2-51","globalId":130,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":51,"question":"建设社会主义先进文化，对传统文化必须批判地继承。这种态度依据的哲学道理是（ ）。","options":["世界是过程集合体的原理","新事物必然战胜旧事物的原理","内容决定形式的原理","辨证的否定的原理"],"answer":3,"answerLetter":"D","explain":"辩证的否定原理强调事物的否定是自我否定，是事物发展环节和联系环节的统一，实质是“扬弃 ”，即既克服又保留。对传统文化批判地继承，就是取其精华、去其糟粕，体现了辩证否定观中既克服旧事 物消极内容又保留积极内容的“扬弃”思想。"},{"id":"marx-2-52","globalId":131,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":52,"question":"阶级产生的根本前提是（ ）。","options":["用暴力掠夺他人财产","人的本质是现实具体的","人的本质是后天形成的","由于产品分配不公出现两极分化"],"answer":3,"answerLetter":"D","explain":"阶级产生的根本前提是社会分工、私有制出现，使得产品分配不公进而出现两极分化。A选项暴力掠 夺不是根本前提；B、C选项关于人的本质的描述与阶级产生无关。"},{"id":"marx-2-53","globalId":132,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":53,"question":"劳动力商品使用价值的特殊性是（ ）。","options":["能生产出具有使用价值的物品","能生产出具有价值的物品","仅能生产出自身价值","能生产出大于自身价值的价值"],"answer":3,"answerLetter":"D","explain":"劳动力商品使用价值的特殊性在于它不仅能创造出自身价值，还能创造出比自身价值更大的价值 ，即剩余价值。选项A和B表述不够体现劳动力商品使用价值特殊性，C项仅能生产自身价值说法错误。 答案 ：D"},{"id":"marx-2-54","globalId":133,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":54,"question":"社会历史发展的决定性是指（ ）。","options":["历史决定论","历史被动论","历史宿命论","历史意志论"],"answer":0,"answerLetter":"A","explain":"社会历史发展的决定性强调社会历史发展具有自身固有的客观规律性，这与历史决定论观点相符 ，历史决定论承认社会历史发展受客观规律支配。 历史被动论强调人在历史面前完全被动，忽视人的主观能 动性，不符合社会历史发展决定性的内涵。 历史宿命论将历史发展归结为不可抗拒的命运，带有迷信色彩 ，与基于客观规律的社会历史发展决定性不同。 历史意志论过分夸大个人意志对历史的作用，也不符合社会 历史发展决定性基于客观规律的本质。"},{"id":"marx-2-55","globalId":134,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":55,"question":"私人劳动和社会劳动形成的条件是（ ）。","options":["技术进步和生产资料公有制","技术进步和生产资料私有制","社会分工和生产资料公有制","社会分工和生产资料私有制"],"answer":3,"answerLetter":"D","explain":"社会分工使得生产者之间相互联系、相互依存，每个生产者的劳动都是社会总劳动的一部分，这是 私人劳动转化为社会劳动的前提条件。 生产资料私有制决定了生产者的劳动具有私人性质，生产什么、生产 多少都由私人决定。所以私人劳动和社会劳动形成的条件是社会分工和生产资料私有制。"},{"id":"marx-2-56","globalId":135,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":56,"question":"在唯物辩证法看来,发展的实质是（ ）。","options":["事物数量的增加","事物的一切运动变化","事物根本性质的变化","新事物的产生和旧事物的灭亡"],"answer":3,"answerLetter":"D","explain":"唯物辩证法中，发展不是简单的事物数量增加，A选项事物数量增加不一定是发展，比如单纯的人 口数量增加，不一定意味着社会发展。 事物的一切运动变化不一定是发展，B选项，像物体位置的机械移动 等简单变化不属于发展。 事物根本性质的变化可能是倒退，不一定是发展，C选项，比如生物的病变导致根 本性质变化，并非是发展。 发展的实质是新事物的产生和旧事物的灭亡，新事物符合客观规律、具有强大生 命力和远大前途，它代替旧事物是历史的必然，这体现了发展的前进上升趋势。"},{"id":"marx-2-57","globalId":136,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":57,"question":"理论联系实际是（ ）。","options":["马克思主义理论特征？","学习马克思主义的目的","马克思主义活的灵魂？","学习马克思主义的方法"],"answer":3,"answerLetter":"D","explain":"理论联系实际强调将马克思主义理论与实际相结合，它是学习马克思主义的重要方法，通过联系实 际能更好理解和运用马克思主义。A选项马克思主义理论特征是科学性与革命性等；B选项学习马克思主义目 的是为了改造世界等；C选项马克思主义活的灵魂是具体问题具体分析。"},{"id":"marx-2-58","globalId":137,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":58,"question":"社会形态最基本的划分法之一是（ ）。","options":["意识形态划分法","经济社会形态划分法","文化形态划分法","政治形态划分法"],"answer":1,"answerLetter":"B","explain":"社会形态最基本划分法有经济社会形态划分法和技术社会形态划分法。经济社会形态划分法侧重从 生产关系角度划分，对认识社会发展规律等很重要。而意识形态、文化、政治形态划分法并非社会形态最基 本划分法。"},{"id":"marx-2-59","globalId":138,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":59,"question":"私人垄断资本同资产阶级国家政权相结合形成（ ）。","options":["垄断资本主义","国家资本主义","国家垄断资本主义","金融资本主义"],"answer":2,"answerLetter":"C","explain":"私人垄断资本与资产阶级国家政权相结合，就产生了国家垄断资本主义 。垄断资本主义范围宽泛 ；国家资本主义是资本与国家政权结合但并非私人垄断资本与政权结合这种特定形式；金融资本主义强调金 融资本占主导，与题干表述不符。"},{"id":"marx-2-60","globalId":139,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":60,"question":"在物质和运动的关系问题上,唯心主义的错误在于（ ）。","options":["否认物质的绝对运动","夸大相对静止的存在","否认物质是运动的主体","主张没有运动的物质"],"answer":2,"answerLetter":"C","explain":"唯心主义在物质和运动关系上，往往脱离物质谈运动，认为是精神等非物质的东西在运动，即否认 物质是运动的主体。 A选项否认物质的绝对运动，更多是形而上学的观点，不是唯心主义在物质和运动关系 上的典型错误。 B选项夸大相对静止的存在也是形而上学的表现，并非唯心主义在物质和运动关系上的关键 错误。 D选项主张没有运动的物质是形而上学的观点，不符合唯心主义特点。"},{"id":"marx-2-61","globalId":140,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":61,"question":"阶级作为一种社会现象首先是一个（ ）。","options":["经济范畴","政治范畴","文化范畴","交往范畴"],"answer":0,"answerLetter":"A","explain":"阶级是根据人们在社会经济结构中所处地位不同而划分的，经济因素是划分阶级的基础，所以阶级 首先是一个经济范畴。"},{"id":"marx-2-62","globalId":141,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":62,"question":"理性认识的三种形式是（ ）。","options":["概念、判断、推理","感觉、知觉、表象","抽象、具体、再抽象","分析、归纳、综合"],"answer":0,"answerLetter":"A","explain":"理性认识是认识的高级阶段，其三种形式为概念、判断、推理 。B选项感觉、知觉、表象是感性认 识的形式。C、D选项并非理性认识的形式。"},{"id":"marx-2-63","globalId":142,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":63,"question":"社会意识具有复杂的结构，从其主体的角度看可分为（ ）。","options":["社会心理和思想体系","意识形态和非意识形态","个体意识和群体意识","先进意识和落后意识"],"answer":2,"answerLetter":"C","explain":"题目强调从主体角度对社会意识分类。A选项是从社会意识高低层次角度分；B选项是从是否反映经 济基础角度分；D选项并非标准分类方式。C选项个体意识和群体意识是从主体角度（个体与群体）划分的。"},{"id":"marx-2-64","globalId":143,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":64,"question":"私人垄断资本主义阶段,社会经济生活中的万能垄断者是（ ）。","options":["垄断的工业资本家","垄断的银行资本家","垄断的商业资本家","垄断的农业资本家"],"answer":1,"answerLetter":"B","explain":"在私人垄断资本主义阶段，银行由普通的中介人变成了万能的垄断者。银行资本与工业资本融合形 成金融资本，银行垄断资本地位上升。答案选B。"},{"id":"marx-2-65","globalId":144,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":65,"question":"在意识问题上，唯心主义的错误在于（ ）。","options":["忽视意识的主观特征","抹煞意识的主观特征","夸大意识的能动作用","否认意识的能动作用"],"answer":2,"answerLetter":"C","explain":"唯心主义在意识问题上，往往脱离物质基础，过分强调意识对物质的决定作用，也就是夸大了意识 的能动作用。"},{"id":"marx-2-66","globalId":145,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":66,"question":"揭示事物的发展状态和形式的规律是（ ）。","options":["对立统一规律","质量互变规律","否定之否定规律","本质决定现象规律"],"answer":1,"answerLetter":"B","explain":"质量互变规律揭示了事物发展的状态和形式，量变是事物数量的增减和场所的变更，体现了事物发 展的连续性；质变是事物根本性质的变化，是事物由一种质态向另一种质态的飞跃，体现了事物发展连续性 的中断。量变和质变相互转化、相互渗透，揭示了事物发展是连续性和阶段性的统一，也就是事物发展的状 态和形式。 对立统一规律揭示了事物发展的源泉和动力。 否定之否定规律揭示了事物发展的方向和道路。 “本质决定现象规律”不属于唯物辩证法的基本规律。"},{"id":"marx-2-67","globalId":146,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":67,"question":"利息的本质是（ ）。","options":["剩余价值的特殊转化形式","平均利润的特殊转化形式","使用借贷资本支付的报酬","使用产业资本支付的报酬"],"answer":0,"answerLetter":"A","explain":"利息是职能资本家使用借贷资本而让渡给借贷资本家的一部分剩余价值，其本质是剩余价值的特殊 转化形式。答案：A 。"},{"id":"marx-2-68","globalId":147,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":68,"question":"揭示事物发展趋势和道路的规律是（ ）。","options":["否定之否定规律","质量互变规律","对立统一规律","内容和形式相互作用规律"],"answer":0,"answerLetter":"A","explain":"否定之否定规律揭示了事物发展的方向和道路，它表明事物发展是前进性和曲折性的统一，呈现螺 旋式上升或波浪式前进的趋势。 质量互变规律揭示了事物发展变化的状态和形式。 对立统一规律揭示了事 物发展的源泉和动力。 内容和形式相互作用规律主要阐述内容与形式之间的辩证关系，并非揭示事物发展趋 势和道路。"},{"id":"marx-2-69","globalId":148,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":69,"question":"两条根本对立的认识路线是（ ）。","options":["可知论和不可知论","唯物主义反映论和唯心主义先验论","主观唯心主义认识和客观唯心主义认识论","能动革命的反映论和直观被动的反映论"],"answer":1,"answerLetter":"B","explain":"哲学上两条根本对立的认识路线，是围绕认识的本质问题展开，即认识是从物到感觉和思想，还是 从思想和感觉到物。唯物主义反映论坚持从物到感觉和思想，认为认识是主体对客体的反映；唯心主义先验 论坚持从思想和感觉到物，把认识看作是先于物质、先于实践经验的东西。所以两条根本对立的认识路线是 唯物主义反映论和唯心主义先验论。"},{"id":"marx-2-70","globalId":149,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":70,"question":"社会主义的分配原则是（ ）。","options":["按劳分配","按需分配","按生产要素分配","按资分配"],"answer":0,"answerLetter":"A","explain":"社会主义的分配原则是按劳分配，它是在生产资料社会主义公有制条件下，对社会总产品作各项必 要的社会扣除以后，按照个人提供给社会的劳动的数量和质量分配个人消费品。按需分配是共产主义社会高 级阶段的分配方式；按生产要素分配是市场经济条件下的一种分配方式；按资分配是资本主义的分配方式之 一。"},{"id":"marx-2-71","globalId":150,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":71,"question":"土地价格是（ ）。","options":["地价值的货币表现","级差地租的货币表现","利息的资本化","地租的资本化"],"answer":3,"answerLetter":"D","explain":"土地本身没有价值，土地价格是地租收入的资本化，即把地租看作是银行存款利息，按照一定的利 息率倒算出的资本量就是土地价格。"},{"id":"marx-2-72","globalId":151,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":72,"question":"在真理的检验标准问题上，下列各项中说法正确的是（ ）。","options":["多数人认可的就是真理","个人觉得有用的就是真理","少数人坚持的就是真理","在实践中证实的才是真理"],"answer":3,"answerLetter":"D","explain":"真理的检验标准是实践，实践是检验真理的唯一标准。A选项多数人认可不一定是真理，可能存在群 体认知错误；B选项个人觉得有用带有很强的主观性，不能作为真理标准；C选项少数人坚持也不一定是真理 。只有D选项符合实践是检验真理唯一标准这一正确观点。"},{"id":"marx-2-73","globalId":152,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":73,"question":"两种商品相互交换的量的关系或比例就是商品的","options":["价值","价格","使用价值","交换价值"],"answer":3,"answerLetter":"D","explain":"交换价值首先表现为一种使用价值同另一种使用价值相交换的量的关系或比例 。价值是凝结在商品 中的无差别的人类劳动，它决定交换价值。价格是价值的货币表现。使用价值是商品能满足人们某种需要的 属性。题干描述的是交换价值的概念。"},{"id":"marx-2-74","globalId":153,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":74,"question":"社会主义的根本任务是（ ）。","options":["解放和发展生产力","巩固无产阶级专政","坚持和改善党的领导","发展社会主义民主法制"],"answer":0,"answerLetter":"A","explain":"社会主义的根本任务是解放和发展生产力。这是基于生产力在社会发展中的决定性作用，以及社会 主义本质要求等多方面得出的。只有不断解放和发展生产力，才能解决社会主义初级阶段的主要矛盾，实现 社会主义的目标。其他选项巩固无产阶级专政、坚持和改善党的领导、发展社会主义民主法制虽然对社会主 义建设很重要，但不是根本任务。"},{"id":"marx-2-75","globalId":154,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":75,"question":"为获取高额垄断利润，垄断组织在采购原材料时大多采取（ ）。","options":["垄断高价","垄断低价","浮动价格","固定价格"],"answer":1,"answerLetter":"B","explain":"垄断组织为获取高额垄断利润，在销售商品时会采用垄断高价，而在采购原材料等生产要素时则会 采取垄断低价，以降低成本，增加利润。"},{"id":"marx-2-76","globalId":155,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":76,"question":"在真理问题上坚持辩证法，就是要承认任何真理都是（ ）。","options":["客观性和主观性的统一","主观性和相对性的统一","客观性和绝对性的统一","绝对性和相对性的统一"],"answer":3,"answerLetter":"D","explain":"真理具有客观性，这是真理的本质属性。同时真理又具有绝对性和相对性，是绝对性和相对性的统 一。承认真理是绝对性和相对性的统一，体现了在真理问题上坚持辩证法。因为只强调绝对性，会走向僵化 ；只强调相对性，会走向相对主义，所以要辩证看待。"},{"id":"marx-2-77","globalId":156,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":77,"question":"社会主义革命可以在一国或数国首先胜利理论的提出者是（ ）。","options":["马克思","列宁","斯大林","毛泽东"],"answer":1,"answerLetter":"B","explain":"列宁基于对帝国主义阶段资本主义经济政治发展不平衡规律的深刻认识，提出社会主义革命可以在 一国或数国首先胜利的理论。马克思和恩格斯所处时代认为社会主义革命将在几个主要资本主义国家同时发 生。斯大林和毛泽东主要是在列宁之后推动社会主义实践等发展。"},{"id":"marx-2-78","globalId":157,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":78,"question":"唯物辩证法的总特征是（ ）。","options":["联系和发展的观点","量变和质变的观点","对立统一的观点","辩证否定的观点"],"answer":0,"answerLetter":"A","explain":"唯物辩证法认为世界是普遍联系和永恒发展的，联系和发展的观点是贯穿唯物辩证法其他规律和范 畴的主线，是唯物辩证法的总特征。B选项量变和质变是揭示事物发展状态和形式的规律；C选项对立统一规 律是唯物辩证法的实质和核心；D选项辩证否定观是事物自身的否定，是联系和发展的环节。答案：A 。"},{"id":"marx-2-79","globalId":158,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":79,"question":"在资本主义社会，决定劳动力价值的因素中一般不包括（ ）。","options":["生存资料的价值","生产资料的价值","延续和养育后代所需的费用","必要的教育培训费用"],"answer":1,"answerLetter":"B","explain":"劳动力价值包括维持劳动者自身生存所必需的生活资料价值（对应A项）、劳动者繁育后代所必需的 生活资料价值（对应C项）、劳动者接受教育和训练所支出的费用（对应D项）。生产资料价值主要与商品生 产等相关，并非决定劳动力价值的因素。"},{"id":"marx-2-80","globalId":159,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":80,"question":"近几十年来垄断组织国际化的最主要形式是（ ）。","options":["国际卡特尔","国际辛迪加","国际康采恩","跨国公司"],"answer":3,"answerLetter":"D","explain":"在垄断组织国际化形式中，跨国公司凭借其在全球生产、销售、研发等方面的布局与掌控力，成为 近几十年来垄断组织国际化最主要形式。国际卡特尔、国际辛迪加主要是早期的国际垄断同盟形式，国际康 采恩相对也不如跨国公司在当代垄断组织国际化中占据主导。"},{"id":"marx-2-81","globalId":160,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":81,"question":"列宁的物质定义表明，客观实在性是（ ）。","options":["生命物质的共性","自然物质的共性","有形物质的共性","一切物质的共性"],"answer":3,"answerLetter":"D","explain":"列宁的物质定义指出物质是标志客观实在的哲学范畴，这种客观实在是人通过感觉感知的，它不依 赖于我们的感觉而存在，为我们的感觉所复写、摄影、反映。这表明客观实在性是一切物质的共性，不局限 于生命物质、自然物质或有形物质。"},{"id":"marx-2-82","globalId":161,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":82,"question":"社会主义革命胜利以后,首先要经过（ ）。","options":["从资本主义向社会主义过渡的阶段","社会主义初级阶段","共产主义第一阶段","战时共产主义阶段"],"answer":0,"answerLetter":"A","explain":"社会主义革命胜利后，一般会经历从资本主义向社会主义过渡的阶段，对生产资料私有制进行改造 等，为社会主义制度的全面建立奠定基础。社会主义初级阶段是我国在生产力落后、商品经济不发达条件下 建设社会主义必然要经历的特定阶段，并非所有社会主义革命胜利后都直接进入此阶段；共产主义第一阶段 即社会主义阶段，但题干问的是首先经历的阶段；战时共产主义是苏俄在特定战争时期的政策，不具有普遍 适用性。"},{"id":"marx-2-83","globalId":162,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":83,"question":"近朱者赤，近墨者黑。这句话强调的是（ ）。","options":["内因是事物发展变化的根据","外部条件对事物发展变化有重要影响","外因通过内因而起作用","外因和内因共同推动事物发展"],"answer":1,"answerLetter":"B","explain":"“近朱者赤，近墨者黑”意思是靠着朱砂的变红，靠着墨的变黑，强调的是周围环境（外部条件 ）对人的影响。所以这句话强调的是外部条件对事物发展变化有重要影响，答案选B。"},{"id":"marx-2-84","globalId":163,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":84,"question":"列宁对于无产阶级革命的重大理论贡献是（ ）。","options":["提出了战时共产主义政策","提出了新经济政策","提出了利用资本主义发展社会主义的理论","提出了社会主义革命将首先在一国或数国胜利的理论"],"answer":3,"answerLetter":"D","explain":"列宁突破了马克思主义关于无产阶级革命将在几个主要资本主义国家同时发生的设想，提出了社会 主义革命将首先在一国或数国胜利的理论，这是对无产阶级革命的重大理论贡献。A选项战时共产主义政策、 B选项新经济政策、C选项利用资本主义发展社会主义理论主要是关于社会主义建设方面。"},{"id":"marx-2-85","globalId":164,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":85,"question":"生产关系范畴反映的是人与人之间的（ ）。","options":["经济关系","政治关系","思想关系","血缘关系"],"answer":0,"answerLetter":"A","explain":"生产关系是人们在物质资料的生产过程中形成的社会关系，它是生产方式的社会形式，本质上是人 与人之间的经济关系。"},{"id":"marx-2-86","globalId":165,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":86,"question":"真理具有客观性，被称为客观真理，是因为（ ）。","options":["真理是事物发展的客观规律","真理是对事物及其规律的正确反映","真理是不依赖于意识的客观实在","真理是大多数人承认的客观事实"],"answer":1,"answerLetter":"B","explain":"真理的客观性在于它是对客观事物及其规律的正确反映。真理反映的内容是客观的，不以人的意志 为转移。 A选项，真理不是客观规律本身，而是对规律的正确反映。 C选项，不依赖于意识的客观实在是物 质，不是真理。 D选项，真理不是由多数人承认决定的，即使少数人掌握，只要是对事物及其规律的正确反 映，也是真理。"},{"id":"marx-2-87","globalId":166,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":87,"question":"垄断利润的获得，主要是通过（ ）。","options":["自由竞争实现的","市场调节实现的","垄断价格实现的","行政干预实现的"],"answer":2,"answerLetter":"C","explain":"垄断利润主要是通过垄断价格来实现的，垄断价格包括垄断高价和垄断低价。垄断企业凭借其垄断 地位规定垄断价格，从而获得大大超过平均利润的高额利润。自由竞争时期不存在垄断利润，市场调节和行 政干预并非垄断利润获取的主要方式。"},{"id":"marx-2-88","globalId":167,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":88,"question":"下列不属于19世纪初欧洲空想社会主义者的是（ ）。","options":["傅里叶","圣西门","康德","欧文"],"answer":2,"answerLetter":"C","explain":"19世纪初欧洲空想社会主义者主要代表是圣西门、傅里叶和欧文 。康德是德国古典哲学的创始人 ，不属于空想社会主义者。答案选C。"},{"id":"marx-2-89","globalId":168,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":89,"question":"正确发挥意识能动作用的前提是（ ）。","options":["个人积极性的充分调动","集体智慧的充分发挥","对保守思想的彻底克服","对客观规律的正确反映"],"answer":3,"answerLetter":"D","explain":"意识能动作用的发挥受客观规律的制约，只有正确认识和遵循客观规律，才能正确发挥意识能动作 用。选项A个人积极性、B集体智慧、C克服保守思想都不是发挥意识能动作用的前提。前提是对客观规律的正 确反映。"},{"id":"marx-2-90","globalId":169,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":90,"question":"可知论与不可知论的对立在于是否承认（ ）。","options":["人的认识是先于经验而获得的","思维能够正确地认识现实世界","人的认识是从外部世界得来的","思维能够能动地认识现实世界"],"answer":1,"answerLetter":"B","explain":"可知论认为思维能够正确认识现实世界，不可知论则认为思维不能正确认识现实世界，二者对立的 关键就在于对思维能否正确认识现实世界的不同看法。"},{"id":"marx-2-91","globalId":170,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":91,"question":"马克思主义产生于（ ）。","options":["19世纪20年代","19世纪40年代","19世纪60年代","19世纪80年代"],"answer":1,"answerLetter":"B","explain":"19世纪40年代，资本主义矛盾尖锐，工人运动兴起，马克思和恩格斯批判继承前人理论成果，创立 马克思主义。答案选B。"},{"id":"marx-2-92","globalId":171,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":92,"question":"剩余价值率和利润率的关系是（ ）。","options":["剩余价值率等于利润率","剩余价值率大于利润率","剩余价值率小于利润率","剩余价值率与利润率成反比"],"answer":1,"answerLetter":"B","explain":"剩余价值率是剩余价值与可变资本的比率，即 ；利润率是剩余价值与全部预付资本的比率，即 。因为全部预付资本（c + v）大于可变资本（v），在分子（剩余价值m）相同的情况下，分母越大，比值越 小。所以剩余价值率大于利润率。"},{"id":"marx-2-93","globalId":172,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":93,"question":"客观实在性是（ ）。","options":["自然物质的个性","一切物质的共性","物质的具体形态","物质的存在形式"],"answer":1,"answerLetter":"B","explain":"客观实在性是物质的唯一特性，它概括了宇宙间一切客观存在着的事物和现象的共同本质，是一切 物质的共性。自然物质只是物质的一部分，不能代表一切，A 错误；物质具体形态多样，客观实在性不是指 具体形态，C 错误；物质存在形式是运动等，不是客观实在性，D 错误。"},{"id":"marx-2-94","globalId":173,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":94,"question":"马克思主义的创始人是（ ）。","options":["马克思和李嘉图","马克思和圣西门","马克思和费尔巴哈","马克思和恩格斯"],"answer":3,"answerLetter":"D","explain":"马克思主义是由马克思和恩格斯共同创立的学说体系。李嘉图是英国古典政治经济学代表人物；圣 西门是空想社会主义者；费尔巴哈是旧唯物主义哲学家，他们都不是马克思主义创始人。"},{"id":"marx-2-95","globalId":174,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":95,"question":"剩余价值与利润从数量上看（ ）。","options":["前者大于后者","前者小于后者","两者相等","两者的大小无法判断"],"answer":2,"answerLetter":"C","explain":"利润本质上就是剩余价值，是剩余价值的转化形式。当剩余价值被看作是全部预付资本的产物时 ，就转化为利润。所以剩余价值与利润在数量上是相等的。"},{"id":"marx-2-96","globalId":175,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":96,"question":"下列不属于生产时间的是（ ）。","options":["生产资料采购时间","原材料储备时间","停工时间","自然力作用于产品的时间"],"answer":0,"answerLetter":"A","explain":"生产时间包括劳动时间、自然力独立作用于劳动对象的时间、生产资料储备时间以及正常的停工时 间。而生产资料采购时间属于流通时间，并非生产时间范畴。"},{"id":"marx-2-97","globalId":176,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":97,"question":"支付工资的货币执行的是货币的（ ）。","options":["价值尺度职能","流通手段职能","支付手段职能","贮藏手段职能"],"answer":2,"answerLetter":"C","explain":"支付工资时，货币并非用于衡量商品价值（不是价值尺度），也不是一手交钱一手交货的即时交易 （不是流通手段），更不是把货币当作财富储存起来（不是贮藏手段），而是用于清偿债务、支付赋税、租 金、工资等，这体现的是货币的支付手段职能。"},{"id":"marx-2-98","globalId":177,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":98,"question":"垄断利润的水平一般会","options":["低于平均利润","高于平均利润","等于平均利润","等于成本价格"],"answer":1,"answerLetter":"B","explain":"垄断企业凭借其垄断地位，通过限制产量、提高价格等手段获取高额利润。与自由竞争时期各企业 只能获得平均利润不同，垄断企业能长期获得大大超过平均利润的高额利润。"},{"id":"marx-2-99","globalId":178,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":99,"question":"下列各项包含矛盾双方相互依存相互转化的辩证法思想的是（ ）。","options":["千里之行，始于足下","千里之堤，溃于蚁穴","月晕而风，础润而雨","物极必反，相反相成"],"answer":3,"answerLetter":"D","explain":"A选项“千里之行，始于足下”强调量变是质变的必要准备，体现量变与质变关系。 B选项“千里 之堤，溃于蚁穴”说明量变积累到一定程度会引发质变，是量变与质变原理。 C选项“月晕而风，础润而雨 ”是对自然现象联系的一种描述，体现联系的观点。 D选项“物极必反”表明事物发展到极端会向相反方向 转化，“相反相成”说明矛盾双方既对立又统一，相互依存、相互转化，符合题意。"},{"id":"marx-2-100","globalId":179,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":100,"question":"只要再多走一小步,真理便会变成谬误,这句话说的是（ ）。","options":["真理和谬误相互依存","真理和谬误相互包含","真理和谬误相互排斥","真理和谬误在一定条件下可以相互转化"],"answer":3,"answerLetter":"D","explain":"“再多走一小步，真理便会变成谬误”强调了在特定条件变化（多走一小步这个条件改变）时，真 理就向谬误转变，体现的是真理和谬误在一定条件下的相互转化。"},{"id":"marx-2-101","globalId":180,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":101,"question":"垄断利润就其本质而言，来源于（ ）。","options":["劳动者创造的剩余价值","垄断组织的垄断地位","垄断组织的海外掠夺","垄断组织的垄断资本的实力"],"answer":0,"answerLetter":"A","explain":"垄断利润的来源归根结底是工人阶级和其他劳动人民创造的剩余价值，以及其他劳动者创造的一部 分价值。垄断地位、海外掠夺、垄断资本实力只是获取垄断利润的条件或途径，并非本质来源。"},{"id":"marx-2-102","globalId":181,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":102,"question":"马克思主义认识论认为,认识的本质是（ ）。","options":["主体对客体的直观反映","主体对客体的自由创造","主体对客体的能动反映","主体对客体的简单摹写"],"answer":2,"answerLetter":"C","explain":"马克思主义认识论强调认识是主体在实践基础上对客体的能动反映。A选项直观反映忽略了能动作用 ；B选项自由创造说法不准确，认识基于实践和对客体的反映并非随意创造；D选项简单摹写也没有体现出能 动性。"},{"id":"marx-2-103","globalId":182,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":103,"question":"实行垄断价格的根本目的是为了（ ）。","options":["最大限度占领市场","最大限度降低成本","获取高额垄断利润","获取行业控制权力"],"answer":2,"answerLetter":"C","explain":"垄断企业通过垄断价格，在高价出售产品和低价购买生产资料过程中，使价值和剩余价值实现有利 于垄断资本的再分配，其根本目的就是获取高额垄断利润。"},{"id":"marx-2-104","globalId":183,"part":2,"partName":"第二部分 唯物辩证法与认识论","category":"马原专项 · 第二部分 唯物辩证法与认识论","num":104,"question":"下列各项属于感性认识基本形式的是（ ）。","options":["感觉","概念","判断","推理"],"answer":0,"answerLetter":"A","explain":"感性认识是认识的初级阶段，包括感觉、知觉和表象三种形式。而概念、判断、推理是理性认识的 三种形式。"},{"id":"marx-3-3","globalId":184,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":3,"question":"质量互变规律揭示了（ ）。","options":["事物发展的原因和结果","事物发展的状态和过程","事物发展的趋势和道路","事物发展的源泉和动力"],"answer":1,"answerLetter":"B","explain":"质量互变规律主要阐述事物发展是量变与质变的统一，量变和质变是事物发展变化存在的两种基本 状态，揭示事物发展的状态和形式。"},{"id":"marx-3-2","globalId":185,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":2,"question":"垄断资本家在售卖商品时，一般都会采用（ ）。","options":["垄断高价","垄断低价","市场价格","计划价"],"answer":0,"answerLetter":"A","explain":"垄断资本家为获取高额垄断利润，在售卖商品时往往会凭借其垄断地位，把价格定得远远高于商品 价值，即采用垄断高价。"},{"id":"marx-3-3","globalId":186,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":3,"question":"马克思主义认为，阶级消灭和国家消亡是在（ ）。","options":["社会主义革命中实现的","社会主义初级阶段实现的","社会主义高级阶段实现的","共产主义社会实现的"],"answer":3,"answerLetter":"D","explain":"马克思主义认为，共产主义社会是人类社会发展的最高形态，到那时物质财富极大丰富，人们精神 境界极大提高，实现按需分配，阶级对立和国家存在的经济基础消失，阶级消灭和国家消亡。所以阶级消灭 和国家消亡在共产主义社会实现。"},{"id":"marx-3-4","globalId":187,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":4,"question":"实践作为一种感性物质活动，强调的是（ ）。","options":["实践具有客观物质性","实践具有主观性","实践具有能动性","实践具有历史性"],"answer":0,"answerLetter":"A","explain":"感性物质活动意味着实践是由现实的客观物质要素构成，受客观物质条件的制约，体现了实践具有 客观物质性。"},{"id":"marx-3-5","globalId":188,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":5,"question":"下列各项属于社会基本矛盾的是（ ）。","options":["生产力和生产关系的矛盾","社会存在和社会意识的矛盾","人口增长和资源匮乏的矛盾","发展经济和保护环境的矛盾"],"answer":0,"answerLetter":"A","explain":"社会基本矛盾是指贯穿社会发展过程始终，规定社会发展过程的基本性质和基本趋势，并对社会历 史发展起根本的推动作用的矛盾，生产力和生产关系、经济基础和上层建筑的矛盾是社会基本矛盾，A选项符 合。社会存在和社会意识是历史观基本问题涉及范畴，并非基本矛盾；C、D选项属于具体社会问题引发的矛 盾，并非社会基本矛盾。"},{"id":"marx-3-6","globalId":189,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":6,"question":"主张意识第一性、物质第二性的是（ ）。","options":["辩证法观点","形而上学观点","唯物主义观点","唯心主义观点"],"answer":3,"answerLetter":"D","explain":"哲学的基本派别中，唯心主义认为意识第一性、物质第二性，物质依赖意识而存在。唯物主义则主 张物质第一性、意识第二性。辩证法和形而上学是关于世界状态的不同观点，与物质和意识谁为第一性无关 。答案：D。"},{"id":"marx-3-7","globalId":190,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":7,"question":"垄断资本主义发展的两个阶段是（ ）。","options":["私人垄断资本主义与一般垄断资木主义","私人垄断资本主义与国家垄断资本主义","私人垄断资本主义与国际垄断资本主义","国家垄断资本主义与国际垄断资本主义"],"answer":1,"answerLetter":"B","explain":"垄断资本主义发展经历了私人垄断资本主义和国家垄断资本主义两个阶段。私人垄断资本主义是在 生产集中和资本集中基础上形成的，随着矛盾发展，国家政权与垄断资本相结合形成国家垄断资本主义。答 案是B。"},{"id":"marx-3-8","globalId":191,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":8,"question":"马克思主义认为，决定人的本质的是（ ）。","options":["人的心理素质","人的文化素质","人的社会属性","人的自然属性"],"answer":2,"answerLetter":"C","explain":"马克思主义强调人是社会关系的总和，人的本质不是单个人所固有的抽象物，在其现实性上，它是 一切社会关系的总和，这突出了人的社会属性对决定人本质的关键作用。自然属性是人和动物共有的，心理 素质和文化素质是在社会生活中形成，都不能决定人的本质。"},{"id":"marx-3-9","globalId":192,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":9,"question":"垄断资本主义国家的金融资本是指（ ）。","options":["资本主义国家中处于垄断地位的银行资本","资本主义国家金融领域中流通的所有资本的总和","资本主义国家银行和非银行金融机构资本的总和","垄断的工业资本和银行资本融合形成的资本"],"answer":3,"answerLetter":"D","explain":"金融资本是垄断资本主义阶段居统治地位的资本形式，它是由垄断的工业资本和银行资本，通过金 融联系、资本参与和人事参与，融合或混合生长构成的一种新的资本形式。"},{"id":"marx-3-10","globalId":193,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":10,"question":"马克思主义认为,垄断资本主义发展的历史趋势是（ ）。","options":["生产资料公有制代替生产资料私有制","生产资料私有制代替生产资料公有制","全世界实行垄断资本主义","全世界实行自由竞争资本主义"],"answer":0,"answerLetter":"A","explain":"马克思主义基于对社会发展规律以及资本主义基本矛盾的分析，认为资本主义向社会主义过渡具有 历史必然性。社会主义以生产资料公有制为基础，所以垄断资本主义发展的历史趋势是生产资料公有制代替 生产资料私有制。"},{"id":"marx-3-11","globalId":194,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":11,"question":"实现意识对物质反作用的根本途径是（ ）。","options":["学习书本知识","进行社会调查","参加社会实践","研究实际情况"],"answer":2,"answerLetter":"C","explain":"意识对物质反作用要通过实践才能实现，实践是连接主观与客观的桥梁，只有参加社会实践，才能 将意识转化为改变物质世界的现实力量。而学习书本知识、进行社会调查、研究实际情况都只是实践的部分 环节或准备，不是根本途径。"},{"id":"marx-3-12","globalId":195,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":12,"question":"下列各项正确表述商品含义的是（ ）。","options":["具有使用价值的物品","具有稀缺性的物品","为自己而生产的有用物品","为交换而生产的有用物品"],"answer":3,"answerLetter":"D","explain":"商品是用于交换的劳动产品，首先要是有用的物品（具有使用价值），且是为交换而生产。A选项仅 强调使用价值，没突出交换；B选项稀缺性不是商品定义关键；C选项为自己生产不用于交换，不是商品。D选 项准确表述了商品为交换而生产且有用。"},{"id":"marx-3-13","globalId":196,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":13,"question":"唯物史观和唯心史观在历史创造者问题上的根本对立在于是否承认（ ）。","options":["个人在历史发展中的作用","思想动机在社会发展中的作用","人民群众是推动历史发展的决定力量","剥削阶级代表人物在历史发展中的作用"],"answer":2,"answerLetter":"C","explain":"唯物史观认为人民群众是历史的创造者，是推动历史发展的决定力量；唯心史观则认为少数英雄人 物是历史创造者。二者在历史创造者问题上的根本对立就在于是否承认人民群众是推动历史发展的决定力量 。"},{"id":"marx-3-14","globalId":197,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":14,"question":"下列各项正确说明感性认识和理性认识联系的是（ ）。","options":["理性认识依赖于感性认识？","感性认识可以自动上升到理性认识","感性认识依赖于理性认识？","理性认识可以自动回归到感性认识"],"answer":0,"answerLetter":"A","explain":"感性认识是认识的初级阶段，是对事物表面现象的认识；理性认识是认识的高级阶段，是对事物本 质和规律的认识。 理性认识依赖于感性认识，因为感性认识是理性认识的基础，没有感性认识提供的原材料 ，理性认识就成了无源之水、无本之木，A选项正确。 感性认识要上升到理性认识，需要通过科学的思维方 法，如分析与综合、归纳与演绎等，不是自动上升的，B选项错误。 是理性认识依赖感性认识，而不是感性 认识依赖理性认识，C选项错误。 理性认识回到实践中去指导实践，而不是自动回归到感性认识，D选项错误 。"},{"id":"marx-3-15","globalId":198,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":15,"question":"资本各形态中能划分为固定资本和流动资本的是（ ）。","options":["生产资本","货币资本","商品资本","借贷资本"],"answer":0,"answerLetter":"A","explain":"只有生产资本能依据价值周转方式不同划分为固定资本和流动资本，货币资本、商品资本属于产业 资本循环的职能形式，借贷资本是生息资本的一种形式，它们都不能做此划分。答案：A。"},{"id":"marx-3-16","globalId":199,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":16,"question":"垄断资本主义阶段占统治地位的资本是（ ）。","options":["工业资本","银行资本","金融资本","商业资本"],"answer":2,"answerLetter":"C","explain":"在垄断资本主义阶段，工业垄断资本和银行垄断资本融合形成金融资本，金融资本在经济、政治等 各方面占据统治地位。答案选C。"},{"id":"marx-3-17","globalId":200,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":17,"question":"垄断资本主义社会大体可分为（ ）。","options":["一般垄断资本主义和私人垄断资本主义两个阶段","私人垄断资本主义和国家垄断资本主义两个阶段","一般垄断资本主义、私人垄断资本主义和国家垄断资本主义三个阶段","私人垄断资本主义、国家垄断资本主义和国际垄断资本主义三个阶段"],"answer":1,"answerLetter":"B","explain":"垄断资本主义发展经历了私人垄断资本主义和国家垄断资本主义两个阶段 。在这一发展过程中，先 是私人垄断资本占据主导，后来随着资本主义矛盾加剧，国家政权与垄断资本结合，形成国家垄断资本主义 。"},{"id":"marx-3-18","globalId":201,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":18,"question":"资本输出的两种基本形式是（ ）。","options":["借贷资本和生产资本输出","借贷资本和商品资本输出","生产资本和商品资本输出","货币资本和生产资本输出"],"answer":0,"answerLetter":"A","explain":"资本输出的基本形式有借贷资本输出和生产资本输出。商品资本输出不属于资本输出基本形式，货 币资本是产业资本循环中的一种职能形式，并非资本输出基本形式。"},{"id":"marx-3-19","globalId":202,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":19,"question":"垄断组织获取垄断利润的主要形式是（ ）。","options":["垄断价格","个人联合","参与制","资本输出"],"answer":0,"answerLetter":"A","explain":"垄断组织获取垄断利润主要通过垄断价格，垄断价格包括垄断高价和垄断低价。个人联合是金融寡 头在政治上统治的手段；参与制是金融寡头在经济上统治的方式；资本输出是垄断资本主义经济扩张的重要 手段。"},{"id":"marx-3-20","globalId":203,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":20,"question":"社会总产品从实物形态上按其最终用途可以划分为（ ）。","options":["劳动资料和劳动对象","劳动工具和劳动对象","劳动工具和消费资料","生产资料和消费资料"],"answer":3,"answerLetter":"D","explain":"社会总产品从实物形态按最终用途划分，主要就是用于生产继续进行的生产资料和满足人们生活消 费的消费资料。A选项劳动资料和劳动对象是生产资料的构成部分，并非按最终用途的划分；B选项劳动工具 属于劳动资料，和劳动对象一样，都不是按最终用途对社会总产品的划分；C选项劳动工具属于生产资料范畴 ，划分不完整。答案：D。"},{"id":"marx-3-21","globalId":204,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":21,"question":"社会总产品是社会各个物质生产部门在一定时期（通常是一年）内生产的（ ）。","options":["全部剩余价值的总和","全部生产资料的总和","全部物质资料的总和","全部消费资料的总和"],"answer":2,"answerLetter":"C","explain":"社会总产品指社会各物质生产部门在一定时期（通常为一年）内所生产的全部物质资料的总和。A选 项剩余价值只是产品价值一部分；B选项生产资料只是物质资料一部分；D选项消费资料也只是物质资料一部 分。"},{"id":"marx-3-22","globalId":205,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":22,"question":"我国坚持独立自主、自力更生和对外开放方针的理论基础是（ ）。","options":["量变和质变辩证关系的原理","内容和形式辩证关系的原理","肯定和否定辩证关系的原理","内因和外因辩证关系的原理"],"answer":3,"answerLetter":"D","explain":"独立自主、自力更生强调的是自身内部的力量，这是事物发展的内因。 对外开放是借助外部的有 利条件，属于事物发展的外因。 我国坚持这一方针，正是基于内因是事物发展的根据，外因是事物发展的条 件，外因通过内因起作用的内因和外因辩证关系原理。"},{"id":"marx-3-23","globalId":206,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":23,"question":"英国古典经济学的代表人物是（ ）。","options":["培根和洛克","黑格尔和费尔巴哈","斯密和李嘉图","圣西门和傅立叶"],"answer":2,"answerLetter":"C","explain":"A选项中培根和洛克是英国的哲学家等，并非古典经济学代表人物。 B选项黑格尔和费尔巴哈是德 国古典哲学的代表人物。 C选项，亚当·斯密和大卫·李嘉图是英国古典经济学的杰出代表，他们对古典经 济学理论体系的建立和发展作出重要贡献。 D选项圣西门和傅立叶是空想社会主义的代表人物。"},{"id":"marx-3-24","globalId":207,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":24,"question":"资本有机构成可以表示为（ ）。","options":["生产资本与流通资本的比率","产业资本与商业资本的比率","不变资本与可变资本的比率","固定资本与流动资本的比率"],"answer":2,"answerLetter":"C","explain":"资本有机构成是由资本技术构成决定并反映技术构成变化的资本价值构成，通常用不变资本与可变 资本的比率（c:v）来表示。所以答案是C。"},{"id":"marx-3-25","globalId":208,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":25,"question":"马克思所说未来社会的第一阶段是指（ ）。","options":["社会主义革命时期","向社会主义过渡时期","社会主义初级阶段","社会主义社会"],"answer":3,"answerLetter":"D","explain":"马克思所说未来社会的第一阶段指的是社会主义社会。马克思设想未来社会有两个阶段，第一阶段 是社会主义社会，高级阶段是共产主义社会。A选项社会主义革命时期主要是进行推翻旧制度建立新政权的阶 段；B选项向社会主义过渡时期是从资本主义向社会主义转变的阶段；C选项社会主义初级阶段是我国在生产 力落后、商品经济不发达条件下建设社会主义必然要经历的特定阶段，它不等同于马克思所说未来社会第一 阶段的宽泛概念。"},{"id":"marx-3-26","globalId":209,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":26,"question":"生产不再下降,失业不再增加,企业倒闭停止。这种状态属于本主义再生产周期中的（ ）。","options":["危机阶段","萧条阶段","复苏阶段","高涨阶段"],"answer":1,"answerLetter":"B","explain":"危机阶段的特点是生产猛烈下降，失业急剧增加，企业大量倒闭等，所以A选项不符合。 萧条阶段 的特征是生产不再下降，失业不再增加，企业倒闭停止，但整个经济生活还未全面恢复，题干描述符合萧条 阶段的特点。 复苏阶段生产逐渐回升，就业日益增多等，与题干单纯不再下降、增加等表述不符，C选项排 除。 高涨阶段生产迅速扩张，市场繁荣等，和题干描述不匹配，D选项排除。"},{"id":"marx-3-27","globalId":210,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":27,"question":"资本主义不同生产部门之间的竞争会导致（ ）。","options":["社会必要劳动时间的变化","平均利润的形成","资本主义生产关系本质的变化","全社会的利润总量小于剩余价值总量"],"answer":1,"answerLetter":"B","explain":"不同生产部门之间竞争的手段是资本转移，即把资本从利润率低的部门转移到利润率高的部门，这 种竞争会导致各部门利润率趋于平均化，从而形成平均利润。"},{"id":"marx-3-28","globalId":211,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":28,"question":"人类社会的基本矛盾是（ ）。","options":["人与自然、个人与社会之间的矛盾","先进与落后、创新与守旧之间的矛盾","生产力与生产关系、经济基础与上层建筑之间的矛盾","社会存在与社会意识、物质文明和精神文明之间的矛盾"],"answer":2,"answerLetter":"C","explain":"生产力与生产关系、经济基础与上层建筑之间的矛盾是贯穿人类社会始终的基本矛盾。这两对矛盾 运动推动着人类社会的发展变化。"},{"id":"marx-3-29","globalId":212,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":29,"question":"生产方式是（ ）。","options":["地理环境和人口因素的统一","社会存在和社会意识的统一","经济基础和上层建筑的统一","生产力和生产关系的统一"],"answer":3,"answerLetter":"D","explain":"生产方式是人类借以向自然界谋取必需的生活资料的方式，它包括生产力和生产关系两个方面，是 特定的生产力和生产关系的统一。A选项地理环境和人口因素是社会存在的内容；B选项社会存在与社会意识 相对；C选项经济基础和上层建筑的统一构成社会形态。"},{"id":"marx-3-30","globalId":213,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":30,"question":"我们实现人生价值的最终归宿是（ ）。","options":["社会主义共同理想","共产主义远大理想","天下大同的社会理想","克己奉公的道德理想"],"answer":1,"answerLetter":"B","explain":"共产主义远大理想体现了对全人类解放和每个人自由全面发展的追求，代表了人类最美好的未来 ，是实现人生价值的最终归宿。其他选项，社会主义共同理想是阶段性理想；“天下大同”并非马克思主义 语境下科学表述；克己奉公道德理想主要侧重于道德层面，不能作为实现人生价值最终归宿。"},{"id":"marx-3-31","globalId":214,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":31,"question":"资本主义国家调控经济的主要手段是（ ）。","options":["经济手段和经济计划","经济手段和法律手段","行政手段和经济计划","法律手段和经济计划"],"answer":1,"answerLetter":"B","explain":"资本主义国家对经济的调控手段，主要是经济手段和法律手段，辅之以计划指导和必要的行政手段 。经济手段通过调节经济变量影响市场主体行为；法律手段为经济运行提供规范和保障。"},{"id":"marx-3-32","globalId":215,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":32,"question":"无产阶级政党的组织原则是（ ）。","options":["集体领导制","首长负责制","集体问责制","民主集中制"],"answer":3,"answerLetter":"D","explain":"无产阶级政党的组织原则是民主集中制，它既能充分发扬党内民主，又能实行正确的集中，保证党 意志统一和行动一致。"},{"id":"marx-3-33","globalId":216,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":33,"question":"资本主义国家向某个濒临破产的私人企业注入一定量的国有资本，使之能继续生存下去，此时这个企业的 性质属于","options":["资本主义国有经济","资本主义私有经济","资本主义国有资本和私人资本在企业内部的结合","资本主义国有资本和私人资本在企业外部的结合"],"answer":2,"answerLetter":"C","explain":"国家向濒临破产私人企业注入国有资本，意味着企业内既有国有资本又有私人资本，属于国有资本 和私人资本在企业内部结合。"},{"id":"marx-3-34","globalId":217,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":34,"question":"资本主义商业利润的本质与真正来源是（ ）。","options":["商品在流通过程中的加价","商业店员创造的剩余价值","产业工人创造的一部分剩余价值","商业店员实现的剩余价值"],"answer":2,"answerLetter":"C","explain":"商业利润是产业资本家让渡给商业资本家的一部分剩余价值，这部分剩余价值是产业工人在生产过 程中创造的。商业店员从事单纯商品买卖活动不创造价值和剩余价值，但能实现商品价值和剩余价值。所以 商业利润本质和真正来源是产业工人创造的一部分剩余价值。"},{"id":"marx-3-35","globalId":218,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":35,"question":"社会主义建设的领导核心是（ ）。","options":["工人阶级","工人阶级和全体劳动人民","马克思主义政党","社会主义国家的政府"],"answer":2,"answerLetter":"C","explain":"马克思主义政党是社会主义建设的领导核心，因为党能够把握社会发展规律，制定正确的路线方针 政策，凝聚人民力量等。而工人阶级是领导阶级，全体劳动人民是依靠力量，社会主义国家政府是执行具体 事务的机构，它们都不能等同于领导核心。"},{"id":"marx-3-36","globalId":219,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":36,"question":"下列活动中属于最基本的实践形式的是（ ）。","options":["物质生产活动","处理社会关系活动","科学实验活动","艺术表演活动"],"answer":0,"answerLetter":"A","explain":"实践的基本形式有物质生产实践、处理社会关系的实践、科学实验实践。其中物质生产活动是人类 最基本的实践活动，因为它是人类社会存在和发展的基础，为其他实践活动提供物质基础。答案：A 。"},{"id":"marx-3-37","globalId":220,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":37,"question":"无产阶级专政的最终目标是（ ）。","options":["巩固和发展无产阶级政权","建设社会主义新型民主","消灭剥削进入无阶级社会","巩固和发展社会主义公有制"],"answer":2,"answerLetter":"C","explain":"无产阶级专政的最终目标是消灭剥削、消灭阶级，进入到无阶级社会。选项A巩固和发展无产阶级政 权是阶段性目标；选项B建设社会主义新型民主是实现最终目标过程中的重要任务；选项D巩固和发展社会主 义公有制是实现最终目标的手段之一。只有消灭剥削进入无阶级社会才是最终目标。"},{"id":"marx-3-38","globalId":221,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":38,"question":"资本主义简单再生产实现的条件下，第二部类产品的总价值应等于（ ）。","options":["第一部类工人和资本家消耗的消费资料价值总和","第二部类工人和资本家消耗的消费资料价值总和","两大部类工人和资本家消耗的消费资料价值总和","两大部类工人和资本家消耗的生产资料价值总和"],"answer":2,"answerLetter":"C","explain":"在资本主义简单再生产条件下，社会总产品实现的基本条件是Ⅰ(v + m)=Ⅱc，由此可以引申出Ⅱ(c + v + m)=Ⅰ(v + m)+Ⅱ(v + m)，也就是第二部类产品的总价值等于两大部类工人和资本家消耗的消费资料 价值总和，因为Ⅰ(v + m)是第一部类工人和资本家用于消费的部分，Ⅱ(v + m)是第二部类工人和资本家用 于消费的部分。"},{"id":"marx-3-39","globalId":222,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":39,"question":"下列选项属于经济社会形态的是（ ）。","options":["渔猎社会","工业社会","信息社会","封建社会"],"answer":3,"answerLetter":"D","explain":"经济社会形态是以生产关系的性质为标准划分的社会形态，封建社会是基于特定生产关系性质的社 会形态。渔猎社会、工业社会、信息社会是按照生产力和技术发展水平以及产业结构特征划分的社会形态。 答案选D。"},{"id":"marx-3-40","globalId":223,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":40,"question":"物质资料的生产方式是（ ）。","options":["生产资料与消费资料的统一","劳动资料与劳动对象的统一","生产力与生产关系的统一","劳动者与劳动工具的统一"],"answer":2,"answerLetter":"C","explain":"物质资料生产方式是人类社会存在和发展的基础，它包括生产力和生产关系两个方面，生产力是生 产方式的物质内容，生产关系是生产方式的社会形式，二者有机统一。"},{"id":"marx-3-41","globalId":224,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":41,"question":"资本主义简单再生产实现的条件下，第一部类生产的全部产品的总价值应等于（ ）。","options":["第一部类消耗的生产资料的价值总和","第二部类消耗的生产资料的价值总和","两大部类消耗的生产资料的价值总和","两大部类消耗的生活资料的价值总和"],"answer":2,"answerLetter":"C","explain":"在资本主义简单再生产条件下，第一部类生产的全部产品的总价值要满足两大部类对生产资料的需 求，即第一部类生产的全部产品的总价值应等于两大部类消耗的生产资料的价值总和。"},{"id":"marx-3-42","globalId":225,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":42,"question":"资本主义社会的发展大体分为（ ）。","options":["分工、协作和机器大工业三个阶段","自由竞争和垄断两个阶段","私人垄断、国家垄断和国际垄断三个阶段","私人垄断和国家垄断两个阶段"],"answer":1,"answerLetter":"B","explain":"资本主义社会发展经历自由竞争资本主义和垄断资本主义两个大阶段。A选项分工等阶段表述的是生 产形式发展，不是资本主义社会发展阶段。C、D选项中国家垄断、国际垄断等都属于垄断资本主义阶段的细 分，并非资本主义社会发展的两大基本阶段。"},{"id":"marx-3-43","globalId":226,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":43,"question":"社会主义由空想变为科学的标志性著作是（ ）。","options":["《资本论》","《德意志意识形态》","《共产党宣言》","《反杜林论》"],"answer":2,"answerLetter":"C","explain":"《共产党宣言》的发表，标志着科学社会主义的诞生，它使社会主义从空想变为科学。《资本论》 主要是深入剖析资本主义经济规律；《德意志意识形态》对唯物史观有重要阐述；《反杜林论》全面系统地 阐述了马克思主义理论体系。"},{"id":"marx-3-44","globalId":227,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":44,"question":"社会资本在生产的核心问题是（ ）。","options":["剩余价值的实现问题","国民收入的实现问题","社会总产品的实现问题","国民生产总值的实现问题"],"answer":2,"answerLetter":"C","explain":"社会资本再生产的核心问题是社会总产品的实现问题，包括价值补偿和实物补偿。因为只有社会总 产品都能销售出去，重新获得价值补偿，并买到新的生产资料和生活资料，社会资本再生产才能顺利进行。"},{"id":"marx-3-45","globalId":228,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":45,"question":"下列选项属于马克思主义三个组成部分之一的是（ ）。","options":["马克思主义政治学","马克思主义哲学","马克思主义伦理学","马克思主义社会学"],"answer":1,"answerLetter":"B","explain":"马克思主义由马克思主义哲学、马克思主义政治经济学和科学社会主义三部分组成。B选项马克思主 义哲学符合。答案：B 。"},{"id":"marx-3-46","globalId":229,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":46,"question":"下列选项属于意识形态的是（ ）。","options":["语言学","逻辑学","数学","哲学"],"answer":3,"answerLetter":"D","explain":"意识形态是反映社会经济关系、阶级关系的社会意识形式。语言学、逻辑学、数学是对客观世界的 中性描述，不具有阶级性，不属于意识形态。而哲学是系统化、理论化的世界观，反映一定阶级的利益和要 求，属于意识形态。"},{"id":"marx-3-47","globalId":230,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":47,"question":"资本主义的意识形态（ ）。","options":["只具有历史进步性","只具有阶级局限性","既无历史进步性也无阶级局限性","既有历史进步性又有阶级局限性"],"answer":3,"answerLetter":"D","explain":"资本主义意识形态在反对封建专制等方面起到过推动社会进步的作用，具有历史进步性；但它本质 上是为资产阶级利益服务的，代表资产阶级的意志，具有阶级局限性。所以资本主义意识形态既有历史进步 性又有阶级局限性。"},{"id":"marx-3-48","globalId":231,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":48,"question":"资本主义地租是（ ）。","options":["农产品价值低于生产价格的差额","土地所有者得到的平均利润","超过平均利润的超额利润","农业工人创造的全部剩余价值"],"answer":2,"answerLetter":"C","explain":"资本主义地租是农业资本家租种土地所有者的土地而缴纳给土地所有者的、由农业工人创造的超过 平均利润的那部分剩余价值，即超额利润。"},{"id":"marx-3-49","globalId":232,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":49,"question":"资本主义利息的本质是（ ）。","options":["货币资本使用权的价格","剩余价值的特殊转化形式","借贷资本的报酬","平均利润的特殊转化形式"],"answer":1,"answerLetter":"B","explain":"利息是职能资本家使用借贷资本而让渡给借贷资本家的一部分剩余价值。所以资本主义利息的本质 是剩余价值的特殊转化形式。"},{"id":"marx-3-50","globalId":233,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":50,"question":"资本主义再生产的特征是（ ）。","options":["简单再生产","扩大再生产","粗放型再生产","集约型再生产"],"answer":1,"answerLetter":"B","explain":"资本主义再生产的特征是扩大再生产。资本家为了获取更多剩余价值和在竞争中取胜，不会满足于 简单再生产，而是会不断扩大生产规模，进行扩大再生产。"},{"id":"marx-3-51","globalId":234,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":51,"question":"下列关于股份资本的表述中不正确的是（ ）。","options":["它使资本的形式由单个资本变为联合资本","它带有社会资本的性质","它是资本主义生产关系的一次自我“扬弃”","它没有突破单个私人资本的局限性"],"answer":3,"answerLetter":"D","explain":"股份资本把许多单个资本联合起来，由单个资本变为联合资本，所以A选项表述正确。 股份资本不 再是单个私人资本，带有社会资本性质，B选项表述正确。 股份资本一定程度上突破了单个私人资本局限性 ，对资本主义生产关系进行了自我“扬弃”，C选项表述正确。 股份资本突破了单个私人资本的局限性，D选 项说没有突破，表述错误。"},{"id":"marx-3-52","globalId":235,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":52,"question":"下列选项中，反映实践对认识具有决定作用的是（ ）。","options":["芳林新叶催陈叶，流水前波让后波","沉舟侧畔千帆过，病树前头万木春","勿以恶小而为之，勿以善小而不为","纸上得来终觉浅，绝知此事要躬行"],"answer":3,"answerLetter":"D","explain":"A、B选项体现的是发展的观点，新事物代替旧事物；C选项强调的是量变和质变的关系。D选项“纸 上得来终觉浅，绝知此事要躬行”意思是从书本上得到的知识毕竟比较肤浅，要透彻地认识事物还必须亲自 实践，体现了实践对认识具有决定作用。"},{"id":"marx-3-53","globalId":236,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":53,"question":"下列选项中，属于君主立宪制类型的是（ ）。","options":["合议制和专制独裁制","合议制和二元君主制","议会君主制和二元君主制","专制独裁制和二元君主制"],"answer":2,"answerLetter":"C","explain":"君主立宪制主要分为议会君主制和二元君主制。合议制一般用于描述行政机关的组织形式等，与君 主立宪制分类无关，专制独裁制和君主立宪制是不同的政治体制类型。所以答案选C。"},{"id":"marx-3-54","globalId":237,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":54,"question":"资本主义国家的民主制度存在形式上平等而事实上不平等的矛盾，根本原因在于","options":["宪法是由资产阶级制定的","民主的原则是与实践相脱节的","劳动人民不能参与国家政权的管理","民主权利的实现受到资本主义生产资料私有制的限制"],"answer":3,"answerLetter":"D","explain":"经济基础决定上层建筑，资本主义生产资料私有制是资本主义社会的经济基础，这一私有制决定了 在资本主义民主制度下，民主权利的实现必然受到限制，导致形式上平等而事实上不平等。A选项宪法由谁制 定不是根本原因；B选项民主原则与实践脱节是表现而非根本原因；C选项劳动人民并非完全不能参与国家政 权管理，只是在私有制下参与程度有限，且这也不是根本原因。"},{"id":"marx-3-55","globalId":238,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":55,"question":"资本主义企业的生产成本是（ ）。","options":["不变资本价值与剩余价值之和","可变资本价值与剩余价值之和","流动资本与剩余价值之和","不变资本价值和可变资本价值之和"],"answer":3,"answerLetter":"D","explain":"资本主义企业生产成本是生产单位商品所耗费的不变资本与可变资本之和。因为这两部分资本是生 产过程中实际耗费的，用于补偿生产过程中的资本消耗。而剩余价值是工人创造的被资本家无偿占有的超过 劳动力价值的价值，不包含在生产成本内。流动资本包含可变资本以及部分不变资本，但这种表述不准确。 所以答案选D。"},{"id":"marx-3-56","globalId":239,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":56,"question":"资本主义造就的埋葬自身的社会力量是（ ）。","options":["无产阶级","科学技术","巨大的社会财富","社会化的生产力"],"answer":0,"answerLetter":"A","explain":"无产阶级是随着资本主义生产方式的产生发展而逐渐形成壮大的，他们受剥削压迫最深，最具革命 性，代表先进生产力和社会发展方向，是资本主义制度的掘墓人。而科学技术、巨大社会财富并非埋葬资本 主义的社会力量，社会化生产力只是为埋葬资本主义提供了物质基础，真正起关键推动作用的社会力量是无 产阶级。"},{"id":"marx-3-57","globalId":240,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":57,"question":"下列选项中，正确表述了认识的客体的含义的是（ ）。","options":["认识的客体是主体实践和认识的对象","认识的客体是主体创造出来的对象","认识的客体是一切客观事物","认识的客体是整个外部自然界"],"answer":0,"answerLetter":"A","explain":"认识的客体是主体实践和认识活动所指向的对象。B选项主体不能创造客体；C选项并非一切客观事 物都是认识客体，只有进入主体实践和认识范围的才是；D选项整个外部自然界太宽泛，只有与主体发生联系 的部分才是认识客体。"},{"id":"marx-3-58","globalId":241,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":58,"question":"下列关于人的本质的表述中，正确的是（ ）。","options":["人的本质不是后天的而是先天的","人的本质不是具体的而是抽象的","人的本质不是变化的而是永恒的","在阶级社会里人的本质是有阶级性的"],"answer":3,"answerLetter":"D","explain":"人的本质是一切社会关系的总和。人是在后天的社会生活和社会实践中形成自身本质的，不是先天 的，A 错误。 人的本质是具体的，因为社会关系是多样且具体的，不是抽象的，B 错误。 社会关系是不断 变化发展的，所以人的本质也是变化的，不是永恒不变的，C 错误。 在阶级社会中，社会关系具有阶级性 ，这就决定了人的本质具有阶级性，D 正确。"},{"id":"marx-3-59","globalId":242,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":59,"question":"下列选项中，正确表述了实践含义的是（ ）。","options":["实践是主体纯主观的精神性活动","实践是主观创造客观世界的活动","实践是主体应付外部环境的活动","实践是主体改造和探索客体的社会性物质活动"],"answer":3,"answerLetter":"D","explain":"实践是人类能动地改造世界的社会性的物质活动。A选项说实践是纯主观精神活动错误；B选项主观 不能直接创造客观世界；C选项应付外部环境不是实践本质。只有D符合实践的定义。"},{"id":"marx-3-60","globalId":243,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":60,"question":"下列观点中，属于辩证唯物主义认识论区别于其他一切认识论的最基本观点的是（ ）。","options":["实践是认识的基础","认识是主体对客体的反映","世界是可以认识的","认识是辩证发展的过程"],"answer":0,"answerLetter":"A","explain":"辩证唯物主义认识论强调实践在认识中的基础地位，实践是认识的来源、动力、目的和检验标准 ，这是其区别于其他认识论的最基本观点。B选项很多认识论都认同认识是主体对客体的反映；C选项可知论 都认为世界可认识；D选项一些哲学也有认识辩证发展的观点，但都不如实践是认识的基础这一观点凸显辩证 唯物主义认识论的独特性。"},{"id":"marx-3-61","globalId":244,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":61,"question":"下列选项中属于上层建筑两大组成部分的是（ ）。","options":["政治思想和法律思想","政治制度和法律制度","政治法律思想和道德观念","政治法律制度和社会意识形态"],"answer":3,"answerLetter":"D","explain":"上层建筑由政治上层建筑和观念上层建筑组成。政治法律制度属于政治上层建筑，社会意识形态属 于观念上层建筑。"},{"id":"marx-3-62","globalId":245,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":62,"question":"下列选项中属于最基本的实践活动的是（ ）。","options":["社会管理活动","科学实验活动","社会改革活动","物质生产活动"],"answer":3,"answerLetter":"D","explain":"物质生产活动是人类最基本的实践活动，因为它是人类社会存在和发展的基础，为其他实践活动提 供物质基础。其他选项如社会管理活动、科学实验活动、社会改革活动等都依赖于物质生产活动。"},{"id":"marx-3-63","globalId":246,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":63,"question":"下列资本形式中不属于职能资本的是（ ）。","options":["产业资本","商业资本","借贷资本","农业资本"],"answer":2,"answerLetter":"C","explain":"职能资本是对剩余价值的生产和实现，实际发挥了职能作用的资本。产业资本在生产领域生产剩余 价值，商业资本在流通领域实现剩余价值，农业资本也在农业生产等实际生产经营过程中发挥作用，属于职 能资本。 借贷资本是为了取得利息而暂时贷给职能资本家使用的货币资本，它不直接参与生产和流通等职能 活动，只是凭借资本所有权获取利息，不属于职能资本。"},{"id":"marx-3-64","globalId":247,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":64,"question":"作为认识的初级阶段，感性认识的三种形式是（ ）。","options":["概念、判断、推理","感觉、知觉、表象","分析、归纳、综合","识记、联想、假说"],"answer":1,"answerLetter":"B","explain":"感性认识是认识的初级阶段，它的三种形式是感觉、知觉、表象 。A选项概念、判断、推理是理性 认识形式；C选项分析、归纳、综合属于思维方法；D选项识记、联想、假说不属于认识的形式分类。"},{"id":"marx-3-65","globalId":248,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":65,"question":"作为真理的马克思主义是发展的，与时俱进的，这是因为真理具有（ ）。","options":["相对性","能动性","绝对性","普遍性"],"answer":0,"answerLetter":"A","explain":"真理的相对性表明真理是有条件的、有限的。由于客观世界是不断发展的，社会实践也是不断发展 的，所以基于实践基础上的真理也要不断发展，与时俱进。马克思主义作为真理，也要随着时代、实践、科 学发展而不断发展，这体现了真理的相对性。 真理不具有能动性，能动性一般指意识的能动性，B选项错误 。 真理的绝对性强调真理的客观性、无条件性等，与马克思主义与时俱进的发展关系不大，C选项不符合。 普遍性不是真理的特性，D选项错误。"},{"id":"marx-3-66","globalId":249,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":66,"question":"《共产党宣言》的作者是（ ）。","options":["马克思、恩格斯","列宁、斯大林","卢森堡、拉法格","毛泽东"],"answer":0,"answerLetter":"A","explain":"《共产党宣言》是马克思和恩格斯为共产主义者同盟起草的纲领，是两人合作的成果。所以答案是 A。"},{"id":"marx-3-67","globalId":250,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":67,"question":"19世纪初期欧洲空想社会主义的代表人物不包括","options":["法国的圣西门？","法国的傅立叶","英国的欧文？？","德国的黑格尔"],"answer":3,"answerLetter":"D","explain":"19世纪初期欧洲空想社会主义代表人物是法国的圣西门、傅立叶和英国的欧文。而黑格尔是德国古 典哲学的代表人物，并非空想社会主义代表。答案选D。"},{"id":"marx-3-68","globalId":251,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":68,"question":"白菜、韭菜、芹菜、菠菜与蔬菜的关系属于（ ）。","options":["部分与整体的关系","个性与共性的关系","现象与本质的关系","形式与内容的关系"],"answer":1,"answerLetter":"B","explain":"白菜、韭菜、芹菜、菠菜等是具体的蔬菜种类，它们具有各自独特的特点。而蔬菜是对这一类可食 用植物的统称，包含了白菜、韭菜等各种具体蔬菜的共同特征。所以白菜、韭菜等具体蔬菜与蔬菜之间是个 性与共性的关系。"},{"id":"marx-3-69","globalId":252,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":69,"question":"辩证唯物主义认为,认识的本质是（ ）。","options":["主体对客体的直观反映","绝对观念的显现","主体对客体的能动反映","神秘天意的启示"],"answer":2,"answerLetter":"C","explain":"辩证唯物主义强调认识是在实践基础上主体对客体的能动反映。A选项直观反映忽略了能动作用 ；B选项绝对观念的显现是客观唯心主义观点；D选项神秘天意的启示也是客观唯心主义，与辩证唯物主义相 悖。"},{"id":"marx-3-70","globalId":253,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":70,"question":"辩证法和形而上学的区别在于如何回答","options":["世界的本质是什么的问题？","世界可否被认识的问题","世界的存在是怎样的问题？","世界有否统一性的问题"],"answer":2,"answerLetter":"C","explain":"辩证法和形而上学探讨的是世界的存在状态和发展方式等问题，即世界是怎样存在的。A选项世界本 质是什么的问题，是唯物主义和唯心主义的分歧点；B选项世界可否被认识是可知论和不可知论的区别；D选 项世界有否统一性是一元论和二元论的差别。只有C选项符合辩证法（用联系、发展、全面观点看世界存在 ）和形而上学（用孤立、静止、片面观点看世界存在）的区别。"},{"id":"marx-3-71","globalId":254,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":71,"question":"辩证唯物主义认为，物质的唯一特性是（ ）。","options":["广延性","持续性","客观实在性","可知性"],"answer":2,"answerLetter":"C","explain":"辩证唯物主义强调物质是不依赖于人的意识，并能为人的意识所反映的客观实在，客观实在性是物 质区别于意识的唯一特性。广延性、持续性等是物质的一些属性，但不是唯一特性，可知性强调物质能被认 识，并非物质的唯一特性。"},{"id":"marx-3-72","globalId":255,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":72,"question":"一种理论是不是真理，根本之点是看它（ ）。","options":["是否与已有的理论相一致","是否与客观实际相一致","是否说得清楚明白","是否被大多数人承认"],"answer":1,"answerLetter":"B","explain":"真理是人们对于客观事物及其规律的正确认识，所以一种理论是不是真理关键要看是否与客观实际 相一致。A选项与已有理论一致不一定就是真理，已有理论也可能有误；C选项说得清楚明白不代表就是真理 ；D选项被大多数人承认也不一定是真理，比如曾经很多人认为“地心说”正确，但实际并非如此。答案 ：B。"},{"id":"marx-3-73","globalId":256,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":73,"question":"德国古典哲学是马克思主义哲学的直接理论来源。马克思恩格斯批判地吸取了黑格尔哲学的（ ）。","options":["唯物主义思想","辩证法思想","可知论思想","决定论思想"],"answer":1,"answerLetter":"B","explain":"马克思恩格斯批判地吸取了黑格尔辩证法的合理内核，以及费尔巴哈唯物主义的基本内核，从而创 立了马克思主义哲学。黑格尔哲学最突出的贡献是辩证法。"},{"id":"marx-3-74","globalId":257,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":74,"question":"地理环境是（ ）。","options":["社会制度性质的决定性因素","社会经济结构的划分依据","社会形态更替的决定力量","社会存在发展的必要条件"],"answer":3,"answerLetter":"D","explain":"地理环境是社会存在和发展的必要条件，它能影响社会发展速度，但不是社会制度性质、社会经济 结构划分以及社会形态更替的决定性力量。生产力和生产关系的矛盾运动等才是这些方面的关键决定因素。"},{"id":"marx-3-75","globalId":258,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":75,"question":"依据价值周转方式的不同,资本可划分为（ ）。","options":["固定资本和流动资本","不变资本和可变资本","固定资本和可变资本","流动资本和不变资本"],"answer":0,"answerLetter":"A","explain":"根据价值周转方式不同，资本分为固定资本和流动资本。固定资本价值是逐步转移到产品中，流动 资本价值是一次性转移到产品中。而不变资本和可变资本是依据在剩余价值生产中作用不同划分的。"},{"id":"marx-3-76","globalId":259,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":76,"question":"依据劳动二重性原理,具体劳动（ ）。","options":["创造新价值","创造剩余价值","创造超额剩余价值","创造使用价值"],"answer":3,"answerLetter":"D","explain":"劳动二重性指具体劳动和抽象劳动。具体劳动是生产不同使用价值的不同性质和不同形式的劳动 ，它创造商品的使用价值；抽象劳动创造新价值、剩余价值、超额剩余价值。"},{"id":"marx-3-77","globalId":260,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":77,"question":"不变资本和可变资本数量构成上的比例是资本的","options":["有机构成","价值构成","技术构成","数量构成"],"answer":1,"answerLetter":"B","explain":"资本价值构成是指不变资本和可变资本数量构成上的比例。资本技术构成是由生产技术决定的生产 资料和劳动力之间的量的比例。资本有机构成是由资本技术构成决定并反映技术构成变化的资本价值构成。 题干强调不变资本与可变资本数量构成比例，所以是价值构成。"},{"id":"marx-3-78","globalId":261,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":78,"question":"除《哲学的贫困》外，标志马克思主义公开问世的经典著作是（ ）。","options":["《关于费尔巴哈的提纲》","《德意志意识形态》","《共产党宣言》","《资本论》"],"answer":2,"answerLetter":"C","explain":"《共产党宣言》的发表，标志着马克思主义的公开问世 ，它全面系统地阐述了科学社会主义理论 。答案选C。"},{"id":"marx-3-79","globalId":262,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":79,"question":"共产主义社会的分配原则是（ ）。","options":["按劳分配","按需分配","平均分配","定量分配"],"answer":1,"answerLetter":"B","explain":"共产主义社会生产力高度发达，物质财富极大丰富，人们的思想觉悟极大提高，能够实行按需分配 ，即按照每个人的实际需要分配产品。按劳分配是社会主义社会的分配原则，平均分配在历史上一些特定时 期存在但不是共产主义分配原则，定量分配也不符合共产主义分配特点。"},{"id":"marx-3-80","globalId":263,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":80,"question":"共产主义的本质因素是（ ）。","options":["实现生产资料公有制","人民生活富裕","实行按需分配","人的自由而全面发展"],"answer":3,"answerLetter":"D","explain":"共产主义社会的本质是实现人的自由全面发展，这是共产主义社会最根本的特征和本质因素。生产 资料公有制、按需分配是共产主义社会的经济特征，人民生活富裕是社会主义的追求目标之一，但这些都不 是共产主义的本质因素。答案：D。"},{"id":"marx-3-81","globalId":264,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":81,"question":"以劳动力形式存在的那部分资本是（ ）。","options":["不变资本","可变资本","固定资本","流通资本"],"answer":1,"answerLetter":"B","explain":"以生产资料形式存在的资本，在生产过程中不改变自己的价值量，叫不变资本；以劳动力形式存在 的资本，在生产过程中发生了价值增殖，叫可变资本。固定资本是指以厂房、机器、设备等劳动资料形式存 在的生产资本；流通资本是指处于流通领域中的货币资本和商品资本。所以以劳动力形式存在的那部分资本 是可变资本。"},{"id":"marx-3-82","globalId":265,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":82,"question":"部门平均劳动生产率提高之后，会导致单位商品的价值量（ ）。","options":["增加","降低","不变","无法判断"],"answer":1,"answerLetter":"B","explain":"单位商品价值量由社会必要劳动时间决定，部门平均劳动生产率提高意味着生产单位商品的社会必 要劳动时间缩短，所以单位商品价值量降低。"},{"id":"marx-3-83","globalId":266,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":83,"question":"除了商业资本和产业资本的分工，商业资本独立化的条件还有（ ）。","options":["商业资本和借贷资本的分工","商业资本家有独立的投资","存在独立的商业活动","存在出卖劳动力为生的商业店员"],"answer":1,"answerLetter":"B","explain":"【标准答案：B】"},{"id":"marx-3-84","globalId":267,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":84,"question":"股票价格是股息收入的资本化，这表明（ ）。","options":["股票价格等于股票票面额","股票这种商品是有价值的","股票价格的变动唯一取决于股息收入","股票价格与股息成正比变化，与存款利息率成反比变化"],"answer":3,"answerLetter":"D","explain":"股票价格=股息/存款利息率，所以股票价格与股息成正比，与存款利息率成反比。A选项，股票价格 一般不等于票面额；B选项，股票本身无价值，只是凭证；C选项，股票价格变动不唯一取决于股息收入。答 案：D"},{"id":"marx-3-85","globalId":268,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":85,"question":"雇佣工人在剩余劳动时间创造的是（ ）。","options":["商品的使用价值","商品的价值","资本家无偿占有的剩余价值","劳动力的价值"],"answer":2,"answerLetter":"C","explain":"雇佣工人的劳动时间分为必要劳动时间和剩余劳动时间。在必要劳动时间内创造劳动力自身的价值 ，在剩余劳动时间内创造被资本家无偿占有的剩余价值。商品使用价值是具体劳动创造的，商品价值是由必 要劳动时间和剩余劳动时间共同创造的价值总和。"},{"id":"marx-3-86","globalId":269,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":86,"question":"意识的起源和认识的起源是（ ）。","options":["一致的","不一致的","同时的","不同时的"],"answer":0,"answerLetter":"A","explain":"意识起源于物质世界长期发展以及人类社会的产生，而认识起源于实践，实践是人类有意识有目的 的活动，从根本上来说意识起源和认识起源都与人类社会及实践相关，本质上是一致的。"},{"id":"marx-3-87","globalId":270,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":87,"question":"判断一种观点是非对错的标准是（ ）。","options":["以伟人之是非为是非","以吾心之是非为是非","以众人的意见定是非","以实践中是否达到预想效果定是非"],"answer":3,"answerLetter":"D","explain":"实践是检验真理的唯一标准，判断一种观点对错应看其在实践中是否达到预想效果。A 选项以伟人 是非为标准，忽视了伟人也可能出错；B 选项以个人内心为标准过于主观；C 选项众人意见不一定就是正确 的，可能存在从众等不合理情况。"},{"id":"marx-3-88","globalId":271,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":88,"question":"从较长时期看,再生产劳动力所必需的消费资料的物质内容（ ）。","options":["不会有很大变化","会不断扩大","会不断缩小","只能有小幅度微调"],"answer":1,"answerLetter":"B","explain":"随着社会生产力的发展和社会进步，人们的生活水平会逐步提高，对消费资料的质量、种类等需求 也会增加，所以从较长时期看，再生产劳动力所必需的消费资料的物质内容会不断扩大。答案选B。"},{"id":"marx-3-89","globalId":272,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":89,"question":"从性质上看，发达资本主义国家对发展中国家的“经济援助”是（ ）。","options":["帮助发展中国家克服经济困难的一种方式","新殖民主义的一种方式","扼杀发展中国家经济发展的手段","促进发展中国家经济独立的工具"],"answer":1,"answerLetter":"B","explain":"发达资本主义国家对发展中国家的“经济援助”，并非真心帮助发展中国家发展经济，其背后往往 隐藏着政治、经济等多方面的利益诉求，是一种新殖民主义手段，目的是继续控制发展中国家。"},{"id":"marx-3-90","globalId":273,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":90,"question":"马克思主义认为,资本主义意识形态（ ）。","options":["只具有历史进步性","既有历史进步性又有阶级局限性","只具有阶级局限性","既无历史进步性又无阶级局限性"],"answer":1,"answerLetter":"B","explain":"资本主义意识形态在反对封建主义时起过积极作用，具有历史进步性；但它本质是维护资产阶级利 益，为资本主义制度服务，又有阶级局限性。"},{"id":"marx-3-91","globalId":274,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":91,"question":"从理论上讲，股票的价格（ ）。","options":["同股息成正比，同利息率成反比","同股息成反比，同利息率成正比","同股息和利息率都成正比","同股息和利息率都成反比"],"answer":0,"answerLetter":"A","explain":"股票价格=股息/利息率，从这个公式可以看出，股息越高，股票价格越高，二者成正比；利息率越 高，股票价格越低，二者成反比。"},{"id":"marx-3-92","globalId":275,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":92,"question":"从政治经济学的角度看，当代资本主义国家中那些掌握了国民经济命脉、财力雄厚、进行跨部门经营、对 社会生活各方面有巨大影响的大财团的资本属于","options":["工业资本？","商业资本？","金融资本？","银行资本"],"answer":2,"answerLetter":"C","explain":"金融资本是由工业垄断资本和银行垄断资本融合在一起而形成的一种垄断资本，掌握国民经济命脉 、进行跨部门经营等是金融资本的典型特征。大财团通常就是金融资本的代表。"},{"id":"marx-3-93","globalId":276,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":93,"question":"人的本质在其现实性上是（ ）。","options":["人的道德品性","人的经济地位","人的价值追求","一切社会关系的总和"],"answer":3,"answerLetter":"D","explain":"马克思指出人的本质不是单个人所固有的抽象物，在其现实性上，它是一切社会关系的总和。这一 观点强调人是处于社会关系网络中的，而非由道德品性、经济地位或价值追求单方面决定。"},{"id":"marx-3-94","globalId":277,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":94,"question":"从现象到本质,从不甚深刻的本质到更深刻的本质,说的是认识的（ ）。","options":["辩证运动","绝对运动","相对运动","辩证否定"],"answer":0,"answerLetter":"A","explain":"认识是一个不断深化的过程，从现象到本质，再到更深刻本质，这体现了认识的辩证发展。认识的 辩证运动包括从实践到认识，再从认识到实践的多次反复和不断发展，这种从浅层次本质到深层次本质的推 进符合认识辩证运动的特点。 绝对运动、相对运动主要侧重于描述物体在空间中的运动状态，与认识的深化 过程无关。 辩证否定强调事物自身的否定、发展和联系环节，与认识从现象到本质这种深化过程的直接关联 性不大。"},{"id":"marx-3-95","globalId":278,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":95,"question":"从作用上看，国家垄断资本主义对国民经济的调节和管理（ ）。","options":["维护了全社会的利益","维护了全体资本家的利益","维护了垄断资产阶级的整体利益","维护了全体私有者的利益"],"answer":2,"answerLetter":"C","explain":"国家垄断资本主义是私人垄断资本和国家政权相结合的垄断资本主义，其目的是为了维护垄断资产 阶级的利益。它不可能维护全社会、全体资本家（非垄断资本家利益难以保障）以及全体私有者利益，主要 是维护垄断资产阶级整体利益。"},{"id":"marx-3-96","globalId":279,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":96,"question":"马克思主义是一个具有内在逻辑联系的科学体系，其中处于核心地位的是（ ）。","options":["辩证唯物主义","历史唯物主义","政治经济学","科学社会主义"],"answer":3,"answerLetter":"D","explain":"马克思主义哲学（辩证唯物主义和历史唯物主义）是科学的世界观和方法论，政治经济学是马克思 主义的具体应用和论证，而科学社会主义是马克思主义的核心，它指明了无产阶级革命的目标和方向，体现 了马克思主义的根本价值和追求。"},{"id":"marx-3-97","globalId":280,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":97,"question":"有的哲学家认为,天地万物都是元气构成的,一切有形物体的生长毁灭都是元气聚散的结果。这是一种（ ）。","options":["朴素唯物主义观点","机械唯物主义观点","主观唯心主义观点","客观唯心主义观点"],"answer":0,"answerLetter":"A","explain":"该哲学家将天地万物归结为具体的物质形态“元气”，这符合古代朴素唯物主义把世界本原归结为 某种或某几种具体物质形态的特点。"},{"id":"marx-3-98","globalId":281,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":98,"question":"从小脱离社会、在狼群中生存的“狼孩”没有意识,这一事实说明（ ）。","options":["意识是生物长期进化的结果","意识是社会的产物","意识是人脑的机能","意识是人脑对客观世界的反映"],"answer":1,"answerLetter":"B","explain":"“狼孩”虽有人脑，但因从小脱离社会而没有意识，这表明意识的产生离不开社会环境，强调了意 识是社会的产物。"},{"id":"marx-3-99","globalId":282,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":99,"question":"单位商品价值量与劳动生产率的关系是（ ）。","options":["二者成正比","二者成反比","二者总按相同比例变化","二者总按不同比例变化"],"answer":1,"answerLetter":"B","explain":"劳动生产率提高，生产单位商品耗费的社会必要劳动时间减少，单位商品价值量降低，所以单位商 品价值量与劳动生产率成反比。"},{"id":"marx-3-100","globalId":283,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":100,"question":"马克思主义哲学认为，人们追求符合客观实际的认识，归根到底是为了？","options":["把握事物现象","揭示事物本质","追求自我实现？","改造客观世界"],"answer":3,"answerLetter":"D","explain":"马克思主义哲学强调认识世界的目的是为了改造世界。把握事物现象和揭示事物本质都属于认识世 界的范畴，而追求自我实现并非马克思主义哲学所强调的认识目的核心。所以归根到底人们追求符合客观实 际的认识是为了改造客观世界。"},{"id":"marx-3-101","globalId":284,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":101,"question":"商品经济成为最普遍的、占统治地位的经济形式的社会形态是（ ）。","options":["原始社会","奴隶社会","封建社会","资本主义社会"],"answer":3,"answerLetter":"D","explain":"在原始社会、奴隶社会、封建社会，自然经济占主导地位，商品经济只是处于从属地位。到了资本 主义社会，商品经济得到充分发展，成为最普遍、占统治地位的经济形式。"},{"id":"marx-3-102","globalId":285,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":102,"question":"有人把个别的、局部的经验当作普遍真理，到处搬用，否认科学理论的指导意义。这在认识论上犯了类 似于（ ）。","options":["唯理论的错误","经验论的错误","唯心主义先验论的错误","直观被动反映论的错误"],"answer":1,"answerLetter":"B","explain":"题干中把个别的、局部经验当作普遍真理，过分夸大经验作用，忽视科学理论，这是经验论的特点 。经验论夸大经验认识作用，贬低理性认识。"},{"id":"marx-3-103","globalId":286,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":103,"question":"有人认为，只有写到书本上的理论才是真实可靠的，因而不顾实际情况，死搬书本上的教条。这在认识 论上犯了（ ）。","options":["类似唯心主义先验论的错误","类似直观被动反映论的错误","类似经验论的错误","类似唯理论的错误"],"answer":3,"answerLetter":"D","explain":"唯理论片面强调理性认识的可靠性，认为只有理性认识是可靠的，而感性认识是不可靠的，不顾实 际情况，死搬书本教条，就是过于相信理性的书本理论，属于类似唯理论的错误。 唯心主义先验论强调认识 先于物质、先于实践经验，题干未体现。直观被动反映论主要是旧唯物主义在认识上的缺陷，强调对事物直 观、被动的反映，与题干不符。经验论则片面强调感性经验的重要性，轻视理性认识，也与题干不符。答案 ：D"},{"id":"marx-3-104","globalId":287,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":104,"question":"当代主要资本主义国家经济发展的新形式和新特征是（ ）。","options":["国家垄断取代私人垄断","私人垄断取代国家垄断","自由竞争取代私人垄断","自由竞争取代国家垄断"],"answer":0,"answerLetter":"A","explain":"在当代，资本主义国家经济发展中，国家对经济的干预和调节不断加强，国家垄断资本主义得到广 泛发展，国家垄断在一定程度上取代私人垄断占据主导地位。所以答案是A 。"},{"id":"marx-3-105","globalId":288,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":105,"question":"当前世界金融危机中,资本主义国家向私人企业注入一部分资金属于（ ）。","options":["建立资本主义国有经济和国有企业的一种方式","国家和私人资本在企业内部结合的一种方式","国家和私人资本在企业外部结合的一种方式","资本主义国家实行经济计划的一种方式"],"answer":1,"answerLetter":"B","explain":"资本主义国家向私人企业注入资金，意味着国家资本和私人资本在企业内部融合，这种形式改变了 企业资本构成。"},{"id":"marx-3-106","globalId":289,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":106,"question":"矛盾的斗争性是指（ ）。","options":["矛盾双方相互依存","矛盾双方相互渗透","矛盾双方相互排斥","矛盾双方在一定条件下相互转化"],"answer":2,"answerLetter":"C","explain":"矛盾的斗争性强调的是矛盾双方相互对立、相互排斥的属性。 选项A“矛盾双方相互依存”和选项 B“矛盾双方相互渗透”体现的是矛盾的同一性中矛盾双方相互联系的方面。 选项D“矛盾双方在一定条件下 相互转化”也是矛盾同一性的表现。"},{"id":"marx-3-107","globalId":290,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":107,"question":"商品资本职能转化为商业资本职能的条件，除了商人有独立的投资外还必须有（ ）。","options":["商业资本家和产业资本家之间的分工","商业资本家和借贷资本家之间的分工","商业资本家和银行资本家之间的分工","商业资本家和商业店员之间的分工"],"answer":0,"answerLetter":"A","explain":"商品资本职能转化为商业资本职能需要两个条件，一是商人有独立投资，二是商业资本家和产业资 本家之间形成分工。产业资本家专注生产，商业资本家专门从事商品买卖。而其他选项中商业资本家与借贷 资本家、银行资本家、商业店员之间的分工并非商品资本职能转化为商业资本职能的必要条件。"},{"id":"marx-3-108","globalId":291,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":108,"question":"在21世纪到来的前夕，英国广播公司（BBC）在全球范围举行过一次“千年思想家”网上评选，结果高居 榜首的是马克思。马克思主义之所以至今仍受到人们的普遍关注，充满生机和活力，是因为（ ）。","options":["它完成了对各种客观事物的认识","它正确反映了社会发展规律并具有与时俱进的理论品质","它是检验人们各种认识是否正确的标准","它对人们的各种实践活动都有具体的指导作用"],"answer":1,"answerLetter":"B","explain":"马克思主义能一直受关注有活力，主要是因为其自身科学性，正确反映社会发展规律，且能与时俱 进适应时代发展。A选项说完成对各种客观事物认识，过于绝对，认识是不断发展的；C选项实践才是检验认 识正确与否的标准，不是马克思主义；D选项马克思主义提供的是一般指导，不是对各种实践活动都有具体指 导。"},{"id":"marx-3-109","globalId":292,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":109,"question":"党的十七大报告指出:“要始终把实现好、维护好、发展好最广大人民的根本利益作为党和国家一切工作 的出发点和落脚点。”这体现了马克思主义政党的（ ）。","options":["阶级性质","组织原则","根本宗旨","政治纲领"],"answer":2,"answerLetter":"C","explain":"马克思主义政党的根本宗旨是全心全意为人民服务，把实现好、维护好、发展好最广大人民的根本 利益作为党和国家一切工作的出发点和落脚点，正是这一根本宗旨的体现。 A选项阶级性质强调政党代表的 阶级属性，题干未突出此方面；B选项组织原则如民主集中制等，题干未涉及；D选项政治纲领是政党为实现 其政治目标而提出的政治主张和行动方案，题干主要强调的是对人民利益的重视，并非政治纲领内容。答案 ：C"},{"id":"marx-3-110","globalId":293,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":110,"question":"在必要劳动时间不变的情况下，将工作日延长所生产出的剩余价值是（ ）。","options":["绝对剩余价值","相对剩余价值","超额剩余价值","平均剩余价值"],"answer":0,"answerLetter":"A","explain":"绝对剩余价值是在必要劳动时间不变的条件下，通过延长工作日从而绝对延长剩余劳动时间所生产 的剩余价值；相对剩余价值是在工作日长度不变时，通过缩短必要劳动时间相对延长剩余劳动时间生产的剩 余价值；超额剩余价值是个别资本家提高劳动生产率，使商品个别价值低于社会价值而多得的那部分剩余价 值。题干说在必要劳动时间不变，延长工作日生产的剩余价值，符合绝对剩余价值定义。"},{"id":"marx-3-111","globalId":294,"part":3,"partName":"第三部分 历史唯物主义与资本主义论","category":"马原专项 · 第三部分 历史唯物主义与资本主义论","num":111,"question":"当代资本主义国家经济关系的一系列新变化表明（ ）。","options":["其社会性质已发生本质改变","其基本矛盾已得到彻底解决","其社会发生了阶段性的部分质变","其社会主要矛盾得到了根本缓解"],"answer":2,"answerLetter":"C","explain":"当代资本主义国家经济关系虽有新变化，但资本主义私有制未变，所以社会性质未发生本质改变 ，基本矛盾也未彻底解决，社会主要矛盾也没有根本缓解。不过，这些新变化确实使资本主义社会在自身范 围内发生了阶段性的部分质变。"},{"id":"marx-4-4","globalId":295,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":4,"question":"矛盾是事物发展的动力，这说明事物发展的根本原因是（ ）。","options":["事物的内部矛盾","事物的特殊矛盾","事物的外部矛盾？","事物的主要矛盾"],"answer":0,"answerLetter":"A","explain":"唯物辩证法认为，事物发展的动力和源泉是矛盾，而推动事物发展的根本原因在于事物的内部矛盾 ，外部矛盾是事物发展的条件，特殊矛盾和主要矛盾并非事物发展根本原因的准确表述。"},{"id":"marx-4-2","globalId":296,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":2,"question":"商业利润的来源是（ ）。","options":["商品流通中的贱买贵卖","商业店员和产业工人创造的剩余价值","产业工人创造的剩余价值","商业店员创造的剩余价值"],"answer":2,"answerLetter":"C","explain":"商业利润本质上是产业工人在生产过程中创造的剩余价值的一部分。商业资本家通过剥削商业店员 的剩余劳动，来实现产业资本家让渡给他们的那部分剩余价值。A选项贱买贵卖只是商业利润实现的途径，并 非来源；商业店员的劳动不创造剩余价值，只是实现剩余价值，所以B、D选项错误。"},{"id":"marx-4-3","globalId":297,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":3,"question":"在必要劳动时间和劳动生产率不变的条件下增加剩余价值生产的方法是（ ）。","options":["绝对剩余价值生产","相对剩余价值生产","超额剩余价值生产","平均剩余价值生产"],"answer":0,"answerLetter":"A","explain":"绝对剩余价值是指在必要劳动时间不变的条件下，通过绝对延长工作日，从而绝对延长剩余劳动时 间来生产出来的剩余价值。题干强调在必要劳动时间和劳动生产率不变条件下增加剩余价值生产，符合绝对 剩余价值生产概念。 相对剩余价值生产是在工作日长度不变时，通过缩短必要劳动时间，相对延长剩余劳动 时间获得，不符合题干“必要劳动时间不变”条件。 超额剩余价值是个别资本家通过提高劳动生产率，使自 己商品的个别价值低于社会价值而比一般资本家多得的那部分剩余价值，与题干条件不符。 不存在“平均剩 余价值生产”这种说法。"},{"id":"marx-4-4","globalId":298,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":4,"question":"地理环境在社会发展中的作用是（ ）。","options":["影响社会结构的划分","影响社会发展的速度","决定社会制度的性质","决定社会形态的更替"],"answer":1,"answerLetter":"B","explain":"地理环境是社会存在和发展的必要条件，能影响社会发展速度，比如良好的地理环境利于生产开展 从而加快发展，恶劣地理环境可能阻碍发展。但它不能决定社会制度性质、社会形态更替，也并非影响社会 结构划分的关键因素。"},{"id":"marx-4-5","globalId":299,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":5,"question":"对立统一规律揭示了（ ）。","options":["事物发展的方向和道路","事物发展的源泉和动力","事物发展的状态和过程","事物发展的趋向和走势"],"answer":1,"answerLetter":"B","explain":"对立统一规律认为矛盾双方既对立又统一推动事物发展，所以它揭示的是事物发展的源泉和动力。 而A选项事物发展的方向和道路是由否定之否定规律揭示；C选项事物发展的状态和过程是质量互变规律揭示 。D选项表述不准确。"},{"id":"marx-4-6","globalId":300,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":6,"question":"矛盾有两个基本属性，一个是同一性，另一个是（ ）。","options":["客观性","普遍性","特殊性","斗争性"],"answer":3,"answerLetter":"D","explain":"矛盾的两个基本属性是同一性和斗争性 。这是哲学中关于矛盾的基本知识点。所以答案选D。"},{"id":"marx-4-7","globalId":301,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":7,"question":"商业资本家对商业店员的剥削主要体现在无偿占有（ ）。","options":["店员销售商品的劳动所创造的全部价值","店员销售商品的劳动所实现的全部价值","店员必要劳动实现的价值","店员剩余劳动实现的剩余价值"],"answer":3,"answerLetter":"D","explain":"商业店员的劳动分为必要劳动和剩余劳动。在必要劳动时间内实现的价值，补偿商业资本家支付给 店员的工资；在剩余劳动时间内实现的剩余价值，被商业资本家无偿占有。商业资本家剥削店员主要是占有 其剩余劳动实现的剩余价值，而不是销售商品劳动创造或实现的全部价值，也不是必要劳动实现的价值。答 案：D"},{"id":"marx-4-8","globalId":302,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":8,"question":"在当前社会主义初级阶段，我国人民的历史使命和共同理想是（ ）。","options":["实现共产主义","建设中国特色社会主义","实现平均分配","实现全人类的彻底解放"],"answer":1,"answerLetter":"B","explain":"在社会主义初级阶段，我国人民的历史使命和共同理想是建设中国特色社会主义。实现共产主义是 最高理想；实现平均分配不符合我国分配政策导向，是不现实的；实现全人类的彻底解放是共产主义远大目 标的内涵之一，但不是社会主义初级阶段的共同理想。"},{"id":"marx-4-9","globalId":303,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":9,"question":"地理环境在社会发展中的作用主要通过（ ）。","options":["对个体心理素质的影响实现","对物质生产的影响实现","对个体生理结构的影响实现","对民族气质的影响实现"],"answer":1,"answerLetter":"B","explain":"地理环境是社会物质生活的必要条件之一，其作用主要是通过对物质生产的影响来实现的，物质生 产是人类社会存在和发展的基础。"},{"id":"marx-4-10","globalId":304,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":10,"question":"第二次世界大战后，新发展起来的国际垄断组织是（ ）。","options":["跨国公司","国际卡特尔","国际辛迪加","国际托拉斯"],"answer":0,"answerLetter":"A","explain":"第二次世界大战后，跨国公司成为新发展起来的国际垄断组织形式。国际卡特尔、国际辛迪加、国 际托拉斯在二战前就已存在且发展，二战后跨国公司迅速发展并成为主要国际垄断组织形式。"},{"id":"marx-4-11","globalId":305,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":11,"question":"对思维与存在的同一性问题的不同回答区分了（ ）。","options":["唯物主义和唯心主义","辩证法和形而上学","可知论和不可知论","反映论和先验论"],"answer":2,"answerLetter":"C","explain":"思维与存在的同一性问题探讨的是思维能否正确认识存在，对这一问题肯定回答的是可知论，否定 回答的是不可知论。A选项唯物主义和唯心主义是对思维和存在何者为第一性的不同回答来区分；B选项辩证 法和形而上学是对世界是怎样存在的不同回答区分；D选项反映论和先验论主要围绕认识的来源等方面区分。 答案：C。"},{"id":"marx-4-12","globalId":306,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":12,"question":"那种主张“天赋的才能”“天生的心灵禀赋”的观点属于（ ）。","options":["唯心主义先验论","旧唯物论的直观反映论","唯物主义反映论","辩证唯物论的能动反映论"],"answer":0,"answerLetter":"A","explain":"题干强调“天赋”“天生”，即认为人的认识和才能是先于实践、先于物质而存在的，这符合唯心 主义先验论的特点，它主张认识来源于人先天的精神。"},{"id":"marx-4-13","globalId":307,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":13,"question":"商业资本所获得的利润相当于（ ）。","options":["平均利润","超额利润","垄断利润","企业利润"],"answer":0,"answerLetter":"A","explain":"商业资本是在流通领域中独立发挥作用的资本形式，商业资本家投资商业，目的是为了获取利润 ，且商业资本作为一种与产业资本并列的独立资本形式，也要获得平均利润，否则商业资本家就会转移资本 。"},{"id":"marx-4-14","globalId":308,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":14,"question":"在对外经济侵略中，最具新殖民主义特点的做法是（ ）。","options":["高价推销工业品和高科技产品","低价收购初级产品和原材料","实行“对外援助”","大量对外输出“过剩资本”"],"answer":2,"answerLetter":"C","explain":"新殖民主义打着“援助”旗号，通过经济、政治等手段控制发展中国家，“对外援助”表面是帮助 ，实际藏有控制目的，是新殖民主义特点做法。而A、B选项是传统殖民主义在贸易方面手段，D选项大量对外 输出“过剩资本”是垄断资本主义经济特征之一，但不是最具新殖民主义特点做法。"},{"id":"marx-4-15","globalId":309,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":15,"question":"第二次世界大战后，主要资本主义国家的经济发展进入到（ ）。","options":["自由竞争资本主义阶段","垄断竞争资本主义阶段","私人垄断资本主义阶段","国家垄断资本主义阶段"],"answer":3,"answerLetter":"D","explain":"第二次世界大战后，由于新科技革命等因素，资本主义国家对经济生活进行全面干预和调节，使国 家垄断资本主义得到迅速发展并在经济生活中占据主导地位。"},{"id":"marx-4-16","globalId":310,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":16,"question":"对外国文化要有分析、有选择、有批判地借鉴和吸收,这种态度体现的哲学道理是（ ）。","options":["对立统一的原理","辩证否定的原理","内容和形式关系的原理","原因和结果关系的原理四"],"answer":1,"answerLetter":"B","explain":"辩证否定观强调事物的否定是自身的否定，是事物发展和联系的环节，实质是“扬弃”，即既克服 又保留。对外国文化有分析、有选择、有批判地借鉴和吸收，就是取其精华、去其糟粕，这符合辩证否定观 的要求。而对立统一原理强调矛盾双方的相互对立与统一；内容和形式关系原理侧重于内容决定形式等方面 ；原因和结果关系原理关注因果联系。均与题干对外国文化的态度不符。"},{"id":"marx-4-17","globalId":311,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":17,"question":"能动反映论区别于机械反映论的根本标志是（ ）。","options":["肯定思维能正确地反映存在","认为认识过程是纯粹的观念创造","肯定思维对存在的决定作用","认为认识过程是反映和创造的统一"],"answer":3,"answerLetter":"D","explain":"能动反映论强调认识过程不仅是对客观世界的简单摹写，更是一种创造性的活动，把实践引入认识 论，认识过程是反映和创造的统一。 机械反映论把认识看成是照镜子式的、直观被动的反映，忽视了人的主 观能动性。能动反映论与机械反映论的根本区别就在于是否承认认识过程是反映和创造的统一。"},{"id":"marx-4-18","globalId":312,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":18,"question":"第一次工业革命时期，英美等主要资本主义国家处于","options":["自由竞争资本主义阶段？","私人垄断资本主义阶段","一般垄断资本主义阶段？","国家垄断资本主义阶段"],"answer":0,"answerLetter":"A","explain":"第一次工业革命时期，资本主义生产力迅速发展，在经济运行中强调自由竞争、自由贸易等原则 ，此时处于自由竞争资本主义阶段。 私人垄断资本主义阶段、一般垄断资本主义阶段（一般垄断即私人垄断 ）是在19世纪末20世纪初第二次工业革命后逐渐形成的。 国家垄断资本主义阶段是在20世纪30年代后，特别 是二战后得到广泛发展。"},{"id":"marx-4-19","globalId":313,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":19,"question":"对物质和意识哪个是第一性问题的不同回答，形成了哲学上的两大基本派别。这两大基本派别是（ ）。","options":["唯物主义和唯心主义","辩证法和形而上学","一元论和二元论","可知论和不可知论"],"answer":0,"answerLetter":"A","explain":"哲学的基本问题是思维和存在的关系问题，也就是意识和物质的关系问题。对物质和意识哪个是第 一性问题的不同回答，划分出唯物主义（认为物质第一性）和唯心主义（认为意识第一性）两大基本派别 。"},{"id":"marx-4-20","globalId":314,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":20,"question":"能够划分为固定资产和流动资本形态的是（ ）。","options":["流通资本","商品资本","货币资本","生产资本"],"answer":3,"answerLetter":"D","explain":"只有生产资本能依据价值周转方式不同，划分为固定资本和流动资本。流通资本是处于流通领域的 资本，商品资本、货币资本属于流通资本，它们都不能进行这样的划分。"},{"id":"marx-4-21","globalId":315,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":21,"question":"商业资本执行的是（ ）。","options":["产业资本中商品资本的职能","产业资本中货币资本的职能","产业资本中生产资本的职能","产业资本中流通资本的职能"],"answer":0,"answerLetter":"A","explain":"商业资本是从产业资本中分离出来，专门从事商品买卖，独立发挥资本职能，以获取商业利润为目 的的一种资本形式。它执行的是产业资本循环中商品资本的职能，通过销售商品实现价值和剩余价值。答案 选A。"},{"id":"marx-4-22","globalId":316,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":22,"question":"在国际共产主义运动史上,第一个无产阶级政党是（ ）。","options":["共产主义者间盟","德国社会民主工党","中国共产党","俄国社会民主工党"],"answer":0,"answerLetter":"A","explain":"共产主义者同盟是世界上第一个无产阶级政党，1847 年 6 月在伦敦成立。德国社会民主工党成立 于 1869 年；中国共产党成立于 1921 年；俄国社会民主工党成立于 1898 年 ，均晚于共产主义者同盟。答 案：A"},{"id":"marx-4-23","globalId":317,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":23,"question":"年利润率的计算公式是（ ）。","options":["年利润量／年预付可变资本","年利润量／年预付不变资本","年剩余价值量／年预付可变资本","年剩余价值量／年预付总资本"],"answer":3,"answerLetter":"D","explain":"年利润率是年剩余价值量与年预付总资本的比率。年利润量本质上就是年剩余价值量，年利润率反 映预付总资本的增值程度。选项A是年剩余价值率的一种形式（年剩余价值量与年预付可变资本的比率 ），B选项计算无意义，C是年剩余价值率。只有D符合年利润率公式。"},{"id":"marx-4-24","globalId":318,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":24,"question":"商业资本执行的是产业资本中（ ）。","options":["货币资本的职能","生产资本的职能","流通资本的职能","商品资本的职能"],"answer":3,"answerLetter":"D","explain":"商业资本是从产业资本中分离出来，专门从事商品买卖，独立发挥资本职能，以获取商业利润为目 的的一种资本形式。它执行的是产业资本循环中商品资本的职能，即销售商品，实现价值和剩余价值。答案 选D。"},{"id":"marx-4-25","globalId":319,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":25,"question":"在国家垄断资本主义阶段之前，资本主义处于（ ）。","options":["自由竞争资本主义阶段","私人垄断资本主义阶段","垄断竞争资本主义阶段","金融垄断资本主义阶段"],"answer":1,"answerLetter":"B","explain":"资本主义发展经历了自由竞争资本主义和垄断资本主义两个阶段，垄断资本主义又分为私人垄断资 本主义和国家垄断资本主义。所以在国家垄断资本主义阶段之前是私人垄断资本主义阶段。"},{"id":"marx-4-26","globalId":320,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":26,"question":"否定之否定规律揭示了（ ）。","options":["事物的发展是必然性和偶然性的统一","事物的发展是量变和质变的统一","事物的发展是前进性和曲折性的统一","矛盾是事物发展的动力和源泉"],"answer":2,"answerLetter":"C","explain":"否定之否定规律表明，事物发展的方向是前进的，因为每一次否定都是对旧事物的扬弃，推动事物 向更高阶段发展；而发展的道路是曲折的，会经历肯定 - 否定 - 否定之否定的过程，不是直线上升的。 A选项事物发展是必然性和偶然性的统一，主要涉及唯物辩证法的范畴，与否定之否定规律无关。 B选项量变 和质变的统一是质量互变规律的内容。 D选项矛盾是事物发展的动力和源泉是对立统一规律的内容。"},{"id":"marx-4-27","globalId":321,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":27,"question":"根据邓小平的概括，下列选项不属于社会主义本质的是（ ）。","options":["解放生产力，发展生产力","消灭剥削，消除两极分化","允许个别人先富起来","最终达到共同富裕"],"answer":2,"answerLetter":"C","explain":"社会主义本质是解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕。“允许 个别人先富起来”是实现共同富裕的一种途径和手段，并非社会主义本质内容。"},{"id":"marx-4-28","globalId":322,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":28,"question":"年剩余价值率是（ ）。","options":["剩余价值与可变资本之比","剩余价值与不变资本之比","一年内剩余价值总量与一年预付可变资本之比","一年内剩余价值总量与一年预付总资本之比"],"answer":2,"answerLetter":"C","explain":"年剩余价值率是衡量一年内预付可变资本的增殖程度，是一年内剩余价值总量与一年预付可变资本 之比。A选项是剩余价值率的概念；B选项无对应经济概念；D选项是年利润率概念。"},{"id":"marx-4-29","globalId":323,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":29,"question":"改革不仅存在于社会主义社会中，而且存在于其他社会形态中。这说明改革具有","options":["主体能动性","历史局限性","普遍性","特殊性"],"answer":2,"answerLetter":"C","explain":"题干强调改革在多种社会形态中都存在，体现的是改革普遍存在于不同社会形态，即改革具有普遍 性。"},{"id":"marx-4-30","globalId":324,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":30,"question":"根据价值周转方式的不同，资本家的生产资本可以划分为（ ）。","options":["不变资本和可变资本","固定资本和流动资本","商品资本和流通资本","个别资本和社会资本"],"answer":1,"answerLetter":"B","explain":"生产资本根据价值周转方式不同分为固定资本和流动资本。固定资本价值逐步转移，流动资本价值 一次性转移。A选项不变资本和可变资本是按在剩余价值生产中作用不同划分；C选项商品资本是产业资本循 环阶段之一，流通资本概念不准确；D选项个别资本和社会资本是从资本运动角度划分。"},{"id":"marx-4-31","globalId":325,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":31,"question":"农产品的社会生产价格由（ ）。","options":["优等地的生产条件决定","中等地的生产条件决定","劣等地的生产条件决定","各类土地的平均生产条件决定"],"answer":2,"answerLetter":"C","explain":"因为如果农产品社会生产价格由优等地或中等地生产条件决定，劣等地就会退出生产，农产品产量 就会减少，价格上升，所以农产品社会生产价格只能由劣等地生产条件决定，这样才能保证劣等地也投入生 产，满足社会对农产品的需求。"},{"id":"marx-4-32","globalId":326,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":32,"question":"上世纪下半叶，从第二次世界大战结束后到冷战结束前，西方主要发达资本主义国家处于","options":["自由竞争资本主义阶段","私人垄断资本主义阶段","国家垄断资本主义","国家垄断资本主义阶段"],"answer":3,"answerLetter":"D","explain":"【标准答案：D】"},{"id":"marx-4-33","globalId":327,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":33,"question":"在经济危机和萧条阶段，资本主义国家向私人企业注入一部分国有资金以维持其生存的经济行为属于","options":["建立资本主义国有经济和国有企业的一种方式","国家和私人资本在企业内部结合的一种方式","国家和私人资本在企业外部结合的一种方式","资本主义国家实行经济计划的一种方式"],"answer":1,"answerLetter":"B","explain":"国家向私人企业注入国有资金，这意味着国有资本与私人资本在企业内部实现了融合。"},{"id":"marx-4-34","globalId":328,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":34,"question":"概念、判断、推理是（ ）。","options":["理性认识的三种形式","感性认识的三种形式","社会心理的三种形式","意识形态的三种形式"],"answer":0,"answerLetter":"A","explain":"理性认识是认识的高级阶段，包括概念、判断、推理三种形式。感性认识的三种形式是感觉、知觉 和表象。社会心理和意识形态与概念、判断、推理不属于对应关系。"},{"id":"marx-4-35","globalId":329,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":35,"question":"根据社会意识反映社会存在的程度和特点，可以把社会意识划分为（ ）。","options":["个体意识和群体意识","意识形态和非意识形态","先进意识和落后意识","社会心理和思想体系"],"answer":3,"answerLetter":"D","explain":"社会意识从反映社会存在的程度和特点看，分为社会心理和思想体系。社会心理是低层次、不系统 、不定型的社会意识；思想体系是高层次、系统化、理论化的社会意识。A选项是从主体角度划分；B选项是 从与经济基础关系角度划分；C选项并非按照反映社会存在程度和特点划分。"},{"id":"marx-4-36","globalId":330,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":36,"question":"农业资本家所获得的剩余价值是（ ）。","options":["级差地租","绝对地租","垄断地租","平均利润"],"answer":3,"answerLetter":"D","explain":"农业资本家投资农业，其目的和工业资本家等一样，是为了获取平均利润。农业工人创造的剩余价 值，一部分以地租形式缴纳给土地所有者，另一部分就是农业资本家获得的平均利润。"},{"id":"marx-4-37","globalId":331,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":37,"question":"设想没有物质的运动的观点是（ ）。","options":["朴素唯物主义","机械唯物主义","不可知论","唯心主义"],"answer":3,"answerLetter":"D","explain":"物质和运动是不可分割的，物质是运动的载体，运动是物质的根本属性和存在方式。 设想没有物 质的运动，那就把运动看作是脱离物质的独立存在，这实际上是将精神、意识等非物质的东西当作运动的主 体，属于唯心主义观点。"},{"id":"marx-4-38","globalId":332,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":38,"question":"在劳动资料这一复杂系统中，最能标志生产力发展水平的是（ ）。","options":["运输设备","传动装置","动力系统","生产工具"],"answer":3,"answerLetter":"D","explain":"生产工具是劳动资料中最主要、最具有决定意义的因素，它直接体现了人们改造自然的深度和广度 ，是衡量生产力发展水平的客观尺度。而运输设备、传动装置、动力系统虽也是劳动资料组成部分，但相比 之下，生产工具对生产力发展水平的标志作用更为突出。"},{"id":"marx-4-39","globalId":333,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":39,"question":"感性认识的三种形式是（ ）。","options":["感觉、概念、判断","概念、判断、推理","感觉、知觉、表象","感觉、知觉、推理"],"answer":2,"answerLetter":"C","explain":"感性认识是认识的初级阶段，它是人们通过感官获得的关于事物的现象、外部联系的认识，其三种 形式为感觉、知觉和表象。A选项中概念属于理性认识；B选项概念、判断、推理均是理性认识形式；D选项推 理属于理性认识。所以答案选C。"},{"id":"marx-4-40","globalId":334,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":40,"question":"根据是否承认世界的统一性,可以把哲学派别划分为（ ）。","options":["唯物论和唯心论","一元论和二元论","可知论和不可知论","辦证法和形而上学"],"answer":1,"answerLetter":"B","explain":"对世界统一性问题的不同回答区分出一元论和二元论。一元论承认世界有一个统一的本原，二元论 则认为世界有两个相互独立的本原。 A选项唯物论和唯心论是根据对物质和意识何者为第一性的回答划分的 。 C选项可知论和不可知论是根据对思维和存在是否具有同一性的回答划分的。 D选项辩证法和形而上学是 对世界是怎样存在的不同回答，辩证法用联系、发展、全面的观点看问题，形而上学用孤立、静止、片面的 观点看问题。"},{"id":"marx-4-41","globalId":335,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":41,"question":"农业资本家在同一块土地上连续追加投资,使劳动生产率提高所获得的剩余价值属于（ ）。","options":["级差地租I","级差地租Ⅱ","绝对地租","垄断利润"],"answer":1,"answerLetter":"B","explain":"级差地租Ⅱ是由于在同一块土地上连续追加投资的劳动生产率不同而形成的级差地租。题干中农业 资本家在同一块土地连续追加投资提高劳动生产率获得的剩余价值符合级差地租Ⅱ的概念。"},{"id":"marx-4-42","globalId":336,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":42,"question":"共产主义社会的两个阶段是指（ ）。","options":["社会主义社会和共产主义社会","过渡阶段和社会主义社会","社会主义初级阶段和高级阶段","共产主义社会初级阶段和高级阶段分"],"answer":0,"answerLetter":"A","explain":"马克思把共产主义社会划分为第一阶段和高级阶段，列宁把共产主义社会第一阶段称为社会主义社 会 ，所以共产主义社会两个阶段指社会主义社会和共产主义社会（这里共产主义社会指的是共产主义社会高 级阶段）。"},{"id":"marx-4-43","globalId":337,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":43,"question":"构成商品价格基础的是（ ）。","options":["使用价值","价值","商品供给","商品需求"],"answer":1,"answerLetter":"B","explain":"价值决定价格，价格是价值的货币表现，所以构成商品价格基础的是价值。而使用价值是商品能满 足人们某种需要的属性，与价格基础无关；商品供给和需求影响价格，但不是价格基础。"},{"id":"marx-4-44","globalId":338,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":44,"question":"货币转化为资本的前提是（ ）。","options":["货币在运动中发生了价值增值","货币投入流通带来剩余价值","货币所有者购买到劳动力商品","货币可以购买到生产资料"],"answer":2,"answerLetter":"C","explain":"劳动力商品具有能创造比自身价值更大价值的特点，货币所有者购买到劳动力商品，才可能实现价 值增值，从而使货币转化为资本。"},{"id":"marx-4-45","globalId":339,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":45,"question":"认识的主体和客体之间最基础性的关系是（ ）。","options":["认识关系","实践关系","相互依存的关系","相互作用的关系"],"answer":1,"answerLetter":"B","explain":"实践是认识的基础，认识的主体和客体之间首先是改造与被改造的实践关系，这是最基础性的关系 ，其他关系都基于此。"},{"id":"marx-4-46","globalId":340,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":46,"question":"社会改革和社会革命都根源于（ ）。","options":["生产力和生产关系的矛盾","社会存在和社会意识的矛盾","人口增长和资源匮乏的矛盾","创新意识和传统观念的矛盾"],"answer":0,"answerLetter":"A","explain":"生产力和生产关系的矛盾是社会基本矛盾，是社会发展的根本动力，社会改革与社会革命都是为了 解决这一矛盾，推动社会发展。社会存在和社会意识的矛盾虽也是社会基本矛盾，但不是社会改革和革命根 源；人口增长和资源匮乏、创新意识和传统观念的矛盾不属于社会基本矛盾，不是社会改革和革命根源。答 案：A"},{"id":"marx-4-47","globalId":341,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":47,"question":"在马克思主义理论体系中，科学社会主义是其（ ）。","options":["理论基础","核心内容","指导原则","前提条件"],"answer":1,"answerLetter":"B","explain":"马克思主义主要包括马克思主义哲学、马克思主义政治经济学和科学社会主义三大部分。马克思主 义哲学是理论基础，马克思主义政治经济学是运用马克思主义哲学对资本主义的理论剖析，科学社会主义则 是在两者基础上得出的关于未来社会的构想，是核心内容，指明了奋斗目标和发展方向。所以答案是B。"},{"id":"marx-4-48","globalId":342,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":48,"question":"集中体现着共产主义社会主要特征和本质要求的原则标志是（ ）。","options":["各尽所能，按需分配","各尽所能，按才能分配","各尽所能，按劳分配","各尽所能，按地位分配"],"answer":0,"answerLetter":"A","explain":"“各尽所能、按需分配”不只是一个个人消费品分配方式，而是一个集中体现着共产主义社会主要 特征和本质要求的原则标志。按劳分配是社会主义社会分配方式，按才能、按地位分配不符合共产主义理念 。答案：A 。"},{"id":"marx-4-49","globalId":343,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":49,"question":"认识事物的最根本方法是（ ）。","options":["普遍联系法","阶级分析法","矛盾分析法","具体分析法"],"answer":2,"answerLetter":"C","explain":"矛盾是事物发展的源泉和动力，矛盾分析法是认识事物最根本的方法，它能帮助我们从本质上认识 事物及事物间的关系。A选项普遍联系法强调事物相互联系；B选项阶级分析法主要用于分析阶级社会中的现 象；D选项具体分析法侧重于具体问题具体对待，但都不如矛盾分析法根本。"},{"id":"marx-4-50","globalId":344,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":50,"question":"社会革命的基本形式是（ ）。","options":["和平发展","暴力革命","渐进改革","文化宣传"],"answer":1,"answerLetter":"B","explain":"社会革命是阶级斗争的最高表现，暴力革命是社会革命的基本形式。因为统治阶级不会自动退出历 史舞台，只有通过暴力革命，才能推翻反动统治阶级，实现社会形态的根本变革。和平发展、渐进改革多属 于社会改良，不能从根本上改变社会制度。文化宣传是革命的辅助手段，并非基本形式。"},{"id":"marx-4-51","globalId":345,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":51,"question":"古希腊哲学家克拉底鲁否认相对静止的存在,认为世界万物像一阵旋风,瞬息万变,不可捉摸。这是一种 （ ）。","options":["相对主义诡辩论观点","形而上学观点","唯物辩证法观点","庸俗唯物主义观点"],"answer":0,"answerLetter":"A","explain":"克拉底鲁否认相对静止，只承认绝对运动，这使得事物失去了质的稳定性和确定性，陷入了只强调 运动的相对性而忽视相对静止的错误，这正是相对主义诡辩论的特征。形而上学是用孤立、静止、片面的观 点看问题；唯物辩证法坚持联系、发展、全面，承认绝对运动和相对静止统一；庸俗唯物主义把意识直接归 结为物质，与题干描述不符。答案：A.相对主义诡辩论观点"},{"id":"marx-4-52","globalId":346,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":52,"question":"既承认历史发展的决定性又承认历史发展的选择性，这属于","options":["历史唯物论观点","相对主义观点","历史循环论观点","折衷主义观点"],"answer":0,"answerLetter":"A","explain":"历史唯物论认为社会历史发展具有客观规律性（即决定性），同时在一定程度上人的主体选择性也 发挥作用。 相对主义夸大事物和认识的相对性，否定确定性和客观性。 历史循环论把历史看成周而复始的 循环运动，否定社会进步。 折衷主义是把各种不同的观点无原则地拼凑在一起。答案：A 。既承认历史发展 决定性又承认选择性，符合历史唯物论观点。"},{"id":"marx-4-53","globalId":347,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":53,"question":"认识是主体对客体的能动反映。这是一种（ ）。","options":["辩证唯物主义认识论观点","机械唯物主义认识论观点","主观唯心主义认识论观点","客观唯心主义认识论观点"],"answer":0,"answerLetter":"A","explain":"辩证唯物主义认识论认为认识是主体对客体的能动反映。它强调认识过程中主体的能动性以及认识 与实践的辩证关系。 机械唯物主义认识论把认识看成是直观的、消极被动的反映，不承认主体的能动作用。 主观唯心主义认识论把认识看作是主观自生的，是心灵的自由创造物。 客观唯心主义认识论把认识看作是来 自“客观精神”的启示或赋予。"},{"id":"marx-4-54","globalId":348,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":54,"question":"在平均利润形成以前，资本有机构成高的部门，它的利润率一般（ ）。","options":["高于社会平均水平","低于社会平均水平","等于社会平均水平","等于其剩余价值率"],"answer":1,"answerLetter":"B","explain":"资本有机构成高意味着在该部门总资本中，不变资本所占比重较大，可变资本所占比重较小。在剩 余价值率相同的条件下，可变资本是剩余价值的源泉，可变资本占比小，该部门创造的剩余价值相对较少 ，进而利润率相对较低。而平均利润形成前，资本有机构成高的部门利润率一般低于社会平均水平。"},{"id":"marx-4-55","globalId":349,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":55,"question":"关于马克思主义的产生，下列说法错误的是（ ）。","options":["马克思主义是历史时代的产物","马克思主义是实践经验的总结","马克思主义是科学成果的升华","马克思主义是先天智慧的结晶"],"answer":3,"answerLetter":"D","explain":"马克思主义是在特定历史时代背景下，基于实践经验总结以及对当时科学成果升华而产生的，并非 先天智慧结晶，它是在社会发展和人类实践过程中形成的。"},{"id":"marx-4-56","globalId":350,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":56,"question":"既承认社会形态发展的客观规律又承认人的自觉活动的作用,这种观点属于（ ）。","options":["历史唯物论观点","唯意志论观点","折衷主义观点","机械决定论观点"],"answer":0,"answerLetter":"A","explain":"历史唯物论既强调社会形态发展是有客观规律的，这是不以人的意志为转移的，同时也承认人的自 觉活动对社会发展有能动作用。 唯意志论片面夸大了人的意志的作用，否定社会发展的客观规律。 折衷主 义是把各种不同的观点无原则地拼凑在一起。 机械决定论只承认客观规律性，否认人的自觉能动性。答案 ：A"},{"id":"marx-4-57","globalId":351,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":57,"question":"认识主体具有的突出特点是（ ）。","options":["能动性","被动性","消极性","积极性"],"answer":0,"answerLetter":"A","explain":"认识主体是指处于一定社会关系中从事实践活动和认识活动的人，人在认识过程中不是被动、消极 地反映对象，而是积极主动地去认识和改造世界，能动性是认识主体突出特点。"},{"id":"marx-4-58","globalId":352,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":58,"question":"社会主义根本的和首要的任务是（ ）。","options":["解放和发展生产力","加强无产阶级专政","巩固共产党的领导","镇压资产阶级的反抗"],"answer":0,"answerLetter":"A","explain":"社会主义的根本任务是解放和发展生产力，这是由社会主义的本质决定的，只有解放和发展生产力 ，才能提高人民生活水平，体现社会主义制度优越性等。而其他选项如加强无产阶级专政、巩固共产党领导 并非首要和根本任务，镇压资产阶级反抗不符合社会主义发展阶段特点。"},{"id":"marx-4-59","globalId":353,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":59,"question":"在前苏联推行所谓“社会主义苏联模式”的领导人是（ ）。","options":["列宁","斯大林","布哈林","托洛斯基"],"answer":1,"answerLetter":"B","explain":"“社会主义苏联模式”指苏联在斯大林领导下，按照斯大林的规划所确立起来的国家政治经济体制 。列宁时期是苏俄探索社会主义建设道路阶段，尚未形成该模式。布哈林、托洛斯基并非推行“社会主义苏 联模式”的领导人。答案选B。"},{"id":"marx-4-60","globalId":354,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":60,"question":"关于社会分工的产生，下列表述中正确的是（ ）。","options":["社会分工是私有制的产物","社会分工是商品经济的产物","社会分工是资本主义的产物","社会分工是生产力发展的产物"],"answer":3,"answerLetter":"D","explain":"生产力的发展促使人们的生产活动专业化，从而产生了社会分工。私有制、商品经济、资本主义都 是在社会分工之后，在一定条件下出现的，它们不是社会分工产生的原因。所以社会分工是生产力发展的产 物。"},{"id":"marx-4-61","globalId":355,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":61,"question":"既坚持历史决定论又承认主体选择的作用，这属于（ ）。","options":["历史唯物论观点","相对主义观点","诡辩论观点","折衷主义观点"],"answer":0,"answerLetter":"A","explain":"历史唯物论认为社会历史发展有其客观规律性，同时也承认人的主体选择性。主体选择性是在遵循 历史发展规律基础上的选择。相对主义、诡辩论、折衷主义都不能正确处理历史决定论与主体选择的关系。 相对主义否定事物的确定性和稳定性；诡辩论以虚假论据、欺诈的方式进行似是而非的论证；折衷主义把各 种不同观点无原则地拼凑在一起。所以既坚持历史决定论又承认主体选择作用属于历史唯物论观点。"},{"id":"marx-4-62","globalId":356,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":62,"question":"认识主体与认识客体之间最基本的关系是（ ）。","options":["改造与被改造的关系","相互依存的关系","反映与被反映的关系","相互作用的关系"],"answer":0,"answerLetter":"A","explain":"认识主体与认识客体多种关系中，实践关系即改造与被改造关系是最基本的，因为认识是在实践基 础上发生的，只有通过改造世界才能更好地认识世界。"},{"id":"marx-4-63","globalId":357,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":63,"question":"关于社会主义民主，下列不正确的选项是（ ）。","options":["人类社会最高类型的民主","绝大多数人的民主","人民群众完全自由","人民群众当家作主"],"answer":2,"answerLetter":"C","explain":"社会主义民主是人类社会最高类型的民主，是绝大多数人的民主，本质是人民群众当家作主。而 “人民群众完全自由”这种说法错误，自由是相对的，要在法律等规范内享有自由，不存在完全不受限制的 自由。"},{"id":"marx-4-64","globalId":358,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":64,"question":"在社会发展中起决定作用的是（ ）。","options":["人和自然的矛盾","剥削阶级和被剥削阶级的矛盾","先进思想和落后思想的矛盾","生产力和生产关系的矛盾"],"answer":3,"answerLetter":"D","explain":"生产力和生产关系的矛盾是人类社会基本矛盾之一，生产力决定生产关系，生产关系反作用于生产 力，这一矛盾运动推动着人类社会从低级向高级发展，在社会发展中起决定作用。A选项人和自然的矛盾并非 对社会发展起决定作用；B选项剥削阶级和被剥削阶级的矛盾是特定社会阶段的矛盾，不是根本决定因素 ；C选项先进思想和落后思想的矛盾属于社会意识层面的矛盾，不起决定作用。"},{"id":"marx-4-65","globalId":359,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":65,"question":"黑格尔、费尔巴哈是（ ）。","options":["德国古典哲学的代表人物","英国古典政治经济学的代表人物","英国空想社会主义的代表人物","法国空想社会主义的代表人物"],"answer":0,"answerLetter":"A","explain":"黑格尔和费尔巴哈是德国哲学家，在德国古典哲学发展中有重要地位。德国古典哲学是马克思主义 的理论来源之一。而英国古典政治经济学代表人物如亚当·斯密等，英国、法国空想社会主义代表人物分别 有欧文、圣西门、傅立叶等。"},{"id":"marx-4-66","globalId":360,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":66,"question":"商品的使用价值反映的是（ ）。","options":["人与人的关系","人与自然的关系","生产关系","交换关系"],"answer":1,"answerLetter":"B","explain":"使用价值是商品能满足人们某种需要的属性，即商品的有用性。它是商品的自然属性，体现的是人 与自然的关系。比如粮食能充饥，这种满足人对食物需求的属性，是基于粮食本身的自然特质，和自然条件 相关，而非人与人之间的社会关系等。"},{"id":"marx-4-67","globalId":361,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":67,"question":"实现意识能动作用的根本途径是（ ）。","options":["学习科学理论","投身社会实践","了解实际情况","制定周密计划"],"answer":1,"answerLetter":"B","explain":"意识能动作用的实现必须通过人们的实践活动，实践是连接主观与客观的桥梁，只有投身社会实践 ，才能将意识转化为现实。而学习科学理论、了解实际情况、制定周密计划都只是为实践做准备，本身不能 直接实现意识能动作用。"},{"id":"marx-4-68","globalId":362,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":68,"question":"在社会主义思想史上，标志着科学社会主义理论公开面世的第一个纲领性文件是（ ）。","options":["《共产党宣言》","《法兰西内战》","《社会主义从空想到科学的发展》","《哥达纲领批判》"],"answer":0,"answerLetter":"A","explain":"《共产党宣言》是科学社会主义理论公开面世的第一个纲领性文件，它系统阐述了科学社会主义基 本原理，为无产阶级革命提供了理论指导。"},{"id":"marx-4-69","globalId":363,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":69,"question":"坚持马克思主义哲学的认识路线，就必须在工作中坚持","options":["一切从实际出发","—切从主观的愿望出发","一切从理论出发","—切从臆造的规律出发"],"answer":0,"answerLetter":"A","explain":"马克思主义哲学认识路线强调物质第一性，意识第二性，认识是对客观世界的反映。所以要从客观 实际出发。而B从主观愿望、C从理论、D从臆造规律出发，都违背了从客观实际出发的要求。"},{"id":"marx-4-70","globalId":364,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":70,"question":"商品价值的实体是（ ）。","options":["使用价值","交换价值","具体劳动","抽象劳动"],"answer":3,"answerLetter":"D","explain":"商品价值是凝结在商品中的无差别的一般人类劳动，即抽象劳动。具体劳动形成商品的使用价值 ，交换价值是价值的表现形式，使用价值是商品能满足人们某种需要的属性。所以商品价值的实体是抽象劳 动。"},{"id":"marx-4-71","globalId":365,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":71,"question":"20世纪后半期垄断组织发展的新形式是（ ）。","options":["辛迪加","卡特尔","托拉斯","混合联合"],"answer":3,"answerLetter":"D","explain":"20世纪后半期，垄断组织在形式上有了新发展，混合联合公司成为主要形式。而辛迪加、卡特尔、 托拉斯是垄断组织较早期的形式。"},{"id":"marx-4-72","globalId":366,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":72,"question":"在生产力和生产关系这对矛盾中（ ）。","options":["生产力的性质决定生产关系的性质","生产力的变化落后于生产关系的变化","生产关系总是适应生产力的发展水平","生产关系可以超越生产力的发展水平"],"answer":0,"answerLetter":"A","explain":"生产力决定生产关系，生产力的性质决定生产关系的性质 ，有什么样的生产力就有什么样的生产关 系与之相适应。生产关系会适应生产力，但并非总是适应，生产关系变化滞后于生产力变化，且不能超越生 产力发展水平。所以A正确。"},{"id":"marx-4-73","globalId":367,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":73,"question":"货币转化为资本的决定性条件是，货币的所有者在流通中购买到（ ）。","options":["劳动工具","劳动力","劳动场所","劳动对象"],"answer":1,"answerLetter":"B","explain":"货币转化为资本的关键在于能够带来剩余价值。劳动力商品具有独特的使用价值，它在使用过程中 不仅能创造出自身价值，还能创造出比自身价值更大的价值，即剩余价值。而劳动工具、劳动场所、劳动对 象只是生产过程中的物质要素，本身不能使货币转化为资本。"},{"id":"marx-4-74","globalId":368,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":74,"question":"检验认识的真理性，就是要检验人们的认识是否（ ）。","options":["与多数人的愿望和要求相符合","与已被实践证明的理论相符合","与客观事物及其规律相符合","与党的路线方针政策相符合"],"answer":2,"answerLetter":"C","explain":"真理是人们对客观事物及其规律的正确反映，检验认识的真理性，就是看认识是否与客观事物及其 规律相符合。多数人的愿望、已有的理论、党的路线方针政策都不能作为检验真理的标准，只有实践才能检 验认识是否符合客观事物及其规律。"},{"id":"marx-4-75","globalId":369,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":75,"question":"商品交换中价值与价格的关系表现为（ ）。","options":["价格总是高于价值","价格总是低于价值","价格总是等于价值","价格总是围绕价值上下波动"],"answer":3,"answerLetter":"D","explain":"价值是凝结在商品中的无差别的人类劳动，价格是价值的货币表现。在商品交换中，受供求关系等 因素影响，价格与价值并非总是相等。 当供大于求时，价格会低于价值；当供小于求时，价格会高于价值。 但从长期和总体来看，价格围绕价值上下波动，这是价值规律的表现形式。"},{"id":"marx-4-76","globalId":370,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":76,"question":"世界观是（ ）。","options":["人们对整个世界的根本看法和观点","人们对精神世界的根本看法和观点","人们对物质世界的根本看法和观点","人们对外部世界的根本看法和观点"],"answer":0,"answerLetter":"A","explain":"世界观是人们对整个世界以及人与世界关系的总的看法和根本观点，这里的世界既包括物质世界也 包括精神世界等，是整体的世界概念。答案选A 。"},{"id":"marx-4-77","globalId":371,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":77,"question":"劳动力的价值决定有一个重要特点,即（ ）。","options":["它由其生产的剩余价值决定","它由其使用价值决定","它包含历史和道德因素","它包含习惯和法律因素"],"answer":2,"answerLetter":"C","explain":"劳动力价值包括维持劳动者自身生存、养活家属及劳动者接受教育和训练所支出的费用。不同国家 或同一国家不同时期，因社会经济文化条件等不同，这些费用存在差异，所以劳动力价值包含历史和道德因 素。A选项，劳动力价值不是由剩余价值决定；B选项，使用价值不能决定劳动力价值；D选项习惯和法律因素 不是劳动力价值决定的重要特点。"},{"id":"marx-4-78","globalId":372,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":78,"question":"社会历史发展的动力有多种，但最基本的动力是（ ）。","options":["阶级斗争","社会改革","科学技术革命","社会基本矛盾"],"answer":3,"answerLetter":"D","explain":"社会基本矛盾（生产力和生产关系、经济基础和上层建筑的矛盾）贯穿于人类社会发展过程的始终 ，并规定了社会发展过程中各种社会形态、社会制度的基本性质，是推动社会发展的最基本动力。阶级斗争 是阶级社会发展的直接动力；社会改革是推动社会发展的又一重要动力；科学技术革命是推动经济和社会发 展的强大杠杆。答案选D。"},{"id":"marx-4-79","globalId":373,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":79,"question":"事物发展的动力和源泉是（ ）。","options":["事物的内部矛盾","事物的外部矛盾","事物的主要矛盾","矛盾的主要方面"],"answer":0,"answerLetter":"A","explain":"唯物辩证法认为，事物发展的动力和源泉是内部矛盾。内部矛盾是事物变化发展的根据，外部矛盾 是事物变化发展的条件，主要矛盾决定事物发展进程，矛盾主要方面决定事物性质。"},{"id":"marx-4-80","globalId":374,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":80,"question":"在苏维埃俄国提出并领导实施新经济政策的是（ ）。","options":["列宁","斯大林","布哈林","托洛斯基"],"answer":0,"answerLetter":"A","explain":"新经济政策是1921 年列宁领导苏维埃俄国开始实施的政策，旨在解决战时共产主义政策带来的危机 ，恢复和发展经济。答案：A。"},{"id":"marx-4-81","globalId":375,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":81,"question":"阶级消灭和国家消亡是在（ ）。","options":["社会主义革命中实现的","社会主义初级阶段实现的","无产阶级专政建立后实现的","共产主义社会实现的"],"answer":3,"answerLetter":"D","explain":"共产主义社会是人类最理想的社会形态，在共产主义社会，生产力高度发展，物质财富极大丰富 ，阶级对立和阶级差别将最终消失，作为阶级统治工具的国家也会自行消亡。而社会主义革命、社会主义初 级阶段以及无产阶级专政建立后，都还未达到阶级完全消灭和国家完全消亡的程度。"},{"id":"marx-4-82","globalId":376,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":82,"question":"社会意识具有复杂而精微的结构。从反映社会存在的程度和特点来看，社会意识包括","options":["社会心理和思想体系","意识形态和非意识形态","个体意识和群体意识","主流意识和非主流意识"],"answer":0,"answerLetter":"A","explain":"从反映社会存在的程度和特点看，社会意识分为社会心理和思想体系。社会心理是低层次、不系统 、不定型的社会意识；思想体系是高层次、系统化、理论化的社会意识。B选项是从对经济基础的关系角度划 分；C选项是从意识主体角度划分；D选项并非从反映社会存在程度和特点划分。"},{"id":"marx-4-83","globalId":377,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":83,"question":"斯密和李嘉图是（ ）。","options":["德国古典哲学的代表人物","英国古典政治经济学的代表人物","英国空想社会主义的代表人物","法国空想社会主义的代表人物"],"answer":1,"answerLetter":"B","explain":"斯密和李嘉图是英国古典政治经济学的重要代表人物，在政治经济学领域有着突出贡献。德国古典 哲学代表人物如康德等；空想社会主义代表人物如圣西门、傅立叶、欧文等。"},{"id":"marx-4-84","globalId":378,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":84,"question":"在运动和静止关系问题上，只承认绝对运动，否认相对静止的观点属于（ ）。","options":["唯物辩证法","形而上学","相对主义诡辩论","主观唯心主义"],"answer":2,"answerLetter":"C","explain":"相对主义诡辩论片面夸大事物的相对性，只承认绝对运动，否认相对静止，会导致对事物认识的不 确定性和随意性。唯物辩证法既承认绝对运动又承认相对静止；形而上学往往否认运动，只承认静止；主观 唯心主义强调主观精神决定一切，与运动静止关系无直接关联。"},{"id":"marx-4-85","globalId":379,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":85,"question":"揭示事物发展动力和源泉的规律是（ ）。","options":["对立统一规律","质量互变规律","内容和形式相互作用规律","否定之否定规律"],"answer":0,"answerLetter":"A","explain":"对立统一规律揭示了事物发展的动力和源泉。矛盾双方既对立又统一，推动事物的发展。质量互变 规律揭示事物发展的状态和形式；否定之否定规律揭示事物发展的方向和道路；内容和形式相互作用规律不 属于唯物辩证法三大规律，主要说明内容与形式的辩证关系。所以选A。"},{"id":"marx-4-86","globalId":380,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":86,"question":"利息率的变动区间是在（ ）。","options":["平均利润率和零之间","剩余价值和零之间","利润率和零之间","年剩余价值和零之间"],"answer":0,"answerLetter":"A","explain":"利息是平均利润的一部分，利息率不能高于平均利润率，否则职能资本家无利可图不会借贷；利息 率也不能为零，否则借贷资本所有者不会贷出资本。所以利息率变动区间在平均利润率和零之间。"},{"id":"marx-4-87","globalId":381,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":87,"question":"社会主义从一国向多国发展壮大起始于（ ）。","options":["第一次世界大战以后","第二次世界大战以后","中国社会主义革命以后","古巴社会主义革命以后"],"answer":1,"answerLetter":"B","explain":"第二次世界大战后，社会主义在世界范围内获得大发展，从一国实践发展为多国实践，形成了社会 主义阵营。所以社会主义从一国向多国发展壮大起始于第二次世界大战以后。"},{"id":"marx-4-88","globalId":382,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":88,"question":"提出社会主义革命同时胜利论的是（ ）。","options":["马克思恩格斯","列宁","斯大林","毛泽东"],"answer":0,"answerLetter":"A","explain":"马克思和恩格斯基于当时的历史条件，提出社会主义革命将在几个主要资本主义国家“同时发生 ”并取得胜利的理论。列宁根据帝国主义时代资本主义经济政治发展不平衡的规律，提出社会主义革命可能 在一国或数国首先取得胜利。斯大林、毛泽东主要是在社会主义建设等方面有诸多理论贡献。答案：A。"},{"id":"marx-4-89","globalId":383,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":89,"question":"在真理标准问题上坚持辩证法，就是要承认实践标准（ ）。","options":["既是抽象的又是具体的","既是必然的又是偶然的","既是普遍的又是特殊的","既是绝对的又是相对的"],"answer":3,"answerLetter":"D","explain":"实践作为检验真理的标准，具有确定性（绝对性）和不确定性（相对性）。确定性（绝对性）是指 实践是检验真理的唯一标准，凡经过实践证明了的一切认识都是客观真理，都具有不可推翻的性质；不确定 性（相对性）是指实践在一定历史条件下是有限的，具体的实践活动对于真理的检验具有一定的局限性。在 真理标准问题上坚持辩证法，就要看到实践标准的这两重属性，即既是绝对的又是相对的。"},{"id":"marx-4-90","globalId":384,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":90,"question":"杰出人物在历史上的作用表现为（ ）。","options":["定程度上推动社会的发展","摆脱历史条件的制约","改变历史发展的规律","决定历史时代的特点"],"answer":0,"answerLetter":"A","explain":"杰出人物能在一定程度上推动社会发展，A 正确；杰出人物不能摆脱历史条件制约，B 错；历史发 展规律具有客观性，无法改变，C 错；杰出人物不能决定历史时代特点，时代特点由当时的经济、政治等诸 多因素决定，D 错。"},{"id":"marx-4-91","globalId":385,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":91,"question":"两种商品可以按一定比例相互交换的原因，在于它们","options":["有不同的使用价值","都是具体劳动的产物","对人们有共同的效应","在生产中都耗费了一般的人类劳动"],"answer":3,"answerLetter":"D","explain":"两种商品能按一定比例交换，是因为它们具有价值，而价值是凝结在商品中的无差别的一般人类劳 动。选项A不同使用价值是商品交换的前提而非按比例交换原因；选项B具体劳动创造使用价值，不是按比例 交换的关键；选项C共同效应类似使用价值层面，不是按比例交换依据。选项D指出生产中耗费一般人类劳动 ，即具有价值，这才是能按比例交换的原因。"},{"id":"marx-4-92","globalId":386,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":92,"question":"社会主义的根本的和首要的任务是（ ）。","options":["解放和发展生产力","建立和完善社会主义公有制","建设社会主义的政治文明","建设社会主义的精神文明"],"answer":0,"answerLetter":"A","explain":"生产力是社会发展的最根本动力，社会主义本质是解放生产力，发展生产力，消灭剥削，消除两极 分化，最终达到共同富裕。所以社会主义根本和首要任务是解放和发展生产力。"},{"id":"marx-4-93","globalId":387,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":93,"question":"脱离实践的理论是空洞的理论；没有理论指导的实践是盲目的实践。这句话强调的是（ ）。","options":["认识过程中摹写与创造的统一","认识过程中感性与理性的统一","认识过程中真理与价值的统一","认识过程中理论与实践的统一"],"answer":3,"answerLetter":"D","explain":"题干前半句强调理论不能脱离实践，后半句强调实践需要理论指导，整体突出的是理论和实践相互 依存、不可分割，即认识过程中理论与实践的统一。"},{"id":"marx-4-94","globalId":388,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":94,"question":"在真理观上坚持辩证法,就必须承认（ ）。","options":["真理的内容是客观的,形式是主观的","真理既具有绝对性,又貝有相对性","真理既是正确的,又包含错误因素","真理既具有普遍性,又具有多样性检验"],"answer":1,"answerLetter":"B","explain":"辩证法强调用联系、发展、全面的观点看问题。在真理观上坚持辩证法，就是要看到真理是一个不 断发展的过程，具有两重属性，即绝对性和相对性。绝对真理和相对真理是相互依存、相互包含、相互转化 的，这体现了辩证法的观点。 选项A只是阐述了真理的客观性和主观性的方面，没有体现辩证法关于发展等 方面的要求。 选项C表述错误，真理和错误有明确界限，真理不包含错误因素。 选项D中真理普遍性表述不 准确，且真理多样性说法错误，真理是对客观事物及其规律的正确反映，不存在多样性的问题。"},{"id":"marx-4-95","globalId":389,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":95,"question":"借贷资本是（ ）。","options":["与产业资本、商业资本相同的职能资本","与商业资本、银行资本相同的流通资本","从职能资本运动中分离出来的特殊资本形式","与其他职能资本家获得同样利润的资本形式"],"answer":2,"answerLetter":"C","explain":"借贷资本是从职能资本（产业资本和商业资本）运动中分离出来的特殊资本形式，它不执行职能资 本那样的生产和实现剩余价值等职能。A选项说与职能资本相同错误；B选项中银行资本不是流通资本概念 ，且借贷资本与商业资本、银行资本性质不同；D选项借贷资本获得的是利息，职能资本家获得平均利润，二 者不同。"},{"id":"marx-4-96","globalId":390,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":96,"question":"金、银、铜、铁、铝等同金属的关系属于（ ）。","options":["部分与整体的关系","个别与一般的关系","现象与本质的关系","形式与内容的关系"],"answer":1,"answerLetter":"B","explain":"金、银、铜、铁、铝等是具体的金属种类，而金属是对它们共同属性的概括。个别金属体现了金属 这一“一般”概念的特征，所以它们是个别与一般的关系。答案选B。"},{"id":"marx-4-97","globalId":391,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":97,"question":"列宁称之为“社会主义的最充分的物质准备”、“社会主义的前阶”的是（ ）。","options":["自由竞争资本主义","私人垄断资本主义","国家垄断资本主义","国际垄断资本主义"],"answer":2,"answerLetter":"C","explain":"国家垄断资本主义阶段，国家对经济进行全面干预调节，使生产、资本等方面出现新变化，为社会 主义准备了更充分物质条件。私人垄断主要还是垄断组织自身发展，自由竞争资本主义离社会主义物质准备 更远，国际垄断资本主义是国家垄断发展的延伸，基础仍是国家垄断资本主义。所以列宁称国家垄断资本主 义是“社会主义的最充分的物质准备”“社会主义的前阶”。"},{"id":"marx-4-98","globalId":392,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":98,"question":"唯物辩证法的总特征有两个，一个是联系的观点，另一个是（ ）。","options":["发展的观点","对立统一的观点","实践的观点","辩证否定的观点"],"answer":0,"answerLetter":"A","explain":"唯物辩证法总特征是联系和发展，这是其区别于其他哲学的重要特点。对立统一是唯物辩证法实质 和核心；实践观点是马克思主义哲学首要的基本观点；辩证否定观是辩证法的内容之一，但非总特征。所以 应选发展的观点。"},{"id":"marx-4-99","globalId":393,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":99,"question":"在资本主义社会,垄断组织销售产品时多采取（ ）。","options":["垄断高价","垄断低价","社会生产价格","市场价格"],"answer":0,"answerLetter":"A","explain":"垄断组织目的是获取高额垄断利润，销售产品时会凭借其垄断地位尽可能抬高价格，多采取垄断高 价。"},{"id":"marx-4-100","globalId":394,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":100,"question":"唯物辩证法认为，发展的实质是（ ）。","options":["事物数量的增加","事物位置的移动","事物性质的变化","新事物的产生和旧事物的灭亡"],"answer":3,"answerLetter":"D","explain":"唯物辩证法中发展不是简单的数量增加、位置移动或性质变化，这些可能只是变化但不一定是发展 。发展强调的是事物由低级向高级、由简单向复杂、由无序向有序的前进和上升运动，其实质是新事物的产 生和旧事物的灭亡。"},{"id":"marx-4-101","globalId":395,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":101,"question":"在资本主义社会中,利润率是（ ）。","options":["剩余价值与可变资本的比率","剩余价值与不变资本的比率","剩余价值与预付总资本的比率","剩余价值与预付流通资本的比率"],"answer":2,"answerLetter":"C","explain":"利润率是剩余价值与预付总资本的比率。预付总资本包含不变资本和可变资本等。A选项剩余价值与 可变资本的比率是剩余价值率；B选项表述错误；D选项预付流通资本只是预付总资本一部分，不是利润率定 义。"},{"id":"marx-4-102","globalId":396,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":102,"question":"经济危机的周期爆发,使资本主义再生产也具有了周期性。资本主义再生产周期中决定性的阶段是（ ）。","options":["危机阶段","萧条阶段","复苏阶段","高涨阶段"],"answer":0,"answerLetter":"A","explain":"危机阶段是资本主义再生产周期的决定性阶段，它既是上一周期的终点，又是新周期的起点。在危 机阶段，经济矛盾集中爆发，生产急剧下降等。"},{"id":"marx-4-103","globalId":397,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":103,"question":"列宁所提出的社会主义革命在一国或数国首先胜利的理论立足于（ ）。","options":["马克思恩格斯的科学预言","巴黎公社原则","资本主义发展不平衡规律","生产力决定论"],"answer":2,"answerLetter":"C","explain":"列宁根据资本主义发展不平衡规律，得出社会主义革命在一国或数国首先胜利的结论。资本主义发 展不平衡使得有的国家发展较快，有的较慢，矛盾尖锐程度不同，从而为一国或数国首先胜利创造了条件。 马克思恩格斯认为社会主义革命将在几个主要资本主义国家同时发生，A选项不符；巴黎公社原则主要强调无 产阶级专政等方面，与本题联系不大，B排除；生产力决定论不能直接得出社会主义革命在一国或数国首先胜 利的结论，D排除。"},{"id":"marx-4-104","globalId":398,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":104,"question":"生产关系是指人们在物质生产过程中结成的（ ）。","options":["社会关系","经济关系","交往关系","竞争关系"],"answer":1,"answerLetter":"B","explain":"生产关系本质上是人们在物质生产过程中形成的经济关系。从概念定义出发，生产关系侧重经济层 面。"},{"id":"marx-4-105","globalId":399,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":105,"question":"唯物辩证法提供的最根本的认识方法是（ ）。","options":["逻辑分析法","阶级分析法","矛盾分析法","精神分析法"],"answer":2,"answerLetter":"C","explain":"唯物辩证法的实质和核心是对立统一规律，也就是矛盾规律。矛盾分析法是认识事物的根本方法 ，因为它揭示了事物发展的源泉和动力，贯穿于唯物辩证法其他规律和范畴之中。 逻辑分析法侧重于思维的 逻辑规则等，并非唯物辩证法最根本认识方法；阶级分析法是分析社会阶级关系等的方法，不属于唯物辩证 法范畴；精神分析法是心理学领域弗洛伊德等创立的分析精神层面的方法，和唯物辩证法无关。"},{"id":"marx-4-106","globalId":400,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":106,"question":"在资本主义社会中，银行资本家所获得的利润率水平（ ）。","options":["大体与借贷资本家获得的利息率水平相同","大体与职能资本家获得的平均利润率水平相同","大大高于职能资本家获得的平均利润率水平","大大低于职能资本家获得的平均利润率水平"],"answer":1,"answerLetter":"B","explain":"银行资本家投资于银行业，其目的也是获取利润，而且获得的利润也应相当于平均利润，这是由部 门之间的竞争和资本的自由转移实现的。所以银行资本家所获利润率大体与职能资本家获得的平均利润率水 平相同。"},{"id":"marx-4-107","globalId":401,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":107,"question":"决定股票价格的基本因素是（ ）。","options":["股息和贷款利息率","股息和汇率","股息和存款利息率","存款利息率和贷款利息率"],"answer":2,"answerLetter":"C","explain":"股票价格与股息成正比，与存款利息率成反比，股息和存款利息率是决定股票价格的基本因素。答 案：C"},{"id":"marx-4-108","globalId":402,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":108,"question":"列宁提出社会主义可能在一国或数国首先胜利的理论依据是（ ）。","options":["资本主义必然灭亡社会主义必然胜利的规律","帝国主义时代资本主义政治经济发展不平衡的规律","资本主义国家无产阶级与资产阶级斗争的规律","生产关系必须适合生产力发展要求的规律"],"answer":1,"answerLetter":"B","explain":"列宁依据帝国主义时代资本主义政治经济发展不平衡的规律，得出社会主义可能在一国或数国首先 胜利的结论。资本主义政治经济发展不平衡使得一些国家相对薄弱，为社会主义革命突破提供了机会。答案 ：B"},{"id":"marx-4-109","globalId":403,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":109,"question":"生产力发展水平的主要标志是（ ）。","options":["生产工具","运输工具","通讯设备","包装设备"],"answer":0,"answerLetter":"A","explain":"生产工具直接作用于劳动对象，它的发展水平是衡量生产力发展水平的客观尺度，是生产力发展水 平的主要标志。而运输工具、通讯设备、包装设备等只是生产过程中的辅助工具或设备，不能像生产工具那 样直接体现生产力的核心发展程度。"},{"id":"marx-4-110","globalId":404,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":110,"question":"唯物辩证法有两个总特征，一个是普遍联系的观点，另一个是（ ）。","options":["质量互变的观点","永恒发展的观点","对立统一的观点","辩证否定的观点"],"answer":1,"answerLetter":"B","explain":"唯物辩证法的两个总特征是普遍联系和永恒发展。质量互变、对立统一、辩证否定是唯物辩证法的 规律和范畴，并非总特征。"},{"id":"marx-4-111","globalId":405,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":111,"question":"真理的发展是一个（ ）。","options":["从主观真理走向客观真理的过程","从局部真理走向全面真理的过程","从具体真理走向抽象真理的过程","从相对真理走向绝对真理的过程"],"answer":3,"answerLetter":"D","explain":"真理具有相对性和绝对性，是相对性和绝对性的统一。真理的发展就是不断从相对真理走向绝对真 理的过程。不存在主观真理，A 错；真理并非简单从局部到全面，B 不准确；真理是具体的，不存在从具体 走向抽象，C 错。"},{"id":"marx-4-112","globalId":406,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":112,"question":"决定利息量的因素是（ ）。","options":["银行自有资本总额和平均利润率","银行自有资本总额和利息率","借贷资本总额和平均利润率","借贷资本总额和利息率"],"answer":3,"answerLetter":"D","explain":"利息量取决于借贷资本总额和利息率，利息量=借贷资本总额×利息率 。平均利润率影响的是利率 的高低范围等，但不是直接决定利息量的因素；银行自有资本总额与利息量计算并无直接关系。"},{"id":"marx-4-113","globalId":407,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":113,"question":"垄断的工业资本和垄断的银行资本融合或混合生长所构成的资本是（ ）。","options":["股份资本","金融资本","商业资本","虚拟资本"],"answer":1,"answerLetter":"B","explain":"金融资本就是垄断的工业资本和垄断的银行资本融合或混合生长构成的资本。A选项股份资本是通过 发行股票的方式筹集起来的企业资本；C选项商业资本是从产业资本中分离出来，专门从事商品买卖，独立发 挥资本职能的资本；D选项虚拟资本是以有价证券形式存在，并能给持有者带来一定收益的资本。"},{"id":"marx-4-114","globalId":408,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":114,"question":"生产力范畴反映的是（ ）。","options":["人与人之间的经济关系","人与人之间的政治关系","人与自然之间的关系","人与人之间的思想关系"],"answer":2,"answerLetter":"C","explain":"生产力是人类利用自然、改造自然的能力，所以它反映的是人与自然之间的关系。"},{"id":"marx-4-115","globalId":409,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":115,"question":"唯物辩证法有两个总特征，一个是永恒发展的观点，另一个是（ ）。","options":["普遍联系的观点","对立统一的观点","质量互变的观点","辩证否定的观点"],"answer":0,"answerLetter":"A","explain":"唯物辩证法总特征是普遍联系和永恒发展，所以另一个总特征就是普遍联系的观点。"},{"id":"marx-4-116","globalId":410,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":116,"question":"真理都是具体的,包罗万象的真理是不存在的。这说明任何真理都具有（ ）。","options":["全面性","相对性","绝对性","客观性"],"answer":1,"answerLetter":"B","explain":"真理的相对性表明真理是有条件的、有限的。因为真理都是具体的，不是包罗万象的，意味着真理 在广度和深度上都是有限的，有其适用范围，这体现了真理的相对性。 全面性不是真理的特性；真理绝对性 强调真理的客观性和世界可知性等，与题干表述不符；客观性指真理内容是客观的，题干强调的不是客观性 。"},{"id":"marx-4-117","globalId":411,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":117,"question":"决定人口生产的发展方向和基本趋势的是（ ）。","options":["地理环境","物质生产","风俗习惯","人伦道德"],"answer":1,"answerLetter":"B","explain":"物质生产从根本上决定了人口生产的发展方向和基本趋势，物质生产方式制约着人口生产的社会形 式、人口数量和质量等。地理环境、风俗习惯、人伦道德虽对人口生产有影响，但并非起决定作用。"},{"id":"marx-4-118","globalId":412,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":118,"question":"垄断的工业资本和银行资本融合生长构成（ ）。","options":["国家垄断资本","金融资本","私人垄断资本","借贷资本"],"answer":1,"answerLetter":"B","explain":"垄断的银行资本和垄断的工业资本融合生长，形成金融资本。"},{"id":"marx-4-119","globalId":413,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":119,"question":"生产要素的购买时间属于资本周转过程中的（ ）。","options":["生产时间","流通时间","劳动时间","停工时间"],"answer":1,"answerLetter":"B","explain":"资本周转过程包括生产时间和流通时间。生产要素购买是在市场上进行，属于资本处于流通领域的 活动，所以生产要素的购买时间属于流通时间。"},{"id":"marx-4-120","globalId":414,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":120,"question":"唯物辩证法与形而上学根本对立和斗争的焦点在于，是否承认（ ）。","options":["联系具有复杂多样性","新事物必然战胜旧事物","质变是量变的必然结果","矛盾是事物发展的动力"],"answer":3,"answerLetter":"D","explain":"唯物辩证法和形而上学的根本对立焦点在于对事物发展动力的不同看法。唯物辩证法认为矛盾是事 物发展的动力，而形而上学否认矛盾的存在。A选项联系的复杂多样性、B选项新事物战胜旧事物、C选项质变 与量变关系，都不是二者对立焦点。"},{"id":"marx-4-121","globalId":415,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":121,"question":"生产资料的购买时间属于（ ）。","options":["运输时间","劳动时间","非劳动时间","流通时间"],"answer":3,"answerLetter":"D","explain":"流通时间是指产业资本停留在流通领域内的时间，包括购买时间和销售时间。生产资料购买属于产 业资本在流通领域的活动，所以生产资料的购买时间属于流通时间。 运输时间是产品运输过程的时间，与生 产资料购买时间概念不同；劳动时间是劳动者运用劳动资料作用于劳动对象生产出某种产品所需要的时间 ，和购买生产资料时间无关；非劳动时间包含自然力独立作用于劳动对象的时间等，也不涉及生产资料购买 时间。"},{"id":"marx-4-122","globalId":416,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":122,"question":"唯物辩证法与形而上学在真理观上的对立，表现在是否承认（ ）。","options":["真理具有客观性","真理具有相对性","真理中包含着错误","真理来源于主观创造"],"answer":1,"answerLetter":"B","explain":"唯物辩证法坚持用联系、发展、全面的观点看问题，形而上学用孤立、静止、片面的观点看问题。 在真理观上，唯物辩证法认为真理是发展的，具有相对性，是不断发展变化的，这体现了辩证法发展的观点 。而形而上学往往把真理看成是绝对不变的。 A选项真理具有客观性是唯物主义真理观都承认的，不是唯物 辩证法与形而上学在真理观上的对立点。 C选项真理和错误有严格界限，真理中不包含错误，该说法本身错 误。 D选项真理来源于实践，而不是主观创造，该说法错误。"},{"id":"marx-4-123","globalId":417,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":123,"question":"真理是没有阶级性的，在真理面前人人平等。这是因为（ ）。","options":["真理就是客观规律，与人的阶级地位无关","真理具有客观性，包含着不依赖于人类的客观内容","真理是绝对性和相对性的统一，是不断发展的","真理是具体的，都有其适用的条件和范围"],"answer":1,"answerLetter":"B","explain":"真理具有客观性，它包含着不依赖于主体、不依赖于人类的客观内容，正是因为这种客观性，决定 了真理没有阶级性，在真理面前人人平等。A选项真理并不完全等同于客观规律；C选项真理绝对性和相对性 统一强调的是真理的发展特性，与在真理面前人人平等的原因无关；D选项真理的具体性强调适用条件范围 ，也不是在真理面前人人平等的原因。"},{"id":"marx-4-124","globalId":418,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":124,"question":"科学社会主义思想史上的第一个纲领性文件是（ ）。","options":["《德意志意识形态》","《关于费尔巴哈的提纲》","《共产党宣言》","《哥达纲领批判》"],"answer":2,"answerLetter":"C","explain":"《共产党宣言》是科学社会主义思想史上第一个纲领性文件，它系统阐述了科学社会主义理论，为 无产阶级运动提供了科学理论指导 。而A选项《德意志意识形态》主要是阐述历史唯物主义；B选项《关于费 尔巴哈的提纲》是马克思主义新世界观的天才萌芽；D选项《哥达纲领批判》批判拉萨尔主义，进一步丰富了 科学社会主义学说。答案：C 。"},{"id":"marx-4-125","globalId":419,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":125,"question":"马克思主义把人类社会的发展划分为五种社会形态，这种划分法所依据的标准是（ ）。","options":["意识形态的不同性质","生产关系的不同性质","生产力的不同水平","人的发展的不同状况"],"answer":1,"answerLetter":"B","explain":"马克思主义以生产关系的不同性质为标准，将人类社会发展划分为原始社会、奴隶社会、封建社会 、资本主义社会、共产主义社会五种社会形态。生产力是根本决定力量，但划分社会形态依据的直接标准是 生产关系。"},{"id":"marx-4-126","globalId":420,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":126,"question":"剩余价值的唯一源泉是工人的（ ）。","options":["具体劳动","必要劳动","个别劳动","剩余劳动"],"answer":3,"answerLetter":"D","explain":"剩余价值是雇佣工人所创造的并被资本家无偿占有的超过劳动力价值的那部分价值。工人的剩余劳 动是创造剩余价值的源泉，具体劳动创造使用价值，必要劳动补偿劳动力价值，个别劳动不直接与剩余价值 的产生有特定联系。"},{"id":"marx-4-127","globalId":421,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":127,"question":"下列不属于当代资本主义国家经济结构新变化的是（ ）。","options":["高科技产业的大发展","产业工人的大幅增加","第三产业的大发展","信息产业的兴起"],"answer":1,"answerLetter":"B","explain":"当代资本主义国家经济结构新变化主要体现在高科技产业、第三产业、信息产业等兴起和发展。随 着科技进步与产业结构调整，产业工人数量是逐渐减少而非大幅增加。答案选B。"},{"id":"marx-4-128","globalId":422,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":128,"question":"正确认识和评价杰出人物的历史作用,应该坚持（ ）。","options":["历史主义的原则和精神分析的方法","现实主义的原则和精神分析的方法","历史主义的原则和阶级分析的方法","现实主义的原则和阶级分析的方法"],"answer":2,"answerLetter":"C","explain":"评价杰出人物历史作用，需将其置于特定历史背景，这就是历史主义原则；同时，在阶级社会中 ，人物活动受阶级制约，所以要用阶级分析方法。精神分析主要用于心理学领域，现实主义原则与评价杰出 人物历史作用关联不大。"},{"id":"marx-4-129","globalId":423,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":129,"question":"马克思主义的革命性既表现为它具有彻底的批判精神，又表现为它具有","options":["完整的理论体系","严密的逻辑结构","鲜明的政治立场","崇高的社会理想"],"answer":2,"answerLetter":"C","explain":"马克思主义的革命性，集中表现为它的彻底的批判精神和鲜明的政治立场。马克思主义代表无产阶 级和广大人民的根本利益，具有鲜明政治立场，这与革命性紧密相关。而完整理论体系、严密逻辑结构体现 的是马克思主义科学性等方面，崇高社会理想主要强调对未来社会的构想，并非直接体现革命性。"},{"id":"marx-4-130","globalId":424,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":130,"question":"剩余价值转化为利润，是由于把剩余价值看作是（ ）。","options":["不变资本的产物","可变资本的产物","全部预付资本的产物","全部所费资本的产物"],"answer":2,"answerLetter":"C","explain":"当把剩余价值看作是全部预付资本（包括不变资本和可变资本）的产物时，剩余价值就转化为利润 。因为资本家投入的全部预付资本都参与生产过程，他们会认为利润是所有投入资本带来的，而不是仅把可 变资本看作产生剩余价值的唯一因素。不变资本在生产中不发生价值增殖，可变资本才是产生剩余价值的源 泉，但资本家不这么认为，他们把剩余价值当成全部预付资本带来的收益。"},{"id":"marx-4-131","globalId":425,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":131,"question":"垄断利润的真正来源于（ ）。","options":["垄断行为所创造的更多市场价值","垄断势力在自由市场上的巧取豪夺","工人阶级和劳动人民所创造的剩余价值","生产和非生产领域劳动者共同创造的物质财富"],"answer":2,"answerLetter":"C","explain":"垄断利润归根结底来自工人阶级和劳动人民所创造的剩余价值。垄断企业通过垄断价格出售产品等 手段，将其他企业工人创造的一部分剩余价值和小生产者创造的一部分价值转化为垄断利润，同时还包括对 本国无产阶级和其他劳动人民剥削的加强获得更多剩余价值。"},{"id":"marx-4-132","globalId":426,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":132,"question":"马克思主义的根本理论特征是（ ）。","options":["科学性和革命性的统","逻辑性和历史性的统","自然观和历史观的统","世界观和方法论的统"],"answer":0,"answerLetter":"A","explain":"马克思主义具有科学性，它是对客观世界特别是人类社会本质和规律的正确反映；同时具有革命性 ，它是无产阶级和广大人民群众推翻旧世界、建设新世界的理论，科学性与革命性的统一是马克思主义的根 本理论特征。"},{"id":"marx-4-133","globalId":427,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":133,"question":"剩余价值转化为利润后，商品价值表现为（ ）。","options":["不变资本与可变资本之和","不变资本与剩余价值之和","生产成本与利润之和","生产成本与平均利润之和"],"answer":2,"answerLetter":"C","explain":"当剩余价值转化为利润后，商品价值原本的“不变资本 + 可变资本 + 剩余价值”形式，就表现为 “生产成本（不变资本 + 可变资本） + 利润”。"},{"id":"marx-4-134","globalId":428,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":134,"question":"下列各项不属于共产主义社会基本特征的是（ ）。","options":["生产力高度发展和物质财富极大丰富","实行社会公有制和按需分配","计划经济和市场经济相结合","人的自由而全面发展"],"answer":2,"answerLetter":"C","explain":"共产主义社会生产力高度发达，物质财富极大丰富，实行社会公有制，按需分配，人的自由全面发 展是共产主义社会中人的发展状态。而计划经济与市场经济相结合是社会主义经济体制特点，并非共产主义 社会基本特征。"},{"id":"marx-4-135","globalId":429,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":135,"question":"直接经验和间接经验的关系是（ ）。","options":["认识中内容和形式的关系","认识中“源”和“流”的关系","感性认识和理性认识的关系","实践和理论的关系"],"answer":1,"answerLetter":"B","explain":"直接经验是通过亲身实践获得的知识，间接经验是从他人或书本等途径获取的知识。实践是认识的 来源，直接经验是认识的“源”，间接经验归根结底也源于实践，是认识的“流”。"},{"id":"marx-4-136","globalId":430,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":136,"question":"垄断利润和垄断价格的出现","options":["使价值规律在某些领域不起作用","使价值规律作用的形式发生变化","否定了价值规律","改变了价值规律的内涵"],"answer":1,"answerLetter":"B","explain":"价值规律是商品经济的基本规律，只要存在商品生产和商品交换，价值规律就必然起作用。垄断利 润和垄断价格的出现，并没有否定价值规律，也没有改变价值规律的内涵。 只是在垄断条件下，价值规律作 用的形式发生了变化，即市场价格围绕垄断价格上下波动。"},{"id":"marx-4-137","globalId":431,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":137,"question":"马克思主义的最高社会理想是（ ）。","options":["消灭等级制度，实现人人平等","推翻资本主义，实现共产主义","消灭贫富悬殊，实行平均主义","取消按资分配，实行按劳分配"],"answer":1,"answerLetter":"B","explain":"马克思主义致力于实现以劳动人民为主体的最广大人民的根本利益，其最高社会理想是推翻资本主 义，实现共产主义，共产主义社会是物质财富极大丰富、人民精神境界极大提高、每个人自由而全面发展的 社会。A选项“消灭等级制度，实现人人平等”不够全面准确表述马克思主义最高理想；C选项“平均主义 ”不符合马克思主义理念，共产主义并非平均主义；D选项“取消按资分配，实行按劳分配”只是共产主义社 会分配方式的描述，不能完整概括最高理想。"},{"id":"marx-4-138","globalId":432,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":138,"question":"时间和空间既是绝对的、无限的是相对的、有限的。这是一种","options":["诡辩论的观点？？？","辩证唯物主义的观点","实用至受的观点？？？","形而上学的观点"],"answer":1,"answerLetter":"B","explain":"辩证唯物主义认为时间和空间是绝对性与相对性、无限性与有限性的辩证统一。一方面，时间和空 间作为物质运动的存在形式，它们的客观实在性是不变的、无条件的，因而是绝对的；物质世界在时间和空 间上又是无限的。另一方面，时间和空间的具体特性受物质运动的具体特性所制约，是随着物质运动的变化 而变化的，因而是相对的；具体事物在时间和空间上又是有限的。 诡辩论往往片面夸大相对性而否定绝对性 等；实用主义主要强调有用即真理；形而上学用孤立、静止、片面的观点看问题，均不符合对时空这种辩证 认识。"},{"id":"marx-4-139","globalId":433,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":139,"question":"下列各项既属于不变资本又属于流动资本的是（ ）。","options":["以生产工具形式存在的资本","以劳动对象形式存在的资本","以劳动力形式存在的资本","以厂房设备形式存在的资本"],"answer":1,"answerLetter":"B","explain":"不变资本是指在生产过程中不改变自己价值量的资本，可变资本是改变价值量的资本，劳动力属于 可变资本，所以C排除。 流动资本是一次投入、一次收回，固定资本是多次投入、多次收回。生产工具、厂 房设备属于固定资本，A、D排除。 劳动对象是一次投入生产过程，价值一次性转移，既属于不变资本（不改 变价值量）又属于流动资本（一次投入一次收回）。"},{"id":"marx-4-140","globalId":434,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":140,"question":"纸上得来终觉浅，绝知此事要躬行。”这句话强调的是（ ）。","options":["直接经验是知识的唯一来源","书本知识是根本不可靠的","间接经验是知识的唯一来源","真理是在实践中检验和发展的"],"answer":3,"answerLetter":"D","explain":"“纸上得来终觉浅，绝知此事要躬行”意思是从书本上获取的知识比较浅显，要透彻地认识事物还 必须亲自实践。这突出了实践对认识的重要性，真理需要在实践中去检验和发展。A选项直接经验不是知识唯 一来源，还有间接经验；B选项书本知识并非根本不可靠；C选项间接经验不是唯一来源。"},{"id":"marx-4-141","globalId":435,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":141,"question":"马克思主义认识论认为，真理的发展是一个（ ）。","options":["从主观真理走向客观真理的过程","从局部真理走向全面真理的过程","从相对真理走向绝对真理的过程","从具体真理走向抽象真理的过程"],"answer":2,"answerLetter":"C","explain":"马克思主义认识论认为，真理具有相对性和绝对性，是二者的统一。真理的发展是不断从相对真理 走向绝对真理的过程。相对真理是指在一定条件下对事物的一定程度、一定层次的正确认识，它有待于扩展 和深化；绝对真理是指真理的无条件性、无限性。人类认识是一个不断深化的过程，是从相对真理走向绝对 真理、接近绝对真理的永无止境的过程。 A选项，真理本身就是客观的，不存在从主观真理走向客观真理。 B选项，局部真理走向全面真理表述不准确，不是马克思主义关于真理发展的核心观点。 D选项，真理是具体 的，不是从具体走向抽象，这种表述错误。"},{"id":"marx-4-142","globalId":436,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":142,"question":"实践作为检验真理的标准，既具有确定性，又具有（ ）。","options":["普遍性","特殊性","不确定性","绝对性"],"answer":2,"answerLetter":"C","explain":"实践作为检验真理的标准具有确定性（绝对性）和不确定性（相对性）。确定性是指实践是检验真 理的唯一标准等；不确定性指实践对真理的检验是一个过程，受一定历史条件制约等。所以这里应选不确定 性。"},{"id":"marx-4-143","globalId":437,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":143,"question":"下列各项属于技术社会形态序列的是（ ）。","options":["原始社会","农业社会","封建社会","资本主义社会"],"answer":1,"answerLetter":"B","explain":"技术社会形态是以生产力和技术发展水平以及与此相适应的产业结构为标准划分的社会形态。农业 社会是按照技术发展水平及产业结构划分的，是以农业技术和农业产业为主导的社会形态。 而原始社会、封 建社会、资本主义社会属于以生产关系性质为标准划分的社会形态，即经济社会形态序列。"},{"id":"marx-4-144","globalId":438,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":144,"question":"中国共产党的思想路线的核心是（ ）。","options":["一切从实际出发","理论联系实际","实事求是","在实践中检验真理和发展真理"],"answer":2,"answerLetter":"C","explain":"中国共产党的思想路线是一切从实际出发，理论联系实际，实事求是，在实践中检验真理和发展真 理。其中，实事求是是党的思想路线的核心，它贯穿于思想路线的各个方面 ，其他三个方面都围绕“实事求 是”展开。"},{"id":"marx-4-145","globalId":439,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":145,"question":"垄断资本实现其经济上统治的方式是（ ）。","options":["股份制","合作制","垄断制","参与制"],"answer":3,"answerLetter":"D","explain":"垄断资本在经济上统治主要是通过“参与制”实现的，“参与制”是指金融寡头通过掌握一定数量 的股票来层层控制企业的制度。"},{"id":"marx-4-146","globalId":440,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":146,"question":"实现共产主义社会的根本条件和基础是（ ）。","options":["社会生产力的高度发展","人与人关系的高度和谐","人的思想觉悟的极大提高","自然生态环境的极大改善"],"answer":0,"answerLetter":"A","explain":"生产力决定生产关系，经济基础决定上层建筑。共产主义是一种更高级的社会形态，要实现它，需 要有坚实的物质基础，这就依赖于社会生产力的高度发展。只有生产力高度发展，才能为共产主义社会的建 立提供足够的物质财富等条件。"},{"id":"marx-4-147","globalId":441,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":147,"question":"下列各项属于因果联系的是（ ）。","options":["风来雨至,电闪雷鸣","冬去春来,夏尽秋至","摩擦生热,热胀冷缩","夜尽昼至,昼尽夜来"],"answer":2,"answerLetter":"C","explain":"因果联系是指事物之间存在引起和被引起的关系。 A选项中，风来雨至、电闪雷鸣，风不是雨产生 的必然原因，电闪和雷鸣也并非严格因果关系，它们常是伴随大气变化等其他因素同时出现。 B选项冬去春 来、夏尽秋至，以及D选项夜尽昼至、昼尽夜来，这些都是地球公转、自转引起的周期性自然现象，并非因果 联系中那种严格的引起和被引起关系。 C选项摩擦生热，摩擦是生热的原因，热胀冷缩中温度变化是物体体 积变化的原因，存在引起和被引起的关系，属于因果联系。"},{"id":"marx-4-148","globalId":442,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":148,"question":"资本的价值构成是指（ ）。","options":["固定资本和流动资本的比例","所用资本和所费资本的比例","生产资料和劳动力的比例","不变资本和可变资本的比例"],"answer":3,"answerLetter":"D","explain":"资本价值构成是指资本在价值形态上由不变资本和可变资本所构成的数量比例。C选项生产资料和劳 动力的比例是资本的技术构成。A选项固定资本和流动资本是按资本周转方式划分。B选项所用资本和所费资 本比例与资本构成概念不同。"},{"id":"marx-4-149","globalId":443,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":149,"question":"资本的有机构成可表示为（ ）。","options":["c v","m c","m","m v"],"answer":0,"answerLetter":"A","explain":"【标准答案：A】"},{"id":"marx-4-150","globalId":444,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":150,"question":"垄断资本主义国家事实上的主宰者是（ ）。","options":["产业资本家","商业资本家","大土地所有者","金融寡头"],"answer":3,"answerLetter":"D","explain":"在垄断资本主义阶段，金融寡头凭借其在经济领域的统治地位进而掌控国家政权等各方面，成为垄 断资本主义国家事实上的主宰者。产业资本家、商业资本家、大土地所有者都不具备这样全面主宰的地位。"},{"id":"marx-4-151","globalId":445,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":151,"question":"马克思主义认为，世界的真正统一性在于它的（ ）。","options":["广延性","存在性","物质性","可知性"],"answer":2,"answerLetter":"C","explain":"马克思主义哲学认为，纷繁复杂、无限多样的世界具有共同的本质，即物质性，世界统一于物质。 广延性是物质的一种属性，不能等同于世界统一性；存在性概念宽泛，不能准确体现世界统一基础；可知性 强调人对世界的认识，与世界统一性无关。"},{"id":"marx-4-152","globalId":446,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":152,"question":"人们正确发挥主观能动作用的根本途径是（ ）。","options":["认识客观规律","制定周密计划","依靠广大群众","参加社会实践"],"answer":3,"answerLetter":"D","explain":"社会实践是人类认识和改造世界的基础活动。只有通过社会实践，人们才能接触到客观事物，进而 认识客观规律，并将对规律的认识应用于改造世界的活动中，正确发挥主观能动作用。认识客观规律只是前 提，制定周密计划要基于实践，依靠广大群众也要通过实践来实现主观能动作用的发挥。"},{"id":"marx-4-153","globalId":447,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":153,"question":"唯物史观认为，地理环境是（ ）。","options":["社会物质生活的必要条件？","经济社会形态的划分依据？","社会形态更替的决定力量？","技术社会形态的划分依据"],"answer":0,"answerLetter":"A","explain":"地理环境是社会存在和发展的必要条件，为人类提供生存和发展的自然条件，影响生产部门的分布 和发展方向等。经济社会形态划分依据是生产关系，社会形态更替决定力量是生产力与生产关系、经济基础 与上层建筑的矛盾运动，技术社会形态划分依据是生产力和技术发展水平。所以选A。"},{"id":"marx-4-154","globalId":448,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":154,"question":"下列各项正确说明意识本质的是（ ）。","options":["意识是人脑对客观世界的反映","意识是独立于物质的精神实体","意识是人的纯粹主观创造","意识是感性认识和理性认识的产物"],"answer":0,"answerLetter":"A","explain":"意识的本质是客观内容和主观形式的统一，是人脑对客观世界的反映。 B选项，意识依赖于物质 ，不能独立于物质存在，所以B错误。 C选项，意识不是纯粹主观创造的，它来源于客观世界，所以C错误。 D选项，意识是物质世界长期发展的产物，也是社会实践的产物，并非感性认识和理性认识的产物，所以D错 误。"},{"id":"marx-4-155","globalId":449,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":155,"question":"资本国际化进程大体是（ ）。","options":["从货币资本、生产资本到商品资本的国际化","从借贷资本、产业资本到商业资本的国际化","从商业资本、借贷资本到产业资本的国际化","从商品资本、货币资本到生产资本的国际化"],"answer":2,"answerLetter":"C","explain":"资本国际化是资本主义生产方式发展到一定阶段的必然现象，其进程是与资本主义发展阶段相适应 的。在资本主义发展过程中，商业资本首先实现国际化，随着资本主义发展，借贷资本走向国际化，到了垄 断资本主义阶段，产业资本大规模国际化。"},{"id":"marx-4-156","globalId":450,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":156,"question":"人民群众创造历史的活动受历史条件的制约。这种观点是说（ ）。","options":["人民群众不能推动社会形态的更替","人民群众不能随心所欲地创造历史","人民群众不是社会发展的决定力量","人民群众不是社会历史活动的主体"],"answer":1,"answerLetter":"B","explain":"人民群众创造历史活动受历史条件制约，意味着其创造活动不能脱离当时的历史环境，不能随心所 欲。A选项人民群众是推动社会形态更替的重要力量；C选项人民群众是社会发展的决定力量；D选项人民群众 是社会历史活动的主体。"},{"id":"marx-4-157","globalId":451,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":157,"question":"唯物史观认为，杰出人物的出现是（ ）。","options":["历史命运的安排","纯粹的历史必然","时代发展的需要","纯粹的历史偶然"],"answer":2,"answerLetter":"C","explain":"唯物史观强调，杰出人物是适应时代发展需要而产生的。时代发展面临特定任务与矛盾，需要杰出 人物引领推动。杰出人物的出现既非命运安排这种唯心说法，也不是纯粹必然或偶然，而是必然性与偶然性 的统一，其中时代发展的需要这一必然性起关键作用。"},{"id":"marx-4-158","globalId":452,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":158,"question":"下列各项中，强调认识来源于实践的是？","options":["不积跬步，无以至千里？","蝉噪林愈静，鸟鸣山更幽","不积小流，无以成江海？","近水知鱼性，近山识鸟音"],"answer":3,"answerLetter":"D","explain":"A和C选项强调积累的重要性；B选项体现的是矛盾的对立统一；D选项“近水知鱼性，近山识鸟音 ”意思是靠近水才能了解鱼的习性，靠近山才能识别鸟的声音，说明要通过实践（接近水和山这些实践活动 ）才能获得对鱼性和鸟音的认识，强调认识来源于实践。"},{"id":"marx-4-159","globalId":453,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":159,"question":"资本家提高劳动生产率的直接目的是（ ）。","options":["生产绝对剩余价值","获取超额剩余价值","生产相对剩余价值","降低劳动力价值"],"answer":1,"answerLetter":"B","explain":"个别资本家提高劳动生产率，使自己商品的个别价值低于社会价值，从而在竞争中获得额外的剩余 价值，即超额剩余价值。 生产绝对剩余价值主要靠延长工作日等手段，不是提高劳动生产率的直接目的。 相对剩余价值是整个社会劳动生产率提高的结果，不是个别资本家提高劳动生产率的直接目的。 降低劳动力 价值是整个社会劳动生产率提高带来的，不是个别资本家提高劳动生产率的直接目的。"},{"id":"marx-4-160","globalId":454,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":160,"question":"垄断资本主义为向社会主义过渡准备的物质基础是（ ）。","options":["资本主义议会制度","国家管理经济职能","社会化大生产","经济全球化"],"answer":2,"answerLetter":"C","explain":"垄断资本主义时期，生产社会化、资本社会化和管理社会化都达到了很高程度，为向社会主义过渡 准备了最充分的物质基础即社会化大生产。资本主义议会制度是政治形式，与物质基础无关；国家管理经济 职能是一种手段，并非物质基础；经济全球化是世界经济发展趋势，不是向社会主义过渡的物质基础。答案 ：C"},{"id":"marx-4-161","globalId":455,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":161,"question":"人民群众是历史的创造者。这是因为人民群众是社会变革的决定力量，还因为（ ）。","options":["人民群众是社会物质财富和精神财富的创造者","人民群众的一切活动都能推动历史进步","人民群众的愿望要求都是天然合理的","民群众的活动是不受历史条件制约的"],"answer":0,"answerLetter":"A","explain":"人民群众是历史创造者，体现在他们是社会物质财富和精神财富创造者，同时是社会变革决定力量 ，A选项正确。B中“一切活动”表述错误，部分活动可能违背历史发展规律，不能推动进步；C“愿望要求都 是天然合理”过于绝对，有的不合理；D人民群众活动受历史条件制约。"},{"id":"marx-4-162","globalId":456,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":162,"question":"唯物史观认为，人的本质在其现实性上是（ ）。","options":["人的价值追求","人的政治立场","人的情感态度","人的一切社会关系的总和"],"answer":3,"answerLetter":"D","explain":"唯物史观强调人的本质不是单个人所固有的抽象物，在其现实性上，它是一切社会关系的总和。这 一观点从社会关系的角度全面、深刻地揭示了人的本质，而A选项人的价值追求、B选项人的政治立场、C选项 人的情感态度都只是人的某一方面特征，不能全面涵盖人的本质。"},{"id":"marx-4-163","globalId":457,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":163,"question":"下列各项中，属于辩证唯物主义认识论区别于旧唯物主义认识论的观点是（ ）。","options":["认识客体具有客观性的观点","认识是主体对客体的反映的观点","物质世界可以认识的观点","实践是认识的基础的观点"],"answer":3,"answerLetter":"D","explain":"辩证唯物主义认识论强调实践是认识的基础，实践对认识具有决定作用，这是旧唯物主义认识论所 没有的。旧唯物主义认识论不懂得实践在认识中的作用。A、B、C选项是二者共有的观点。"},{"id":"marx-4-164","globalId":458,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":164,"question":"唯物主义认识论和唯心主义认识论的根本区别是（ ）。","options":["前者是可知论,后者是不可知论","前者是能动反映论,后者是机械反映论","前者是反映论,后者是先验论","前者是唯理论,后者是经验论"],"answer":2,"answerLetter":"C","explain":"唯物主义认识论坚持反映论，认为认识是主体对客体的反映，认识来源于客观世界。 唯心主义认 识论坚持先验论，认为认识先于物质、先于实践经验，是先天就有的。这是二者的根本区别。"},{"id":"marx-4-165","globalId":459,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":165,"question":"意识对于人的生理活动具有一定影响作用，这表明（ ）。","options":["意识对物质具有能动性","意识是客观事物本身","意识对物质具有决定性","意识是人脑的机能"],"answer":0,"answerLetter":"A","explain":"意识对人的生理活动有影响，体现了意识能够反作用于人体生理，这是意识对物质具有能动作用的 表现之一。B选项意识不是客观事物本身，是对客观事物的主观反映；C选项物质决定意识，不是意识决定物 质；D选项意识是人脑机能表述正确，但与题干强调的意识对生理活动影响这一能动作用不符。"},{"id":"marx-4-166","globalId":460,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":166,"question":"资本循环中起决定性作用的阶段是（ ）。","options":["购买阶段","生产阶段","销售阶段","流通阶段"],"answer":1,"answerLetter":"B","explain":"资本循环包括购买、生产、销售三个阶段。生产阶段是资本家使用购买来的劳动力和生产资料进行 生产，生产出包含剩余价值的商品，这一阶段直接创造价值和剩余价值，对资本循环起决定性作用。购买阶 段为生产准备条件，销售阶段实现商品价值和剩余价值，但都不如生产阶段关键。答案：B。"},{"id":"marx-4-167","globalId":461,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":167,"question":"垄断组织实行垄断价格的根本目的是为了","options":["扩大市场份额","降低生产成本","获取高额垄断利润","获取平均利润"],"answer":2,"answerLetter":"C","explain":"垄断组织作为垄断资本主义阶段的经济组织形式，其核心目标就是凭借垄断地位获取高额利润。实 行垄断价格是其达成这一目标的重要手段。而扩大市场份额、降低生产成本并非根本目的，平均利润也不是 垄断组织追求的，它们追求的是大大高于平均利润的高额垄断利润。"},{"id":"marx-4-168","globalId":462,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":168,"question":"社会总产品的两大部类是指（ ）。","options":["生产资料部类和消费资料部类","劳动资料部类和劳动对象部类","可变资本部类和不变资本部类","固定资本部类和流动资本部类"],"answer":0,"answerLetter":"A","explain":"社会总产品从实物形态按最终用途划分，可分为生产资料和消费资料，相应地社会生产便分为生产 生产资料的第一部类和生产消费资料的第二部类。"},{"id":"marx-4-169","globalId":463,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":169,"question":"唯物主义与唯心主义的区别在于如何问答","options":["世界的本质是什么的问题","世界可否被认识的问题","世界的存在是怎样的问题","世界统一性的问题"],"answer":0,"answerLetter":"A","explain":"唯物主义和唯心主义是对世界本质的不同回答。唯物主义认为物质是世界的本原，唯心主义认为意 识是世界的本原，二者分歧在于对世界本质是什么的问题的回答。B选项世界可否被认识涉及的是可知论与不 可知论；C选项世界的存在怎样是辩证法和形而上学探讨的内容；D选项世界统一性问题包含在对世界本质的 探讨中，但不如A选项直接准确。"},{"id":"marx-4-170","globalId":464,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":170,"question":"银行利润的本质是（ ）。","options":["生产部门的雇佣工人所创造的剩余价值","银行雇员创造的剩余价值","银行收取的贷款利息","银行收取的服务费"],"answer":0,"answerLetter":"A","explain":"银行利润来源于贷款利息和存款利息的差额，其本质和产业利润一样，都是产业工人创造的剩余价 值的转化形式。银行利润归根结底是生产部门的雇佣工人所创造的剩余价值。银行雇员的劳动虽也有一定作 用，但他们的劳动不创造价值和剩余价值。贷款利息只是银行利润的来源形式，不是本质。银行收取的服务 费同样只是利润来源的一部分形式，不是本质。"},{"id":"marx-4-171","globalId":465,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":171,"question":"资本循环中实现价值增值的阶段是（ ）。","options":["购买阶段","生产阶段","销售阶段","运输阶段"],"answer":1,"answerLetter":"B","explain":"在资本循环的生产阶段，资本家让劳动力与生产资料相结合进行生产，工人的劳动创造出包含剩余 价值的商品，实现了价值增值。购买阶段是为生产剩余价值做准备，销售阶段是实现商品价值和剩余价值。 运输阶段不属于资本循环的基本阶段。答案：B。"},{"id":"marx-4-172","globalId":466,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":172,"question":"马克思把人类社会历史划分为依次更替的五种社会形态：原始社会、奴隶社会、封建社会、资本主义社 会、共产主义社会（社会主义社会是它的第一阶段）。五种社会形态划分的依据是（ ）。","options":["人的发展状况","地理环境的状况","生产力的水平","生产关系的性质"],"answer":3,"answerLetter":"D","explain":"马克思划分五种社会形态的依据是生产关系的性质，不同的生产关系性质决定了社会形态的不同。 生产力水平是影响社会发展的重要因素，但不是划分社会形态的直接依据；人的发展状况、地理环境状况与 社会形态划分依据无关。"},{"id":"marx-4-173","globalId":467,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":173,"question":"社会总产品是社会各个物质生产部门在一定时期（通常是一年）内生产的（ ）。","options":["全部生产资料的总和","全部消费资料的总和","全部物质资料的总和","全部剩余价值的总和"],"answer":2,"answerLetter":"C","explain":"社会总产品指社会各个物质生产部门在一定时期内（通常为一年）所生产出来的全部物质资料的总 和。它既包括生产资料，也包括消费资料。A只提到生产资料，B只提到消费资料，D剩余价值总和概念不符。"},{"id":"marx-4-174","globalId":468,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":174,"question":"唯心史观在历史创造者问题上的根本错误在于（ ）。","options":["否认个人在历史发展中的作用","否认思想动机在历史发展中的作用","否认少数英雄人物是推动历史发展的决定力量","否认广大人民群众是推动历史发展的决定力量"],"answer":3,"answerLetter":"D","explain":"唯心史观从意识决定物质出发，往往夸大英雄人物或精神力量的作用，而忽视甚至否认人民群众对 历史发展的决定作用。答案选D。因为唯心史观的根本错误就是颠倒社会存在和社会意识关系，在历史创造者 问题上，就是否认人民群众的决定作用 。"},{"id":"marx-4-175","globalId":469,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":175,"question":"银行资本家的自有资本的银行利润在数量上通常（ ）。","options":["高于平均利润","等于平均利润","与平均利润无关","相当于平均利润"],"answer":3,"answerLetter":"D","explain":"银行资本家投资银行业，也要求获得平均利润，否则会转移资本到其他行业。银行利润在数量上通 常相当于平均利润。"},{"id":"marx-4-176","globalId":470,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":176,"question":"资本有机构成的提高一般是以","options":["社会总资本的增大为前提","生产资料的增大为前提","流通资本的增大为前提","单个资本的增大为前提"],"answer":3,"answerLetter":"D","explain":"资本有机构成提高意味着不变资本在总资本中所占比重增大，可变资本比重相对减少。而单个资本 增大，才能有更多资金用于购置先进生产设备等不变资本，从而推动资本有机构成提高。社会总资本增大不 一定直接带来单个企业资本有机构成提高；生产资料增大若没有单个资本增大的支撑难以实现资本有机构成 提高；流通资本增大与资本有机构成提高没有直接关联。"},{"id":"marx-4-177","globalId":471,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":177,"question":"马克思说，资本主义“不自觉地为一个更高级的生产形势创造物质条件”，它的“历史人物和存在理由 ”是（ ）。","options":["发明创造新科技成果","发展社会劳动生产力","生产先进的机器设备","建立完善的市场经济"],"answer":2,"answerLetter":"C","explain":"【标准答案：C】"},{"id":"marx-4-178","globalId":472,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":178,"question":"我国坚持走自己的路,建设中国特色社会主义伟大实践的理论基础是（ ）。","options":["矛盾的主要方面和次要方面辩证关系的原理","矛盾的普遍性和特殊性辩证关系的原理","主要矛盾和次要矛盾辩证关系的原理","事物的量变和质变辩证关系的原理"],"answer":1,"answerLetter":"B","explain":"矛盾的普遍性和特殊性辩证关系原理是马克思主义普遍真理同各国具体实际相结合的哲学基础。建 设中国特色社会主义，一方面要坚持社会主义的一般特征和基本原则，这体现了矛盾的普遍性；另一方面 ，又要结合中国的实际情况，体现中国特色，这体现了矛盾的特殊性。所以矛盾的普遍性和特殊性辩证关系 原理是建设中国特色社会主义伟大实践的理论基础。"},{"id":"marx-4-179","globalId":473,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":179,"question":"资本主义国家的政体主要有（ ）。","options":["两党制和多党制两种","君主立宪制和民主共和制两种","一党制、两党制和多党制三种","君主立宪制、民主共和制和专制独裁制三种"],"answer":1,"answerLetter":"B","explain":"资本主义国家政体主要围绕权力组织形式划分。君主立宪制是以君主为国家元首但君主权力受宪法 限制；民主共和制是国家权力机关和国家元首由选举产生。而选项A中两党制和多党制是政党制度，并非政体 ；选项C同样说的是政党制度；选项D中专制独裁制不符合资本主义国家普遍的政治特征，资本主义国家大多 遵循民主政治原则。"},{"id":"marx-4-180","globalId":474,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":180,"question":"资本周转速度与周转次数之间（ ）。","options":["成正比例关系","成反比例关系","按同比例变化","无直接联系"],"answer":0,"answerLetter":"A","explain":"资本周转速度是指资本在一定时期内的周转次数，周转次数越多，资本周转速度就越快，所以资本 周转速度与周转次数成正比例关系。"},{"id":"marx-4-181","globalId":475,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":181,"question":"人类认识发展的根本动力是（ ）。","options":["兴趣爱好","社会实践","求知欲望","好奇心理"],"answer":1,"answerLetter":"B","explain":"社会实践是人类认识发展的根本动力。实践为认识提供新课题，推动认识在探索和解决新课题中向 前发展；实践锻炼和提高主体的认识能力。而兴趣爱好、求知欲望、好奇心理虽然对认识发展有一定作用 ，但都不是根本动力。"},{"id":"marx-4-182","globalId":476,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":182,"question":"生产方式包括（ ）。","options":["劳动者和劳动工具两个方面","地理环境和人口因素两个方面","生产力和生产关系两个方面","经济基础和上层建筑两个方面"],"answer":2,"answerLetter":"C","explain":"生产方式是人类借以向自然界谋取必需的生活资料的方式，它包括生产力和生产关系两个方面，生 产力是生产方式的物质内容，生产关系是生产方式的社会形式。A选项劳动者和劳动工具只是生产力的部分要 素；B选项地理环境和人口因素属于社会存在，但不是生产方式；D选项经济基础和上层建筑构成社会形态。"},{"id":"marx-4-183","globalId":477,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":183,"question":"我们党制定和执行独立自主、自力更生以及对外开放方针的理论基础是（ ）。","options":["矛盾的同一性和斗争性辩证关系的原理","事物发展的内因和外因辩证关系的原理","矛盾的普遍性和特殊性辩证关系的原理","事物发展的量变和质变辩证关系的原理"],"answer":1,"answerLetter":"B","explain":"内因是事物发展变化的根据，外因是事物发展变化的条件，外因通过内因而起作用。我国坚持独立 自主、自力更生是重视内因，对外开放是重视外因，所以理论基础是事物发展的内因和外因辩证关系原理。"},{"id":"marx-4-184","globalId":478,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":184,"question":"资本主义国家对国民经济的管理和调节，主要依靠（ ）。","options":["经济手段","法律手段","行政手段","计划手段"],"answer":0,"answerLetter":"A","explain":"在资本主义国家对国民经济管理调节中，经济手段具有诱导性、间接性等特点，能通过市场机制影 响经济主体行为，是主要方式。法律手段、行政手段、计划手段也会用，但重要性和使用频率不如经济手段 。"},{"id":"marx-4-185","globalId":479,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":185,"question":"资本主义商业店员所从事的商品买卖活动（ ）。","options":["创造商品的价值和使用价值","实现商品的价值和使用价值","创造商品的价格剩余价值","实现商品的价值和剩余价值"],"answer":3,"answerLetter":"D","explain":"商业店员从事商品买卖活动，本身不创造价值和剩余价值，但通过他们的劳动能实现商品的价值和 剩余价值。"},{"id":"marx-4-186","globalId":480,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":186,"question":"人类社会的基本矛盾有两对，一对是生产力和生产关系的矛盾，另一对是（ ）。","options":["社会存在和社会意识的矛盾","剥削阶级和被剥削阶级的矛盾","经济基础和上层建筑的矛盾","先进思想和落后思想的矛盾"],"answer":2,"answerLetter":"C","explain":"人类社会基本矛盾包含生产力与生产关系的矛盾、经济基础与上层建筑的矛盾。A选项社会存在与社 会意识是历史观基本问题；B选项剥削阶级和被剥削阶级矛盾是特定社会阶段阶级矛盾；D选项先进思想和落 后思想矛盾不属于社会基本矛盾。"},{"id":"marx-4-187","globalId":481,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":187,"question":"生产关系包括多方面的内容，其中起决定作用的是（ ）。","options":["人们在生产中的相互关系","生产资料的所有制形式","产品的分配方式","产品的交换方式"],"answer":1,"answerLetter":"B","explain":"生产资料所有制形式决定着生产中人与人的关系、产品分配方式等，是生产关系的基础，起决定作 用。答案：B 。"},{"id":"marx-4-188","globalId":482,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":188,"question":"无产阶级专政的实质就是（ ）。","options":["无产阶级作为统治阶级掌握国家政权","消灭剥削、消灭阶级，最终实现共产主义","镇压敌对阶级的反抗","领导和组织社会主义建设"],"answer":0,"answerLetter":"A","explain":"无产阶级专政的实质，就是无产阶级作为统治阶级掌握国家政权 。其他选项是无产阶级专政的任务 等方面，并非实质。"},{"id":"marx-4-189","globalId":483,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":189,"question":"资本主义国家主要的政体形式是（ ）。","options":["君主立宪制和民主共和制","君主立宪制、民主共和制和专制独裁制","两党制和多党制","一党制、两党制和多党制"],"answer":0,"answerLetter":"A","explain":"政体形式指的是国家政权的组织形式。资本主义国家主要的政体形式为君主立宪制（如英国）和民 主共和制（如美国） 。 选项B中专制独裁制不属于资本主义国家普遍的、主要的政体形式，资本主义国家宣 扬民主等理念，专制独裁不符合其主流政治形态。 选项C和D中两党制、多党制、一党制属于政党制度，并非 政体形式，与题目所问不符。"},{"id":"marx-4-190","globalId":484,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":190,"question":"资本主义商业企业的利润率应大体相当于（ ）。","options":["剩余价值率","平均利润率","银行的贷款利率","银行的存款利率"],"answer":1,"answerLetter":"B","explain":"在资本主义经济中，商业资本家投资商业，其目的也是获取利润，商业利润是商业资本家从事商业 经营活动所获得的利润，商业资本家获得的利润率应大体相当于平均利润率，否则资本就会在不同部门之间 流动，直至形成平均利润率。"},{"id":"marx-4-191","globalId":485,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":191,"question":"社会主义民主的本质是（ ）。","options":["人民当家作主","解放和发展生产力","消灭剥削和压迫","促进人的自由全面发展"],"answer":0,"answerLetter":"A","explain":"社会主义民主是人民的民主，其本质就是人民当家作主，人民是国家的主人。B选项解放和发展生产 力是社会主义的根本任务；C选项消灭剥削和压迫是社会主义的目标之一；D选项促进人的自由全面发展是共 产主义的价值目标。"},{"id":"marx-4-192","globalId":486,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":192,"question":"下列说法中，属于正确发挥人的主观能动性的是（ ）。","options":["人有多大胆，地有多大产","不怕做不到，就怕想不到","纸上谈兵，画饼充饥","量力而行，尽力而为"],"answer":3,"answerLetter":"D","explain":"A、B选项夸大了主观能动性，忽视客观规律；C选项只是空想，没有实际行动去发挥主观能动性。 D选项既考虑到从实际出发（量力而行），又强调充分发挥主观能动性（尽力而为），是正确发挥主观能动性 的体现。"},{"id":"marx-4-193","globalId":487,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":193,"question":"资本主义商业资本执行的是产业资本的（ ）。","options":["货币资本职能","商品资本职能","生产资本职能","流通资本职能"],"answer":1,"answerLetter":"B","explain":"商业资本是从产业资本中分离出来，专门从事商品买卖，独立发挥资本职能，以获取商业利润为目 的的一种资本形式。它执行的是产业资本循环中的商品资本职能，通过销售商品实现商品价值和剩余价值。"},{"id":"marx-4-194","globalId":488,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":194,"question":"社会主义社会的改革是（ ）。","options":["社会主义基本经济制度的改变","社会土义核心价值观的根本改变","社会主义基本政治制度的改变","社会主义制度的自我完善和发展"],"answer":3,"answerLetter":"D","explain":"社会主义社会的改革是在坚持社会主义基本制度的前提下，对生产关系和上层建筑中不适应生产力 发展的部分进行调整和变革，目的是为了更好地推动社会主义的发展，并非改变社会主义的基本经济制度、 政治制度以及核心价值观，而是社会主义制度的自我完善和发展。"},{"id":"marx-4-195","globalId":489,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":195,"question":"下列选项属于马克思主义三个主要组成部分之一的是（ ）。","options":["马克思主义政治学","科学社会主义","马克思主义伦理学","空想社会主义"],"answer":1,"answerLetter":"B","explain":"马克思主义三个主要组成部分是马克思主义哲学、马克思主义政治经济学和科学社会主义 。选项 A马克思主义政治学、C马克思主义伦理学不属于这三个主要部分；D空想社会主义是科学社会主义的理论来源 ，并非马克思主义主要组成部分。"},{"id":"marx-4-196","globalId":490,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":196,"question":"资本主义的国有资本和国有经济一般不参与（ ）。","options":["基础设施的建设","战略性科学研究","普通消费品生产","公共产品生产"],"answer":2,"answerLetter":"C","explain":"资本主义国有资本和国有经济主要投向私人资本不愿投入或无力承担、但对国民经济发展至关重要 的领域，像基础设施建设、战略性科学研究、公共产品生产等，这些领域投资大、周期长、收益慢。而普通 消费品生产盈利性相对较好，私人资本愿意且有能力进行，国有资本一般不参与。"},{"id":"marx-4-197","globalId":491,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":197,"question":"资本主义经济危机产生的根源是（ ）。","options":["资本主义生产方式的基本矛盾","社会两大部类的比例失调","商品供给和需求的矛盾","国家宏观调控的缺失"],"answer":0,"answerLetter":"A","explain":"资本主义经济危机根源在于资本主义生产方式基本矛盾，即生产的社会化与生产资料资本主义私人 占有之间的矛盾，这是资本主义自身无法克服的矛盾。而B社会两大部类比例失调、C商品供给和需求矛盾、 D国家宏观调控缺失都是经济危机的表现或影响因素，并非根源。"},{"id":"marx-4-198","globalId":492,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":198,"question":"资本主义生产部门之间的竞争形成（ ）。","options":["商品价值","生产成本","剩余价值","平均利润"],"answer":3,"answerLetter":"D","explain":"资本主义生产部门之间竞争的结果是使各部门的利润率趋于平均化，形成平均利润率，进而形成平 均利润。商品价值是由生产商品的社会必要劳动时间决定的；生产成本是生产单位商品所耗费的不变资本和 可变资本之和；剩余价值是雇佣工人创造的被资本家无偿占有的超过劳动力价值的价值，它们都不是生产部 门之间竞争形成的。"},{"id":"marx-4-199","globalId":493,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":199,"question":"资本主义的生产成本不应包括（ ）。","options":["工人的工资","原材料费用","机器设备的折旧费","机器设备未折旧部分"],"answer":3,"answerLetter":"D","explain":"资本主义生产成本是生产单位商品所耗费的不变资本与可变资本之和。A选项工人工资属于可变资本 ；B选项原材料费用和C选项机器设备折旧费属于不变资本。而机器设备未折旧部分不构成当前商品生产的实 际耗费，不计入生产成本。"},{"id":"marx-4-200","globalId":494,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":200,"question":"资本主义经济中，农业资本家获得的剩余价值是（ ）。","options":["级差地租","绝对地租","平均利润","利息"],"answer":2,"answerLetter":"C","explain":"在资本主义经济中，农业资本家投资农业，其目的也是为了获得与其他行业大致相同的收益，即平 均利润。农业工人创造的剩余价值，一部分以地租形式（包括级差地租和绝对地租）交给土地所有者，另一 部分则被农业资本家占有，这部分就是平均利润。利息与农业资本家获得的剩余价值无直接关系。"},{"id":"marx-4-201","globalId":495,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":201,"question":"资本主义生产的成本不包括（ ）。","options":["工人的工资","原材料的耗费","固定资本的折旧费","固定资本未折旧的部分"],"answer":3,"answerLetter":"D","explain":"资本主义生产成本是生产单位商品所耗费的不变资本与可变资本之和。工人工资属于可变资本；原 材料耗费和固定资本折旧费属于不变资本。而固定资本未折旧部分不构成当前商品生产已耗费的成本。答案 ：D"},{"id":"marx-4-202","globalId":496,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":202,"question":"下列各项中，正确说明意识能动性的是（ ）。","options":["人有多大胆，地有多大产","不怕做不到，就怕想不到","纸上谈兵，画饼充饥","量力而行，尽力而为"],"answer":3,"answerLetter":"D","explain":"意识能动性是指意识能动地反映世界和通过实践改造世界的能力和作用，既要尊重客观规律，又要 充分发挥主观能动性。 A选项“人有多大胆，地有多大产”、B选项“不怕做不到，就怕想不到”夸大了意识 的能动作用，忽视了客观规律。 C选项“纸上谈兵，画饼充饥”只是停留在意识层面，没有通过实践去改造 世界，不能正确体现意识能动性。 D选项“量力而行，尽力而为”既考虑到客观实际（量力而行），又强调 发挥主观能动性（尽力而为），正确说明了意识能动性。"},{"id":"marx-4-203","globalId":497,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":203,"question":"资本主义经济中的计划管理（ ）。","options":["消除了资本主义的生产无政府状态","能够自觉保持社会再生产的比例关系","阻碍了生产的发展和经济结构的优化","可以对经济周期进行一定的调节与控制"],"answer":3,"answerLetter":"D","explain":"资本主义的计划管理是在资本主义私有制基础上进行的，不能从根本上消除生产无政府状态和自觉 保持社会再生产比例关系，A、B 选项错误；计划管理在一定程度上能促进生产发展和经济结构优化，并非阻 碍，C 错误；资本主义的计划管理可以在一定程度上对经济周期进行调节与控制 。"},{"id":"marx-4-204","globalId":498,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":204,"question":"资本主义相对过剩人口是指（ ）。","options":["劳动力供给超过资本对劳动力的需求而出现的过剩人口","人口增长超过生活资料的增长而出现的过剩人口","人口增长超过生产资料的增长而出现的过剩人口","人口增长超过资本增长而出现的过剩人口"],"answer":0,"answerLetter":"A","explain":"资本主义相对过剩人口是指劳动力供给超过了资本对它的需求，从而形成相对多余的人口。这是资 本主义特有的人口规律，并非人口增长与生活资料、生产资料、资本增长简单对比的问题。"},{"id":"marx-4-205","globalId":499,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":205,"question":"下列各项中正确说明真理问题的是（ ）。","options":["真理是有价值的","有用即真理","真理是永恒的","真理是万能的"],"answer":0,"answerLetter":"A","explain":"A选项正确，真理具有价值性，能指导实践满足人的需求。B选项“有用即真理”是实用主义真理观 ，把价值等同于真理，错误。C选项真理是具体的有条件的，不是永恒不变的，该说法错误。D选项真理不是 万能的，说法过于绝对。"},{"id":"marx-4-206","globalId":500,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":206,"question":"下列选项中，表示要坚持适度原则的是（ ）。","options":["因地制宜","对症下药","注意分寸","实事求是"],"answer":2,"answerLetter":"C","explain":"“注意分寸”强调做事要把握好度，不能过度或不及，体现适度原则。“因地制宜”是根据不同地 方特点采取合适办法；“对症下药”是针对具体病症用药，强调具体问题具体分析；“实事求是”强调从实 际出发探寻规律。"},{"id":"marx-4-207","globalId":501,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":207,"question":"资本主义国家的国体是（ ）。","options":["议会民主制","君主立宪制","资产阶级专政","总统共和制"],"answer":2,"answerLetter":"C","explain":"国体指的是国家的阶级本质，即社会各阶级在国家中的地位。资本主义国家是资产阶级掌握政权 ，其国体是资产阶级专政。而议会民主制、君主立宪制、总统共和制都属于政体，是国家政权的组织形式。"},{"id":"marx-4-208","globalId":502,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":208,"question":"资本主义民主共和制国家中掌握立法权的是（ ）。","options":["国家元首","政府","法院","议会"],"answer":3,"answerLetter":"D","explain":"在资本主义民主共和制国家，议会是立法机关，掌握立法权；国家元首主要履行礼仪性等职责；政 府掌握行政权；法院掌握司法权。所以答案是D议会。"},{"id":"marx-4-209","globalId":503,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":209,"question":"资本主义再生产周期四个阶段的顺序一般为（ ）。","options":["萧条—危机—复苏—高涨","复苏—高涨—危机—萧条","危机—萧条—复苏—高涨","高涨—萧条—危机—复苏"],"answer":2,"answerLetter":"C","explain":"资本主义再生产周期一般是从危机开始，经历萧条阶段，经济缓慢恢复进入复苏阶段，之后走向高 涨，又为下一次危机埋下伏笔，所以顺序是危机—萧条—复苏—高涨。"},{"id":"marx-4-210","globalId":504,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":210,"question":"下列关于利息率的表述中不正确的是（ ）。","options":["它的最低界限不能等于零","通常在平均利润率和零之间变动","由国家的习惯和法律传统决定","与平均利润率和企业利润率按相同比例变动"],"answer":3,"answerLetter":"D","explain":"利息率的高低有一定界限，其最低界限不能等于零，否则借贷资本家无利可图，A 选项正确； 利 息是平均利润的一部分，所以利息率通常在平均利润率和零之间变动，B 选项正确； 利息率在一定程度上受 国家习惯和法律传统等因素影响，C 选项正确； 利息率与平均利润率有关，但企业利润率较为复杂，受多种 因素影响，利息率并非与企业利润率按相同比例变动，D 选项错误。"},{"id":"marx-4-211","globalId":505,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":211,"question":"下列关于人的本质的表述，只涉及人与动物根本区别的是（ ）。","options":["劳动是人的本质","人的需要即人的本质","人的本质是人的全部属性的总和","人的本质是人的自然属性的总和"],"answer":0,"answerLetter":"A","explain":"劳动创造了人，劳动是人类生存和发展的基础，也是人与动物的根本区别，A选项符合。B选项人的 需要并非人与动物根本区别；C选项人的全部属性总和表述宽泛，未突出与动物根本区别；D选项人的本质主 要是社会属性，并非自然属性总和。"},{"id":"marx-4-212","globalId":506,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":212,"question":"下列关于人的本质的说法中不正确的是（ ）。","options":["人的本质是发展变化的","人的本质是现实具体的","人的本质是后天形成的","人的本质是人人相同的"],"answer":3,"answerLetter":"D","explain":"人的本质是一切社会关系的总和。由于不同人的社会关系不同，所以人的本质不是人人相同的。同 时，社会关系是不断发展变化的，所以人的本质是发展变化的；在特定社会关系中形成的人的本质也是现实 具体的，并且是在后天社会生活实践中形成的。"},{"id":"marx-4-213","globalId":507,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":213,"question":"下列选项中，正确表述一个完整认识过程的是（ ）。","options":["感觉——知觉——表象","概念——判断——推理","实践——认识——实践","意识——物质——意识"],"answer":2,"answerLetter":"C","explain":"认识过程是在实践基础上由感性认识上升到理性认识，再由理性认识回到实践的过程，即实践 - 认识 - 实践。 A选项“感觉 - 知觉 - 表象”是感性认识的三种形式。 B选项“概念 - 判断 - 推理”是理 性认识的三种形式。 D选项“意识 - 物质 - 意识”表述错误，辩证唯物主义认识论强调实践在认识过程中 的基础地位，应是实践 - 认识 - 实践。"},{"id":"marx-4-214","globalId":508,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":214,"question":"下列关于生产力和生产关系的表述中，不正确的是（ ）。","options":["生产力的性质决定生产关系的性质","生产力的发展决定生产关系的改变","生产关系对生产力具有巨大的反作用","生产关系总是适应生产力的发展要求"],"answer":3,"answerLetter":"D","explain":"生产力决定生产关系，生产关系反作用于生产力，但生产关系并不总是适应生产力发展要求，当生 产关系不适应生产力时，就会阻碍生产力发展。"},{"id":"marx-4-215","globalId":509,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":215,"question":"下列选项中不属于马克思主义直接理论来源的是（ ）。","options":["德国古典哲学","法国启蒙思想","英国古典经济学","英法两国空想社会主义学说"],"answer":1,"answerLetter":"B","explain":"马克思主义直接理论来源是德国古典哲学、英国古典政治经济学和英法两国空想社会主义学说。法 国启蒙思想不属于其直接理论来源。答案选B。"},{"id":"marx-4-216","globalId":510,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":216,"question":"下列关于意识起源的正确说法是（ ）。","options":["意识是主观自生的","意识是自然界长期发展的产物","意识是人脑的机能","意识是客观世界的主观映像"],"answer":1,"answerLetter":"B","explain":"选项A，意识不是主观自生的，它是物质世界长期发展的产物，A错误。 选项B，意识是自然界长期 发展的产物，同时也是社会历史的产物，该选项阐述了意识起源，正确。 选项C，“意识是人脑的机能”强 调的是意识产生的生理基础，不是起源，C不符合题意。 选项D，“意识是客观世界的主观映像”说明的是意 识的本质，不是起源，D不符合题意。"},{"id":"marx-4-217","globalId":511,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":217,"question":"下列选项中属于共产主义社会显著特征的是（ ）。","options":["按生产要素分配","各尽所能，按劳分配","按能力大小分配","各尽所能，按需分配"],"answer":3,"answerLetter":"D","explain":"共产主义社会生产力高度发达，物质财富极大丰富，人们的思想觉悟极大提高，实行各尽所能、按 需分配，不再按生产要素、能力大小分配，按劳分配是社会主义社会分配方式。所以答案是D。"},{"id":"marx-4-218","globalId":512,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":218,"question":"下列观点中属于客观唯心主义的是（ ）。","options":["天地万物皆在吾心中","存在就是被感知","物是感觉的集合","万物是“绝对精神”的体现"],"answer":3,"answerLetter":"D","explain":"客观唯心主义把客观精神（如上帝、理念、绝对精神等）看作世界的主宰和本原。 A选项“天地万 物皆在吾心中”，强调万物在“吾心”，是主观唯心主义，把人的主观精神当作世界本原。 B选项“存在就 是被感知”，以人的感知来判定存在，属于主观唯心主义。 C选项“物是感觉的集合”，将物归结为感觉集 合，也是主观唯心主义。 D选项“万物是‘绝对精神’的体现”，把“绝对精神”这一客观精神当作万物的 本原，属于客观唯心主义。"},{"id":"marx-4-219","globalId":513,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":219,"question":"下列选项中属于意识形态的是（ ）。","options":["哲学","逻辑学","语言学","物理学"],"answer":0,"answerLetter":"A","explain":"意识形态是指反映一定社会经济形态、从而也反映一定阶级或社会集团的利益和要求的观念体系。 哲学具有强烈的阶级性，是系统化理论化的世界观，属于意识形态。而逻辑学、语言学、物理学是对客观世 界的一般性规律的总结，不具有阶级性，不属于意识形态。"},{"id":"marx-4-220","globalId":514,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":220,"question":"资产阶级道德观的基本原则是（ ）。","options":["利己主义","拜金主义","自由主义","享乐主义"],"answer":0,"answerLetter":"A","explain":"资产阶级道德观从个人主义出发，以利己主义为基本原则，将个人利益置于首位。拜金主义、自由 主义、享乐主义是资产阶级道德观在不同方面的表现，并非基本原则。"},{"id":"marx-4-221","globalId":515,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":221,"question":"资产阶级民主制的核心和主要标志是（ ）。","options":["议会制","三权分立制","普选制","多党制"],"answer":0,"answerLetter":"A","explain":"在资产阶级民主制中，议会是国家的立法机关和权力中心，它集中体现了资产阶级民主制的原则和 特征，所以议会制是资产阶级民主制的核心和主要标志。答案：A。"},{"id":"marx-4-222","globalId":516,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":222,"question":"自然规律与社会规律的区别在于（ ）。","options":["前者是客观的,后者是主观的","前者是绝对的,后者是相对的","前者是通过自然力量相互作用实现的,后者是通过人的自觉活动实现的","前者是不以人的意志为转移的,后者是可以随人的意志改变而改变的"],"answer":2,"answerLetter":"C","explain":"自然规律和社会规律都是客观的，不以人的意志为转移，不存在主观或可随人意志改变、绝对相对 之分。自然规律通过自然力量相互作用实现，社会规律通过人的自觉活动实现，这是二者重要区别。"},{"id":"marx-4-223","globalId":517,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":223,"question":"作为人类社会发展的最高社会形态，共产主义社会的物质基础是（ ）。","options":["与任何繁荣的封建社会相当的社会生产力","与一般资本主义社会相当的社会生产力","与发达资本主义国家相当的社会生产力","远远高于以往一切社会的高度发达的社会生产力"],"answer":3,"answerLetter":"D","explain":"共产主义是人类社会发展的最高形态，其物质基础必然要远超以往社会。以往社会包括封建社会、 一般资本主义社会以及发达资本主义国家所处的生产力水平。共产主义社会需要远远高于以往一切社会的高 度发达的社会生产力作为支撑，才能实现按需分配等特征。答案选D。"},{"id":"marx-4-224","globalId":518,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":224,"question":"自由竞争资本主义时期，资本主义国家对外经济联系的主要方式是（ ）。","options":["商品资本输出","借贷资本输出","生产资本输出","货币资本输出"],"answer":0,"answerLetter":"A","explain":"在自由竞争资本主义时期，资本主义国家经济实力相对有限，主要依靠商品输出获取利润和拓展市 场。而借贷资本输出、生产资本输出等大规模资本输出形式是在垄断资本主义阶段才占据重要地位。货币资 本输出表述不准确，不属于主要方式。答案：A 。"},{"id":"marx-4-225","globalId":519,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":225,"question":"作为马克思恩格斯一生最重要的理论发现，使社会主义从空想变成科学的是（ ）。","options":["唯物论和辩证法学说","唯物论和劳动价值学说","唯物史观和剩余价值学说","唯物史观和阶级斗争学说"],"answer":2,"answerLetter":"C","explain":"唯物史观揭示了人类社会发展的一般规律，剩余价值学说揭示了资本主义社会发展的特殊规律，二 者为科学社会主义的创立奠定了理论基础，使社会主义从空想变为科学。答案：C。"},{"id":"marx-4-226","globalId":520,"part":4,"partName":"第四部分 社会主义与共产主义论","category":"马原专项 · 第四部分 社会主义与共产主义论","num":226,"question":"作为认识和实践活动的承担者，认识主体所具有的突出特点是（ ）。","options":["能动性","社会性","历史性","客观性"],"answer":0,"answerLetter":"A","explain":"认识主体是指认识和实践活动的承担者，人作为认识主体，与动物消极适应自然不同，具有能动地 反映和改造世界的能力，能动性是其突出特点。"}]);

if (typeof module !== 'undefined' && module.exports) {
  module.exports = MARX_CHOICE_DATA;
}
